function ftzIcon(name, size, color) {
  const svg = _svgIcons[name];
  if (!svg) return '';
  let out = svg;
  if (size) out = out.replace(/width="1em"/, `width="${size}"`).replace(/height="1em"/, `height="${size}"`);
  if (color) out = out.replace(/stroke="currentColor"/g, `stroke="${color}"`).replace(/fill="currentColor"/g, `fill="${color}"`);
  return out;
}
// Shorthand icon helpers — Radiance & Onyx use PNG images (displayed inline like SVGs), Boost uses SVG
function _onyxImg(size){const s=size||'18';return '<img src="/fortized%20badges/onyx.png" width="'+s+'" height="'+s+'" style="display:inline-block;vertical-align:middle;object-fit:contain;" alt="Onyx">';}
function _radianceImg(size){const s=size||'16';return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 24 24" style="display:inline-block;vertical-align:middle;object-fit:contain;" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="radianceGrad-'+Math.random()+'" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" style="stop-color:#ff77e4;stop-opacity:1" /><stop offset="100%" style="stop-color:#fff93e;stop-opacity:1" /></linearGradient></defs><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="url(#radianceGrad-'+Math.random()+')" /></svg>';}
function _radiancePlusImg(size){return _radianceImg(size)}
function _boostSvg(size){return ftzIcon('boost',size||'18','currentColor');}

// ══════════════════════════════════════════════════════════
// COMPANION BRIDGE  (localhost process scanner)
// ══════════════════════════════════════════════════════════
// The Fortized Companion is a tiny local helper (Python script) that
// exposes running processes on http://127.0.0.1:47832.
// If it's not running we fall back to manual activity picking.
const COMPANION_PORT = 47832;
const COMPANION_BASE = 'http://127.0.0.1:' + COMPANION_PORT;
let _companionOnline = false;

async function companionFetch(path) {
  try {
    const r = await fetch(COMPANION_BASE + path, { signal: AbortSignal.timeout(1500) });
    if (!r.ok) return null;
    _companionOnline = true;
    return await r.json();
  } catch {
    _companionOnline = false;
    return null;
  }
}

async function companionGetProcesses() {
  const data = await companionFetch('/processes');
  return data?.processes || null;
}

async function companionGetIdleTime() {
  const data = await companionFetch('/idle');
  return data?.idle_seconds ?? null;
}

async function companionPing() {
  const data = await companionFetch('/ping');
  _companionOnline = !!(data?.status === 'ok');
  return _companionOnline;
}

// ══════════════════════════════════════════════════════════
// FAVICON NOTIFICATION SWAP
// ══════════════════════════════════════════════════════════
let _faviconHasNotif = false;
function setFaviconNotif(hasNotif) {
  if (_faviconHasNotif === hasNotif) return;
  _faviconHasNotif = hasNotif;
  const el = document.getElementById('favicon');
  if (el) el.href = hasNotif ? '/Fortized icon notif.png' : '/Fortized icon.png';
}
// Re-check unread badge (and favicon) whenever the tab regains focus/visibility
if (!window._faviconFocusHooked) {
  window._faviconFocusHooked = true;
  const _refreshBadge = () => { try { if (typeof updateNotifBadge === 'function' && window.CU) updateNotifBadge(); } catch(_) {} };
  window.addEventListener('focus', _refreshBadge);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) _refreshBadge(); });
}

// ════════════════════════════════════════════
// GLOBAL STATE
// ════════════════════════════════════════════
let CU = null;
// ── PROFILE LIGHT-CACHE ──────────────────────────────────────────────────
// Discord-style stale-while-revalidate: keep a tiny per-user blob in
// localStorage (pfp + displayName + lastStatus) so DM/friend/member lists
// paint REAL data on first frame, before any network round-trip. When the
// async profile fetch returns, we refresh both the cache and the visible
// row. Without this, every cold load shows a wall of grey fallback avatars
// while the user waits for the batch query.
const _profileCache = (() => {
  try {
    const raw = localStorage.getItem('ftz_profile_cache_v1');
    if (raw) return JSON.parse(raw) || {};
  } catch {}
  return {};
})();
let _profileCacheSaveTimer = null;
function _persistProfileCache() {
  if (_profileCacheSaveTimer) return;
  _profileCacheSaveTimer = setTimeout(() => {
    _profileCacheSaveTimer = null;
    try { localStorage.setItem('ftz_profile_cache_v1', JSON.stringify(_profileCache)); } catch {}
  }, 500);
}
function rememberProfile(u) {
  if (!u || !u.username) return;
  const entry = _profileCache[u.username] || {};
  let dirty = false;
  if (u.pfp && entry.pfp !== u.pfp) { entry.pfp = u.pfp; dirty = true; }
  if (u.displayName && entry.displayName !== u.displayName) { entry.displayName = u.displayName; dirty = true; }
  if (u.status && entry.status !== u.status) { entry.status = u.status; dirty = true; }
  if (dirty) {
    _profileCache[u.username] = entry;
    _persistProfileCache();
    if (u.pfp) _pfpCache[u.username] = u.pfp; // keep legacy cache aligned
  }
}
function cachedProfile(username) {
  return _profileCache[username] || _profileCache[(username||'').toLowerCase()] || null;
}
// Legacy in-memory PFP cache retained for backwards compatibility — now
// hydrated from the profile cache so existing call sites keep working.
const _pfpCache = (() => {
  const out = {};
  for (const [k, v] of Object.entries(_profileCache)) {
    if (v && v.pfp) out[k] = v.pfp;
  }
  // Migrate any old standalone pfp cache.
  try {
    const oldRaw = localStorage.getItem('ftz_pfp_cache_v1');
    if (oldRaw) {
      const old = JSON.parse(oldRaw) || {};
      for (const [k, v] of Object.entries(old)) {
        if (v && !out[k]) {
          out[k] = v;
          _profileCache[k] = { ..._profileCache[k], pfp: v };
        }
      }
      localStorage.removeItem('ftz_pfp_cache_v1');
      _persistProfileCache();
    }
  } catch {}
  return out;
})();
function _persistPfpCache() { _persistProfileCache(); } // alias
const _pfpCropCache = {}; // username -> {leftPct, topPct, widthPct} for GIF avatar CSS cropping
const _liveStatusCache = {}; // username -> status, updated by real-time presence events
const _liveGameActivityCache = {}; // username -> { name, metadata, startedAt } | null
const _liveActivityCache = {};     // username -> { activities:[...] }
const _verifiedCache = {};   // username -> bool (populated via getUserByName)
let curBastion = null;
let curChannel = null;
let curDM = null;
// ── Chat scroll position persistence ──
const _chatScrollPositions = {};
function _saveChatScroll(key, el) {
  if (!el || !key) return;
  _chatScrollPositions[key] = { top: el.scrollTop, height: el.scrollHeight };
}
function _restoreChatScroll(key, el) {
  if (!el || !key) return false;
  const saved = _chatScrollPositions[key];
  if (!saved) return false;
  // If the scroll height changed significantly (new messages loaded), go to bottom
  if (Math.abs(el.scrollHeight - saved.height) > 200) return false;
  el.scrollTop = saved.top;
  return true;
}
// Unread tracking per channel: Map<bastionIdx_chIdx, {count:number, mentions:number}>
const _channelUnread = new Map();
function getChannelUnreadKey(bIdx, chIdx) { return bIdx+'_'+chIdx; }
function getChannelUnread(bIdx, chIdx) { return _channelUnread.get(getChannelUnreadKey(bIdx,chIdx)) || {count:0, mentions:0}; }
function markChannelUnread(bIdx, chIdx, mentionMe) {
  const k = getChannelUnreadKey(bIdx,chIdx);
  const cur = _channelUnread.get(k) || {count:0, mentions:0};
  cur.count++;
  if (mentionMe) cur.mentions++;
  _channelUnread.set(k, cur);
  // Re-render sidebar to show badge
  const scroll = document.querySelector('.sidebar-scroll');
  if (curBastion === bIdx && scroll) renderBastionSidebar(scroll);
}
function clearChannelUnread(bIdx, chIdx) {
  _channelUnread.delete(getChannelUnreadKey(bIdx,chIdx));
}
let voiceConnected = false;
let _outlineMode = false;
let voiceChannel = null;
let voiceParticipants = [];
