let quizAnswers = [];
let activeReportData = null;
const SUPER_ADMINS = ['staw', 'fortized', 'joyster'];
const SUPER_ADMIN = 'staw'; // legacy compat
const JOYSTER_ACCOUNT = 'joyster';
const FORTIZED_ACCOUNT = 'fortized';
// Role hierarchy: superadmin > admin > moderator
// superadmin: maximum power, access to private data, can enable important stuff, has access to the privacy of the users (precise age)
// admin: set by superadmins, limited data access, limited power, can do important stuff but with limits, only see age tier
// moderator: set by superadmins only, very limited, nearly zero data access, only moderation tools (nsfw, reports, user lookup restrained)

// ════════════════════════════════════════════════════════════
// STATUS MODULE — Single Source of Truth
// ════════════════════════════════════════════════════════════
// Every status color, label, and helper lives here.
// Nothing else in the codebase should define status constants.
// ════════════════════════════════════════════════════════════
const FtzStatus = (() => {
  const MODES = Object.freeze({
    online:    { color: '#3ecf6e', label: 'Online',          order: 0 },
    away:      { color: '#f59e0b', label: 'Idle',            order: 1 },
    dnd:       { color: '#f87171', label: 'Do Not Disturb',  order: 2 },
    invisible: { color: '#6b7280', label: 'Invisible',       order: 3 },
    offline:   { color: '#6b7280', label: 'Offline',         order: 4 },
  });

  const VALID = new Set(Object.keys(MODES));
  // Discord-style idle thresholds:
  //  - 10 min of no input while the tab is visible → auto-Idle (matches
  //    Discord's "Idle After 10 minutes" default exactly).
  //  - 3 min after the tab is hidden (alt-tab / minimised / window not in
  //    focus) → auto-Idle. Hidden gets a shorter timer because we already
  //    know the user isn't looking at the chat.
  // The previous 25 / 5 min values left users showing as "Online" long
  // after they'd walked away — broke the "is this person actually there
  // right now?" signal that statuses exist for.
  const IDLE_TIMEOUT_ACTIVE  = 10 * 60 * 1000; // 10 min when tab visible
  const IDLE_TIMEOUT_HIDDEN  = 3 * 60 * 1000;  // 3 min when tab hidden

  const CUSTOM_DURATIONS = Object.freeze([
    { id: '30m',     label: '30 min',     ms: 30 * 60000 },
    { id: '1h',      label: '1 hour',     ms: 60 * 60000 },
    { id: '4h',      label: '4 hours',    ms: 4 * 60 * 60000 },
    { id: 'today',   label: 'Today',      ms: null },      // computed at set-time
    { id: 'forever', label: "Don't Clear", ms: Infinity },
  ]);

  // ── Helpers ──────────────────────────────────────────────
  function isValid(s) { return VALID.has(s); }
  function sanitize(s) { return VALID.has(s) ? s : 'offline'; }
  function color(s) { return (MODES[s] || MODES.offline).color; }
  function label(s) { return (MODES[s] || MODES.offline).label; }
  // What others see (invisible → offline)
  function visible(s) { return s === 'invisible' ? 'offline' : sanitize(s); }
  // Label for public display (invisible → Offline)
  function publicLabel(s) { return s === 'invisible' ? 'Offline' : label(s); }
  // Is this user "present" (not offline/invisible)?
  function isPresent(s) { return s === 'online' || s === 'away' || s === 'dnd'; }
  // Sort comparator for friend lists (online first)
  function sortOrder(s) { return (MODES[s] || MODES.offline).order; }

  // ── Status icon SVGs ────────────────────────────────────
  const _STATUS_ICONS = Object.freeze({
    online:    { vb:'0 0 16 16', path:'<circle cx="8" cy="8" r="8"/>' },
    away:      { vb:'0 0 24 24', path:'<path d="M12,2h-.46a1,1,0,0,0-.9.77,1,1,0,0,0,.46,1.09A5.92,5.92,0,0,1,14,9,6,6,0,0,1,3.93,13.4a1,1,0,0,0-1.65,1A10,10,0,1,0,12,2Z"/>' },
    dnd:       { vb:'0 0 296 296', path:'<path d="M148,0C66.393,0,0,66.393,0,148s66.393,148,148,148s148-66.393,148-148S229.607,0,148,0z M223.407,110.008l-11.011,53.934c-2.817,13.799-4.237,27.848-4.237,41.932c0,20.493-16.673,37.166-37.166,37.166H137.34c-11.397,0-21.539-5.459-27.961-13.895l-55.675-57.829c-5.375-5.583-5.207-14.466,0.377-19.842c5.584-5.375,14.467-5.206,19.842,0.377l23.462,24.369c0.837,0.869,2.135,1.107,3.226,0.591c1.091-0.516,1.73-1.671,1.589-2.869L91.241,80.953c-0.907-7.697,4.597-14.672,12.294-15.579c7.697-0.909,14.672,4.598,15.579,12.294l5.315,45.108c0.116,0.987,0.982,1.712,1.974,1.654c0.992-0.058,1.767-0.88,1.767-1.874V66.993c0-7.75,6.283-14.033,14.033-14.033c7.75,0,14.033,6.283,14.033,14.033v56.453c0,1.214,0.957,2.212,2.17,2.264c1.213,0.052,2.251-0.862,2.354-2.071l3.929-46.159c0.658-7.722,7.456-13.45,15.173-12.792c7.722,0.658,13.45,7.451,12.792,15.173l-4.614,54.201c-0.097,1.14,0.711,2.157,1.844,2.321c1.132,0.163,2.195-0.585,2.424-1.705l6.079-29.775c1.411-6.909,8.162-11.358,15.063-9.956C220.359,96.356,224.816,103.1,223.407,110.008z"/>' },
    invisible: { vb:'0 0 512 512', path:'<g transform="translate(42.667,42.667)"><path d="M213.333,0C331.154,0,426.667,95.513,426.667,213.333c0,117.821-95.513,213.333-213.333,213.333C95.513,426.667,0,331.154,0,213.333C0,95.513,95.513,0,213.333,0z M213.333,106.667c-58.91,0-106.667,47.756-106.667,106.667s47.756,106.667,106.667,106.667s106.667-47.756,106.667-106.667S272.244,106.667,213.333,106.667z"/></g>' },
    offline:   { vb:'0 0 512 512', path:'<g transform="translate(42.667,42.667)"><path d="M213.333,0C331.154,0,426.667,95.513,426.667,213.333c0,117.821-95.513,213.333-213.333,213.333C95.513,426.667,0,331.154,0,213.333C0,95.513,95.513,0,213.333,0z M213.333,106.667c-58.91,0-106.667,47.756-106.667,106.667s47.756,106.667,106.667,106.667s106.667-47.756,106.667-106.667S272.244,106.667,213.333,106.667z"/></g>' },
  });

  function dotSvg(st, sz) {
    const s = sanitize(st);
    const i = _STATUS_ICONS[s] || _STATUS_ICONS.offline;
    const c = color(s);
    const n = parseInt(sz, 10) || 12;
    const half = n / 2;
    const aroundColor = '#1f232b';  // Solid dark color (not transparent)
    // All statuses: dark circle bg + colored icon centered
    const inner = Math.round(n * 0.65);
    const off = Math.round((n - inner) / 2);
    return '<svg width="'+n+'" height="'+n+'" viewBox="0 0 '+n+' '+n+'" xmlns="http://www.w3.org/2000/svg">'
      + '<circle cx="'+half+'" cy="'+half+'" r="'+half+'" fill="'+aroundColor+'"/>'
      + '<svg x="'+off+'" y="'+off+'" width="'+inner+'" height="'+inner+'" viewBox="'+i.vb+'" fill="'+c+'">'+i.path+'</svg>'
      + '</svg>';
  }

  // Helper to blend two colors and ensure readability
  function _blendColorsForProfileCard(color1, color2) {
    // Parse hex colors
    const c1 = parseInt(color1.substring(1), 16);
    const c2 = parseInt(color2.substring(1), 16);

    // Extract RGB components
    const r1 = (c1 >> 16) & 255, g1 = (c1 >> 8) & 255, b1 = c1 & 255;
    const r2 = (c2 >> 16) & 255, g2 = (c2 >> 8) & 255, b2 = c2 & 255;

    // Average the colors (50/50 blend)
    let r = Math.round((r1 + r2) / 2);
    let g = Math.round((g1 + g2) / 2);
    let b = Math.round((b1 + b2) / 2);

    // Desaturate to reduce color intensity (make it more neutral/light)
    const brightness = (r + g + b) / 3;
    const desaturate = 0.4;  // 40% saturation
    r = Math.round(r * desaturate + brightness * (1 - desaturate));
    g = Math.round(g * desaturate + brightness * (1 - desaturate));
    b = Math.round(b * desaturate + brightness * (1 - desaturate));

    // Lighten to ensure readability
    const lighten = 0.25;  // Add 25% lightness
    r = Math.min(255, Math.round(r + (255 - r) * lighten));
    g = Math.min(255, Math.round(g + (255 - g) * lighten));
    b = Math.min(255, Math.round(b + (255 - b) * lighten));

    return '#' + [r, g, b].map(x => ('0' + x.toString(16)).slice(-2)).join('');
  }

  function updateDots(username, st) {
    const s = sanitize(st);
    // Update all status dots with class-based selectors
    const selectors = [
      '.profile-status-dot[data-for="'+username+'"]',
      '.ml-entry[data-member="'+username+'"] .ml-status',
      '.mpp-status-dot[data-for="'+username+'"]',
      '.dm-home-status[data-for="'+username+'"]'
    ];
    selectors.forEach(sel => {
      document.querySelectorAll(sel).forEach(el => {
        el.dataset.dotStatus = s;
        el.innerHTML = dotSvg(s, el.dataset.dotSize || '12');
        el.style.background = 'none';
        el.style.boxShadow = 'none';
        el.style.filter = '';
      });
    });
  }

  // ── Duration helpers for custom status ──────────────────
  function durationMs(id) {
    if (id === 'today') {
      const now = new Date();
      return new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1) - now;
    }
    const d = CUSTOM_DURATIONS.find(d => d.id === id);
    return d ? d.ms : Infinity;
  }

  // ── Status state management (Discord-style) ────────────
  // _manualStatus: what the user explicitly chose (persisted)
  // _autoAway: whether we auto-set the user to "away" due to inactivity
  // When auto-away, we restore _manualStatus on user activity
  let _idleTimer = null;
  let _manualStatus = null;   // The status the user picked (online/away/dnd/invisible)
  let _autoAway = false;      // True when we forced "away" due to idle
  let _customStatusTimer = null;

  function _broadcast(status) {
    if (!CU?.username) return;
    const vis = visible(status);
    // Real-time: emit status:set so server broadcasts presence:update to all clients
    FortizedSocial.socketEmit('status:set', { status: status });
    // Persistence: write to Supabase (async, non-blocking)
    FortizedSocial.setStatus(CU.username, vis).catch(e => {
      console.warn('[FtzStatus] broadcast failed:', e);
    });
  }

  function set(status) {
    if (!CU?.username) return;
    status = sanitize(status);
    const prev = _manualStatus;
    _manualStatus = status;
    _autoAway = false;
    CU.status = status;
    // Save manual status to localStorage for persistence across reloads
    try { localStorage.setItem('ftz_manual_status_' + CU.username, status); } catch (e) { _dbg('[Status] localStorage write failed', e); }
    _broadcast(status);
    saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
    updateUserbar();
    refreshCustomStatusBubble();
    if (prev !== status && typeof _logJoysterEvent === 'function') {
      _logJoysterEvent(`changed status to "${status}"`);
    }
  }

  // Restore the user's manually chosen status on login
  function restoreManualStatus() {
    if (!CU?.username) return;
    try {
      const saved = localStorage.getItem('ftz_manual_status_' + CU.username);
      if (saved && isValid(saved)) {
        _manualStatus = saved;
        CU.status = saved;
        _broadcast(saved);
        updateUserbar();
        return;
      }
    } catch (e) { _dbg('[Status] localStorage read failed', e); }
    // Default to online
    _manualStatus = CU.status || 'online';
    CU.status = _manualStatus;
    _broadcast(_manualStatus);
    updateUserbar();
  }

  // ── Idle / Activity Detection (Discord-style) ──────────
  // - Only auto-away if user chose "online" — never override DND/invisible/manual-away
  // - On activity, restore to manual status
  function _goIdle() {
    if (!CU) return;
    // Only auto-away if user's manual status is "online"
    if (_manualStatus !== 'online') return;
    _autoAway = true;
    CU.status = 'away';
    _broadcast('away');
    updateUserbar();
  }

  function _resetIdle() {
    if (_idleTimer) clearTimeout(_idleTimer);
    // If we auto-set away, restore the user's manual status on activity
    if (_autoAway && CU) {
      _autoAway = false;
      CU.status = _manualStatus || 'online';
      _broadcast(CU.status);
      updateUserbar();
    }
    // Only start idle timer if manual status is "online"
    if (_manualStatus === 'online') {
      const timeout = document.hidden ? IDLE_TIMEOUT_HIDDEN : IDLE_TIMEOUT_ACTIVE;
      _idleTimer = setTimeout(_goIdle, timeout);
    }
  }

  // ── Companion-based system idle detection ───────────────
  let _companionIdlePoller = null;
  const COMPANION_IDLE_POLL_MS = 15_000;
  const COMPANION_IDLE_THRESHOLD = 10 * 60; // 10 min

  let _companionIdlePollRunning = false;
  function _startCompanionIdlePoll() {
    if (_companionIdlePoller) return;
    _companionIdlePoller = setInterval(async () => {
      if (_companionIdlePollRunning) return;
      if (!CU?.username || !_companionOnline) return;
      _companionIdlePollRunning = true;
      try {
        const idleSec = await companionGetIdleTime();
        if (typeof idleSec !== 'number' || idleSec < 0) return;
        if (idleSec >= COMPANION_IDLE_THRESHOLD && _manualStatus === 'online' && !_autoAway) {
          _goIdle();
        } else if (idleSec < COMPANION_IDLE_THRESHOLD && _autoAway) {
          _autoAway = false;
          CU.status = _manualStatus || 'online';
          _broadcast(CU.status);
          updateUserbar();
        }
      } catch (e) { _dbg('[Status] idle poll failed', e); } finally { _companionIdlePollRunning = false; }
    }, COMPANION_IDLE_POLL_MS);
  }

  function _stopCompanionIdlePoll() {
    if (_companionIdlePoller) { clearInterval(_companionIdlePoller); _companionIdlePoller = null; }
  }

  function initIdle() {
    // DOM-level activity detection (works in browser + Electron)
    ['mousemove','keydown','click','touchstart','scroll','mousedown'].forEach(ev => {
      document.addEventListener(ev, _resetIdle, { passive: true });
    });
    _resetIdle();

    document.addEventListener('visibilitychange', () => {
      if (!CU?.username) return;
      if (document.hidden) {
        // Tab hidden — start short idle timer (only if manual is online)
        if (_idleTimer) clearTimeout(_idleTimer);
        if (_manualStatus === 'online') {
          _idleTimer = setTimeout(_goIdle, IDLE_TIMEOUT_HIDDEN);
        }
      } else {
        // Tab visible — restore from auto-away and reset idle timer
        _resetIdle();
      }
    });

    // If companion is running, use system-level idle detection too
    companionPing().then(online => { if (online) _startCompanionIdlePoll(); }).catch(e => _dbg('[Companion] ping failed:', e?.message));

    // Use Firebase onDisconnect as a backup to set offline status when tab closes
    // (Primary offline detection is via Socket.IO disconnect + sendBeacon to Supabase)
    if (CU?.username) {
      try {
        firebase.database().ref('statuses/' + CU.username).onDisconnect().set('offline');
      } catch(e) { console.warn('[Status] onDisconnect setup failed:', e?.message); }
    }
    // Mark offline ONLY when the tab is actually closed (not on navigation/refresh).
    // Socket.IO disconnect on the server (see server.js) is the source of truth —
    // the old sendBeacon('/api/presence/offline') was a belt-and-braces fallback
    // but the proxy (Cloudflare) returns 405 for POST on that path, so we rely
    // on socket disconnect alone.
    window.addEventListener('pagehide', (e) => {
      if (!CU?.username) return;
      _stopCompanionIdlePoll();
      if (typeof _stopAutoActivityDetection === 'function') _stopAutoActivityDetection();
      stopCrossDeviceSync();
    });
  }

  // ── Custom Status ───────────────────────────────────────
  function _clearCustomTimer() {
    if (_customStatusTimer) { clearTimeout(_customStatusTimer); _customStatusTimer = null; }
  }

  function _onCustomExpiry() {
    delete CU.customStatus;
    // Explicitly null out in Firebase — dbUpdate won't remove deleted fields
    try {
      const uname = (CU.username || '').toLowerCase();
      if (uname) firebase.database().ref('users/' + uname + '/customStatus').set(null);
    } catch(e) { console.warn('[Status] Custom status clear failed:', e?.message); }
    saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
    refreshCustomStatusBubble();
    toast('Custom status cleared', 'info');
  }

  function setCustom(emoji, text, durationId) {
    if (!text) return;
    _clearCustomTimer();
    const cs = { emoji: emoji || '😊', text, set: new Date().toISOString() };
    const ms = durationMs(durationId || 'forever');
    if (ms !== Infinity && ms > 0) {
      cs.clearAt = new Date(Date.now() + ms).toISOString();
      _customStatusTimer = setTimeout(_onCustomExpiry, ms);
    }
    CU.customStatus = cs;
    // Direct write to customStatus sub-path so Firebase listeners fire immediately
    try {
      const uname = (CU.username || '').toLowerCase();
      if (uname) firebase.database().ref('users/' + uname + '/customStatus').set(cs);
    } catch(e) { console.warn('[Status] Custom status write failed:', e?.message); }
    saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
    refreshCustomStatusBubble();
    if (typeof _logJoysterEvent === 'function') {
      _logJoysterEvent(`set custom status ${cs.emoji || ''} "${text}"`);
    }
  }

  function clearCustom() {
    _clearCustomTimer();
    delete CU.customStatus;
    // Explicitly null out in Firebase — dbUpdate won't remove deleted fields
    try {
      const uname = (CU.username || '').toLowerCase();
      if (uname) firebase.database().ref('users/' + uname + '/customStatus').set(null);
    } catch(e) { console.warn('[Status] Custom status clear failed:', e?.message); }
    saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
    refreshCustomStatusBubble();
  }

  function restoreCustomTimer() {
    const cs = CU?.customStatus;
    if (!cs?.clearAt) return;
    const remaining = new Date(cs.clearAt) - Date.now();
    if (remaining <= 0) {
      delete CU.customStatus;
      saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
      return;
    }
    _clearCustomTimer();
    _customStatusTimer = setTimeout(_onCustomExpiry, remaining);
  }

  return Object.freeze({
    MODES, VALID, CUSTOM_DURATIONS,
    IDLE_TIMEOUT_ACTIVE, IDLE_TIMEOUT_HIDDEN,
    isValid, sanitize, color, label, visible, publicLabel, isPresent, sortOrder,
    durationMs, dotSvg, updateDots,
    set, initIdle, restoreManualStatus, broadcast: _broadcast,
    setCustom, clearCustom, restoreCustomTimer,
  });
})();

