function markChannelRead(bastionIdx) {
  const bar = document.getElementById(`ch-new-msgs-bar-${bastionIdx}`);
  if (bar) bar.classList.remove('show');
  // Channel unread tracking is per-message-id (not per-notification), so there's
  // no per-channel notification filter. Badge refresh covers visual state.
  updateNotifBadge().catch(()=>{});
}

function showNewMessagesBar(chatType, count = 1) {
  const barId = chatType === 'dm' ? 'dm-new-msgs-bar' : chatType === 'gc' ? 'gc-new-msgs-bar' : `ch-new-msgs-bar-${chatType}`;
  const textId = chatType === 'dm' ? 'dm-new-msgs-text' : chatType === 'gc' ? 'gc-new-msgs-text' : `ch-new-msgs-text-${chatType}`;
  const bar = document.getElementById(barId);
  const text = document.getElementById(textId);
  if (bar && text) {
    const msg = count === 1 ? '1 new message' : `${count} new messages`;
    text.textContent = msg;
    bar.classList.add('show');
  }
}
function scrollToMsg(msgId) {
  if(!msgId)return;
  try {
    const row=document.querySelector(`[data-msgid="${CSS.escape(String(msgId))}"]`);
    if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.style.background='rgba(255,249,62,.06)';row.style.transition='background .3s';setTimeout(()=>row.style.background='',1500);}
  } catch(e) { _wrn('scrollToMsg', e); }
}
// Smart auto-scroll: track whether user is at bottom
let _chatAutoScroll={};
let _chatScrollDebounce={};
let _chatObservers={};
function _initChatScroll(msgsEl){
  if(!msgsEl)return;
  const id=msgsEl.id;
  _chatAutoScroll[id]={atBottom:true,newCount:0,newBarInserted:false};
  // Guard against re-attaching duplicate listeners when the same element is
  // re-initialised (e.g. switching between DMs keeps #dm-msgs mounted).
  if(msgsEl.dataset.chatScrollInit==='1'){
    if(_chatObservers[id]){try{_chatObservers[id].disconnect();}catch{}}
    const obs=new MutationObserver(()=>{if(_chatAutoScroll[id]?.atBottom) msgsEl.scrollTop=msgsEl.scrollHeight;});
    obs.observe(msgsEl,{childList:true,subtree:true});
    _chatObservers[id]=obs;
    return;
  }
  msgsEl.dataset.chatScrollInit='1';
  msgsEl.addEventListener('scroll',()=>{
    // Debounce scroll calculations to avoid jank
    if(_chatScrollDebounce[id]) return;
    _chatScrollDebounce[id]=true;
    requestAnimationFrame(()=>{
      _chatScrollDebounce[id]=false;
      const atBot=msgsEl.scrollHeight-msgsEl.scrollTop-msgsEl.clientHeight<150;
      _chatAutoScroll[id].atBottom=atBot;
      const pastBar=msgsEl.querySelector('.chat-past-bar');
      if(pastBar){
        const scrolledUp=msgsEl.scrollTop<msgsEl.scrollHeight-msgsEl.clientHeight-300;
        pastBar.classList.toggle('show',scrolledUp);
      }
      if(atBot){
        _chatAutoScroll[id].newCount=0;
        // Remove the NEW bar when user scrolls to bottom
        _removeNewMsgBar(id);
        const btn=msgsEl.parentElement?.querySelector('.chat-new-msg-btn');
        if(btn)btn.classList.remove('show');
      }
    });
  },{passive:true});
  // Observe DOM changes — when new messages are appended, auto-scroll if at bottom
  if(_chatObservers[id]){try{_chatObservers[id].disconnect();}catch{}}
  const obs=new MutationObserver(()=>{
    if(_chatAutoScroll[id]?.atBottom){
      msgsEl.scrollTop=msgsEl.scrollHeight;
    }
  });
  obs.observe(msgsEl,{childList:true,subtree:true});
  _chatObservers[id]=obs;
  // Handle images/embeds loading after render — keep scroll at bottom
  msgsEl.addEventListener('load',function(e){
    if(e.target.tagName==='IMG'&&_chatAutoScroll[id]?.atBottom){
      msgsEl.scrollTop=msgsEl.scrollHeight;
    }
  },true);
}
function _notifyNewMsg(msgsElId){
  const state=_chatAutoScroll[msgsElId];
  if(!state||state.atBottom){scrollBottom(msgsElId);requestAnimationFrame(()=>scrollBottom(msgsElId,true));return;}
  state.newCount++;
  const msgsEl=document.getElementById(msgsElId);
  if(!msgsEl)return;

  // Show sticky notification banner
  const chatType = msgsElId.includes('dm') ? 'dm' : msgsElId.includes('gc') ? 'gc' : msgsElId.match(/\d+/)?.[0];
  if (chatType) showNewMessagesBar(chatType, state.newCount);

  // Insert the NEW bar before the first new (unread) message if not yet inserted
  if(!state.newBarInserted){
    state.newBarInserted=true;
    const allRows=msgsEl.querySelectorAll('.msg-row');
    const lastRow=allRows.length?allRows[allRows.length-1]:null;
    if(lastRow){
      const bar=document.createElement('div');
      bar.className='new-msg-bar';
      bar.id='new-msg-bar-'+msgsElId;
      bar.innerHTML='<span class="new-msg-label">NEW MESSAGES</span>';
      // Insert before the last row (which is the first new message)
      lastRow.parentElement.insertBefore(bar,lastRow);
    }
  }
  let btn=msgsEl.parentElement?.querySelector('.chat-new-msg-btn');
  if(!btn){
    btn=document.createElement('div');btn.className='chat-new-msg-btn';
    btn.onclick=()=>{
      const el=document.getElementById(msgsElId);
      if(el) el.scrollTo({top:el.scrollHeight,behavior:'smooth'});
      btn.classList.remove('show');state.newCount=0;
      _removeNewMsgBar(msgsElId);
    };
    msgsEl.parentElement.appendChild(btn);
  }
  btn.innerHTML=`${state.newCount} New Message${state.newCount>1?'s':''} <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="6,9 12,15 18,9"/></svg>`;
  btn.classList.add('show');
}
function _removeNewMsgBar(msgsElId){
  const state=_chatAutoScroll[msgsElId];
  if(state) state.newBarInserted=false;
  const bar=document.getElementById('new-msg-bar-'+msgsElId);
  if(bar) bar.remove();
}
function formatTimeAgo(iso) {
  if (!iso) return '';
  const d = new Date(iso), now = new Date();
  const diff = (now - d) / 1000;
  if (diff < 60) return 'just now';
  if (diff < 3600) return Math.floor(diff/60) + 'm ago';
  if (diff < 86400) return Math.floor(diff/3600) + 'h ago';
  return Math.floor(diff/86400) + 'd ago';
}
function timeAgoHTML(iso){ if(!iso) return ''; return `<span class="time-ago" data-ts="${escapeHTML(String(iso))}">${formatTimeAgo(iso)}</span>`; }
if (!window._timeAgoTicker) {
  window._timeAgoTicker = setInterval(() => {
    if (document.hidden) return;
    try {
      document.querySelectorAll('.time-ago[data-ts]').forEach(el => {
        const v = formatTimeAgo(el.getAttribute('data-ts'));
        if (el.textContent !== v) el.textContent = v;
      });
    } catch(_) {}
  }, 60000);
}
function _formatElapsed(startIso) {
  if (!startIso) return '';
  const diff = (Date.now() - new Date(startIso).getTime()) / 1000;
  if (diff < 60) return 'a few seconds';
  if (diff < 3600) return Math.floor(diff/60) + ' min';
  const h = Math.floor(diff/3600);
  const m = Math.floor((diff%3600)/60);
  return h + 'h ' + (m > 0 ? m + 'm' : '');
}
function attachFile(inputId) { openFileUpload(inputId || 'ch-input'); }

// ── Role System ──
// Role membership is stored lowercase (addStaff normalises on insert, SUPER_ADMINS
// is declared lowercase). Compare case-insensitively so that a user whose
// current username happens to be mixed-case ("Staw") still matches the
// lowercase entry ("staw") — otherwise granted rights look broken after refresh.
function _normRoleName(u) { return (u || '').toString().trim().toLowerCase(); }
function _roleListHas(list, username) {
  if (!username || !Array.isArray(list)) return false;
  const n = _normRoleName(username);
  for (let i = 0; i < list.length; i++) {
    if (_normRoleName(list[i]) === n) return true;
  }
  return false;
}
function isSuperAdmin() { return !!CU?.username && _roleListHas(SUPER_ADMINS, CU.username); }
function _getStaffData() {
  try { return JSON.parse(localStorage.getItem('ftz_staff')||'{}'); } catch(e) { console.warn('[Staff] Parse failed:', e); return {admins:[], moderators:[]}; }
}
function isAdmin() {
  if (isSuperAdmin()) return true;
  const staff = _getStaffData();
  return !!CU?.username && _roleListHas(staff.admins, CU.username);
}
function isModerator() {
  if (isAdmin()) return true;
  const staff = _getStaffData();
  return !!CU?.username && _roleListHas(staff.moderators, CU.username);
}
function getStaffRole(username) {
  if (!username) return null;
  if (_roleListHas(SUPER_ADMINS, username)) return 'superadmin';
  const staff = _getStaffData();
  if (_roleListHas(staff.admins, username)) return 'admin';
  if (_roleListHas(staff.moderators, username)) return 'moderator';
  return null;
}
function hasStaffAccess() { return isModerator(); } // any staff role

async function logAudit(action, target, note='') {
  const entry = {action,target,note,by:CU?.username,at:new Date().toISOString()};
  let log = [];
  try { log = JSON.parse(localStorage.getItem('ftz_audit_log')||'[]'); } catch(e) { console.warn('[Audit] Parse failed:', e); }
  log.unshift(entry);
  localStorage.setItem('ftz_audit_log', JSON.stringify(log.slice(0,500)));
  try { await FortizedSocial.adminPushAuditLog(entry); } catch(e) { console.warn('[Audit] Push failed:', e?.message); }
}

// ════════════════════════════════════════════
// TOAST
// ════════════════════════════════════════════
let _lastToast = { key: '', at: 0, el: null, count: 0 };
function toast(msg, type='info') {
  const container = document.getElementById('toast-container') || (() => {
    const c = document.createElement('div');
    c.id = 'toast-container';
    c.style.cssText = 'position:fixed;bottom:80px;right:20px;z-index:var(--z-toast,6000);display:flex;flex-direction:column-reverse;gap:8px;pointer-events:none;';
    document.body.appendChild(c);
    return c;
  })();
  const key = (type||'info') + '|' + (typeof msg === 'string' ? msg : '');
  const now = Date.now();
  // Dedupe: same toast within 2.5s updates a counter on the existing toast instead of stacking
  if (_lastToast.key === key && now - _lastToast.at < 2500 && _lastToast.el && _lastToast.el.isConnected) {
    _lastToast.count += 1;
    _lastToast.at = now;
    const badge = _lastToast.el.querySelector('.ftz-toast-count');
    if (badge) badge.textContent = '×' + (_lastToast.count + 1);
    else _lastToast.el.insertAdjacentHTML('beforeend', '<span class="ftz-toast-count" style="margin-left:6px;opacity:.6;font-size:11px;font-weight:700;">×2</span>');
    return;
  }
  const el = document.createElement('div');
  const icons = {success:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M20 6L9 17l-5-5"/></svg>',error:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>',info:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>',warning:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>'};
  el.className = 'ftz-toast ' + (type || 'info');
  el.style.setProperty('--toast-duration', '3s');
  el.innerHTML = `<span style="flex-shrink:0;display:flex;">${icons[type]||icons.info}</span><span>${typeof msg==='string'?msg.replace(/</g,'&lt;'):msg}</span>`;
  container.appendChild(el);
  _lastToast = { key, at: now, el, count: 0 };
  setTimeout(() => el.remove(), 3500);
}

// ════════════════════════════════════════════
// SOFT REFRESH + NAV KEYBINDS
// ════════════════════════════════════════════
// Soft refresh: re-render current view without full page reload
function _ftzSoftRefresh() {
  if (_currentView === 'home') { try { renderHomePanel(); } catch(e) { console.warn('[Refresh] Home failed:', e?.message); } }
  else if (_currentView === 'dms' || _currentView === 'friends') { try { showDMFriendsHome(); } catch(e) { console.warn('[Refresh] DMs failed:', e?.message); } }
  else if (_currentView === 'discover') { try { renderDiscoverGrid(); } catch(e) { console.warn('[Refresh] Discover failed:', e?.message); } }
  else if (_currentView === 'atelier') { try { refreshCU().then(()=>{ switchAtelierTab(_atelierTab||'overview'); }).catch(()=>{ switchAtelierTab(_atelierTab||'overview'); }); } catch(e) { console.warn('[Refresh] Atelier failed:', e?.message); } }
  else if (_currentView === 'bastion' && curBastion !== null) {
    try { if (curChannel === 'overview') renderOverviewRoom(); else if (curChannel !== null) selectChannel(curChannel); } catch(e) { console.warn('[Refresh] Bastion failed:', e?.message); }
  }
  // Spin the refresh icon
  const btn = document.getElementById('tb-nav-refresh');
  if (btn) { btn.classList.add('spinning'); setTimeout(() => btn.classList.remove('spinning'), 600); }
}

// Keybinds: Alt+← (back), Alt+→ (forward), Ctrl+R (soft refresh)
document.addEventListener('keydown', function(e) {
  // Skip keyboard shortcuts if user is typing in an input/textarea
  const tag = document.activeElement?.tagName;
  const isTyping = tag === 'INPUT' || tag === 'TEXTAREA' || document.activeElement?.isContentEditable;

  // Alt+ArrowLeft = Back
  if (e.altKey && e.key === 'ArrowLeft') { e.preventDefault(); history.back(); return; }
  // Alt+ArrowRight = Forward
  if (e.altKey && e.key === 'ArrowRight') { e.preventDefault(); history.forward(); return; }
  // Ctrl+R = Full page reload
  if (e.ctrlKey && !e.shiftKey && e.key === 'r') { e.preventDefault(); location.reload(); return; }

  // ── Up arrow in empty chat input = edit last message ──
  if (isTyping && e.key === 'ArrowUp') {
    const ta = document.activeElement;
    if (ta && (ta.tagName === 'TEXTAREA' || ta.tagName === 'INPUT') && !ta.value.trim()) {
      const container = ta.closest('.chat-input-outer')?.parentElement;
      if (container) {
        const msgsEl = container.querySelector('.chat-msgs,[id^="ch-msgs-"],[id="dm-msgs"],[id="gc-msgs"]');
        if (msgsEl) {
          const rows = msgsEl.querySelectorAll('.msg-row[data-from="'+CSS.escape(CU.username)+'"]');
          if (rows.length) { e.preventDefault(); editMsg(rows[rows.length-1].dataset.msgid); return; }
        }
      }
    }
  }

  // ── Quick Navigation Shortcuts (only when not typing) ──
  if (isTyping) return;

  // Ctrl+K / Cmd+K = Open advanced search (the topbar input is readonly and
  // just opens the modal on click — the shortcut should match that behavior
  // rather than focusing an input that does nothing).
  if ((e.ctrlKey || e.metaKey) && (e.key === 'k' || e.key === 'K')) {
    e.preventDefault();
    if (typeof openAdvancedSearch === 'function') openAdvancedSearch();
    return;
  }
  // Ctrl+Shift+M = Go to Messages/DMs
  if (e.ctrlKey && e.shiftKey && e.key === 'M') { e.preventDefault(); showView('dms'); return; }
  // Ctrl+Shift+H = Go to Home
  if (e.ctrlKey && e.shiftKey && e.key === 'H') { e.preventDefault(); showView('home'); return; }
  // Ctrl+Shift+D = Go to Discover
  if (e.ctrlKey && e.shiftKey && e.key === 'D') { e.preventDefault(); showView('discover'); return; }
  // Ctrl+Shift+A = Go to Atelier (profile/settings)
  if (e.ctrlKey && e.shiftKey && e.key === 'A') { e.preventDefault(); showView('atelier'); return; }
});

// ════════════════════════════════════════════
// VIEW MANAGEMENT + CLIENT-SIDE ROUTING
// ════════════════════════════════════════════
let _currentView = 'home';

// ── Subpage Router ──
// Maps URL paths to views:
//   /app/           → home
//   /app/messages   → dms (DMs + friends)
//   /app/discover   → discover
//   /app/atelier    → atelier
//   /app/bastion?[bastionGlobalId]/[channelIdx] → bastion
const _ftzRouter = {
  // Path → view name mapping
  routes: {
    '/app':          'home',
    '/app/':         'home',
    '/app/messages': 'dms',
    '/app/discover': 'discover',
    '/app/atelier':  'atelier',
    '/app/bastion':  'bastion',
    '/app/forum':    'forum',
  },
  // View → path mapping (reverse)
  paths: {
    'home':     '/app/',
    'dms':      '/app/messages',
    'friends':  '/app/messages',
    'discover': '/app/discover',
    'atelier':  '/app/atelier',
    'bastion':  '/app/bastion',
    'forum':    '/app/forum',
  },
  // Parse current URL to determine view + params
  parseRoute: function() {
    const path = window.location.pathname.replace(/\/+$/, '') || '/app';
    const search = window.location.search;
    // Vanity URL: /b/:slug → bastion lookup
    const vanityMatch = path.match(/^\/b\/([a-zA-Z0-9_-]+)$/);
    if (vanityMatch) {
      return { view: 'bastion', vanity: vanityMatch[1], bastionId: null, roomId: null };
    }
    const view = this.routes[path] || this.routes[path + '/'] || 'home';
    let bastionId = null, roomId = null, dmTarget = null;
    if (view === 'bastion' && search) {
      // Format: /app/bastion?[bastionGlobalId]/[roomIdx]
      const raw = search.substring(1); // strip leading ?
      const parts = raw.split('/');
      bastionId = decodeURIComponent(parts[0] || '');
      roomId = parts[1] ? decodeURIComponent(parts[1]) : null;
    }
    if (view === 'dms' && search) {
      // Format: /app/messages?u=<username>
      try {
        const u = new URLSearchParams(search).get('u');
        if (u) dmTarget = decodeURIComponent(u).toLowerCase();
      } catch(_) {}
    }
    return { view, bastionId, roomId, dmTarget };
  },
  // Push a new URL without reloading
  pushState: function(view, params) {
    let url = this.paths[view] || '/app/';
    if (view === 'bastion' && params?.bastionId) {
      url = '/app/bastion?' + encodeURIComponent(params.bastionId);
      if (params.roomId != null) url += '/' + encodeURIComponent(params.roomId);
    }
    if (view === 'dms' && params?.dmTarget) {
      url = '/app/messages?u=' + encodeURIComponent(params.dmTarget);
    }
    if (window.location.pathname + window.location.search !== url) {
      history.pushState({ view, params: params || {} }, '', url);
    }
  },
  // Replace current URL (for initial load, no history entry)
  replaceState: function(view, params) {
    let url = this.paths[view] || '/app/';
    if (view === 'bastion' && params?.bastionId) {
      url = '/app/bastion?' + encodeURIComponent(params.bastionId);
      if (params.roomId != null) url += '/' + encodeURIComponent(params.roomId);
    }
    if (view === 'dms' && params?.dmTarget) {
      url = '/app/messages?u=' + encodeURIComponent(params.dmTarget);
    }
    history.replaceState({ view, params: params || {} }, '', url);
  },
  // Navigate to initial view based on URL or _initialView (called after init)
  applyInitialRoute: async function() {
    const parsed = this.parseRoute();
    const { view: urlView, vanity, roomId, dmTarget } = parsed;
    let { bastionId } = parsed;
    // Vanity URL resolution: look up bastion by vanity slug
    if (vanity) {
      try {
        const all = await FortizedSocial.getGlobalBastions();
        const match = (all || []).find(b => (b.vanity || '').toLowerCase() === vanity.toLowerCase());
        if (match) bastionId = match.globalId;
      } catch(_){}
      if (!bastionId) { showView('home'); return; }
    }
    // Use _initialView from the subpage HTML if the URL is just /app/ or /app
    const view = (urlView === 'home' && window._initialView && window._initialView !== 'home') ? window._initialView : urlView;
    if (view === 'bastion' && bastionId) {
      // Find bastion by globalId and open it
      const idx = (CU.bastions || []).findIndex(b => b.globalId === bastionId);
      if (idx >= 0) {
        openBastion(idx);
        if (roomId != null) {
          const chIdx = parseInt(roomId);
          if (!isNaN(chIdx) && chIdx >= 0) {
            requestAnimationFrame(() => selectChannel(chIdx));
          } else if (roomId === 'overview') {
            requestAnimationFrame(() => openOverviewRoom());
          }
        }
        return;
      }
      // Bastion not found — fall through to home
    }
    if (view === 'dms' || view === 'friends') {
      // If the URL carries a ?u=<username> (from a prior session / reload),
      // open that DM instead of the friends home.
      if (dmTarget && view === 'dms') {
        showView('dms');
        // Defer so view-dms is mounted before openDMView inserts into dm-chat-wrap.
        setTimeout(() => { try { openDMView(dmTarget); } catch(e) { console.warn('[Route] openDM failed:', e?.message); } }, 0);
        return;
      }
      showView('dms');
      return;
    }
    if (view === 'discover' || view === 'atelier' || view === 'forum') {
      showView(view);
      return;
    }
    showView('home');
  }
};

// Handle browser back/forward
window.addEventListener('popstate', function(e) {
  const state = e.state;
  if (!state || !state.view) {
    // No state — parse from URL
    const { view, bastionId, roomId, dmTarget } = _ftzRouter.parseRoute();
    if (view === 'bastion' && bastionId) {
      const idx = (CU.bastions || []).findIndex(b => b.globalId === bastionId);
      if (idx >= 0) { openBastion(idx); return; }
    }
    if (view === 'dms' && dmTarget) {
      showView('dms', true);
      setTimeout(() => { try { openDMView(dmTarget); } catch(_){} }, 0);
      return;
    }
    showView(view || 'home', true);
    return;
  }
  if (state.view === 'bastion' && state.params?.bastionId) {
    const idx = (CU.bastions || []).findIndex(b => b.globalId === state.params.bastionId);
    if (idx >= 0) {
      openBastion(idx);
      if (state.params.roomId != null) {
        const chIdx = parseInt(state.params.roomId);
        if (!isNaN(chIdx)) requestAnimationFrame(() => selectChannel(chIdx));
        else if (state.params.roomId === 'overview') requestAnimationFrame(() => openOverviewRoom());
      }
      return;
    }
  }
  if (state.view === 'dms' && state.params?.dmTarget) {
    showView('dms', true);
    setTimeout(() => { try { openDMView(state.params.dmTarget); } catch(_){} }, 0);
    return;
  }
  showView(state.view || 'home', true);
});
function showView(v, _skipPush) {
  // ── Settings & bastion settings open as modals over the current page ──
  if (v === 'profile') {
    closeModal('modal-bsettings'); // close other if open
    openModal('modal-settings');
    _settingsOriginal = CU ? structuredClone({displayName:CU.displayName,bio:CU.bio,email:CU.email,password:CU.password,pfp:CU.pfp,banner:CU.banner,socials:CU.socials,notifSettings:CU.notifSettings,pronouns:CU.pronouns,profileTheme:CU.profileTheme}) : null;
    clearSettingsDirty();
    buildProfileNav(document.getElementById('profile-nav'));
    buildProfileView('myprofile');
    return;
  }
  if (v === 'bsettings') {
    closeModal('modal-settings'); // close other if open
    openModal('modal-bsettings');
    return;
  }

  // Close settings/bsettings modals when navigating to a normal view
  closeModal('modal-settings');
  closeModal('modal-bsettings');
  clearSettingsDirty();

  _currentView = v;
  // Update URL (skip for bastion — openBastion handles that)
  if (!_skipPush && v !== 'bastion' && typeof _ftzRouter !== 'undefined') {
    // For DMs, carry the currently-open target into the URL so the in-flight
    // navigation doesn't strip ?u=<username> and leave a naked /app/messages
    // history entry between two DM switches.
    const routeParams = (v === 'dms' && typeof curDM === 'string' && curDM) ? { dmTarget: curDM } : undefined;
    if (_ftzRouter._initialLoad) _ftzRouter.replaceState(v, routeParams);
    else _ftzRouter.pushState(v, routeParams);
  }
  // Close mobile sidebars on navigation
  if (typeof closeMobileSidebar === 'function') closeMobileSidebar();
  // Sync mobile tab bar
  setTimeout(() => { try { _syncMobileTabBar(); } catch (e) { _dbg('[Mobile] tab bar sync failed', e); } }, 50);
  const _mtb = document.getElementById('mobile-tab-bar');
  if (_mtb) _mtb.style.display = '';
  // Stop admin polling when leaving admin view
  if (v !== 'admin' && _reportPollInterval) { clearInterval(_reportPollInterval); _reportPollInterval = null; }
  // Leave chat subscriptions when navigating away from their views
  if (v !== 'dms') { _leaveActiveDM(); _leaveActiveGC(); }
  if (v !== 'bastion') { _leaveActiveChannel(); }
  // Stop Joyster bubbles when leaving home — Joyster only lives on the homepage
  if (v !== 'home' && typeof _stopJoysterBubbles === 'function') _stopJoysterBubbles();
  // Clean up GC panel when leaving DMs view
  if (v !== 'dms') document.getElementById('gc-member-panel')?.remove();

  // Restore sidebar if it was hidden (e.g. after profile view)
  const _sb = document.querySelector('.sidebar');
  if (_sb) _sb.style.display = '';

  // Hide ALL views explicitly (override any inline display styles)
  document.querySelectorAll('.view').forEach(el => {
    el.style.display = 'none';
    el.classList.remove('active');
  });

  // Show only the target view
  const vEl = document.getElementById('view-' + v);
  if (vEl) {
    vEl.style.display = 'flex';
    vEl.classList.add('active');
    // Smooth fade + slide in
    vEl.style.opacity = '0';
    vEl.style.transform = 'translateY(4px)';
    requestAnimationFrame(() => {
      vEl.style.transition = 'opacity .22s cubic-bezier(.22,1,.36,1), transform .22s cubic-bezier(.22,1,.36,1)';
      vEl.style.opacity = '1';
      vEl.style.transform = 'translateY(0)';
      setTimeout(() => { vEl.style.transition = ''; vEl.style.transform = ''; }, 260);
    });
  }

  // Nav active state
  document.querySelectorAll('.rail-btn').forEach(el => el.classList.remove('active'));
  document.querySelectorAll('.rail-bastion').forEach(el => el.classList.remove('active'));
  // (home btn is now a rail-btn, handled by the loop above)
  const rBtn = document.getElementById('rb-' + v);
  if (rBtn) rBtn.classList.add('active');

  // Post-show callbacks
  if (v === 'atelier') {
    const target = window._atelierPendingTab || 'radiance';
    window._atelierPendingTab = null;
    _atelierTab = target;
    renderAtelierTab(target);
    setTimeout(() => {
      const _go = () => { switchAtelierTab(target); refreshDailyBtn(); };
      refreshCU().then(_go).catch(_go);
    }, 0);
  }
  if (v === 'home') setTimeout(() => renderHomePanel(), 0);
  if (v === 'discover') setTimeout(() => loadDiscover(), 0);
  if (v === 'friends') setTimeout(() => renderFriendsList('all'), 0);
  if (v === 'forum') setTimeout(() => _forumInit(), 0);
  if (v === 'dms' && !curDM && !curGC) setTimeout(() => { showDMFriendsHome(); }, 50);

  updateTopbar(v);
  updateSidebar(v);
}

function updateTopbar(v) {
  const title = document.getElementById('topbar-title');
  const desc = document.getElementById('tb-desc');
  const sep = document.getElementById('tb-sep');
  const acts = document.getElementById('tb-actions');
  if (!title) return;
  if (sep) sep.style.display = 'none';
  if (desc) desc.textContent = '';
  if (acts) acts.innerHTML = '';
  const labels = {home:'Home',dms:'Direct Messages',friends:'Direct Messages',discover:'Discover',atelier:'Atelier',profile:'Settings',bsettings:'Bastion Settings',bhub:'Overview',forum:'Forum'};
  if (v === 'bastion') {
    const b = CU?.bastions?.[curBastion];
    title.textContent = b?.name || 'Bastion';
  } else if (labels[v]) title.textContent = labels[v];
  // Update document title for subpage (Discord-style: Fortized | Page)
  const docTitles = {home:null,dms:'Friends',friends:'Friends',discover:'Discover',atelier:'Atelier',profile:'Settings',bsettings:'Bastion Settings',bhub:'Overview'};
  if (v === 'bastion') {
    _updateBastionTitle();
  } else {
    document.title = docTitles[v] ? 'Fortized | ' + docTitles[v] : 'Fortized';
  }
  // On mobile, add member list toggle for bastion views
  if (_isMobile() && v === 'bastion' && acts) {
    acts.insertAdjacentHTML('beforeend', '<button class="tb-act-btn" title="Members" onclick="toggleMobileMemberPanel()" style="position:relative;"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/></svg></button>');
  }
  // Show/hide staff console button in topbar
  const adminBtn = document.getElementById('tb-admin-btn');
  if (adminBtn) adminBtn.style.display = hasStaffAccess() ? 'flex' : 'none';
  updateOnyxDisplay();
}
// Update document title for bastion view: Fortized | #room | Bastion Name
function _updateBastionTitle() {
  const b = CU?.bastions?.[curBastion];
  if (!b) { document.title = 'Fortized'; return; }
  const bName = b.name || 'Bastion';
  const tbTitle = document.getElementById('topbar-title');
  if (tbTitle) tbTitle.textContent = bName;
  if (curChannel === 'overview' || curChannel === null) {
    document.title = 'Fortized | ' + bName;
  } else {
    const ch = b.channels?.[curChannel];
    const chName = ch?.name || 'channel';
    document.title = 'Fortized | #' + chName + ' | ' + bName;
  }
}
