function renderAtelierSidebar(scroll) {
  if (!scroll) return;
  // Show Direct Messages sidebar instead of Atelier navigation
  renderDMSidebar(scroll);
}
function _defaultPfpUrl(name) {
  // Deterministic random based on name — always same for same user
  const hash = (name||'').split('').reduce((a,c) => a + c.charCodeAt(0), 0);
  return hash % 2 === 0 ? '/default%20pfp.png' : '/default%20pfp2.png';
}
function buildAvatarHTML(pfp, name, size, cropData) {
  const s = 'width:'+size+'px;height:'+size+'px;border-radius:50%;object-fit:cover;display:block;flex-shrink:0;';
  const defaultUrl = _defaultPfpUrl(name);
  const initial = (name||'?')[0].toUpperCase();
  const fs = Math.floor(size/2.2);
  const fallbackJS = 'this.onerror=null;this.style.display=\'none\';const sp=document.createElement(\'span\');sp.textContent=\''+initial+'\';sp.style.cssText=\'display:flex;align-items:center;justify-content:center;width:'+size+'px;height:'+size+'px;border-radius:50%;font-size:'+fs+'px;background:var(--panel2,#1a1c2e);color:rgba(255,255,255,.6);font-family:var(--font-display);font-weight:800;flex-shrink:0;\';this.parentElement.insertBefore(sp,this)';
  // GIF avatar with CSS-based crop (preserves animation)
  if (pfp && cropData && cropData.widthPct) {
    return '<div style="width:'+size+'px;height:'+size+'px;border-radius:50%;overflow:hidden;position:relative;flex-shrink:0;display:block;">'
      + '<img src="'+pfp+'" style="position:absolute;left:'+cropData.leftPct+'%;top:'+cropData.topPct+'%;width:'+cropData.widthPct+'%;height:auto;" onerror="'+fallbackJS+'">'
      + '</div>';
  }
  if (pfp) return '<img src="'+pfp+'" style="'+s+'" onerror="'+fallbackJS+'">';
  return '<img src="'+defaultUrl+'" style="'+s+'" onerror="'+fallbackJS+'">';
}
function renderRailBastions() {
  const cont = document.getElementById('rail-bastions');
  if (!cont) return;
  // Load user's bastion order + groups
  const orderKey = 'ftz_bastion_order';
  const groupKey = 'ftz_bastion_groups';
  let order = [];
  let groups = {};
  try { order = JSON.parse(localStorage.getItem(orderKey)||'[]'); } catch (e) { _dbg('[Sidebar] order parse failed', e); }
  try { groups = JSON.parse(localStorage.getItem(groupKey)||'{}'); } catch (e) { _dbg('[Sidebar] groups parse failed', e); }

  const bastions = CU?.bastions||[];
  // Build ordered list: user order first, then any new bastions
  let orderedIdxs = [];
  order.forEach(id => {
    const idx = bastions.findIndex(b => (b.globalId||b.name) === id);
    if (idx >= 0 && !orderedIdxs.includes(idx)) orderedIdxs.push(idx);
  });
  bastions.forEach((b,i) => { if (!orderedIdxs.includes(i)) orderedIdxs.push(i); });

  // Render grouped and ungrouped bastions
  const renderedInGroup = new Set();
  let html = '';

  // Render groups
  Object.entries(groups).forEach(([gName, gIds]) => {
    const groupBastions = gIds.map(id => {
      const idx = bastions.findIndex(b => (b.globalId||b.name) === id);
      return idx >= 0 ? idx : -1;
    }).filter(i => i >= 0);
    if (!groupBastions.length) return;
    groupBastions.forEach(i => renderedInGroup.add(i));
    html += `<div class="bastion-group" data-group="${escapeHTML(gName)}">
      <div class="bastion-group-header" onclick="_toggleBastionGroup(this)">
        <span style="font-size:7px;transition:transform .2s;">▼</span> ${escapeHTML(gName)}
      </div>`;
    groupBastions.forEach(i => {
      const b = bastions[i];
      html += _renderRailBastion(b, i);
    });
    html += '</div>';
  });

  // Render ungrouped bastions
  orderedIdxs.forEach(i => {
    if (renderedInGroup.has(i)) return;
    html += _renderRailBastion(bastions[i], i);
  });

  cont.innerHTML = html;
  _initBastionDrag();
  _initRailTooltips();
  _initRailNavTooltips();
  _initGlobalTooltips();
}

function _renderRailBastion(b, i) {
  return `<div class="rail-bastion ${curBastion===i?'active':''}" id="rl-b-${i}"
    draggable="true" data-bastion-idx="${i}" data-bastion-id="${escapeHTML(b.globalId||b.name)}"
    onclick="openBastion(${i})"
    oncontextmenu="event.preventDefault();showRailBastionCtx(event,${i})"
    data-rail-tip="${escapeHTML(b.name)}" data-rail-icon="${escapeHTML(b.icon||'')}" data-rail-emblem="" data-rail-verified="${b.verified?'1':''}"
    style="margin-bottom:4px;">
    <div class="bastion-icon">${b.icon
      ? (b.icon.toLowerCase().endsWith('.gif') ? `<img src="${b.icon}" class="gif-emblem" onload="_freezeGifEmblem(this)">` : `<img src="${b.icon}">`)
      : `<span style="font-family:var(--font-display);font-weight:800;font-size:18px;color:var(--accent);">${(b.name||'B')[0].toUpperCase()}</span>`}</div>
  </div>`;
}

// Freeze GIF emblem: render first frame to a canvas, show canvas by default, GIF on hover (via CSS)
function _freezeGifEmblem(img) {
  try {
    const c = document.createElement('canvas');
    c.width = img.naturalWidth || 48;
    c.height = img.naturalHeight || 48;
    c.className = 'gif-still';
    c.style.width = '100%';
    c.style.height = '100%';
    c.style.objectFit = 'cover';
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0, c.width, c.height);
    img.parentElement.insertBefore(c, img);
  } catch(e) { /* cross-origin or other error — just show the GIF */ }
}

function _initBastionDrag() {
  const cont = document.getElementById('rail-bastions');
  if (!cont) return;
  let dragEl = null;
  cont.querySelectorAll('.rail-bastion[draggable]').forEach(el => {
    el.addEventListener('dragstart', e => {
      dragEl = el;
      el.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', el.dataset.bastionIdx);
    });
    el.addEventListener('dragend', () => {
      el.classList.remove('dragging');
      cont.querySelectorAll('.rail-bastion').forEach(b => b.classList.remove('drag-over'));
      dragEl = null;
      _saveBastionOrder();
    });
    el.addEventListener('dragover', e => {
      e.preventDefault();
      if (dragEl && dragEl !== el) {
        el.classList.add('drag-over');
      }
    });
    el.addEventListener('dragleave', () => el.classList.remove('drag-over'));
    el.addEventListener('drop', e => {
      e.preventDefault();
      el.classList.remove('drag-over');
      if (dragEl && dragEl !== el) {
        const parent = el.parentNode;
        const allItems = [...parent.querySelectorAll('.rail-bastion')];
        const fromIdx = allItems.indexOf(dragEl);
        const toIdx = allItems.indexOf(el);
        if (fromIdx < toIdx) {
          el.parentNode.insertBefore(dragEl, el.nextSibling);
        } else {
          el.parentNode.insertBefore(dragEl, el);
        }
      }
    });
  });
}

function _saveBastionOrder() {
  const cont = document.getElementById('rail-bastions');
  if (!cont) return;
  const order = [...cont.querySelectorAll('.rail-bastion[data-bastion-id]')].map(el => el.dataset.bastionId);
  localStorage.setItem('ftz_bastion_order', JSON.stringify(order));
}

// Custom tooltip for rail bastions (Discord-style)
let _railTipEl = null;
function _initRailTooltips() {
  const cont = document.getElementById('rail-bastions');
  if (!cont) return;
  cont.querySelectorAll('.rail-bastion[data-rail-tip]').forEach(el => {
    el.addEventListener('mouseenter', _showRailTip);
    el.addEventListener('mouseleave', _hideRailTip);
  });
}
function _showRailTip(e) {
  const el = e.currentTarget;
  const name = el.dataset.railTip;
  const icon = el.dataset.railIcon;
  const emblem = el.dataset.railEmblem || '';
  const verified = el.dataset.railVerified === '1';
  if (!name) return;
  _hideRailTip();
  const tip = document.createElement('div');
  tip.className = 'rail-tooltip';
  const iconHtml = icon
    ? `<div class="rail-tooltip-icon"><img src="${icon}"></div>`
    : `<div class="rail-tooltip-icon"><span style="font-family:var(--font-display);font-weight:800;color:var(--accent);">${name ? name[0].toUpperCase() : 'B'}</span></div>`;
  tip.innerHTML = iconHtml + `<span>${escapeHTML(name)}${verified?_verifiedBadge(14):''}</span>`;
  document.body.appendChild(tip);
  _railTipEl = tip;
  const rect = el.getBoundingClientRect();
  tip.style.left = (rect.right + 12) + 'px';
  tip.style.top = (rect.top + rect.height / 2) + 'px';
  tip.style.transform = 'translateY(-50%) scale(.92)';
  requestAnimationFrame(() => {
    tip.classList.add('visible');
    tip.style.transform = 'translateY(-50%) scale(1)';
  });
}
function _hideRailTip() {
  if (_railTipEl) { _railTipEl.remove(); _railTipEl = null; }
}

