// HOME PANEL
// ════════════════════════════════════════════
function renderHomePanel() {
  // Pull fresh CU in the background so subsequent re-renders show latest data
  try { if (typeof refreshCU === 'function') refreshCU().then(() => { try { _renderHomeFriendsToday(); _renderWhatArePeopleBuying(); _renderWhatsHappening(); renderActiveNowSidebar('home-active-now-list'); } catch(_){} }).catch(()=>{}); } catch(_){}
  // Eagerly clear stale section containers so old data isn't shown while async re-renders
  ['home-friends-today','home-trending-items','home-trending-forum','home-active-now-list'].forEach(id => {
    const _el = document.getElementById(id);
    if (_el) _el.innerHTML = '<div style="padding:10px;text-align:center;"><div class="pl-spinner" style="width:16px;height:16px;border-width:2px;margin:0 auto;"></div></div>';
  });
  // Hero username
  const heroName = document.getElementById('hero-username');
  if (heroName) heroName.textContent = CU?.displayName || CU?.username || '';

  // Initialize hero particles & floating items
  _initHeroEffects();

  // Start Joyster idle speech bubbles. We no longer prefetch AI lines —
  // burns the free Gemini quota for nothing when most bubbles use the
  // hardcoded quips fallback anyway.
  _startJoysterBubbles();

  // DYK strip with rotating content
  const dykEl = document.getElementById('home-dyk-strip');
  if (dykEl) {
    dykEl.innerHTML = getDYKHtml();
    // Auto-rotate DYK every 10s
    if (!window._dykRotateTimer) {
      window._dykRotateTimer = setInterval(() => {
        const el = document.getElementById('home-dyk-strip');
        if (el && el.offsetParent) { el.style.opacity = '0'; el.style.transition = 'opacity .3s'; setTimeout(() => { el.innerHTML = getDYKHtml(); el.style.opacity = '1'; }, 300); }
      }, 10000);
    }
  }

  // Realm data
  const bastions = CU?.bastions||[];
  const friends0 = CU?.friends||[];

  // ── Micro-status strip (live stats under hero) ──
  const _hss = document.getElementById('hero-status-strip');
  if (_hss) {
    const onlineFriends = friends0.length; // will be updated async
    const activeBastions = bastions.length;
    _hss.innerHTML = `<span class="hss-item"><span class="hss-dot" style="background:#3ecf6e;box-shadow:0 0 6px rgba(62,207,110,.4);"></span><span id="hss-online">0</span> friends online</span>
      <span class="hss-sep"></span>
      <span class="hss-item"><span class="hss-dot" style="background:#a78bfa;"></span>${activeBastions} bastion${activeBastions!==1?'s':''}</span>`;
    // Async update online count
    if (friends0.length) {
      FortizedSocial.queryPresence(friends0).then(p => {
        if (!p) return;
        const online = Object.values(p).filter(v => v.status === 'online' || v.status === 'away' || v.status === 'dnd').length;
        const el = document.getElementById('hss-online');
        if (el) el.textContent = online;
      }).catch(()=>{});
    }
  }

  // Quick action strip removed — keeping it clean
  const _qas = document.getElementById('home-quick-actions');
  if (_qas) _qas.innerHTML = '';

  // Realm Bastions — horizontal scroll cards
  const realmB = document.getElementById('realm-bastions');
  if (realmB) {
    if (bastions.length) {
      realmB.innerHTML = bastions.slice(0,10).map((b,i)=>`
        <div class="realm-card" onclick="openBastion(${i})">
          <div class="rc-glow"></div>
          <div class="rc-emblem">${b.icon ? `<img src="${b.icon}">` : (b.emblem||'🏰')}</div>
          <div class="rc-name">${escapeHTML(b.name)}</div>
          <div class="rc-meta">${(b.channels||[]).length} channels</div>
        </div>`).join('') + `
        <div class="realm-card" onclick="openModal('modal-create-bastion')" style="border-style:dashed;border-color:rgba(255,249,62,.12);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;min-height:120px;">
          <div style="font-size:24px;margin-bottom:8px;opacity:.4;">+</div>
          <div class="rc-name" style="color:var(--accent);opacity:.7;">Create Bastion</div>
        </div>`;
    } else {
      realmB.innerHTML = `
        <div class="realm-card" onclick="openModal('modal-create-bastion')" style="border-style:dashed;border-color:rgba(255,249,62,.12);min-width:260px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:28px;">
          <div style="font-size:28px;margin-bottom:10px;color:var(--accent);">${ftzIcon('castle','28')}</div>
          <div class="rc-name" style="color:var(--accent);">Create Your First Bastion</div>
          <div class="rc-meta">Build your fortress, invite your allies</div>
        </div>
        <div class="realm-card" onclick="showView('discover')" style="min-width:220px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:28px;">
          <div style="font-size:28px;margin-bottom:10px;">🧭</div>
          <div class="rc-name">Discover Bastions</div>
          <div class="rc-meta">Explore and join communities</div>
        </div>`;
    }
  }

  // Render home ads (with placeholder fallback when empty)
  _renderHomeAds();

  // Friends online today (main column — no cards, just chips)
  setTimeout(_renderHomeFriendsToday, 100);

  // What are people buying (rectangular card with 6 item cards)
  setTimeout(_renderWhatArePeopleBuying, 140);

  // What's happening (top 4 forum posts by score + recency)
  setTimeout(_renderWhatsHappening, 170);

  // Populate feedback user header & bind shine
  setTimeout(_renderFeedbackUser, 200);

  // Keep the legacy Active Now right sidebar as-is
  setTimeout(() => renderActiveNowSidebar('home-active-now-list'), 220);

  // Check for new announcements once on landing. Subsequent in-app navs
  // don't re-trigger the modal — only a real page refresh does.
  setTimeout(_checkForAnnouncements, 500);
}

// ── Feedback: "A place where…" + regular ──
function _renderFeedbackUser() {
  const el = document.getElementById('home-fb-user');
  if (!el || !CU) return;
  const pfp = CU.pfp || _defaultPfpUrl(CU.username);
  el.innerHTML = `<img class="home-fb-pfp" src="${escapeHTML(pfp)}" onerror="this.src='${_defaultPfpUrl(CU.username)}'">
    <span class="home-fb-name">${escapeHTML(CU.displayName||CU.username)} <span class="home-fb-handle">@${escapeHTML(CU.username)}</span></span>`;
}
async function submitPlaceFeedback() {
  const inp = document.getElementById('home-fb-place-input');
  const anonEl = document.getElementById('home-fb-anon');
  if (!inp) return;
  const text = (inp.value||'').trim();
  if (!text) { toast('Finish the sentence first', 'error'); return; }
  if (text.length < 3) { toast('A bit longer, please', 'error'); return; }
  const anon = !!(anonEl && anonEl.checked);
  const entry = {
    id: 'pf_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
    kind: 'place_where',
    text: 'A place where ' + text,
    sentence: text,
    anonymous: anon,
    username: anon ? null : (CU?.username || null),
    displayName: anon ? null : (CU?.displayName || CU?.username || null),
    pfp: anon ? null : (CU?.pfp || null),
    at: Date.now(),
    status: 'open',
  };
  try {
    if (typeof FortizedSocial.submitPlaceFeedback === 'function') {
      await FortizedSocial.submitPlaceFeedback(entry);
    } else {
      // Fallback: stash in localStorage queue that admins can see
      const q = JSON.parse(localStorage.getItem('ftz_place_feedback_queue')||'[]');
      q.push(entry);
      localStorage.setItem('ftz_place_feedback_queue', JSON.stringify(q));
    }
    inp.value = '';
    toast('Thanks — sent to Fortized!', 'success');
  } catch(e) {
    console.warn('[Feedback] Place submit failed', e);
    toast('Send failed', 'error');
  }
}
async function submitRegularFeedback() {
  const ta = document.getElementById('home-fb-regular-text');
  const sel = document.getElementById('home-fb-regular-cat');
  if (!ta) return;
  const text = (ta.value||'').trim();
  if (!text) { toast('Write something first', 'error'); return; }
  const category = sel?.value || 'other';
  try {
    if (typeof FortizedSocial.adminSubmitSupportTicket === 'function') {
      await FortizedSocial.adminSubmitSupportTicket({
        id: 'fb_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
        username: CU?.username,
        displayName: CU?.displayName || CU?.username,
        email: CU?.email || null,
        category,
        subject: 'Homepage feedback',
        // The admin ticket list renders `t.message`; keep `body` too so older
        // consumers (and localStorage fallback) don't break.
        message: text,
        body: text,
        status: 'open',
        submittedAt: new Date().toISOString(),
      });
    } else {
      // Fallback: queue for admins
      const q = JSON.parse(localStorage.getItem('ftz_support_tickets_queue')||'[]');
      q.push({ username: CU?.username, category, subject: 'Homepage feedback', message: text, body: text, submittedAt: new Date().toISOString() });
      localStorage.setItem('ftz_support_tickets_queue', JSON.stringify(q));
    }
    ta.value = '';
    toast('Feedback sent!', 'success');
  } catch(e) {
    console.warn('[Feedback] Regular submit failed', e);
    toast('Send failed', 'error');
  }
}

// ── Home Friends today (clean chip row in main column — no cards) ──
async function _renderHomeFriendsToday() {
  const el = document.getElementById('home-friends-today');
  if (!el) return;
  const friends = CU?.friends || [];
  if (!friends.length) {
    el.innerHTML = `<div class="home-empty-strip">
      <div style="font-size:12.5px;color:var(--muted);">No friends yet — add some to see who's around today.</div>
      <button class="btn-a" onclick="openModal('modal-add-friend')" style="font-size:11px;padding:6px 14px;">+ Add Friend</button>
    </div>`;
    return;
  }
  el.innerHTML = '<div class="pl-spinner" style="width:18px;height:18px;border-width:2px;margin:8px 6px;"></div>';
  try {
    const presence = await FortizedSocial.queryPresence(friends);
    const DAY = 24 * 60 * 60 * 1000;
    const cutoff = Date.now() - DAY;
    const active = friends.filter(u => {
      const p = presence?.[u]; if (!p) return false;
      const isUp = p.status === 'online' || p.status === 'away' || p.status === 'dnd';
      const lastSeen = p.lastSeen || p.last_seen || 0;
      return isUp || lastSeen > cutoff;
    }).slice(0, 14);
    if (!active.length) {
      el.innerHTML = `<div class="home-empty-strip" style="font-size:12.5px;color:var(--muted);">Get right back in the action — no friends online today.</div>`;
      return;
    }
    const users = await Promise.all(active.map(u => FortizedSocial.getUserByName(u).catch(() => null)));
    el.innerHTML = active.map((u, i) => {
      const ud = users[i] || {};
      const pfp = ud.pfp || _pfpCache[u] || _defaultPfpUrl(u);
      const dn = ud.displayName || u;
      const status = presence?.[u]?.status || 'offline';
      const statusColor = (typeof FtzStatus !== 'undefined') ? FtzStatus.color(status) : (status==='online'?'#3ecf6e':status==='away'?'#f59e0b':status==='dnd'?'#f87171':'rgba(255,255,255,.15)');
      return `<div class="home-online-chip" onclick="openDMView('${escapeHTML(u)}')" title="${escapeHTML(dn)}">
        <span class="hoc-av-wrap">
          <img class="hoc-av" src="${escapeHTML(pfp)}" onerror="this.src='${_defaultPfpUrl(u)}'">
          <span class="hoc-dot" style="background:${statusColor};"></span>
        </span>
        <span class="hoc-name">${escapeHTML(dn)}</span>
      </div>`;
    }).join('');
  } catch(e) {
    console.warn('[Home] Friends today failed:', e);
    el.innerHTML = `<div class="home-empty-strip" style="font-size:12.5px;color:var(--muted);">Unable to load presence right now.</div>`;
  }
}

// ── What's Happening — top 4 forum posts (boosted upvotes, then recency) ──
async function _renderWhatsHappening() {
  const el = document.getElementById('home-trending-forum');
  if (!el) return;
  el.innerHTML = '<div class="home-whats-card"><div style="padding:14px;color:var(--muted);font-size:12px;">Loading…</div></div>';
  try {
    const categoryIds = (typeof FORUM_CATEGORIES !== 'undefined' && FORUM_CATEGORIES) ? FORUM_CATEGORIES.map(c => c.id) : ['general','bugs','suggestions','showcase','offtopic','announcements','event-records'];
    const all = (await Promise.all(categoryIds.map(c => FortizedSocial.getForumThreads(c, 50, 0).catch(()=>[])))).flat();
    // Priority: I. most upvotes (with staff boost), II. most recent
    const top = [...all].sort((a, b) => {
      const sb = _forumNetScore(b), sa = _forumNetScore(a);
      if (sb !== sa) return sb - sa;
      return (b.updated_at || b.created_at || 0) - (a.updated_at || a.created_at || 0);
    }).slice(0, 4);
    if (!top.length) {
      el.innerHTML = `<div class="home-whats-card"><div class="home-whats-empty">
        <div style="font-size:13px;color:var(--muted);margin-bottom:8px;">No forum activity yet — start the conversation!</div>
        <button class="btn-a" onclick="showView('forum')" style="font-size:11px;padding:6px 14px;">Browse Forum</button>
      </div></div>`;
      return;
    }
    el.innerHTML = `<div class="home-whats-card">` + top.map(t => {
      const cat = (typeof FORUM_CATEGORIES !== 'undefined' && FORUM_CATEGORIES || []).find(c => c.id === t.category) || {name:'', color:'#fff', icon:''};
      const net = _forumNetScore(t);
      return `<div class="home-whats-row" onclick="_homeOpenForumThread('${escapeHTML(t.id)}')">
        <div class="hwr-cat" style="color:${cat.color};background:${cat.color}18;">${cat.icon||'●'} ${escapeHTML(cat.name||'')}</div>
        <div class="hwr-body">
          <div class="hwr-title">${escapeHTML(t.title || '')}</div>
          <div class="hwr-meta">by ${escapeHTML(t.author || 'unknown')} · ${_forumTimeAgo(t.updated_at||t.created_at)}</div>
        </div>
        <div class="hwr-stats">
          <span class="hwr-stat"><span class="hwr-stat-ico">👏</span> ${net.toLocaleString()}</span>
          <span class="hwr-stat hwr-stat-replies">💬 ${t.reply_count||0}</span>
        </div>
      </div>`;
    }).join('') + `</div>`;
  } catch(e) {
    console.warn('[Home] Whats happening failed:', e);
    el.innerHTML = '<div class="home-whats-card"><div style="padding:14px;color:var(--muted);font-size:12px;">Failed to load.</div></div>';
  }
}

// ── What are people buying? — rectangular card, 6 item sub-cards ──
// Priority: I. most bought, II. most recent. Fill to 6 with fakes when real < 6.
function _openFortshop() {
  try {
    window._atelierPendingTab = 'shop';
    showView('atelier');
  } catch(e) { console.warn('[Home] openFortshop failed:', e); }
}


async function _renderWhatArePeopleBuying() {
  const el = document.getElementById('home-trending-items');
  if (!el) return;
  el.innerHTML = `<div class="home-buying-inner"><div class="pl-spinner" style="width:18px;height:18px;border-width:2px;margin:14px;"></div></div>`;
  try {
    // Collect real purchase/item data, prefer most bought then most recent
    let bought = [];
    let recent = [];
    try {
      if (typeof FortizedSocial.getFortshopMostBought === 'function') {
        bought = await FortizedSocial.getFortshopMostBought(6).catch(()=>[]);
      }
      if (typeof FortizedSocial.getFortshopRecent === 'function') {
        recent = await FortizedSocial.getFortshopRecent(12).catch(()=>[]);
      } else if (typeof FortizedSocial.getFortshopItems === 'function') {
        recent = await FortizedSocial.getFortshopItems({ sort: 'recent', limit: 12 }).catch(()=>[]);
      }
    } catch(_) {}
    // Dedupe by id
    const seen = new Set();
    const picks = [];
    const push = (arr) => {
      for (const it of (arr || [])) {
        const id = it?.id || it?.name; if (!id) continue;
        if (seen.has(id)) continue;
        seen.add(id); picks.push(it);
        if (picks.length >= 6) break;
      }
    };
    push(bought); push(recent);
    const realCount = picks.length;
    // Top up with fakes if needed. If 0 real: all fake. Else fill to 6 with fakes.
    if (realCount < 6) {
      const fakes = _fortshopFakeItems(6 - realCount, seen);
      for (const f of fakes) picks.push(f);
    }
    // Hydrate buyer pfps after render
    setTimeout(() => { try { _forumHydratePfps(el); } catch(_){} }, 30);
    const myPfp = (CU?.pfp) || _defaultPfpUrl(CU?.username || 'me');
    const ownedDecos = new Set(CU?.ownedDecorations || []);
    const unlockedApps = new Set(CU?.unlockedAppearances || []);
    el.innerHTML = `<div class="home-buying-inner">` + picks.slice(0, 6).map(it => {
      const name = it.name || 'Item';
      const price = it.price != null ? Number(it.price).toLocaleString() : '—';
      const img = it.thumb || it.image || it.src || '';
      const buyers = Array.isArray(it.buyers) ? it.buyers.slice(0,3) : [];
      const buyersHtml = buyers.length ? `<div class="hbc-pfps">${buyers.map(b => `<img class="hbc-pfp" data-forum-author="${escapeHTML(b)}" src="${escapeHTML(_defaultPfpUrl(b))}" onerror="this.src='${_defaultPfpUrl(b)}'" title="${escapeHTML(b)}">`).join('')}${(it.buyerCount && it.buyerCount > buyers.length) ? `<span class="hbc-pfp-more">+${it.buyerCount - buyers.length}</span>` : ''}</div>` : '';
      const isDeco = it.kind === 'decoration' && (it.decoSrc || it.image || it.thumb);
      const pfpPreview = isDeco ? `<img class="hbc-pfp-preview" src="${escapeHTML(myPfp)}" onerror="this.src='${_defaultPfpUrl(CU?.username || 'me')}'" alt="">` : '';
      const owned = !!(it.id && ((it.kind === 'decoration' && ownedDecos.has(it.id)) || (it.kind !== 'decoration' && unlockedApps.has(it.id))));
      const ownedBadge = owned ? `<span class="hbc-owned" title="You already own this">Owned</span>` : '';
      const cardClass = 'home-buy-card' + (isDeco ? ' has-deco-preview' : '') + (owned ? ' is-owned' : '');
      return `<div class="${cardClass}" onclick="_openFortshop()" title="${escapeHTML(name)}">
        <div class="hbc-img">${pfpPreview}${img ? `<img class="hbc-deco" src="${escapeHTML(img)}" onerror="this.onerror=null;this.style.opacity='0'">` : ''}${ownedBadge}</div>
        <div class="hbc-name">${escapeHTML(name)}</div>
        <div class="hbc-price"><img class="hbc-onyx" src="/Onyx.png" onerror="this.style.display='none'"><span>${price}</span></div>
        ${buyersHtml}
      </div>`;
    }).join('') + `</div>`;
  } catch(e) {
    console.warn('[Home] What buying failed:', e);
    el.innerHTML = `<div class="home-buying-inner"><div class="home-empty-strip" style="font-size:12.5px;color:var(--muted);">Fortshop unavailable.</div></div>`;
  }
}

// Fake items drawn from bundled shop data so they look real; filtered to not duplicate real ids.
function _fortshopFakeItems(n, excludeSet) {
  try {
    const pool = [
      ...(typeof PROFILE_DECORATIONS !== 'undefined' ? PROFILE_DECORATIONS : []),
      ...(typeof SHOP_APPEARANCES_ALL !== 'undefined' ? SHOP_APPEARANCES_ALL : []),
    ];
    const filtered = pool.filter(p => !excludeSet || !excludeSet.has(p.id));
    // Shuffle deterministically based on current day for stable rendering during a session
    const seed = new Date().toDateString();
    const rand = _mulberry32(_strHash(seed));
    for (let i = filtered.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [filtered[i], filtered[j]] = [filtered[j], filtered[i]];
    }
    return filtered.slice(0, n).map(it => {
      const isDeco = !!(typeof PROFILE_DECORATIONS !== 'undefined' && PROFILE_DECORATIONS.find(d => d.id === it.id));
      return {
        id: it.id, name: it.name, price: it.price,
        thumb: it.thumb || it.src || it.previewBg || null,
        image: it.image || it.src || null,
        kind: isDeco ? 'decoration' : (it.kind || 'appearance'),
        decoSrc: isDeco ? (it.src || null) : null,
      };
    });
  } catch(_) {
    // As a last resort, fabricate filler cards
    const filler = ['Stellar Mask','Onyx Cloak','Emberglow Hat','Deep Sea Aura','Sunset Ring','Golden Crown'];
    return filler.slice(0, n).map((name, i) => ({ id: 'filler_'+i, name, price: 100 + i*75 }));
  }
}
function _strHash(s) { let h = 0; for (let i=0;i<s.length;i++) h = (h*31 + s.charCodeAt(i)) | 0; return h >>> 0; }
function _mulberry32(a) {
  return function() {
    let t = a += 0x6D2B79F5;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

// ── Home Ads ──
function _pickWeightedAd(ads, ratioFilter) {
  let pool = ratioFilter ? ads.filter(a => (a.ratio||'banner') === ratioFilter) : ads;
  if (!pool.length) return null;
  const weighted = pool.map(a => {
    const owner = a.owner || '';
    const role = getStaffRole(owner);
    let w = 1;
    if (role === 'superadmin') w = 5;
    else if (role === 'admin') w = 3;
    else if (a.ownerVerified) w = 2;
    const boost = Math.max(0.1, Math.min(10, Number(a.adminBoost) || 1));
    w = w * boost;
    return { ad: a, weight: w };
  });
  const total = weighted.reduce((s, w) => s + w.weight, 0);
  let r = Math.random() * total;
  for (const w of weighted) { r -= w.weight; if (r <= 0) return w.ad; }
  return weighted[weighted.length - 1].ad;
}
function _adIsInternal(link) {
  if (!link) return false;
  try { return link.startsWith('/') || link.startsWith(location.origin); } catch(e) { return false; }
}
function _adIsBastionInvite(ad) {
  // Either no customLink (implicit bastion invite) or an internal link pointing to /app/bastion?...
  if (!ad) return false;
  if (!ad.customLink) return !!(ad.bastionId || ad.bastionName);
  if (!_adIsInternal(ad.customLink)) return false;
  const path = ad.customLink.replace(location.origin, '');
  return /^\/app\/bastion\b/.test(path);
}
function _adClickAction(ad) {
  if (ad.customLink) {
    const link = ad.customLink;
    if (_adIsInternal(link)) {
      // Split query for atelier tab / friends sub
      const [rawPath, rawQuery] = link.replace(location.origin, '').split('?');
      const path = (rawPath || '').replace(/\/+$/, '') || '/app';
      const query = rawQuery || '';
      // Bastion invite via URL: /app/bastion?GLOBALID[/CHANNELIDX]
      if (path === '/app/bastion' && query) {
        const parts = query.split('/');
        const bId = decodeURIComponent(parts[0] || '');
        const idx = (CU?.bastions || []).findIndex(b => b.globalId === bId);
        if (idx >= 0) {
          try { openBastion(idx); } catch(e) {}
          return;
        }
        try { promptJoinPublicBastion(bId); } catch(e) { window.location.href = link; }
        return;
      }
      // Atelier with sub-tab
      if (path === '/app/atelier') {
        const tabMatch = query.match(/tab=([\w-]+)/);
        const tab = tabMatch ? tabMatch[1] : 'radiance';
        const allowed = ['radiance','quests','shop','creator','inventory'];
        window._atelierPendingTab = allowed.includes(tab) ? tab : 'radiance';
        try { showView('atelier'); return; } catch(e) {}
      }
      // Friends sub-view inside DMs
      if (path === '/app/messages' && /friends=1/.test(query)) {
        try {
          showView('dms');
          setTimeout(() => { try { showDMFriendsHome(); } catch(_){} }, 80);
          return;
        } catch(e) {}
      }
      const viewMap = {
        '/app': 'home',
        '/app/messages': 'dms',
        '/app/discover': 'discover',
        '/app/atelier': 'atelier',
        '/app/forum': 'forum',
      };
      const view = viewMap[path];
      if (view) { try { showView(view); return; } catch(e) {} }
      window.location.href = link;
    } else {
      window.open(link, '_blank', 'noopener');
    }
  } else {
    promptJoinPublicBastion(ad.bastionId || ad.bastionName || '');
  }
}
async function _getAllActiveAds() {
  let ads = [];
  try { ads = await FortizedSocial.getGlobalAds(); } catch(e) {}
  let blocked = new Set();
  try { blocked = await FortizedSocial.getTakenDownAdIds?.() || new Set(); } catch(e) {}
  const localAds = (CU?.ads||[]).filter(a => _isAdLive(a) && !blocked.has(a.id));
  const allAds = ads.filter(a => !blocked.has(a.id));
  localAds.forEach(la => { if (!allAds.find(a=>a.id===la.id)) allAds.push(la); });
  return allAds;
}
function _renderAdHTML(ad, size) {
  const isBanner = size === 'banner';
  const adKey = '_ad_' + Math.random().toString(36).slice(2,6);
  window[adKey] = ad;
  const isBastionInvite = _adIsBastionInvite(ad);
  // Prefer the ad's own title; only show bastion name/icon for actual bastion invites
  const label = ad.title || (isBastionInvite ? ad.bastionName : '') || 'Sponsored';
  const showBastionIcon = isBastionInvite && ad.bastionIcon;
  const meta = `<div style="display:flex;align-items:center;justify-content:space-between;padding:3px 2px 0;">
          <div style="display:flex;align-items:center;gap:5px;min-width:0;">
            ${showBastionIcon?`<img src="${escapeHTML(ad.bastionIcon)}" style="width:13px;height:13px;border-radius:4px;flex-shrink:0;">`:''}
            <span style="font-size:10px;color:rgba(255,255,255,.35);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(label)} · Sponsored</span>
          </div>
          <span style="font-size:10px;color:rgba(255,255,255,.2);cursor:pointer;flex-shrink:0;transition:color .15s;" onmouseenter="this.style.color='rgba(248,113,113,.6)'" onmouseleave="this.style.color='rgba(255,255,255,.2)'" onclick="event.stopPropagation();_reportAd('${escapeHTML(ad.id)}','${escapeHTML(ad.title||'')}','${escapeHTML(isBastionInvite?(ad.bastionName||''):'')}')">Report ad</span>
        </div>`;
  if (isBanner) {
    // The 728:90 aspect lock lives on the wrapper (.home-banner-ad .ad-banner-inner > a)
    // so placeholder + loaded states share the same footprint. The image just fills it.
    return `<div class="ad-banner-inner">
      <a style="cursor:pointer;" onclick="_adClickAction(window['${adKey}'])">
        <img src="${escapeHTML(ad.image||ad.bastionIcon||'/Fortized banner.png?v=2')}" alt="${escapeHTML(ad.title||'')}" onerror="this.style.background='rgba(255,249,62,.04)'">
      </a>
      ${meta.replace('<div style="display:flex;align-items:center;justify-content:space-between;padding:3px 2px 0;">','<div style="display:flex;align-items:center;justify-content:space-between;padding:0 2px;">')}
    </div>`;
  } else {
    return `<div style="text-align:center;padding:6px 0;">
      <div style="width:300px;margin:0 auto;">
        <a style="display:block;cursor:pointer;border-radius:10px;overflow:hidden;" onclick="_adClickAction(window['${adKey}'])">
          <img src="${escapeHTML(ad.image||ad.bastionIcon||'/Fortized banner.png?v=2')}" style="width:300px;height:250px;object-fit:cover;display:block;border-radius:10px;" alt="${escapeHTML(ad.title||'')}" onerror="this.style.background='rgba(255,249,62,.04)'">
        </a>
        ${meta}
      </div>
    </div>`;
  }
}
let _homeAdTimer = null;
async function _renderHomeAds() {
  if (_homeAdTimer) { clearInterval(_homeAdTimer); _homeAdTimer = null; }
  async function _rotateHomeAd() {
    const bannerEl = document.getElementById('home-ads');
    const sidebarEl = document.getElementById('home-sidebar-ad');
    if (!bannerEl && !sidebarEl) return;
    const allAds = await _getAllActiveAds();
    const bannerAd = _pickWeightedAd(allAds, 'banner');
    const rectAd = _pickWeightedAd(allAds, 'rectangle');
    if (bannerAd) {
      if (bannerEl) { bannerEl.innerHTML = _renderAdHTML(bannerAd, 'banner'); bannerEl.onclick = () => _adClickAction(bannerAd); }
    } else {
      // Show a subtle placeholder (same vibe as the forum ad slot) so the space feels intentional
      if (bannerEl) { bannerEl.innerHTML = '<div class="ad-empty ad-empty-banner">Ad</div>'; bannerEl.onclick = null; }
    }
    if (rectAd) {
      if (sidebarEl) { sidebarEl.innerHTML = _renderAdHTML(rectAd, 'rectangle'); sidebarEl.onclick = () => _adClickAction(rectAd); }
    } else {
      if (sidebarEl) { sidebarEl.innerHTML = '<div class="ad-empty">Ad</div>'; sidebarEl.onclick = null; }
    }
  }
  await _rotateHomeAd();
  _homeAdTimer = setInterval(_rotateHomeAd, 75000);
}

// ── Realm friends loader (horizontal avatars) ──
async function _loadRealmFriends(friends, container, countEl) {
  const _realmSlice = friends.slice(0, 20);
  let _realmPresence = null; // null = query failed, {} = query succeeded
  try { _realmPresence = await FortizedSocial.queryPresence(_realmSlice); } catch(e) { console.warn('[Presence] Realm query failed:', e?.message); }
  const results = await Promise.all(_realmSlice.map(async f => {
    try {
      const u = await FortizedSocial.getUserByName(f);
      const _rLiveSt = _realmPresence?.[f]?.status;
      // If presence query worked, trust it. If it failed (null), use DB status as initial display.
      const st = FtzStatus.sanitize(_rLiveSt !== undefined ? _rLiveSt : (_realmPresence === null ? (u?.status || 'offline') : 'offline'));
      return {username:f, displayName:u?.displayName||f, pfp:u?.pfp||null, status:st};
    } catch { return {username:f, displayName:f, pfp:null, status:'offline'}; }
  }));
  const online = results.filter(r => FtzStatus.isPresent(r.status));
  const offline = results.filter(r => !FtzStatus.isPresent(r.status));
  if (countEl) countEl.textContent = online.length ? online.length + ' online' : '';
  if (!online.length) {
    container.innerHTML = '<div style="padding:8px;font-size:13px;color:var(--muted);">All friends offline</div>';
    return;
  }
  container.innerHTML = online.map(r=>{
    return `<div class="realm-friend" onclick="openDMView('${escapeHTML(r.username)}')" title="${escapeHTML(r.displayName)}">
      <div class="rf-av">
        <div style="width:44px;height:44px;border-radius:50%;overflow:hidden;background:var(--panel2);display:flex;align-items:center;justify-content:center;font-size:16px;">${buildAvatarHTML(r.pfp,r.displayName,44)}</div>
        <span class="rf-status profile-status-dot" data-for="${escapeHTML(r.username)}" data-dot-size="16">${FtzStatus.dotSvg(r.status, 16)}</span>
      </div>
      <div class="rf-name">${escapeHTML(r.displayName)}</div>
    </div>`;
  }).join('') || '<div style="padding:8px;font-size:13px;color:var(--muted);">All friends offline</div>';
}

// ── Right panel friends loader (async with status) ──
async function _loadRPFriends(friends, container, countEl) {
  if (!friends.length) {
    container.innerHTML = '<div class="ftz-empty"><div class="ftz-empty-icon">👥</div><div class="ftz-empty-title">No friends yet</div><div class="ftz-empty-text">Add friends by username to get started!</div></div>';
    return;
  }
  const _rpSlice = friends.slice(0, 15);
  let _rpPresence = null;
  try { _rpPresence = await FortizedSocial.queryPresence(_rpSlice); } catch(e) { console.warn('[Presence] RP query failed:', e?.message); }
  const results = await Promise.all(_rpSlice.map(async f => {
    try {
      const u = await FortizedSocial.getUserByName(f);
      const _rpLiveSt = _rpPresence?.[f]?.status;
      const st = FtzStatus.sanitize(_rpLiveSt !== undefined ? _rpLiveSt : (_rpPresence === null ? (u?.status || 'offline') : 'offline'));
      return {username:f, displayName:u?.displayName||f, pfp:u?.pfp||null, status:st, customStatus:u?.customStatus||null, game:u?.currentGame||null};
    } catch { return {username:f, displayName:f, pfp:null, status:'offline'}; }
  }));
  const online = results.filter(r => FtzStatus.isPresent(r.status));
  const offline = results.filter(r => !FtzStatus.isPresent(r.status));
  if (countEl) countEl.textContent = online.length ? online.length + ' online' : '';
  container.innerHTML = [...online,...offline].map(r=>{
    const activity = r.customStatus?.text ? `${r.customStatus.emoji||''} ${escapeHTML(r.customStatus.text)}` : r.game ? `Playing ${escapeHTML(r.game.name)}` : FtzStatus.publicLabel(r.status);
    return `<div class="rp-friend-item" onclick="openDMView('${escapeHTML(r.username)}')" title="${escapeHTML(activity)}">
      <div class="rp-friend-av">
        <div style="width:28px;height:28px;border-radius:50%;overflow:hidden;display:flex;align-items:center;justify-content:center;background:var(--panel);font-size:12px;">${buildAvatarHTML(r.pfp,r.displayName,28)}</div>
        <span class="rp-friend-status profile-status-dot" data-for="${escapeHTML(r.username)}" data-dot-size="12">${FtzStatus.dotSvg(r.status, 12)}</span>
      </div>
      <div style="flex:1;min-width:0;">
        <div class="rp-friend-name">${escapeHTML(r.displayName)}</div>
        <div class="rp-friend-activity">${escapeHTML(activity)}</div>
      </div>
    </div>`;
  }).join('') || '<div style="padding:10px;font-size:12px;color:var(--muted);text-align:center;">All friends offline</div>';
}

// ── Animated counter ──
function _animateCounter(elId, target) {
  const el = document.getElementById(elId);
  if (!el) return;
  const start = parseInt(el.textContent)||0;
  if (start === target) { el.textContent = target; return; }
  const duration = 400;
  const startTime = performance.now();
  function tick(now) {
    const progress = Math.min((now - startTime) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    el.textContent = Math.round(start + (target - start) * eased);
    if (progress < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

// ── Hero floating items & sparkles ──
function _initHeroEffects() {
  // Sparkles
  const sparkleContainer = document.getElementById('hero-sparkles');
  if (sparkleContainer && !sparkleContainer.children.length) {
    for (let i = 0; i < 12; i++) {
      const s = document.createElement('div');
      s.className = 'hero-sparkle';
      s.style.left = Math.random() * 100 + '%';
      s.style.top = (40 + Math.random() * 50) + '%';
      s.style.animationDelay = (Math.random() * 6) + 's';
      s.style.animationDuration = (4 + Math.random() * 4) + 's';
      sparkleContainer.appendChild(s);
    }
  }
  // Floating items
  const floatContainer = document.getElementById('hero-float-items');
  if (floatContainer && !floatContainer.children.length) {
    const items = ['🎲','#','🎮','🎧','⚔️','🛡️','💎','🏰'];
    items.forEach((item, i) => {
      const el = document.createElement('div');
      el.className = 'hero-float-item';
      el.textContent = item;
      el.style.left = (8 + (i / items.length) * 80) + '%';
      el.style.top = (15 + Math.random() * 55) + '%';
      el.style.animationDelay = (Math.random() * 8) + 's';
      el.style.animationDuration = (10 + Math.random() * 8) + 's';
      el.style.fontSize = (14 + Math.random() * 10) + 'px';
      floatContainer.appendChild(el);
    });
  }
}

// ── Joyster character interactions ──
let _joysterBubbleTimer = null;
let _joysterClickCount = 0;
let _joysterLastTip = -1;
const _JOYSTER_DAILY_LIMIT = 5;

// Joyster AI — talks to our /api/joyster proxy so the Gemini key stays server-side
const JOYSTER_SYSTEM_PROMPT = `You are Joyster the Jester, the official mischievous mascot of Fortized - a gaming/social platform. You're a witty, cocky jester from King Staw's royal court who lives for chaos, pranks, and making people laugh. Personality: playful, arrogant, cheeky, spontaneous, constantly laughing (BAHAHA! Ahahaha! Hehehehe~), terrible puns, teases lovingly, unpredictable, bold, irreverent.

You know Fortized features: Bastions (guilds with roles/channels), Onyx (currency), Radiance/VIP (premium), Atelier (cosmetics shop), voice/party rooms, profiles, custom status.

CRITICAL response rules:
- 1-2 sentences MAX, punchy and snappy — NO essays
- Each response, pick exactly ONE specific detail from the user_context JSON and roast them about it personally (their hovered button, new friend, status change, recent purchase, Onyx balance, etc.). Make it feel like you were WATCHING them.
- Your signature catchphrase is "go touch grass!" — include it in roughly 1 out of every 3 responses, as a closer or punchline
- Stay in character — you're a cocky jester, not a bot
- Vary your laugh: BAHAHA!, Ahahaha!, Hehehehe~
- Energy 9/10, terrible puns welcome
- NO markdown, NO bullets, NO explanations, NO meta-commentary

Example voice (note how they reference a specific thing and sometimes sign off with "go touch grass"):
"BAHAHA! Hovering the Atelier button like it owes you Onyx — just BUY the shiny thing already, cheapskate! Or go touch grass!"
"Hehehe~ New friend? Finally! Your friend count went from tragic to merely sad~"
"Ahahaha! 3 Onyx?! I've seen beggars with fuller pockets. Go touch grass and rethink your life choices!"
"PSST! Changed your status to 'away'? We ALL know you're just watching cat videos~"`;
let _joysterAICache = [];
let _joysterContexts = []; // Track shown contexts to avoid repetition

// ── Joyster live-context tracking ──
// Rolling log of recent user-observable events so the AI can roast specifics.
const _joysterEvents = [];
function _logJoysterEvent(event) {
  _joysterEvents.push({ event: String(event).slice(0, 80), t: Date.now() });
  if (_joysterEvents.length > 8) _joysterEvents.shift();
}
let _joysterHoverLabel = null;
if (typeof document !== 'undefined') {
  document.addEventListener('mouseover', (e) => {
    const el = e.target instanceof Element
      ? e.target.closest('button, .btn, [role="button"], .sidebar-btn, .nav-item, a.btn')
      : null;
    if (!el) return;
    const raw = el.getAttribute('aria-label') || el.title || el.textContent || '';
    const label = raw.replace(/\s+/g, ' ').trim().slice(0, 50);
    if (label) _joysterHoverLabel = label;
  }, { passive: true, capture: true });
}
function _buildJoysterUserContext() {
  const cs = CU?.customStatus;
  const csText = cs?.text || (typeof cs === 'string' ? cs : '');
  return {
    username: CU?.username || null,
    onyx: CU?.onyx ?? 0,
    radiance: !!(CU?.vip || CU?.radiance),
    status: CU?.status || 'unknown',
    customStatus: csText || null,
    friendCount: (CU?.friends || []).length,
    bastionCount: (CU?.bastions || []).length,
    recentHoverButton: _joysterHoverLabel,
    recentEvents: _joysterEvents.slice(-5).map(e => e.event),
    localTimeHour: new Date().getHours(),
  };
}

// Quota safety: keep AI usage well under the Gemini free tier.
// - Daily cap (per browser, persisted) so a long session can't burn the day
// - Min interval so a quick navigate-spree can't fire 10 calls in a minute
const _JOYSTER_AI_DAILY_CAP = 30;
const _JOYSTER_AI_MIN_INTERVAL_MS = 90 * 1000;
let _joysterAIDisabledUntil = 0;
let _joysterAILastCallTs = 0;
function _joysterAIDailyCount() {
  try {
    const today = new Date().toISOString().slice(0, 10);
    const stored = JSON.parse(localStorage.getItem('joyster_ai_daily') || '{}');
    return stored.date === today ? (stored.count || 0) : 0;
  } catch { return 0; }
}
function _joysterAIIncDaily() {
  try {
    const today = new Date().toISOString().slice(0, 10);
    const stored = JSON.parse(localStorage.getItem('joyster_ai_daily') || '{}');
    const count = (stored.date === today ? stored.count || 0 : 0) + 1;
    localStorage.setItem('joyster_ai_daily', JSON.stringify({ date: today, count }));
  } catch {}
}
async function _joysterFetch(bodyObj) {
  return fetch('/api/joyster', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({ body: bodyObj }),
  });
}
async function _getJoysterAIResponse(context) {
  if (Date.now() < _joysterAIDisabledUntil) return null;
  if (Date.now() - _joysterAILastCallTs < _JOYSTER_AI_MIN_INTERVAL_MS) return null;
  if (_joysterAIDailyCount() >= _JOYSTER_AI_DAILY_CAP) return null;
  _joysterAILastCallTs = Date.now();
  _joysterAIIncDaily();
  try {
    const userCtx = _buildJoysterUserContext();
    const promptText = `user_context = ${JSON.stringify(userCtx)}

Directive: ${context || 'Bubble a cocky, personal jester comment for this user.'}

Pick ONE specific detail from user_context and make it the core of your comment. 1-2 sentences, in-character, punchy.`;

    // Primary attempt: systemInstruction + contents (modern v1beta shape)
    let res = await _joysterFetch({
      systemInstruction: {parts:[{text: JOYSTER_SYSTEM_PROMPT}]},
      contents: [{role:'user', parts:[{text: promptText}]}],
      generationConfig: {maxOutputTokens: 120, temperature: 1.0}
    });

    // If that 400s, retry once with the system prompt folded into the user
    // turn — some API keys / model tiers reject top-level systemInstruction.
    if (res.status === 400) {
      const errBody = await res.clone().text().catch(() => '');
      if (!window._joysterErrorLogged) {
        window._joysterErrorLogged = true;
        console.warn('[Joyster] 400 from Gemini — body:', errBody.slice(0, 400));
      }
      res = await _joysterFetch({
        contents: [{role:'user', parts:[{text: JOYSTER_SYSTEM_PROMPT + '\n\n' + promptText}]}],
        generationConfig: {maxOutputTokens: 120, temperature: 1.0}
      });
    }

    if (!res.ok) {
      if (res.status === 429) {
        // Quota exhausted. Free-tier Gemini resets daily — back off until the
        // next UTC day so we don't keep poking the API.
        const ms = (24 * 60 * 60 * 1000);
        _joysterAIDisabledUntil = Date.now() + ms;
        if (!window._joysterWarned) {
          window._joysterWarned = true;
          console.warn('[Joyster] AI quota exhausted (429) — sleeping 24h');
        }
      } else if (res.status >= 400 && res.status < 500) {
        _joysterAIDisabledUntil = Date.now() + 15 * 60 * 1000; // 15m
        if (!window._joysterWarned) {
          window._joysterWarned = true;
          const body = await res.clone().text().catch(() => '');
          console.warn('[Joyster] AI disabled for 15m after', res.status, body.slice(0, 300));
        }
      }
      return null;
    }
    const data = await res.json();
    const text = data?.candidates?.[0]?.content?.parts?.[0]?.text;
    return text ? text.trim().replace(/^["']|["']$/g, '').slice(0, 260) : null;
  } catch { return null; }
}

// Pre-fetch a few AI responses so bubbles feel instant
async function _prefetchJoysterAI() {
  const allContexts = [
    'Greet a Fortized user with maximum chaotic jester energy!',
    'Make a spicy joke about Onyx, currency, or being broke.',
    'Roast their profile, status, or general existence in a loving way.',
    'Make a terrible pun or wordplay about gaming or Fortized.',
    'Dare them to do something bold (create Bastion, customize, voice chat).',
    'Say something COMPLETELY unexpected and chaotic!',
    'Tease them for being inactive or idle too long.',
    'Give a funny "pro tip" about hidden Fortized features.',
    'Challenge them to collect more Onyx or boost their Bastion.',
    'Make them laugh about their friend group or lack thereof.',
  ];
  // Rotate through contexts, pick random ones
  const shuffled = allContexts.sort(() => Math.random() - 0.5);
  const toFetch = shuffled.slice(0, Math.min(5, shuffled.length));
  for (const ctx of toFetch) {
    const resp = await _getJoysterAIResponse(ctx);
    if (resp && resp.length > 8 && resp.length < 220) {
      _joysterAICache.push(resp);
    }
  }
}
function _getJoysterDailyCount() {
  const today = new Date().toISOString().slice(0,10);
  const stored = JSON.parse(localStorage.getItem('joyster_daily')||'{}');
  if (stored.date !== today) return 0;
  return stored.count || 0;
}
function _incJoysterDailyCount() {
  const today = new Date().toISOString().slice(0,10);
  const stored = JSON.parse(localStorage.getItem('joyster_daily')||'{}');
  const count = (stored.date === today ? stored.count || 0 : 0) + 1;
  localStorage.setItem('joyster_daily', JSON.stringify({date:today, count}));
}

