// ── Active chat subscription tracker ────────────────────────────────────────
// Prevents polling intervals and socket rooms from accumulating when users
// switch between DMs / GCs / channels / views. Every opener routes through
// the _leaveActive* helpers before registering its own subscriptions so we
// never leak a second room or polling timer for the same surface.
window._activeSubs = window._activeSubs || { dmKey: null, dmRoom: null, gcRoom: null, chKey: null, chRoom: null };
function _leaveActiveDM() {
  const s = window._activeSubs;
  if (s.dmKey) { try { FortizedSocial.stopDMPolling && FortizedSocial.stopDMPolling(s.dmKey); } catch(_){} s.dmKey = null; }
  if (s.dmRoom) { try { FortizedSocial.leaveRoom && FortizedSocial.leaveRoom('dm', s.dmRoom.id1, s.dmRoom.id2); } catch(_){} s.dmRoom = null; }
  if (typeof _typingListenerOff === 'function') { try { _typingListenerOff(); } catch(_){} _typingListenerOff = null; }
  const _tb = document.getElementById('dm-typing-bar'); if (_tb) _tb.style.opacity = '0';
}
function _leaveActiveGC() {
  const s = window._activeSubs;
  if (s.gcRoom) { try { FortizedSocial.leaveRoom && FortizedSocial.leaveRoom('gc', s.gcRoom); } catch(_){} s.gcRoom = null; }
}
function _leaveActiveChannel() {
  const s = window._activeSubs;
  if (s.chKey) { try { FortizedSocial.stopChannelPolling && FortizedSocial.stopChannelPolling(s.chKey); } catch(_){} s.chKey = null; }
  if (s.chRoom) { try { FortizedSocial.leaveRoom && FortizedSocial.leaveRoom('bastion', s.chRoom.id1, s.chRoom.id2); } catch(_){} s.chRoom = null; }
  if (_annListener) { try { _annListener(); } catch(_){} _annListener = null; }
}
function _leaveAllActiveChats() { _leaveActiveDM(); _leaveActiveGC(); _leaveActiveChannel(); }

let _dmListener = null;
function openDMView(username) {
  if (!username) return;
  username = (username||"").trim().toLowerCase();
  // Save scroll position of previous chat before switching
  if (curDM && curDM !== username) { const _el = document.getElementById('dm-msgs'); if (_el) _saveChatScroll('dm:'+curDM, _el); }
  if (curGC) { const _el = document.getElementById('gc-msgs'); if (_el) _saveChatScroll('gc:'+curGC, _el); }
  if (curBastion !== null && curChannel !== null && curChannel !== 'overview') { const _el = document.getElementById('ch-msgs-'+curChannel); if (_el) _saveChatScroll('ch:'+curBastion+':'+curChannel, _el); }
  // Auto-clear DM notifications from this user (Discord-style)
  try { FortizedSocial.markNotificationReadBySource(CU.username, 'dm', username).then(()=>updateNotifBadge()).catch(e => console.warn('[Notif] Clear DM read failed:', e?.message)); } catch(e) { console.warn('[Notif]', e?.message); }
  // Auto-unhide conversation when opening it
  unhideDMConversation('dm_' + username);
  // Leave any prior DM / GC / channel subscription before wiring this one
  _leaveActiveDM();
  _leaveActiveGC();
  _leaveActiveChannel();
  curDM = username;
  curGC = null;
  _currentGCMeta = null;
  document.getElementById('gc-member-panel')?.remove();
  closeModal('modal-new-dm');
  // curDM is set above, so showView('dms') → pushState picks up the target
  // automatically and the URL becomes /app/messages?u=<username>.
  showView('dms');
  // Update title: Fortized | @username
  document.title = 'Fortized | @' + username;
  // Close mobile drawer when opening a DM chat
  if (window.innerWidth <= 768) closeMobileSidebar();
  // Hide Active Now sidebar when in a DM chat
  const anSidebar = document.getElementById('dm-active-now');
  if (anSidebar) anSidebar.style.display = 'none';
  const topTitle = document.getElementById('topbar-title');
  if (topTitle) topTitle.textContent = 'Direct Messages';
  setTopbarDMActions();
  document.querySelectorAll('.friend-item').forEach(fi=>fi.classList.remove('active'));
  const fi = document.getElementById('dm-fi-'+username);
  if (fi) fi.classList.add('active');

  const wrap = document.getElementById('dm-chat-wrap');
  if (!wrap) return;
  wrap.innerHTML = `
    <div class="chat-wrap">
      <div class="room-topbar">
        <span class="rt-hash"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="opacity:.4;"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg></span>
        <span class="rt-name">${escapeHTML(username)}</span>
      </div>
      <div class="chat-msgs" id="dm-msgs">
        <div class="chat-past-bar"><span>You're viewing older messages</span><button onclick="scrollBottom('dm-msgs')">Jump to Present</button></div>
        <div class="new-messages-bar" id="dm-new-msgs-bar"><span id="dm-new-msgs-text">1 new message</span><button onclick="markDMRead()">Mark as Read</button></div>
        <div class="chat-welcome">
          <div class="w-av" id="dm-welcome-av">${(() => { const _cp = (typeof cachedProfile === 'function' ? cachedProfile(username) : null) || {}; return buildAvatarHTML(_cp.pfp || null, _cp.displayName || username, 60); })()}</div>
          <h3 id="dm-welcome-name">${escapeHTML((typeof cachedProfile === 'function' && cachedProfile(username)?.displayName) || username)}</h3>
          <p>Beginning of your conversation with <strong>${escapeHTML(username)}</strong>.</p>
        </div>
      </div>

      <div class="typing-indicator" id="dm-typing-bar" style="opacity:0;">
        <div class="typing-dots"><span></span><span></span><span></span></div>
        <span id="dm-typing-text"></span>
      </div>
      ${buildChatInputBar({inputId:'dm-input',placeholder:'Message '+escapeHTML(username)+'…',context:'dm'})}
    </div>`;
  loadDMMessages(username);
  setTimeout(() => { if (window.innerWidth > 768) showDMUserPanel(username); _initChatScroll(document.getElementById('dm-msgs')); }, 80);
  setupEmojiAutocomplete('dm-input');
  // Restore composer draft (text + attached file) for this DM partner.
  setTimeout(() => {
    try { _restoreDraftFor('dm', 'dm-input'); } catch(_) {}
    try { _wireInputSafetyNet('dm-input', 'dm'); } catch(_) {}
  }, 50);
  ensureDMExists(username).catch(e => console.warn('[DM] Failed to ensure DM:', e?.message));
  // Join Socket.io room for DM real-time events (typing, edits, deletes).
  // Always lowercased — server's roomKey sorts the names; mixed case
  // produces a different key than the receiver computes locally.
  FortizedSocial.joinRoom('dm', String(CU.username).toLowerCase(), String(username).toLowerCase());
  window._activeSubs.dmRoom = { id1: CU.username, id2: username };
  // Start polling for instant message delivery
  const dmKey = [CU.username.toLowerCase(), username.toLowerCase()].sort().join('__');
  if (FortizedSocial.startDMPolling) FortizedSocial.startDMPolling(dmKey);
  window._activeSubs.dmKey = dmKey;
  _listenTyping(username);
}
function openDMChat(u) { openDMView(u); }

// Ensure DM conversation exists in Firebase dmIndex for both users
async function ensureDMExists(partnerUsername) {
  if (!CU?.username || !partnerUsername || partnerUsername===CU.username) return;
  try {
    const myIdx = await firebase.database().ref('dmIndex/'+CU.username).get().then(s=>s.val()).catch(()=>null);
    const arr = myIdx ? (Array.isArray(myIdx)?myIdx:Object.values(myIdx)) : [];
    if (!arr.includes(partnerUsername)) {
      const newArr = [partnerUsername, ...arr.filter(u=>u!==partnerUsername)].slice(0,30);
      await firebase.database().ref('dmIndex/'+CU.username).set(newArr);
    }
    const theirIdx = await firebase.database().ref('dmIndex/'+partnerUsername).get().then(s=>s.val()).catch(()=>null);
    const arr2 = theirIdx ? (Array.isArray(theirIdx)?theirIdx:Object.values(theirIdx)) : [];
    if (!arr2.includes(CU.username)) {
      const newArr2 = [CU.username, ...arr2.filter(u=>u!==CU.username)].slice(0,30);
      await firebase.database().ref('dmIndex/'+partnerUsername).set(newArr2);
    }
  } catch(e) { _wrn('ensureDMExists', e); }
}

async function loadDMMessages(username) {
  const msgsEl = document.getElementById('dm-msgs');
  if (!msgsEl) return;
  if (_dmListener) { try{_dmListener();}catch(e){_dbg('[DM] Listener cleanup:',e?.message);} _dmListener=null; }
  // Stop any existing DM polling for this conversation
  const dmKey = [CU.username, username].sort().join('__');
  FortizedSocial.stopDMPolling(dmKey);
  try {
    // Discord-style initial fetch: only the last 20 visible messages — the
    // ~one-screen Discord paints first. Older messages are lazy-loaded on
    // scroll-up via _attachLazyLoadOlder().
    const msgs = await FortizedSocial.getDMMessages(CU.username, username, 20);
    renderMessages(msgsEl, msgs||[], 'dm');
    if (!_restoreChatScroll('dm:'+username, msgsEl)) scrollBottom('dm-msgs', true);
    _attachLazyLoadOlder(msgsEl, 'dm');
    _attachDMLiveEdits(CU.username, username);
    // Start polling for new DM messages to enable real-time sync across sessions
    FortizedSocial.startDMPolling(dmKey);
    _dmListener = FortizedSocial.listenDM(CU.username, username, msg => {
      if (curDM!==username) return;
      // Handle edit/delete events from Supabase real-time
      if (msg._event === 'delete') { _liveRemoveMessage({ key: msg.id }); return; }
      if (msg._event === 'update') { _liveUpdateMessage({ key: msg.id, val: () => msg }, 'dm'); return; }
      const el=document.getElementById('dm-msgs');
      if (el) {
        const mid = msg.id != null ? msg.id : (msg.from+msg.timestamp);
        if (el.querySelector(`[data-msgid="${CSS.escape(mid)}"]`)) return; // already rendered
        appendMessage(el,msg,'dm',null); _notifyNewMsg('dm-msgs');
        if(msg.from!==CU.username && !isUserBlocked(msg.from) && !isUserIgnored(msg.from) && !isUserMutedLocal(msg.from) && !isConvoMuted('dm', username)) playNotifSound('message');
      }
    });
  } catch(e){_wrn('DM load',e);}
}

// Reads a chat input safely whether the contenteditable shim is installed
// (`.value` getter) or not (fall back to textContent). Without this fallback
// a race during input mount throws "Cannot read properties of undefined
// (reading 'trim')" mid-send and locks the entire UI.
function _readChatInput(inp) {
  if (!inp) return '';
  return ((typeof inp.value === 'string' ? inp.value : (inp.textContent || '')) || '').trim();
}

// ════════════════════════════════════════════════════════════════
// CHAT DRAFTS — persist text + attached file per-chatbox so the
// composer state survives refresh / tab close. Different drafts for
// each (DM partner | GC | bastion channel).
// ════════════════════════════════════════════════════════════════
const _DRAFTS_KEY = 'ftz_chat_drafts_v1';
function _draftKeyFor(context, inputId) {
  // Compose a stable key per chatbox.
  if (context === 'dm' && curDM) return 'dm:' + String(curDM).toLowerCase();
  if (context === 'gc' && curGC) return 'gc:' + String(curGC).toLowerCase();
  if (context === 'ch' && curBastion !== null && curChannel !== null) {
    const b = CU?.bastions?.[curBastion]; const ch = b?.channels?.[curChannel];
    if (b && ch) return 'ch:' + String(b.globalId||b.name).toLowerCase() + ':' + String(ch.name).toLowerCase();
  }
  // Fallback: per-input only (still better than losing drafts entirely).
  return 'inp:' + (inputId || 'unknown');
}
function _loadDrafts() {
  try { return JSON.parse(localStorage.getItem(_DRAFTS_KEY) || '{}') || {}; }
  catch { return {}; }
}
function _saveDrafts(d) {
  try { localStorage.setItem(_DRAFTS_KEY, JSON.stringify(d)); } catch(_) {}
}
function _saveDraft(key, draft) {
  if (!key) return;
  const all = _loadDrafts();
  if (!draft || (!draft.text && !draft.attachment)) { delete all[key]; }
  else { all[key] = draft; }
  _saveDrafts(all);
}
function _clearDraft(key) {
  if (!key) return;
  const all = _loadDrafts();
  delete all[key];
  _saveDrafts(all);
}
function _getDraft(key) {
  if (!key) return null;
  return _loadDrafts()[key] || null;
}
// Restore the draft for the chatbox that's currently open. Called from
// loadDMMessages / loadGCMessages / loadChannel after the input has been
// painted into the DOM.
function _restoreDraftFor(context, inputId) {
  const inp = document.getElementById(inputId);
  if (!inp) return;
  const key = _draftKeyFor(context, inputId);
  const draft = _getDraft(key);
  if (!draft) return;
  if (draft.text) {
    if (typeof inp.value === 'string') inp.value = draft.text;
    else inp.textContent = draft.text;
    try { autoResize(inp); } catch(_) {}
  }
  if (draft.attachment) {
    window._pendingAttachment = draft.attachment;
    try {
      showAttachmentPreview(draft.attachment.name, draft.attachment.type, draft.attachment.data, draft.attachment.size, context);
    } catch(_) {}
  }
}

// Single safe oninput handler for chat inputs. Wraps the moving parts in
// try/catch so a hiccup in one (e.g. autoResize hitting a value-shim race)
// can't suppress the others — that's how broadcastTyping was silently
// going dark on some sessions.
function onChatInput(el, context, inputId) {
  try { autoResize(el); } catch(e) { console.warn('[Input] autoResize failed', e?.message); }
  // Persist draft text immediately.
  try {
    const text = (typeof el.value === 'string' ? el.value : (el.textContent || ''));
    const key = _draftKeyFor(context, inputId);
    const att = window._pendingAttachment || null;
    _saveDraft(key, { text: text, attachment: att });
  } catch(e) { console.warn('[Input] draft save failed', e?.message); }
  // Typing broadcast — never let this throw, never let it block the rest.
  try {
    if (context === 'dm') broadcastTyping();
    else if (context === 'gc') broadcastGCTyping();
    else if (context === 'ch') broadcastChannelTyping();
  } catch(e) { console.warn('[Input] typing broadcast failed', e?.message); }
  try { updateCharCount(inputId); } catch(_) {}
}

// Per-room typing registry (room key → Set of lowercased usernames). The
// member-list bubble + the chat input typing bar both read from this so a
// single source of truth drives every UI surface.
const _typingByRoom = new Map();
function _setRoomTypingUsers(roomLow, namesLower) {
  if (!roomLow) return;
  if (!namesLower || namesLower.length === 0) {
    _typingByRoom.delete(roomLow);
  } else {
    _typingByRoom.set(roomLow, new Set(namesLower));
  }
}
// Compute the union of typing users in any room that's relevant to the
// chat surface currently on screen, so multiple-room overlap (e.g. a DM
// open while you're also viewing the bastion's member list) doesn't
// cause flicker.
function _activeTypingUsers() {
  const active = new Set();
  // Bastion channel — any matching room
  if (curBastion !== null && curChannel !== null) {
    const b = CU?.bastions?.[curBastion]; const ch = b?.channels?.[curChannel];
    if (b && ch) {
      const k1 = ('bastion:'+(b.globalId||b.name)+':'+ch.name).toLowerCase();
      const k2 = ('bastion:'+(b.name||b.globalId)+':'+ch.name).toLowerCase();
      [k1, k2].forEach(k => { _typingByRoom.get(k)?.forEach(n => active.add(n)); });
    }
  }
  // GC
  if (curGC) {
    const k = 'gc:'+String(curGC).toLowerCase();
    _typingByRoom.get(k)?.forEach(n => active.add(n));
  }
  // DM (the partner's name appears in the DM room)
  if (curDM) {
    const me = String(CU?.username||'').toLowerCase();
    const them = String(curDM).toLowerCase();
    const k = 'dm:'+[me,them].sort().join('__');
    _typingByRoom.get(k)?.forEach(n => active.add(n));
  }
  return active;
}
// Refresh the chat-bubble overlay on every avatar that maps to a typing
// user in the current view. Idempotent — call freely from onTyping or
// after re-renders of the member list.
function _renderTypingBubbles() {
  const active = _activeTypingUsers();
  const all = document.querySelectorAll('.ml-entry, .an-row, .gc-ml-av');
  all.forEach(node => {
    const entry = node.classList.contains('ml-entry') || node.classList.contains('an-row') ? node : node.closest('.ml-entry, .an-row');
    const username = (entry?.dataset.member || entry?.dataset.username || '').toLowerCase();
    const wrap = node.classList.contains('gc-ml-av') ? node : node.querySelector('.gc-ml-av, .ml-av, .ml-av-wrap');
    if (!username || !wrap) return;
    let bubble = wrap.querySelector('.ml-typing-bubble');
    if (active.has(username)) {
      if (!bubble) {
        bubble = document.createElement('div');
        bubble.className = 'ml-typing-bubble';
        bubble.innerHTML = '<span></span><span></span><span></span>';
        wrap.appendChild(bubble);
      }
      if (entry) entry.dataset.typing = '1';
    } else {
      if (bubble) bubble.remove();
      if (entry?.dataset.typing) delete entry.dataset.typing;
    }
  });
}

// Belt-and-braces: bind a programmatic 'input' listener too. The inline
// oninput attribute can be eaten by an unrelated runtime error in
// autoResize / shim init and silently take broadcastTyping with it; a
// listener attached via addEventListener is independent.
function _wireInputSafetyNet(inputId, context) {
  const el = document.getElementById(inputId);
  if (!el || el._ftzInputNet) return;
  el._ftzInputNet = true;
  el.addEventListener('input', () => {
    try {
      if (context === 'dm') broadcastTyping();
      else if (context === 'gc') broadcastGCTyping();
      else if (context === 'ch') broadcastChannelTyping();
      // Also keep the draft in sync from this path so a stuck inline
      // onChatInput doesn't lose the user's text.
      const key = _draftKeyFor(context, inputId);
      const text = (typeof el.value === 'string' ? el.value : (el.textContent || ''));
      const att = window._pendingAttachment || null;
      _saveDraft(key, { text, attachment: att });
    } catch(e) { if (window._ftzDebugTyping) console.warn('[Typing-net] failed', e?.message); }
  });
}

// Persist + restore the pending attachment as a draft side-effect when
// it's added/removed from outside onChatInput (file picker, paste, drop).
function _persistPendingAttachmentChange(context, inputId) {
  try {
    const inp = inputId ? document.getElementById(inputId) : null;
    const key = _draftKeyFor(context, inputId || (context==='dm'?'dm-input':context==='gc'?'gc-input':'ch-input'));
    const text = inp ? (typeof inp.value === 'string' ? inp.value : (inp.textContent || '')) : '';
    const att = window._pendingAttachment || null;
    _saveDraft(key, { text: text, attachment: att });
  } catch(_) {}
}

async function sendDM() {
  _stopTypingBroadcast();
  const inp=document.getElementById('dm-input');
  if (!inp||!curDM) return;
  let text=preprocessMessageText(_readChatInput(inp));
  if (!text && !window._pendingAttachment) return;
  // Safety pre-check
  if (text) { const sw = contentSafetyCheck(text); if (sw) showContentWarning(sw); }
  // Remove any old friend-gate bar if present
  document.getElementById('dm-not-friends-bar')?.remove();
  if (!text) return;
  clearChatInput(inp);
  const rep=replyingTo;
  cancelReply('dm');
  _removeNewMsgBar('dm-msgs');
  const isOutline = _outlineMode;
  _outlineMode = false;
  const msg={id:'local-'+Date.now(),from:CU.username,text,timestamp:new Date().toISOString(),replyTo:rep,outline:isOutline};
  // Optimistic render — show message immediately for sender
  const msgsEl = document.getElementById('dm-msgs');
  if (msgsEl) {
    const lastRows = msgsEl.querySelectorAll('.msg-row');
    const lastAuthor = lastRows.length ? lastRows[lastRows.length-1].dataset.from : null;
    appendMessage(msgsEl, msg, 'dm', lastAuthor);
    scrollBottom('dm-msgs');
    // Register the optimistic row so the server echo reconciles by content instead of spawning a duplicate
    const _optimRow = msgsEl.querySelector('[data-msgid="'+CSS.escape(msg.id)+'"]');
    _registerPendingSend('dm:'+[CU.username, curDM].sort().join('__'), CU.username, text, _optimRow);
  }
  try {
    // Hard 15s timeout: if Supabase hangs (rare but it happens — slow
    // connection, regional outage), the optimistic row was previously
    // stuck in "sending..." forever with no feedback. Now it visibly
    // fails with a Retry button after 15s.
    const savedMsg = await _withSendTimeout(
      FortizedSocial.sendDMMessage(CU.username, curDM, text),
      15000
    );
    if (savedMsg?.id && msgsEl) {
      const localRow = msgsEl.querySelector('[data-msgid="'+CSS.escape(msg.id)+'"]');
      if (localRow) localRow.dataset.msgid = savedMsg.id;
    }
    FortizedSocial.socketEmit('message:send', { type: 'dm', id1: CU.username, id2: curDM, message: savedMsg || msg });
    _trackSendMsgQuest();
  } catch (e) {
    console.error('[sendDM Error]', e.message);
    _markMessageFailed(msgsEl, msg.id, { kind: 'dm', target: curDM, text, replyTo: rep });
    toast('Message failed to send — tap to retry', 'error');
  }
}

// Race a send against a hard timeout so hung server requests fail visibly
// instead of leaving the optimistic row stuck in "sending..." forever.
function _withSendTimeout(promise, ms) {
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(
      () => reject(new Error('Send timed out after ' + Math.round(ms/1000) + 's')),
      ms
    )),
  ]);
}

function _markMessageFailed(msgsEl, localId, payload) {
  if (!msgsEl || !localId) return;
  const row = msgsEl.querySelector('[data-msgid="'+CSS.escape(localId)+'"]');
  if (!row) return;
  row.classList.add('msg-row--failed');
  row.dataset.failedPayload = JSON.stringify(payload || {});
  if (!row.querySelector('.msg-retry-btn')) {
    const btn = document.createElement('button');
    btn.className = 'msg-retry-btn';
    btn.type = 'button';
    btn.innerHTML = '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M23 4v6h-6"/><path d="M20.49 15A9 9 0 116.64 5.64"/></svg> Retry';
    btn.onclick = (ev) => { ev.stopPropagation(); _retryFailedMessage(row); };
    const bubble = row.querySelector('.msg-bubble') || row;
    bubble.appendChild(btn);
  }
}
async function _retryFailedMessage(row) {
  try {
    const p = JSON.parse(row.dataset.failedPayload || '{}');
    if (!p || !p.text) return;
    const parent = row.parentElement;
    row.classList.remove('msg-row--failed');
    row.querySelector('.msg-retry-btn')?.remove();
    if (p.kind === 'dm') {
      try {
        const savedMsg = await FortizedSocial.sendDMMessage(CU.username, p.target, p.text);
        if (savedMsg?.id) row.dataset.msgid = savedMsg.id;
        FortizedSocial.socketEmit('message:send', { type:'dm', id1: CU.username, id2: p.target, message: savedMsg || { from: CU.username, text: p.text, timestamp: new Date().toISOString() } });
        toast('Message sent', 'success');
      } catch (e) {
        _markMessageFailed(parent, row.dataset.msgid, p);
        toast('Still failed — check your connection', 'error');
      }
    } else if (p.kind === 'gc' && p.target) {
      try {
        const ref = firebase.database().ref('groupChats/'+p.target+'/messages').push();
        const now = new Date();
        const msg = { id: ref.key, from: CU.username, text: p.text, time: now.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}), timestamp: now.toISOString(), ...(p.replyTo?{replyTo:p.replyTo}:{}) };
        await ref.set(msg);
        row.dataset.msgid = msg.id;
        FortizedSocial.socketEmit('message:send', { type:'gc', id1: p.target, message: msg });
        toast('Message sent', 'success');
      } catch (e) {
        _markMessageFailed(parent, row.dataset.msgid, p);
        toast('Still failed — check your connection', 'error');
      }
    } else if (p.kind === 'ch' && p.bastion && p.channel) {
      try {
        const savedMsg = await FortizedSocial.sendBastionChannelMessage(p.bastion, p.channel, CU.username, p.text);
        if (savedMsg?.id) row.dataset.msgid = savedMsg.id;
        FortizedSocial.socketEmit('message:send', { type:'bastion', id1: p.bastion, id2: p.channel, message: savedMsg || { from: CU.username, text: p.text, timestamp: new Date().toISOString() } });
        toast('Message sent', 'success');
      } catch (e) {
        _markMessageFailed(parent, row.dataset.msgid, p);
        toast('Still failed — check your connection', 'error');
      }
    }
  } catch(_) {}
}

// ════════════════════════════════════════════════════
// GROUP CHAT SYSTEM
