function _filterForwardTargets(query) { _buildForwardTargets(query); }
async function forwardTo(type, target) {
  const text = forwardMsgText;
  if (!text) return;
  // Build forwardedFrom field for the outgoing message. We only include
  // author/pfp/timestamp when the caller provided them; context (where
  // the original message lives) is always captured when known.
  const origin = _forwardOrigin;
  let forwardedFrom = null;
  if (origin && (origin.author || origin.context)) {
    forwardedFrom = {};
    if (origin.author) forwardedFrom.author = origin.author;
    if (origin.displayName) forwardedFrom.displayName = origin.displayName;
    if (origin.pfp) forwardedFrom.pfp = origin.pfp;
    if (origin.timestamp) forwardedFrom.timestamp = origin.timestamp;
    if (origin.context) forwardedFrom.context = origin.context;
  }
  try {
    if (type === 'dm') {
      const extra = { forwarded: true, forwardedBy: CU.username };
      if (forwardedFrom) extra.forwardedFrom = forwardedFrom;
      await FortizedSocial.sendDMMessage(CU.username, target, text, extra);
      toast('Forwarded to ' + target, 'success');
    } else if (type === 'gc') {
      const msgObj = { from: CU.username, text, time: new Date().toLocaleTimeString('en-GB', {hour:'2-digit',minute:'2-digit'}), timestamp: Date.now(), forwarded: true, forwardedBy: CU.username };
      if (forwardedFrom) msgObj.forwardedFrom = forwardedFrom;
      await firebase.database().ref('groupChats/' + target + '/messages').push(msgObj);
      toast('Forwarded to group chat', 'success');
    } else if (type === 'bastion') {
      const [bi, chId] = target.split(':');
      const b = CU.bastions?.[parseInt(bi)];
      if (b) {
        const msgObj = { from: CU.username, text, time: new Date().toLocaleTimeString('en-GB', {hour:'2-digit',minute:'2-digit'}), timestamp: Date.now(), forwarded: true, forwardedBy: CU.username };
        if (forwardedFrom) msgObj.forwardedFrom = forwardedFrom;
        await firebase.database().ref('bastionMsgs/' + (b.globalId || b.name) + '/' + chId).push(msgObj);
        toast('Forwarded to #' + ((b.channels||[]).find(c=>c.id===chId)?.name || chId), 'success');
      }
    }
  } catch { toast('Forward failed', 'error'); }
  finally { _forwardOrigin = null; }
}
async function forwardToDM(username) {
  return forwardTo('dm', username);
}
function addReactionUI(eOrMsgId, msgIdOrCtx, contextOrNone) {
  // Support both (event, msgId, context) and (msgId, context) signatures
  let x, y, msgId, context, trigger = null;
  if (eOrMsgId && typeof eOrMsgId === 'object' && eOrMsgId.clientX !== undefined) {
    try { eOrMsgId.stopPropagation(); } catch {}
    x = eOrMsgId.clientX; y = eOrMsgId.clientY;
    trigger = eOrMsgId.currentTarget || eOrMsgId.target || null;
    msgId = msgIdOrCtx; context = contextOrNone;
  } else {
    x = window.innerWidth / 2 - 100; y = window.innerHeight / 2 - 100;
    msgId = eOrMsgId; context = msgIdOrCtx;
  }
  _openReactionEmojiPicker(x, y, msgId, context, trigger);
}
function _openReactionEmojiPicker(x, y, msgId, context, trigger) {
  // Reuse the EXACT SAME chatbar emoji picker — just flip it into reaction mode.
  // Clicking an emoji fires toggleReaction(msgId, emoji, context, _reactionSuperMode).
  document.getElementById('giphy-picker')?.remove();
  document.getElementById('sticker-picker')?.remove();
  _emojiPickerMode = 'react';
  _reactionContext = { msgId, context };
  _reactionSuperMode = false;
  activeEmojiTarget = null;

  const panel = document.getElementById('emoji-picker');
  if (!panel) return;
  panel.classList.remove('show');
  buildEmojiPicker();
  // Inject a super-reaction toggle into the footer
  const hoverLabel = panel.querySelector('#epp-hover-label');
  if (hoverLabel) {
    const footer = hoverLabel.parentElement;
    if (footer && !footer.querySelector('.epp-super-toggle')) {
      const toggle = document.createElement('button');
      toggle.className = 'epp-super-toggle';
      toggle.type = 'button';
      toggle.id = 'epp-super-toggle';
      toggle.title = 'Toggle super-reaction (any emoji)';
      toggle.style.cssText = 'margin-left:8px;background:none;border:1px solid rgba(255,255,255,.08);color:rgba(255,255,255,.55);cursor:pointer;font-size:10.5px;font-weight:700;padding:3px 8px;border-radius:10px;letter-spacing:.04em;text-transform:uppercase;transition:all .12s;';
      toggle.innerHTML = '<span style="color:var(--accent);margin-right:3px;">★</span> Super';
      toggle.onclick = () => {
        _reactionSuperMode = !_reactionSuperMode;
        toggle.style.background = _reactionSuperMode ? 'var(--accent-dim)' : 'none';
        toggle.style.borderColor = _reactionSuperMode ? 'var(--accent)' : 'rgba(255,255,255,.08)';
        toggle.style.color = _reactionSuperMode ? 'var(--accent)' : 'rgba(255,255,255,.55)';
      };
      footer.appendChild(toggle);
    }
  }
  // Position relative to the trigger button if we have one; otherwise the click point
  const PW = Math.min(448, window.innerWidth - 16);
  const PH = 440;
  let left, top;
  if (trigger && trigger.getBoundingClientRect) {
    const r = trigger.getBoundingClientRect();
    left = Math.min(Math.max(8, r.right - PW), window.innerWidth - PW - 8);
    top = r.top - PH - 8;
    if (top < 8) top = Math.min(r.bottom + 8, window.innerHeight - PH - 8);
  } else {
    left = x; top = y - PH - 8;
    if (top < 8) top = y + 8;
    if (left + PW > window.innerWidth - 8) left = window.innerWidth - PW - 8;
    if (top + PH > window.innerHeight - 8) top = window.innerHeight - PH - 8;
  }
  panel.style.cssText = `left:${Math.max(8,left)}px;top:${Math.max(8,top)}px;bottom:auto;`;
  panel.classList.add('show');
  setTimeout(() => panel.querySelector('.epp-search-inp')?.focus(), 80);
  // Close on outside click — use click (not mousedown) and a longer delay so the
  // click that opened us never reaches this handler.
  setTimeout(() => {
    function _close(e) {
      if (!panel.contains(e.target)) {
        panel.classList.remove('show');
        _emojiPickerMode = 'insert'; _reactionContext = null; _reactionSuperMode = false;
        document.removeEventListener('click', _close, true);
      }
    }
    document.addEventListener('click', _close, true);
  }, 200);
}
