async function promptJoinPublicBastion(bastionId){
  try{
    const all=await FortizedSocial.getGlobalBastions()||{};
    const bid = (bastionId||'').trim();
    const bidLower = bid.toLowerCase();
    // Priority 1: Exact ID match (most reliable)
    let b = Object.values(all).find(x => x.id === bid);
    // Priority 2: Case-insensitive ID match
    if (!b) b = Object.values(all).find(x => (x.id||'').toLowerCase() === bidLower);
    // Priority 3: Name match (only as last resort for direct name lookups)
    if (!b) b = Object.values(all).find(x => (x.name||'').toLowerCase() === bidLower);
    // Fallback: check current user's bastions only (no longer fetches ALL users)
    if(!b){
      try{
        const users=[CU];
        for(const u of users){
          // Prefer globalId match over name match
          const found=(u.bastions||[]).find(ub=>(ub.globalId||'').toLowerCase()===bidLower) ||
                      (u.bastions||[]).find(ub=>(ub.name||'').toLowerCase()===bidLower);
          if(found){b={...found,id:found.globalId||found.name,owner:found.owner||u.username};break;}
        }
      }catch(e){console.warn('[Bastion] User lookup failed:',e?.message);}
    }
    if(!b){toast('Bastion not found. Try the exact name or use an invite link.','error');return;}
    const gid=b.id||b.globalId;
    const already=(CU.bastions||[]).some(ub=> (gid && ub.globalId===gid) || (gid && ub.globalId===(b.globalId||b.id)));
    if(already){toast('Already joined!','info');openBastion((CU.bastions||[]).findIndex(ub=> (gid && ub.globalId===gid)));return;}
    if(b.public===false){toast('This bastion is invite-only. Ask the owner for an invite link.','error');return;}
    if((b.applicationQuestions||[]).length){showBastionApplicationForm(b);return;}
    const localB={name:b.name,emblem:b.emblem||'🏰',icon:b.icon||null,banner:b.banner||null,tagline:b.tagline||'',desc:b.desc||'',channels:b.channels||[{name:'general',type:'text',desc:'General chat'}],roles:b.roles||[],owner:b.owner,globalId:gid,public:b.public,memberRoles:b.memberRoles||{},automod:b.automod||{},boostLevel:b.boostLevel||0,customEmojis:b.customEmojis||[],invites:b.invites||[],moodDisabled:b.moodDisabled||false,moodLocked:b.moodLocked||false,lockedMood:b.lockedMood||'',customMood:b.customMood||null,memberCount:b.memberCount||1};
    CU.bastions=[...(CU.bastions||[]),localB];
    // Persist user record immediately (skip 300ms debounce) so a refresh
    // right after join doesn't lose the membership, and verify the row
    // actually made it to the DB before broadcasting the join.
    await saveUser(true);
    await FortizedSocial.addBastionMember(gid,CU.username);
    // Safety re-save: if any realtime sync clobbered CU.bastions between
    // the first save and addBastionMember, this forces our local state
    // (which includes the new bastion) back onto the row.
    try { if (!(CU.bastions||[]).some(x=>x.globalId===gid)) CU.bastions=[...(CU.bastions||[]),localB]; await saveUser(true); } catch(_){}
    // Update member count in global
    try{
      const members=await FortizedSocial.getBastionMembers(gid)||[];
      const _gb=await FortizedSocial.getGlobalBastion(gid);
      if(_gb){_gb.memberCount=members.length;await FortizedSocial.saveGlobalBastion(gid,_gb);}
    }catch(e){console.warn('[Bastion] Member count update failed:',e?.message);}
    renderRailBastions();
    toast('Joined '+b.name+'!','success');
    openBastion(CU.bastions.length-1);
    // Welcome system message in first text channel (uses custom welcome if configured)
    if (localB.welcomeEnabled !== false) {
      const wName = CU.displayName||CU.username;
      const wTemplate = localB.welcomeMessage || '**{user}** joined the bastion. Welcome!';
      const membersList = await FortizedSocial.getBastionMembers(gid).catch(()=>[]) || [];
      const wMsg = wTemplate.replace(/\{user\}/g, '**'+wName+'**').replace(/\{bastion\}/g, '**'+b.name+'**').replace(/\{count\}/g, String(membersList.length||1));
      const wChName = localB.welcomeChannel || (b.channels||[]).find(ch=>ch.type==='text')?.name || 'general';
      try { await FortizedSocial.sendBastionChannelMessage(gid, wChName, '__system__', wMsg); } catch(e) { console.warn('[Bastion] Welcome msg failed:', e?.message); }
    }
  }catch(e){toast('Failed to join bastion. Please try again.','error');console.error('[Bastion] Join failed:', e);}
}

