let _selectedBastionTemplate = null;
let _selectedRoleTemplate = null;

function _renderCBRoleTemplateRow() {
  const row = document.getElementById('cb-role-tmpl-row');
  if (!row) return;
  row.innerHTML = Object.entries(ROLE_TEMPLATES).map(([key,t]) => {
    const sel = _selectedRoleTemplate === key;
    return `<div onclick="selectCBRoleTemplate('${key}')" style="padding:6px 12px;border:1.5px solid ${sel?'var(--accent-mid)':'var(--border)'};border-radius:10px;cursor:pointer;font-size:11.5px;font-weight:600;color:${sel?'var(--accent)':'rgba(255,255,255,.5)'};background:${sel?'var(--accent-dim)':'transparent'};transition:all .12s;display:flex;align-items:center;gap:5px;">${t.emoji} ${t.name}</div>`;
  }).join('');
}
function selectCBRoleTemplate(key) {
  _selectedRoleTemplate = _selectedRoleTemplate === key ? null : key;
  _renderCBRoleTemplateRow();
}

function renderBastionTemplateGrid() {
  const grid = document.getElementById('template-grid');
  if (!grid) return;
  const templates = [
    {id:'gaming',emoji:'🎮',name:'Game Hall',desc:'Play together'},
    {id:'fellowship',emoji:'🤝',name:'Fellowship',desc:'Friends & community'},
    {id:'guild',emoji:'⚔️',name:'Guild',desc:'Team & coordination'},
    {id:'study',emoji:'📚',name:'Study Circle',desc:'Learn together'},
    {id:'artisan',emoji:'🎨',name:'Artisans',desc:'Create & showcase'},
    {id:'academy',emoji:'🎓',name:'Academy',desc:'Teaching & courses'},
  ];
  const chIcon={text:'#',voice:ftzIcon('mic','10'),forum:ftzIcon('chat','10'),announcement:ftzIcon('megaphone','10'),poll:ftzIcon('ballot','10')};
  grid.innerHTML = templates.map(t => {
    const tmpl=BASTION_TEMPLATES[t.id];
    const previewChs=(tmpl?.channels||[]).slice(0,5).map(c=>`<div style="display:flex;align-items:center;gap:4px;font-size:10.5px;color:var(--muted-light);padding:2px 0;"><span style="font-size:10px;opacity:.7;">${chIcon[c.type]||'#'}</span>${c.name}</div>`).join('');
    const previewRoles=(tmpl?.roles||[]).slice(0,3).map(r=>`<span style="font-size:9px;padding:1px 6px;border-radius:var(--radius-pill);border:1px solid ${r.color}44;color:${r.color};background:${r.color}11;">${r.name}</span>`).join(' ');
    return `<div class="tmpl-card" id="tmpl-${t.id}" onclick="selectBastionTemplate('${t.id}','${t.emoji}','${t.name}')" style="position:relative;">
      <div class="tmpl-emoji">${t.emoji}</div>
      <div class="tmpl-name">${t.name}</div>
      <div class="tmpl-desc">${t.desc}</div>
      <div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border);">
        <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:4px;">Channels</div>
        ${previewChs}
        ${(tmpl?.channels||[]).length>5?`<div style="font-size:10px;color:var(--muted);">+${tmpl.channels.length-5} more</div>`:''}
        <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-top:6px;margin-bottom:3px;">Roles</div>
        <div style="display:flex;flex-wrap:wrap;gap:3px;">${previewRoles}</div>
      </div>
    </div>`;
  }).join('');
}
function showBastionStep1() {
  _selectedBastionTemplate = null;
  _importedTemplateData = null;
  const s1=document.getElementById('cb-step-1');
  const st=document.getElementById('cb-step-templates');
  const sf=document.getElementById('cb-step-form');
  const si=document.getElementById('cb-step-import');
  const banner=document.getElementById('cb-import-banner');
  if(s1){s1.style.display='';} if(st){st.style.display='none';} if(sf){sf.style.display='none';} if(si){si.style.display='none';}
  if(banner){banner.style.display='none';banner.innerHTML='';}
  // reset template selection
  document.querySelectorAll('[id^=tmpl-]').forEach(el=>el.classList.remove('sel'));
}

function showBastionStep2(type, fromTemplate) {
  const s1=document.getElementById('cb-step-1');
  const st=document.getElementById('cb-step-templates');
  const sf=document.getElementById('cb-step-form');
  const si=document.getElementById('cb-step-import');
  if(s1) s1.style.display='none';
  if(si) si.style.display='none';
  if(type==='template' && !fromTemplate) {
    if(st) { st.style.display=''; renderBastionTemplateGrid(); } if(sf) sf.style.display='none';
  } else {
    if(st) st.style.display='none'; if(sf) sf.style.display='';
    if(_selectedBastionTemplate) {
      const nameInp=document.getElementById('cb-name');
      if(nameInp && !nameInp.value) nameInp.value = _selectedBastionTemplate.name;
      const iconPrev=document.getElementById('cb-icon-preview');
      if(iconPrev) iconPrev.innerHTML = '<span style="font-family:\'Syne\',sans-serif;font-weight:700;font-size:18px;color:var(--accent);">' + (_selectedBastionTemplate.name||'B')[0].toUpperCase() + '</span>';
    }
    _renderCBRoleTemplateRow();
    setTimeout(()=>{document.getElementById('cb-name')?.focus();},80);
  }
}

function selectBastionTemplate(id, emoji, name) {
  _selectedBastionTemplate = {id, emoji, name};
  document.querySelectorAll('[id^=tmpl-]').forEach(el=>{
    el.classList.remove('sel');
    el.style.borderColor='var(--border)';
    el.style.background='transparent';
  });
  const el=document.getElementById('tmpl-'+id);
  if(el){
    el.classList.add('sel');
    el.style.borderColor='var(--accent-mid)';
    el.style.background='var(--accent-dim)';
  }
}

// Preview icon during bastion creation
function previewCBIcon(e) {
  const file = e.target.files[0]; if (!file) return;
  if (file.size > 8*1024*1024) { toast('Max 8 MB','error'); return; }
  const reader = new FileReader();
  reader.onload = ev => {
    const dataUrl = ev.target.result;
    cbIconData = dataUrl;
    const preview = document.getElementById('cb-icon-preview');
    if (preview) preview.innerHTML = '<img src="'+dataUrl+'" style="width:100%;height:100%;object-fit:cover;border-radius:13px;">';
  };
  reader.readAsDataURL(file);
}

