async function importDiscordTemplate() {
  const linkInput = document.getElementById('cb-discord-link');
  const errEl = document.getElementById('cb-import-error');
  const previewEl = document.getElementById('cb-import-preview');
  const link = (linkInput?.value||'').trim();
  if(errEl) errEl.textContent = '';

  // Validate discord.new link format
  const discordMatch = link.match(/discord\.new\/([A-Za-z0-9]+)/);
  if(!discordMatch) {
    if(errEl) errEl.textContent = 'Invalid Discord template link. Expected format: https://discord.new/CODE';
    return;
  }
  const templateCode = discordMatch[1];

  if(previewEl) previewEl.innerHTML = '<div style="text-align:center;padding:16px;color:var(--muted);font-size:12.5px;"><div style="margin-bottom:6px;">Fetching template...</div><div style="width:24px;height:24px;border:2px solid rgba(255,255,255,.1);border-top-color:var(--accent);border-radius:50%;animation:spin .6s linear infinite;margin:0 auto;"></div></div>';

  try {
    // Fetch the Discord template via their API
    const resp = await fetch('https://discord.com/api/v10/guilds/templates/' + encodeURIComponent(templateCode));
    if(!resp.ok) throw new Error('Template not found or expired (HTTP ' + resp.status + ')');
    const data = await resp.json();

    // Parse the template into Fortized format
    const guild = data.serialized_source_guild || {};
    const name = data.name || guild.name || 'Imported Server';
    const desc = data.description || guild.description || '';

    // Map Discord channels to Fortized channels
    const discordChannels = guild.channels || [];
    // Build category map
    const categoryMap = {};
    const categories = [];
    discordChannels.filter(ch => ch.type === 4).forEach(cat => {
      const catId = 'cat_' + (cat.id || Math.random().toString(36).slice(2));
      categoryMap[cat.id] = catId;
      categories.push({id: catId, name: cat.name});
    });

    const typeMap = {0:'text', 2:'voice', 5:'announcement', 13:'forum', 15:'forum'};
    const channels = discordChannels.filter(ch => ch.type !== 4).map(ch => {
      const mapped = {
        name: ch.name || 'unnamed',
        type: typeMap[ch.type] || 'text',
        desc: ch.topic || '',
      };
      if(ch.parent_id != null && categoryMap[ch.parent_id]) {
        mapped.categoryId = categoryMap[ch.parent_id];
      }
      if(ch.nsfw) mapped.nsfw = true;
      return mapped;
    });

    // Map Discord roles to Fortized roles
    const roleColors = ['#fbbf24','#60a5fa','#3ecf6e','#a78bfa','#f87171','#22d3ee','#e879f9','#fb923c','#9ca3af'];
    const discordRoles = (guild.roles || []).filter(r => r.name !== '@everyone').sort((a,b) => (b.position||0) - (a.position||0));
    const roles = discordRoles.map((r, i) => ({
      id: r.name.toLowerCase().replace(/[^a-z0-9]/g,'_') || 'role_'+i,
      name: r.name,
      color: r.color ? '#'+r.color.toString(16).padStart(6,'0') : (roleColors[i % roleColors.length]),
      permissions: (r.permissions & 0x8) ? ['administrator'] : ['send_messages','read_history','add_reactions'],
      priority: Math.max(1, (discordRoles.length - i) * 10),
      displayAsTag: i < 3,
    }));

    // Always ensure admin + member roles exist
    if(!roles.find(r=>r.permissions?.includes('administrator'))) {
      roles.unshift({id:'admin',name:'Admin',color:'#fbbf24',permissions:['administrator'],priority:100,displayAsTag:true});
    }
    if(!roles.find(r=>r.id==='member'||r.name==='Member')) {
      roles.push({id:'member',name:'Member',color:'#60a5fa',permissions:['send_messages','read_history','add_reactions'],priority:1,displayAsTag:false});
    }

    _importedTemplateData = {
      source: 'discord',
      name, desc,
      channels: channels.length ? channels : [{name:'general',type:'text',desc:'General discussion'}],
      categories,
      roles,
      emblem: '🏰',
    };

    // Show preview
    const chIcon = {text:'#',voice:ftzIcon('mic','12'),forum:ftzIcon('chat','12'),announcement:ftzIcon('megaphone','12'),poll:ftzIcon('ballot','12')};
    const previewChs = channels.slice(0,8).map(c=>`<div class="tp-ch"><span class="tp-ch-icon">${chIcon[c.type]||'#'}</span>${escapeHTML(c.name)}</div>`).join('');
    const previewRoles = roles.slice(0,5).map(r=>`<span class="tp-role-pill" style="color:${r.color};background:${r.color}15;border:1px solid ${r.color}33;">${escapeHTML(r.name)}</span>`).join('');
    previewEl.innerHTML = `<div class="tmpl-preview">
      <div class="tp-header">
        <div class="tp-icon" style="background:rgba(88,101,242,.12);"><svg width="26" height="26" viewBox="0 0 24 24" fill="#5865F2"><path d="M20.317 4.37a19.791 19.791 0 00-4.885-1.515.074.074 0 00-.079.037c-.21.375-.444.864-.608 1.25a18.27 18.27 0 00-5.487 0 12.64 12.64 0 00-.617-1.25.077.077 0 00-.079-.037A19.736 19.736 0 003.677 4.37a.07.07 0 00-.032.027C.533 9.046-.32 13.58.099 18.057a.082.082 0 00.031.057 19.9 19.9 0 005.993 3.03.078.078 0 00.084-.028z"/></svg></div>
        <div>
          <div class="tp-name">${escapeHTML(name)}</div>
          <div class="tp-desc">${escapeHTML(desc||'Discord server template')}</div>
        </div>
      </div>
      <div class="tp-stats">
        <div class="tp-stat">#️ ${channels.length} channels</div>
        <div class="tp-stat">🛡️ ${roles.length} roles</div>
        ${categories.length?`<div class="tp-stat">📁 ${categories.length} categories</div>`:''}
      </div>
      <div class="tp-channels">
        <div class="tp-section-label">Channels</div>
        ${previewChs}
        ${channels.length>8?`<div style="font-size:10.5px;color:var(--muted);padding:2px 0;">+${channels.length-8} more</div>`:''}
      </div>
      <div class="tp-roles">
        <div class="tp-section-label">Roles</div>
        <div class="tp-role-pills">${previewRoles}${roles.length>5?`<span style="font-size:9.5px;color:var(--muted);padding:2px 4px;">+${roles.length-5}</span>`:''}</div>
      </div>
    </div>`;
    const continueBtn = document.getElementById('cb-import-continue-btn');
    if(continueBtn) continueBtn.style.display = '';
  } catch(e) {
    if(errEl) errEl.textContent = e.message || 'Failed to fetch Discord template';
    if(previewEl) previewEl.innerHTML = '';
  }
}

async function importFortizedTemplate() {
  const linkInput = document.getElementById('cb-fortized-link');
  const errEl = document.getElementById('cb-import-error');
  const previewEl = document.getElementById('cb-import-preview');
  const link = (linkInput?.value||'').trim();
  if(errEl) errEl.textContent = '';

  // Extract template ID from link
  const ftzMatch = link.match(/template\/([A-Za-z0-9_-]+)/);
  if(!ftzMatch) {
    if(errEl) errEl.textContent = 'Invalid Fortized template link. Expected format: https://fortized.com/template/ID';
    return;
  }
  const templateId = ftzMatch[1];

  if(previewEl) previewEl.innerHTML = '<div style="text-align:center;padding:16px;color:var(--muted);font-size:12.5px;"><div style="margin-bottom:6px;">Fetching template...</div><div style="width:24px;height:24px;border:2px solid rgba(255,255,255,.1);border-top-color:var(--accent);border-radius:50%;animation:spin .6s linear infinite;margin:0 auto;"></div></div>';

  try {
    const snap = await firebase.database().ref('bastionTemplates/' + templateId).get();
    if(!snap.exists()) throw new Error('Template not found. It may have been deleted or the link is invalid.');
    const tmplData = snap.val();

    _importedTemplateData = {
      source: 'fortized',
      name: tmplData.name || 'Imported Bastion',
      desc: tmplData.desc || '',
      channels: tmplData.channels || [{name:'general',type:'text',desc:'General discussion'}],
      categories: tmplData.categories || [],
      roles: tmplData.roles || [{id:'admin',name:'Admin',color:'#fbbf24',permissions:['administrator'],priority:100,displayAsTag:true},{id:'member',name:'Member',color:'#60a5fa',permissions:['send_messages','read_history','add_reactions'],priority:1,displayAsTag:false}],
      emblem: tmplData.emblem || '🏰',
      icon: tmplData.icon || null,
      banner: tmplData.banner || null,
    };

    const chIcon = {text:'#',voice:ftzIcon('mic','12'),forum:ftzIcon('chat','12'),announcement:ftzIcon('megaphone','12'),poll:ftzIcon('ballot','12')};
    const previewChs = _importedTemplateData.channels.slice(0,8).map(c=>`<div class="tp-ch"><span class="tp-ch-icon">${chIcon[c.type]||'#'}</span>${escapeHTML(c.name)}</div>`).join('');
    const previewRoles = _importedTemplateData.roles.slice(0,5).map(r=>`<span class="tp-role-pill" style="color:${r.color};background:${r.color}15;border:1px solid ${r.color}33;">${escapeHTML(r.name)}</span>`).join('');
    previewEl.innerHTML = `<div class="tmpl-preview">
      <div class="tp-header">
        <div class="tp-icon">${_importedTemplateData.icon?`<img src="${_importedTemplateData.icon}">`:(_importedTemplateData.emblem||'🏰')}</div>
        <div>
          <div class="tp-name">${escapeHTML(_importedTemplateData.name)}</div>
          <div class="tp-desc">${escapeHTML(_importedTemplateData.desc||'Fortized bastion template')}</div>
        </div>
      </div>
      <div class="tp-stats">
        <div class="tp-stat">#️ ${_importedTemplateData.channels.length} channels</div>
        <div class="tp-stat">🛡️ ${_importedTemplateData.roles.length} roles</div>
        ${(_importedTemplateData.categories||[]).length?`<div class="tp-stat">📁 ${_importedTemplateData.categories.length} categories</div>`:''}
        ${tmplData.createdBy?`<div class="tp-stat">👤 by @${escapeHTML(tmplData.createdBy)}</div>`:''}
      </div>
      <div class="tp-channels">
        <div class="tp-section-label">Channels</div>
        ${previewChs}
        ${_importedTemplateData.channels.length>8?`<div style="font-size:10.5px;color:var(--muted);padding:2px 0;">+${_importedTemplateData.channels.length-8} more</div>`:''}
      </div>
      <div class="tp-roles">
        <div class="tp-section-label">Roles</div>
        <div class="tp-role-pills">${previewRoles}${_importedTemplateData.roles.length>5?`<span style="font-size:9.5px;color:var(--muted);padding:2px 4px;">+${_importedTemplateData.roles.length-5}</span>`:''}</div>
      </div>
    </div>`;
    const continueBtn = document.getElementById('cb-import-continue-btn');
    if(continueBtn) continueBtn.style.display = '';
  } catch(e) {
    if(errEl) errEl.textContent = e.message || 'Failed to fetch template';
    if(previewEl) previewEl.innerHTML = '';
  }
}

function continueFromImportedTemplate() {
  if(!_importedTemplateData) return;
  const si = document.getElementById('cb-step-import');
  const sf = document.getElementById('cb-step-form');
  const banner = document.getElementById('cb-import-banner');
  if(si) si.style.display='none';
  if(sf) sf.style.display='';

  // Pre-fill form with imported data
  const nameInp = document.getElementById('cb-name');
  const descInp = document.getElementById('cb-desc');
  const iconPrev = document.getElementById('cb-icon-preview');
  if(nameInp) nameInp.value = _importedTemplateData.name || '';
  if(descInp) descInp.value = _importedTemplateData.desc || '';
  if(_importedTemplateData.emblem && iconPrev) iconPrev.textContent = _importedTemplateData.emblem;
  // Emoji emblems disabled — ignore imported emblem

  // Show import info banner
  if(banner) {
    const src = _importedTemplateData.source === 'discord' ? 'Discord server' : 'Fortized bastion';
    banner.style.display = '';
    banner.innerHTML = `<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:rgba(62,207,110,.06);border:1px solid rgba(62,207,110,.15);border-radius:10px;margin-bottom:14px;font-size:12px;color:rgba(62,207,110,.8);font-weight:600;">
      <span style="font-size:15px;">✓</span> Importing from ${src} template — ${_importedTemplateData.channels.length} channels, ${_importedTemplateData.roles.length} roles
    </div>`;
  }
  _renderCBRoleTemplateRow();
  setTimeout(()=>{nameInp?.focus();},80);
}

// ── Bastion Template Link System ──
async function generateBastionTemplateLink(bastionIdx) {
  const b = CU.bastions?.[bastionIdx != null ? bastionIdx : curBastion];
  if(!b) { toast('No bastion selected','error'); return; }

  const templateId = (CU.username + '_tmpl_' + Date.now()).replace(/[^a-z0-9_]/gi,'');
  const tmplData = {
    name: b.name,
    desc: b.desc || '',
    emblem: b.emblem || '🏰',
    icon: b.icon || null,
    banner: b.banner || null,
    channels: (b.channels||[]).map(ch => ({name:ch.name, type:ch.type, desc:ch.desc||'', categoryId:ch.categoryId||null, nsfw:ch.nsfw||false})),
    categories: b.categories || [],
    roles: (b.roles||[]).map(r => ({id:r.id, name:r.name, color:r.color, permissions:r.permissions||[], priority:r.priority||0, displayAsTag:r.displayAsTag||false})),
    createdBy: CU.username,
    createdAt: new Date().toISOString(),
    bastionName: b.name,
  };

  try {
    await firebase.database().ref('bastionTemplates/' + templateId).set(tmplData);
    const link = 'https://fortized.com/template/' + templateId;
    b.templateLink = link;
    b.templateId = templateId;
    await saveUser();
    _syncBastionToGlobal(bastionIdx != null ? bastionIdx : curBastion);
    toast('Template link generated!', 'success');
    return link;
  } catch(e) {
    console.error('[Template] Link generation failed:', e); toast('Failed to generate template link. Please try again.','error');
    return null;
  }
}

async function copyBastionTemplateLink(link) {
  try {
    await navigator.clipboard.writeText(link);
    toast('Template link copied!','success');
  } catch {
    // Fallback
    const ta = document.createElement('textarea');
    ta.value = link; document.body.appendChild(ta); ta.select();
    document.execCommand('copy'); document.body.removeChild(ta);
    toast('Template link copied!','success');
  }
}

async function regenerateBastionTemplateLink(bastionIdx) {
  const b = CU.bastions?.[bastionIdx != null ? bastionIdx : curBastion];
  if(!b) return;
  // Delete old template if exists
  if(b.templateId) {
    try { await firebase.database().ref('bastionTemplates/' + b.templateId).remove(); } catch(e) { console.warn('[Bastion] Template remove failed:', e?.message); }
  }
  b.templateLink = null;
  b.templateId = null;
  const link = await generateBastionTemplateLink(bastionIdx);
  if(link) renderBSettingsMain('templates');
}

async function deleteBastionTemplateLink(bastionIdx) {
  const b = CU.bastions?.[bastionIdx != null ? bastionIdx : curBastion];
  if(!b) return;
  if(b.templateId) {
    try { await firebase.database().ref('bastionTemplates/' + b.templateId).remove(); } catch(e) { console.warn('[Bastion] Template remove failed:', e?.message); }
  }
  b.templateLink = null;
  b.templateId = null;
  await saveUser();
  _syncBastionToGlobal(bastionIdx != null ? bastionIdx : curBastion);
  toast('Template link deleted','info');
  renderBSettingsMain('templates');
}

async function createBastion() {
  const name = document.getElementById('cb-name')?.value?.trim();
  const desc = document.getElementById('cb-desc')?.value?.trim();
  const err = document.getElementById('cb-error');
  if (!name) { if(err)err.textContent='Bastion name is required'; return; }
  if (err) err.textContent = '';
  const createBtn = document.querySelector('#modal-create-bastion .btn-a, #modal-create-bastion .ftz-btn-accent');
  if (createBtn) { createBtn.classList.add('btn-loading'); createBtn.disabled = true; }

  // Check if we have imported template data
  const imported = _importedTemplateData;
  const tmpl = !imported && _selectedBastionTemplate && BASTION_TEMPLATES[_selectedBastionTemplate.id];

  let _chs, _roles, _cats;
  if(imported) {
    _chs = imported.channels;
    _roles = imported.roles.map(r=>({...r}));
    _cats = imported.categories || [];
    // Ensure admin role has full perms
    _roles.forEach(r => { if(r.permissions?.includes('administrator')) r.permissions = PERMISSIONS.map(p=>p[0]); });
  } else if(tmpl) {
    _chs = tmpl.channels;
    _roles = tmpl.roles.map(r=>({...r, permissions: r.id==='admin' ? PERMISSIONS.map(p=>p[0]) : (r.permissions||['send_messages','read_history','add_reactions'])}));
    _cats = [];
  } else {
    _chs = [{name:'general',type:'text',desc:'General discussion'},{name:'announcements',type:'text',desc:'Important announcements'},{name:'lounge',type:'voice',desc:'Voice lounge'}];
    _cats = [];
    const _roleTmpl = _selectedRoleTemplate && ROLE_TEMPLATES[_selectedRoleTemplate];
    _roles = _roleTmpl
      ? _roleTmpl.roles.map(r=>({...r}))
      : [
          {id:'admin',name:'Admin',color:'#fbbf24',permissions:PERMISSIONS.map(p=>p[0])},
          {id:'member',name:'Member',color:'#60a5fa',permissions:['send_messages','read_history','add_reactions']},
        ];
  }
  _selectedRoleTemplate = null;
  _importedTemplateData = null;

  const bastion = {
    name, desc: desc||imported?.desc||tmpl?.description||'',
    tagline: '',
    emblem: null,
    icon: cbIconData||(imported?.icon)||null,
    banner: imported?.banner||null,
    channels: _chs,
    categories: _cats,
    roles: _roles,
    owner: CU.username,
    public: cbVisibility === 'public',
    memberRoles: {[CU.username]:['admin']},
    automod: {blockLinks:false,antiSpam:true,antiRaid:false,slowMode:false,blockInvites:false,imageOnly:false,newAccountFilter:false,profanityFilter:false,mentionLimit:10,keywords:[]},
    boostLevel: 0,
    customEmojis: [],
    invites: [],
    createdAt: new Date().toISOString(),
    memberCount: 1,
  };

  CU.bastions = [...(CU.bastions||[]), bastion];
  await saveUser();

  // Register globally
  try {
    const globalId = CU.username+'_'+Date.now();
    const globalB = {...bastion, owner: CU.username, id: globalId};
    await FortizedSocial.saveGlobalBastion(globalId, globalB);
    CU.bastions[CU.bastions.length-1].globalId = globalId;
    await FortizedSocial.addBastionMember(globalId, CU.username);
    await saveUser();
  } catch (e) { console.warn('[Bastion] global save failed', e); }

  if (createBtn) { createBtn.classList.remove('btn-loading'); createBtn.disabled = false; }
  closeModal('modal-create-bastion');
  renderRailBastions();
  cbIconData = null;
  cbSelectedEmoji = null;
  // Track create_bastion quest completion
  if (!CU.completedQuests?.includes('create_bastion')) {
    CU.completedQuests = [...(CU.completedQuests||[]), 'create_bastion'];
    saveUser(true);
  }
  toast(`${name} created!`, 'success');
  showFeedbackToast('creating a Bastion', 'bastion_create');
  openBastion(CU.bastions.length - 1);
}

