async function _submitAdReport(adId) {
  const reason = document.querySelector('input[name="ad-report-reason"]:checked')?.value;
  const context = document.getElementById('ad-report-context')?.value?.trim();
  const errEl = document.getElementById('ad-report-error');
  if (!reason) { if (errEl) errEl.textContent = 'Please select a reason.'; return; }
  let adSnap = null;
  try {
    const ads = await FortizedSocial.getGlobalAds();
    adSnap = (ads || []).find(a => a && (a.id === adId || a.adId === adId)) || null;
  } catch(_){}
  const now = new Date().toISOString();
  const report = {
    id: 'rpt_' + Date.now(),
    type: 'ad',
    adId,
    adTitle: adSnap?.title || adSnap?.name || '',
    adImage: adSnap?.image || adSnap?.imageUrl || adSnap?.media || '',
    adTarget: adSnap?.link || adSnap?.target || adSnap?.url || '',
    adBastion: adSnap?.bastion || adSnap?.bastionName || '',
    adOwner: adSnap?.owner || adSnap?.createdBy || adSnap?.author || '',
    username: adSnap?.owner || adSnap?.createdBy || adSnap?.author || '',
    reason,
    context,
    reporter: CU?.username,
    reportedAt: now,
    createdAt: now,
    status: 'pending'
  };
  try { await FortizedSocial.adminSaveReport(report); }
  catch(e) { console.warn('[Report] Ad report save failed:', e); }
  try {
    const existing = JSON.parse(localStorage.getItem('ftz_reports')||'[]');
    if (!existing.find(r => r.id === report.id)) existing.push(report);
    localStorage.setItem('ftz_reports', JSON.stringify(existing));
  } catch(_){}
  document.getElementById('modal-report-ad')?.remove();
  toast('Ad reported. Our Safety team will review it.', 'success');
}

// ═══════════════════════════════════════════════════════
// ANNOUNCEMENT SYSTEM — "What's New"
// ═══════════════════════════════════════════════════════

// ANNOUNCEMENT SYSTEM — "What's New"
// ═══════════════════════════════════════════════════════
// The latest post in the Forum's `announcements` category is shown as a
// dismissible update card. It appears ONCE per app load (or refresh) so
// it doesn't get in the way as you move around the app. A new post in
// the forum surfaces a fresh card on the next refresh.

let _latestForumAnnouncement = null;
let _announcementShownThisSession = false;

async function _checkForAnnouncements() {
  try {
    const threads = await FortizedSocial.getForumThreads('announcements', 5, 0);
    if (!Array.isArray(threads) || !threads.length) return;
    const recent = [...threads]
      .filter(t => t && t.id)
      .sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0))[0];
    if (!recent) return;
    _latestForumAnnouncement = recent;
    _maybeShowAnnouncementModal();
  } catch(e) { console.warn('[Announcements] Check failed:', e); }
}

// Build a "version key" that combines the post id with the last edit
// timestamp. Editing the post bumps edited_at so the key changes, which
// re-surfaces the card even if the user previously ticked "Don't show
// this again". A brand-new post also has its own id, so it's covered.
function _announcementSeenKey(post) {
  if (!post || !post.id) return '';
  const stamp = post.edited_at || post.updated_at || post.created_at || '';
  return post.id + '@' + stamp;
}

// Surface the cached announcement, but only once per session. Refreshing
// the page resets the flag so the card returns on the next load.
function _maybeShowAnnouncementModal() {
  if (_announcementShownThisSession) return;
  const a = _latestForumAnnouncement;
  if (!a || !a.id) return;
  if (document.getElementById('modal-whats-new')) return;
  let seen = [];
  try { seen = JSON.parse(localStorage.getItem('ftz_seen_forum_announcements') || '[]'); } catch(_) {}
  const key = _announcementSeenKey(a);
  // Treat both legacy bare-id entries and new versioned keys as "seen"
  // so existing users don't suddenly get the modal again on first load.
  if (seen.includes(key) || seen.includes(a.id)) return;
  _announcementShownThisSession = true;
  _showWhatsNewModal(a);
}

// Pick the first usable media item for the modal hero (attachment first,
// legacy `image` field as fallback). Returns null when the post has no
// media so the card can simply omit the media block.
function _pickAnnouncementMedia(post) {
  if (!post) return null;
  const atts = Array.isArray(post.attachments) ? post.attachments : [];
  const first = atts.find(a => a && a.url && ['image','gif','video'].includes(a.type));
  if (first) return { type: first.type, url: first.url };
  if (post.image) return { type: 'image', url: post.image };
  return null;
}

// Compute upvote/downvote state for the modal so the count + button can
// reflect what the forum already knows about this thread. _forumNetScore
// includes the same staff/admin/superadmin boost that the forum applies,
// so the count in the card matches the forum exactly.
function _announcementVoteState(post) {
  const me = CU?.username || '';
  const likes = Array.isArray(post.likes) ? post.likes : [];
  return {
    score: _forumNetScore(post),
    upvoted: !!me && likes.includes(me),
  };
}

// Wire the announcement card's Open-in-Forum link so it works from any
// page: switch to the forum view first, wait for it to mount, then open
// the thread inside it.
async function _openAnnouncementInForum(threadId) {
  _dismissWhatsNew();
  try {
    if (typeof showView === 'function') showView('forum');
  } catch(_) {}
  // Forum view mounts asynchronously; poll for its container before
  // calling _forumViewThread, which assumes #forum-page-content exists.
  for (let i = 0; i < 25; i++) {
    if (document.getElementById('forum-page-content')) break;
    await new Promise(r => setTimeout(r, 60));
  }
  try { await _forumViewThread(threadId); } catch(e) { console.warn('[Announcements] open failed', e); }
}

// One-click upvote from inside the announcement card. The vote is stored
// against the same forum thread, so the count matches everywhere.
async function _toggleAnnouncementVote() {
  const post = _latestForumAnnouncement;
  if (!post?.id) return;
  if (!CU?.username) { toast('Sign in to react', 'error'); return; }
  // Optimistic UI update
  const me = CU.username;
  post.likes = Array.isArray(post.likes) ? post.likes.slice() : [];
  post.dislikes = Array.isArray(post.dislikes) ? post.dislikes.slice() : [];
  const liSet = new Set(post.likes);
  const diSet = new Set(post.dislikes);
  if (liSet.has(me)) liSet.delete(me);
  else { liSet.add(me); diSet.delete(me); }
  post.likes = [...liSet];
  post.dislikes = [...diSet];
  _refreshAnnouncementVoteUI();
  // Persist
  try { await _forumVote('thread', post.id, 1); } catch(_) {}
}

function _refreshAnnouncementVoteUI() {
  const post = _latestForumAnnouncement;
  if (!post) return;
  const { score, upvoted } = _announcementVoteState(post);
  const btn = document.getElementById('whats-new-upvote');
  if (!btn) return;
  btn.classList.toggle('on', upvoted);
  btn.querySelector('.wn-up-count').textContent = score.toLocaleString();
}

function _showWhatsNewModal(post) {
  if (document.getElementById('modal-whats-new')) return;
  const overlay = document.createElement('div');
  overlay.id = 'modal-whats-new';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;animation:fadeIn .2s;padding:24px;';
  overlay.onclick = e => { if (e.target === overlay) _dismissWhatsNew(); };

  const fmtDate = d => { try { return new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}); } catch { return ''; } };
  const authorName = post.author || 'staff';
  const initialPfp = post.author_pfp || (typeof _defaultPfpUrl === 'function' ? _defaultPfpUrl(authorName) : '');
  const fallbackPfp = typeof _defaultPfpUrl === 'function' ? _defaultPfpUrl(authorName) : '';
  const body = post.content || '';
  const media = _pickAnnouncementMedia(post);
  const { score, upvoted } = _announcementVoteState(post);

  const mediaHTML = media ? (
    media.type === 'video'
      ? `<div style="background:#0a0c12;line-height:0;"><video controls playsinline preload="metadata" src="${escapeHTML(media.url)}" style="width:100%;display:block;max-height:320px;object-fit:cover;background:#000;" onerror="this.parentElement.style.display='none'"></video></div>`
      : `<div style="background:#0a0c12;line-height:0;"><img src="${escapeHTML(media.url)}" style="width:100%;display:block;max-height:320px;object-fit:cover;" onerror="this.parentElement.style.display='none'"></div>`
  ) : '';

  overlay.innerHTML = `
    <div class="whats-new-card">
      <!-- Yellow accent bar (matches Atelier hero language) -->
      <div class="whats-new-accent"></div>
      <!-- Header -->
      <div style="display:flex;align-items:center;justify-content:space-between;padding:22px 26px 18px;border-bottom:1px solid rgba(255,255,255,.06);">
        <div style="display:flex;align-items:center;gap:10px;">
          <div>
            <div style="font-family:var(--font-display);font-size:22px;font-weight:800;color:#fff;line-height:1;letter-spacing:-.01em;display:flex;align-items:center;gap:9px;">What's New <span class="forum-official-logo" role="img" aria-label="Official Fortized" title="Official Fortized announcement" style="margin-left:0;"></span></div>
            <div style="font-size:11.5px;color:rgba(255,255,255,.35);margin-top:5px;letter-spacing:.02em;">${fmtDate(post.created_at)}${post.edited_at && post.edited_at !== post.created_at ? ` <span style="color:rgba(255,249,62,.7);" title="Edited ${new Date(post.edited_at).toLocaleString()}">· edited</span>` : ''}</div>
          </div>
        </div>
        <button onclick="_dismissWhatsNew()" aria-label="Close" style="width:30px;height:30px;border-radius:9px;border:none;background:rgba(255,255,255,.06);color:rgba(255,255,255,.55);cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .15s;" onmouseenter="this.style.background='rgba(255,255,255,.1)';this.style.color='#fff';" onmouseleave="this.style.background='rgba(255,255,255,.06)';this.style.color='rgba(255,255,255,.55)';">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </div>
      <!-- Scroll area: media (edge-to-edge) + text -->
      <div style="overflow-y:auto;flex:1;">
        ${mediaHTML}
        <div style="padding:${media ? '20px' : '22px'} 26px 24px;">
          <div style="font-family:var(--font-display);font-size:19px;font-weight:800;color:#fff;margin-bottom:12px;line-height:1.3;">${escapeHTML(post.title||'')}</div>
          <div style="font-size:13.5px;color:rgba(255,255,255,.66);line-height:1.7;word-break:break-word;">${typeof _forumRenderBody === 'function' ? _forumRenderBody(body) : escapeHTML(body)}</div>
          <!-- Author row -->
          <div style="margin-top:18px;padding-top:14px;border-top:1px solid rgba(255,255,255,.04);display:flex;align-items:center;gap:10px;">
            <img id="whats-new-pfp" src="${escapeHTML(initialPfp || fallbackPfp)}" alt="${escapeHTML(authorName)}" style="width:32px;height:32px;border-radius:50%;object-fit:cover;border:1.5px solid rgba(255,249,62,.18);background:var(--panel);flex-shrink:0;" onerror="this.onerror=null;this.src='${escapeHTML(fallbackPfp)}'">
            <div style="min-width:0;">
              <div style="font-size:12.5px;font-weight:700;color:rgba(255,255,255,.85);">${escapeHTML(authorName)}</div>
              <div style="font-size:10.5px;color:rgba(255,255,255,.35);margin-top:1px;">Posted ${fmtDate(post.created_at)}</div>
            </div>
          </div>
        </div>
      </div>
      <!-- Footer -->
      <div style="padding:14px 26px 18px;border-top:1px solid rgba(255,255,255,.06);display:flex;align-items:center;gap:14px;flex-wrap:wrap;">
        <button id="whats-new-upvote" class="${upvoted?'on':''}" onclick="_toggleAnnouncementVote()" title="Upvote" style="display:inline-flex;align-items:center;gap:6px;padding:7px 13px;border-radius:var(--radius-pill);border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.03);color:rgba(255,255,255,.6);cursor:pointer;font-family:var(--font-display);font-size:12px;font-weight:700;transition:all .15s;">
          <span style="font-size:14px;line-height:1;">👏</span>
          <span class="wn-up-count" style="font-variant-numeric:tabular-nums;">${score.toLocaleString()}</span>
        </button>
        <label style="display:flex;align-items:center;gap:8px;font-size:12px;color:rgba(255,255,255,.5);cursor:pointer;flex:1;min-width:0;">
          <input type="checkbox" id="whats-new-dismiss-check" style="accent-color:var(--accent);">
          <span>Don't show this again</span>
        </label>
        <button onclick="_openAnnouncementInForum('${escapeHTML(post.id)}')" style="font-size:11.5px;color:rgba(255,255,255,.45);background:none;border:none;cursor:pointer;padding:6px 0;">Open in forum →</button>
        <button onclick="_dismissWhatsNew()" style="padding:8px 22px;background:var(--accent);color:var(--rail);border:none;border-radius:10px;font-family:var(--font-display);font-size:12px;font-weight:700;cursor:pointer;transition:all .15s;" onmouseenter="this.style.filter='brightness(1.06)'" onmouseleave="this.style.filter=''">Got it</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);

  // Hydrate the modal asynchronously: pull the author's real PFP and the
  // freshest vote counts from the source thread so they always match
  // what the forum is showing right now.
  _hydrateAnnouncementModal(post.id, post.author);
}

// Async hydration: fetch the author's user record (for the real PFP) and
// the latest forum thread row (for live vote counts). Called once when
// the modal opens; updates are applied in place if the modal is still up.
async function _hydrateAnnouncementModal(threadId, authorName) {
  // 1. Author PFP — forum threads only store the username, not the avatar.
  if (authorName && typeof FortizedSocial?.getUserByName === 'function') {
    try {
      const user = await FortizedSocial.getUserByName(authorName);
      const pfp = user?.pfp || user?.data?.pfp;
      if (pfp) {
        const img = document.getElementById('whats-new-pfp');
        if (img) img.src = pfp;
      }
    } catch(_) {}
  }
  // 2. Live thread state — re-pull likes/dislikes so the modal's count
  //    matches the forum even if the cache was stale.
  if (threadId && typeof FortizedSocial?.getForumThread === 'function') {
    try {
      const fresh = await FortizedSocial.getForumThread(threadId);
      if (fresh && _latestForumAnnouncement?.id === threadId) {
        _latestForumAnnouncement.likes = Array.isArray(fresh.likes) ? fresh.likes : [];
        _latestForumAnnouncement.dislikes = Array.isArray(fresh.dislikes) ? fresh.dislikes : [];
        _refreshAnnouncementVoteUI();
      }
    } catch(_) {}
  }
}

function _renderAnnouncementBody(text) {
  // Legacy helper kept for the admin-side preview. Forum announcements
  // use _forumRenderBody, which already handles markdown + mentions.
  let html = escapeHTML(text);
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong style="color:#fff;font-weight:700;">$1</strong>');
  html = html.replace(/__(.*?)__/g, '<em>$1</em>');
  html = html.replace(/^• (.+)/gm, '<div style="display:flex;gap:6px;margin:2px 0;"><span style="color:var(--accent);">•</span><span>$1</span></div>');
  return html;
}

function _dismissWhatsNew() {
  const modal = document.getElementById('modal-whats-new');
  if (!modal) return;
  const dismissCheck = document.getElementById('whats-new-dismiss-check');
  const shouldRemember = dismissCheck?.checked === true;
  modal.remove();
  // Only persist a "seen" flag if the user explicitly opted out.
  // The key is the id PLUS the last-edit timestamp, so an edit to the
  // same post re-surfaces the card even after the user dismissed it.
  if (shouldRemember && _latestForumAnnouncement?.id) {
    let seen = [];
    try { seen = JSON.parse(localStorage.getItem('ftz_seen_forum_announcements') || '[]'); } catch(_) {}
    const key = _announcementSeenKey(_latestForumAnnouncement);
    const merged = [...new Set([...seen, key])];
    // Trim to the last 50 keys so the array doesn't grow forever.
    localStorage.setItem('ftz_seen_forum_announcements', JSON.stringify(merged.slice(-50)));
  }
}

// Load announcement preview in broadcast tab
async function _loadAnnouncementPreview() {
  const el = document.getElementById('admin-announcements-preview');
  if (!el) return;
  try {
    const all = await FortizedSocial.getAnnouncements() || [];
    const recent = all.slice(0, 3);
    if (!recent.length) { el.innerHTML = '<div style="font-size:12px;color:rgba(255,255,255,.2);padding:8px 0;">No announcements yet.</div>'; return; }
    const fmtDate = d => { try { return new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'short'}); } catch { return ''; } };
    el.innerHTML = recent.map(a => `
      <div style="display:flex;align-items:center;gap:10px;padding:7px 0;${recent.indexOf(a)<recent.length-1?'border-bottom:1px solid rgba(255,255,255,.04);':''}">
        <div style="width:6px;height:6px;border-radius:50%;background:#60a5fa;flex-shrink:0;"></div>
        <div style="flex:1;font-size:12px;color:rgba(255,255,255,.6);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHTML(a.title||'')}</div>
        <div style="font-size:10px;color:rgba(255,255,255,.2);flex-shrink:0;">${fmtDate(a.createdAt)}</div>
      </div>
    `).join('');
  } catch { el.innerHTML = ''; }
}

