// ════════════════════════════════════════════════════════
// FORTIZED TAX SYSTEM
// ────────────────────────────────────────────────────────
// Every transaction is taxed 30% of the price. The 30% tax
// is split into 3 equal buckets:
//   • BURN    — removed from circulation (deflationary)
//   • FOUNDERS — 50/50 Fortized/Staw owner accounts
//   • STAFF    — 50/50 admins/mods pools, each shared equally
// Remaining 70% of price goes to the seller. For direct shop
// purchases (no seller = Team Fortized), the 70% goes to the
// "fortized" account.
// ════════════════════════════════════════════════════════
const FORTIZED_TAX = {
  RATE: 0.30,
  SPLIT_BURN: 1/3,
  SPLIT_FOUNDERS: 1/3,
  SPLIT_STAFF: 1/3,
  FOUNDER_FORTIZED: 0.5,
  FOUNDER_STAW: 0.5,
  STAFF_ADMINS: 0.5,
  STAFF_MODS: 0.5,
};

function computeTaxBreakdown(price) {
  price = Math.max(0, Math.floor(price || 0));
  const tax = Math.floor(price * FORTIZED_TAX.RATE);
  const burn = Math.floor(tax * FORTIZED_TAX.SPLIT_BURN);
  const founders = Math.floor(tax * FORTIZED_TAX.SPLIT_FOUNDERS);
  const staff = tax - burn - founders;
  const fortized = Math.floor(founders * FORTIZED_TAX.FOUNDER_FORTIZED);
  const staw = founders - fortized;
  const adminPool = Math.floor(staff * FORTIZED_TAX.STAFF_ADMINS);
  const modPool = staff - adminPool;
  const net = price - tax;
  return { price, tax, burn, founders, staff, fortized, staw, adminPool, modPool, net };
}

function _taxEventLog(entry) {
  try {
    const log = JSON.parse(localStorage.getItem('ftz_tax_log') || '[]');
    log.push({ ...entry, at: Date.now() });
    while (log.length > 200) log.shift();
    localStorage.setItem('ftz_tax_log', JSON.stringify(log));
  } catch(_){}
}

async function applyTax(price, context) {
  price = Math.max(0, Math.floor(price || 0));
  if (price <= 0) return { price:0, tax:0, burn:0, founders:0, staff:0, fortized:0, staw:0, adminPool:0, modPool:0, net:0 };
  const b = computeTaxBreakdown(price);
  const staff = JSON.parse(localStorage.getItem('ftz_staff') || '{}');
  const admins = (staff.admins || []).filter(Boolean);
  const mods = (staff.moderators || []).filter(Boolean);
  const perAdmin = admins.length ? Math.floor(b.adminPool / admins.length) : 0;
  const perMod = mods.length ? Math.floor(b.modPool / mods.length) : 0;

  const payouts = [];
  if (b.fortized > 0) payouts.push({ u: 'fortized', amt: b.fortized, kind: 'founder' });
  if (b.staw > 0) payouts.push({ u: 'staw', amt: b.staw, kind: 'founder' });
  admins.forEach(u => { if (perAdmin > 0) payouts.push({ u, amt: perAdmin, kind: 'admin' }); });
  mods.forEach(u => { if (perMod > 0) payouts.push({ u, amt: perMod, kind: 'mod' }); });

  const seller = context?.seller || null;
  if (seller && b.net > 0) {
    payouts.push({ u: seller, amt: b.net, kind: 'seller' });
  } else if (!seller && b.net > 0) {
    // Direct shop purchase: 70% to Team Fortized
    payouts.push({ u: 'fortized', amt: b.net, kind: 'shop' });
  }

  // Aggregate by user for fewer writes
  const agg = {};
  payouts.forEach(p => { agg[p.u] = (agg[p.u] || 0) + p.amt; });

  await Promise.all(Object.entries(agg).map(async ([u, amt]) => {
    try {
      const user = await FortizedSocial.getUserByName(u);
      if (user) await FortizedSocial.adminUpdateUserField(u, 'onyx', (user.onyx || 0) + amt);
    } catch(e) { console.warn('[Tax] Payout failed:', u, e?.message); }
  }));

  _taxEventLog({ price, tax: b.tax, burn: b.burn, seller, payer: CU?.username || null, reason: context?.reason || 'transaction' });

  const beneficiaries = new Set(Object.keys(agg));
  if (CU?.username && beneficiaries.has(CU.username)) {
    await refreshCU();
    updateOnyxDisplay();
  }
  return b;
}

// Back-compat wrapper — existing callers pass full price, no seller (shop purchases)
async function distributeOnyxRevenue(cost, context) {
  return applyTax(cost, context || {});
}
async function boostBastion(level, cost) {
  if((CU.onyx||0)<cost){toast('Not enough Onyx!','error');return;}
  showCustomConfirm(`Boost to Level ${level} for ${cost} Onyx?`, async ()=>{
    const b = CU?.bastions?.[curBastion];
    if (!b) return;
    CU.onyx=(CU.onyx||0)-cost;
    b.boostLevel=level;
    await saveUser(); updateOnyxDisplay(); openBoostModal();
    distributeOnyxRevenue(cost);
    toast('Boosted to Level '+level+'!','success');
  });
}
async function confirmLeaveBastion() {
  const b=CU.bastions[curBastion];
  document.getElementById('leave-title').textContent=`Leave ${b.name}?`;
  document.getElementById('leave-confirm-btn').onclick=async()=>{
    try{await FortizedSocial.removeBastionMember(b.globalId||b.name,CU.username);}catch(e){console.warn('[Bastion] Leave failed:',e?.message);}
    if(b.memberRoles) delete b.memberRoles[CU.username];
    CU.bastions.splice(curBastion,1);
    await saveUser(); closeModal('modal-leave-bastion'); curBastion=null;
    renderRailBastions(); showView('home'); toast('Left bastion','info');
  };
  openModal('modal-leave-bastion');
}
async function deleteBastion() {
  confirmDeleteBastion(curBastion);
}

function confirmDeleteBastion(idx) {
  const b = CU.bastions?.[idx];
  if (!b) return;
  const confirmWord = b.name.split(/\s+/)[0].toUpperCase();
  const overlay = document.createElement('div');
  overlay.className = 'input-dialog-overlay';
  overlay.innerHTML = `<div class="input-dialog" style="max-width:420px;">
    <h3 style="color:var(--red);margin-bottom:10px;">🛑 Delete "${escapeHTML(b.name)}"?</h3>
    <p style="margin-bottom:8px;">This action is <strong style="color:var(--red);">permanent</strong> and cannot be undone. All channels, messages, and members will be lost forever.</p>
    <p style="margin-bottom:14px;font-size:12.5px;color:var(--muted-light);">Consider transferring ownership instead — your bastion lives on with someone else in charge.</p>
    <div class="input-dialog-actions" style="margin-bottom:16px;">
      <button class="btn-g" style="flex:1;justify-content:center;" id="cdb-transfer">Transfer Ownership Instead</button>
    </div>
    <div style="border-top:1px solid var(--border);padding-top:14px;margin-top:4px;">
      <p style="font-size:12px;color:var(--muted-light);margin-bottom:10px;">To confirm deletion, type <strong style="color:#fff;font-family:'SF Mono','Cascadia Code',monospace;background:rgba(255,255,255,.06);padding:2px 6px;border-radius:4px;">${escapeHTML(confirmWord)}</strong> below:</p>
      <input type="text" id="cdb-confirm-input" placeholder="Type here to confirm…" autocomplete="off">
      <div class="input-dialog-actions">
        <button class="btn-g" style="flex:1;justify-content:center;" id="cdb-cancel">Cancel</button>
        <button class="btn-d" style="flex:1;justify-content:center;opacity:.4;pointer-events:none;" id="cdb-delete">Delete Bastion</button>
      </div>
    </div>
  </div>`;
  document.body.appendChild(overlay);

  const inp = document.getElementById('cdb-confirm-input');
  const delBtn = document.getElementById('cdb-delete');
  inp.addEventListener('input', () => {
    const match = inp.value.trim().toUpperCase() === confirmWord;
    delBtn.style.opacity = match ? '1' : '.4';
    delBtn.style.pointerEvents = match ? 'auto' : 'none';
  });

  document.getElementById('cdb-cancel').onclick = () => overlay.remove();
  overlay.addEventListener('keydown', e => { if (e.key === 'Escape') overlay.remove(); });

  document.getElementById('cdb-transfer').onclick = () => {
    overlay.remove();
    openBastion(idx);
    setTimeout(() => openBastionSettings('danger'), 100);
  };

  delBtn.onclick = async () => {
    if (inp.value.trim().toUpperCase() !== confirmWord) return;
    overlay.remove();
    try { await FortizedSocial.deleteGlobalBastion(b.globalId || b.name); } catch(e) { console.warn('[Bastion] Global remove failed:', e?.message); }
    CU.bastions.splice(idx, 1);
    await saveUser();
    curBastion = null;
    curChannel = null;
    renderRailBastions();
    showView('home');
    toast('Bastion "' + b.name + '" has been deleted permanently.', 'info');
  };
}
async function transferBastionOwnership() {
  const newOwner=document.getElementById('transfer-owner-input')?.value?.trim();
  if(!newOwner){toast('Enter a username','error');return;}
  const b=CU.bastions[curBastion];
  if(!b||b.owner!==CU.username)return;
  showCustomConfirm(`Transfer ownership of ${b.name} to ${newOwner}? You will lose owner privileges.`, async ()=>{
    b.owner=newOwner;
    if(!b.memberRoles)b.memberRoles={};
    b.memberRoles[newOwner]=['admin'];
    await saveUser();
    try{ _syncBastionToGlobal(curBastion); }catch{}
    renderBSettingsMain('danger');
    toast(`Ownership transferred to ${newOwner}`,'success');
  });
}

// ════════════════════════════════════════════
// ROLES
// ════════════════════════════════════════════
function createNewRole() {
  currentRoleEditing = {id:'r'+Date.now(),name:'New Role',color:ROLE_COLORS[0],permissions:['send_messages','read_history','add_reactions']};
  document.getElementById('re-title').textContent='Create Role';
  document.getElementById('re-delete-btn').style.display='none';
  openRoleEditor();
}
function editRole(idx) {
  const b=CU.bastions[curBastion];
  currentRoleEditing={...b.roles[idx], _idx:idx};
  document.getElementById('re-title').textContent='Edit Role';
  document.getElementById('re-delete-btn').style.display='';
  openRoleEditor();
}
function openRoleEditor() {
  const r=currentRoleEditing;
  document.getElementById('re-name').value=r.name;
  document.getElementById('re-colors').innerHTML=ROLE_COLORS.map(c=>`<div class="color-swatch ${r.color===c?'sel':''}" style="background:${c};" onclick="selectRoleColor('${c}')"></div>`).join('');
  // Priority & Display as Tag
  const extraEl=document.getElementById('re-extras');
  if(extraEl) extraEl.innerHTML=`
    <div style="display:flex;align-items:center;gap:14px;margin-bottom:14px;">
      <div style="flex:1;"><div style="font-size:12px;font-weight:700;margin-bottom:4px;">Priority</div>
        <div style="display:flex;align-items:center;gap:8px;"><input type="range" id="re-priority" min="0" max="100" value="${r.priority||0}" style="flex:1;accent-color:var(--accent);"><span id="re-priority-val" style="font-size:13px;font-weight:700;min-width:24px;text-align:center;">${r.priority||0}</span></div>
      </div>
      <div style="display:flex;align-items:center;gap:8px;"><span style="font-size:12px;font-weight:700;">Display as Tag</span><div class="toggle ${r.displayAsTag?'on':''}" onclick="currentRoleEditing.displayAsTag=!currentRoleEditing.displayAsTag;this.classList.toggle('on')"></div></div>
    </div>`;
  const prSlider=document.getElementById('re-priority');
  if(prSlider)prSlider.oninput=function(){document.getElementById('re-priority-val').textContent=this.value;currentRoleEditing.priority=parseInt(this.value);};
  // Grouped permissions
  const permsEl=document.getElementById('re-perms');
  let permsHTML='';
  PERM_GROUPS.forEach(group=>{
    const groupPerms=PERMISSIONS.filter(p=>p[2]===group);
    if(!groupPerms.length)return;
    permsHTML+=`<div style="margin-bottom:16px;"><div style="font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--accent);margin-bottom:8px;padding-bottom:4px;border-bottom:1px solid var(--border);">${group}</div>`;
    groupPerms.forEach(([key,label])=>{
      permsHTML+=`<div class="perm-row"><div class="perm-info"><div class="perm-label">${label}</div></div><div class="toggle ${(r.permissions||[]).includes(key)?'on':''}" onclick="toggleRolePerm('${key}',this)"></div></div>`;
    });
    permsHTML+=`</div>`;
  });
  if(permsEl)permsEl.innerHTML=permsHTML;
  openModal('modal-role-editor');
}
function selectRoleColor(color) {
  currentRoleEditing.color=color;
  document.querySelectorAll('.color-swatch').forEach(el=>el.classList.toggle('sel',el.style.background===color||el.style.backgroundColor===color));
}
function toggleRolePerm(key, el) {
  const perms=currentRoleEditing.permissions||[];
  if(perms.includes(key)) currentRoleEditing.permissions=perms.filter(p=>p!==key);
  else currentRoleEditing.permissions=[...perms,key];
  el.classList.toggle('on',currentRoleEditing.permissions.includes(key));
}
async function saveRole() {
  const b=CU.bastions[curBastion];
  currentRoleEditing.name=document.getElementById('re-name').value.trim()||currentRoleEditing.name;
  const prSlider=document.getElementById('re-priority');
  if(prSlider) currentRoleEditing.priority=parseInt(prSlider.value)||0;
  if('_idx' in currentRoleEditing) {
    const idx=currentRoleEditing._idx;
    delete currentRoleEditing._idx;
    b.roles[idx]=currentRoleEditing;
  } else { b.roles=[...(b.roles||[]),currentRoleEditing]; }
  await saveUser(); _syncBastionToGlobal(curBastion); closeModal('modal-role-editor'); renderBSettingsMain('roles');
  FortizedSocial.socketEmit('bastion:update', { bastionId: CU.bastions[curBastion]?.globalId, field: 'roles' });
  toast('Role saved!','success');
}
async function deleteCurrentRole() {
  if(!('_idx' in currentRoleEditing)) return;
  showCustomConfirm('Delete this role?', async ()=>{
    const b = CU?.bastions?.[curBastion];
    if (!b?.roles) return;
    b.roles.splice(currentRoleEditing._idx,1);
    await saveUser(); _syncBastionToGlobal(curBastion); closeModal('modal-role-editor'); renderBSettingsMain('roles');
    FortizedSocial.socketEmit('bastion:update', { bastionId: b?.globalId, field: 'roles' });
    toast('Role deleted','info');
  });
}

// Apply role template to current bastion
function applyRoleTemplate(templateId) {
  const tmpl = ROLE_TEMPLATES[templateId];
  if (!tmpl) return;
  showCustomConfirm(`Apply "${tmpl.name}" template? This will replace all existing roles.`, async ()=>{
    const b = CU.bastions[curBastion];
    b.roles = tmpl.roles.map(r=>({...r, id: r.id || ('r'+Date.now()+Math.random().toString(36).slice(2,6))}));
    await saveUser();
    _syncBastionToGlobal(curBastion);
    renderBSettingsMain('roles');
    toast(`"${tmpl.name}" roles applied!`, 'success');
  });
}

// Assign roles modal
let assignRoleBastionIdx=null;
function openAssignRole(bastionIdx, username) {
  assignRoleBastionIdx=bastionIdx; assignRoleMember=username;
  const b=CU.bastions[bastionIdx];
  document.getElementById('ar-title').textContent=`Roles for ${username}`;
  const memberRoles=(b.memberRoles||{})[username]||[];
  document.getElementById('ar-roles').innerHTML=(b.roles||[]).map(r=>`
    <div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--panel);border:1px solid var(--border);border-radius:12px;">
      <div class="role-dot" style="background:${r.color};"></div>
      <div style="flex:1;font-weight:600;">${escapeHTML(r.name)}</div>
      <div class="toggle ${memberRoles.includes(r.id)?'on':''}" onclick="toggleMemberRole('${r.id}',this)"></div>
    </div>`).join('');
  openModal('modal-assign-role');
}
function toggleMemberRole(roleId, el) {
  const b=CU.bastions[assignRoleBastionIdx];
  if(!b.memberRoles) b.memberRoles={};
  if(!b.memberRoles[assignRoleMember]) b.memberRoles[assignRoleMember]=[];
  const roles=b.memberRoles[assignRoleMember];
  if(roles.includes(roleId)) b.memberRoles[assignRoleMember]=roles.filter(r=>r!==roleId);
  else b.memberRoles[assignRoleMember]=[...roles,roleId];
  el.classList.toggle('on',b.memberRoles[assignRoleMember].includes(roleId));
}
async function saveAssignedRoles() {
  const bIdx = assignRoleBastionIdx!=null?assignRoleBastionIdx:curBastion;
  await saveUser(); _syncBastionToGlobal(bIdx); closeModal('modal-assign-role');
  FortizedSocial.socketEmit('bastion:update', { bastionId: CU.bastions[bIdx]?.globalId, field: 'memberRoles' });
  toast('Roles updated!','success');
}

