// CUSTOM EMOJIS
// ════════════════════════════════════════════
function uploadCustomEmoji() {
  const inp=document.getElementById('emoji-file-input');
  if(inp) inp.click();
}
async function processEmojiUpload(e) {
  const file=e.target.files[0]; if(!file) return;
  if(file.size>512*1024){toast('Max 512KB per emoji','error');return;}
  if(!file.type.startsWith('image/')){toast('Images only','error');return;}
  showCustomInput('Emoji Name','Enter a name for this emoji (no spaces):',async(name)=>{
    if(!name?.trim()){toast('Name required','error');return;}
    const cleanName=name.trim().toLowerCase().replace(/\s+/g,'_').replace(/[^a-z0-9_]/g,'');
    const r=new FileReader();
    r.onload=async ev=>{
      const b=CU?.bastions?.[curBastion];
      if (!b) return;
      b.customEmojis=[...(b.customEmojis||[]),{name:cleanName,data:ev.target.result,type:'img',animated:file.type==='image/gif'}];
      await saveUser(); _syncBastionToGlobal(curBastion); renderBSettingsMain('emojis'); toast(`:${cleanName}: added!`,'success');
    };
    r.readAsDataURL(file);
  });
}
async function deleteCustomEmoji(i) {
  showCustomConfirm('Delete this custom emoji?',async()=>{
    const b = CU?.bastions?.[curBastion];
    if (!b?.customEmojis) return;
    b.customEmojis.splice(i,1);
    await saveUser(); _syncBastionToGlobal(curBastion); renderBSettingsMain('emojis'); toast('Emoji removed','info');
  });
}

// ── Bastion Identity: Sub-tab switching ──
function _switchBITab(tab) {
  const emojiSection = document.getElementById('bi-section-emojis');
  const stickerSection = document.getElementById('bi-section-stickers');
  const emojiTab = document.getElementById('bi-tab-emojis');
  const stickerTab = document.getElementById('bi-tab-stickers');
  if (tab === 'emojis') {
    if (emojiSection) emojiSection.style.display = '';
    if (stickerSection) stickerSection.style.display = 'none';
    if (emojiTab) { emojiTab.style.background = 'var(--accent)'; emojiTab.style.color = '#0f1119'; emojiTab.style.fontWeight = '700'; }
    if (stickerTab) { stickerTab.style.background = 'transparent'; stickerTab.style.color = 'var(--muted-light)'; stickerTab.style.fontWeight = '600'; }
  } else {
    if (emojiSection) emojiSection.style.display = 'none';
    if (stickerSection) stickerSection.style.display = '';
    if (stickerTab) { stickerTab.style.background = 'var(--accent)'; stickerTab.style.color = '#0f1119'; stickerTab.style.fontWeight = '700'; }
    if (emojiTab) { emojiTab.style.background = 'transparent'; emojiTab.style.color = 'var(--muted-light)'; emojiTab.style.fontWeight = '600'; }
  }
}

// ── Bots sub-tab switching (bastion settings) ──
function _switchBotsSubTab(tab) {
  const tabs = ['deployed','mybots','marketplace'];
  tabs.forEach(t => {
    const section = document.getElementById('bots-section-'+t);
    const btn = document.getElementById('bots-tab-'+t);
    if (section) section.style.display = (t===tab)?'':'none';
    if (btn) {
      if (t===tab) { btn.style.background='var(--accent)'; btn.style.color='#0f1119'; btn.style.fontWeight='700'; }
      else { btn.style.background='transparent'; btn.style.color='var(--muted-light)'; btn.style.fontWeight='600'; }
    }
  });
}

function deployBotToBastion(botId) {
  const b = CU.bastions?.[curBastion]; if (!b) return;
  const bot = (CU.bots||[]).find(bo=>bo.id===botId); if (!bot) return;
  if (!b.deployedBots) b.deployedBots = [];
  if (b.deployedBots.find(db=>db.id===botId)) { toast('Bot already deployed','info'); return; }
  b.deployedBots.push({...bot, enabled:true});
  saveUser();
  _syncBastionToGlobal(curBastion);
  toast(bot.name+' deployed to bastion!','success');
  renderBSettingsMain('bots');
}

function installArsenalBot(botId) {
  const b = CU.bastions?.[curBastion]; if (!b) return;
  const bot = (typeof ARSENAL_BOTS!=='undefined'?ARSENAL_BOTS:[]).find(ab=>ab.id===botId); if (!bot) return;
  if (!b.deployedBots) b.deployedBots = [];
  if (b.deployedBots.find(db=>db.id===botId)) { toast('Bot already installed','info'); return; }
  b.deployedBots.push({...bot, enabled:true, owner:bot.owner||'Fortized'});
  saveUser();
  _syncBastionToGlobal(curBastion);
  toast(bot.name+' installed!','success');
  renderBSettingsMain('bots');
}

// ── Bastion Identity: Sticker upload/delete ──
function uploadCustomSticker() {
  const inp = document.getElementById('sticker-file-input');
  if (inp) inp.click();
}
async function processCustomStickerUpload(e) {
  const file = e.target.files[0]; if (!file) return;
  if (file.size > 512*1024) { toast('Max 512KB per sticker','error'); return; }
  if (!/^image\/(png|gif|webp)$/.test(file.type)) { toast('Only PNG, GIF, WebP supported','error'); return; }
  showCustomInput('Sticker Name','Enter a name for this sticker:',async(name)=>{
    if (!name?.trim()) { toast('Name required','error'); return; }
    const cleanName = name.trim().toLowerCase().replace(/\s+/g,'_').replace(/[^a-z0-9_]/g,'');
    const r = new FileReader();
    r.onload = async ev => {
      const b = CU.bastions[curBastion];
      if (!b.stickers) b.stickers = [];
      b.stickers.push({name:cleanName, url:ev.target.result, data:ev.target.result, type:'sticker'});
      await saveUser(); _syncBastionToGlobal(curBastion); renderBSettingsMain('emojis'); toast('Sticker "'+cleanName+'" added!','success');
    };
    r.readAsDataURL(file);
  });
}
async function deleteCustomSticker(i) {
  showCustomConfirm('Delete this sticker?',async()=>{
    const b = CU.bastions[curBastion];
    const arr = b.stickers || b.customStickers || [];
    arr.splice(i,1);
    b.stickers = arr;
    await saveUser(); _syncBastionToGlobal(curBastion); renderBSettingsMain('emojis'); toast('Sticker removed','info');
  });
}

