function buildEmojiSidebar() {
  // Icon-only sidebar (Discord-style). Labels are shown as browser tooltips
  // on hover; the emblem itself is all that's rendered. Order:
  //   Frequent, Favorites, Fortized Guide, [bastions…], [unicode categories]
  const bastions = CU?.bastions || [];
  const visibleBastions = bastions
    .map((b, i) => ({ b, i }))
    .filter(({ b }) => Array.isArray(b?.customEmojis) && b.customEmojis.some(ce => ce && ce.name && ce.data));
  let html = '';
  const btn = (id, title, iconHtml, extraClass) => `<button class="epp-sidebar-btn${_emojiPickerTab===id?' active':''}${extraClass?' '+extraClass:''}" id="etab-${id}" data-epp-tab="${id}" title="${escapeHTML(title)}" aria-label="${escapeHTML(title)}"><span class="epp-sidebar-emblem">${iconHtml}</span></button>`;
  html += btn('frequent', 'Frequently used', _EMOJI_CATEGORY_SVGS.frequent);
  html += btn('favorites', 'Favorites', _EMOJI_CATEGORY_SVGS.favorites);
  html += btn('ftz', 'Fortized Guide', _EMOJI_CATEGORY_SVGS.ftz, 'is-ftz');
  if (visibleBastions.length) {
    html += '<div class="epp-sidebar-sep"></div>';
    if (_hasActiveRadiance()) {
      html += btn('bastions', 'All Bastions', _EMOJI_CATEGORY_SVGS.bastions);
    }
    visibleBastions.forEach(({ b, i }) => {
      const active = _emojiPickerTab === 'bastion-' + i;
      const name = b.name || 'Bastion';
      const initials = escapeHTML(name.slice(0,2).toUpperCase());
      const fallback = `<span style="font-size:11px;font-weight:700;letter-spacing:.5px;">${initials}</span>`;
      let emblem;
      if (b.icon) {
        emblem = `<img src="${escapeHTML(b.icon)}" alt="${escapeHTML(name)}" style="width:100%;height:100%;object-fit:cover;border-radius:8px;" onerror="this.outerHTML='${fallback.replace(/'/g,"\\'")}'">`;
      } else if (b.emblem && !/^https?:|^data:/.test(b.emblem)) {
        emblem = `<span style="font-size:18px;line-height:1;">${escapeHTML(b.emblem)}</span>`;
      } else if (b.emblem) {
        emblem = `<img src="${escapeHTML(b.emblem)}" alt="${escapeHTML(name)}" style="width:100%;height:100%;object-fit:cover;border-radius:8px;" onerror="this.outerHTML='${fallback.replace(/'/g,"\\'")}'">`;
      } else {
        emblem = fallback;
      }
      html += `<button class="epp-sidebar-btn${active?' active':''}" id="etab-bastion-${i}" data-epp-tab="bastion-${i}" title="${escapeHTML(name)}" aria-label="${escapeHTML(name)}"><span class="epp-sidebar-emblem">${emblem}</span></button>`;
    });
  }
  html += '<div class="epp-sidebar-sep"></div>';
  const catLabels = {
    smileys: 'Faces & Expressions', people: 'People & Hands', nature: 'Nature & Animals',
    food: 'Food & Drinks', travel: 'Travel & Places', activities: 'Fun & Activities',
    hearts: 'Hearts & Love', symbols: 'Symbols & Signs', flags: 'Flags',
  };
  ['smileys','people','nature','food','travel','activities','hearts','symbols','flags'].forEach(id => {
    html += btn(id, catLabels[id] || (id.charAt(0).toUpperCase()+id.slice(1)), _EMOJI_CATEGORY_SVGS[id]);
  });
  return html;
}

function buildEmojiTabBar() {
  // Legacy — now uses sidebar instead
  return '';
}
// Helper: get the right edge of the chat input bar
function _getChatInputRight() {
  const outer = document.querySelector('.chat-input-outer');
  if (outer) return outer.getBoundingClientRect().right;
  const chatWrap = document.querySelector('.chat-wrap');
  if (chatWrap) return chatWrap.getBoundingClientRect().right - 12;
  return window.innerWidth - 20;
}
function toggleEmojiPicker(targetId) {
  // Reset mode to 'insert' — reactions use a separate flow.
  _emojiPickerMode = 'insert';
  _reactionContext = null;
  _reactionSuperMode = false;
  activeEmojiTarget = targetId;
  document.getElementById('giphy-picker')?.remove();
  document.getElementById('sticker-picker')?.remove();
  document.getElementById('botcmd-picker')?.remove();
  const panel = document.getElementById('emoji-picker');
  if (!panel) return;
  if (panel.classList.contains('show')) { panel.classList.remove('show'); return; }
  buildEmojiPicker();

  // Position relative to the input target (works for chat, bio, forum composer, etc.)
  const refEl = document.getElementById(targetId);
  const outerEl = refEl ? refEl.closest('.chat-input-outer') : null;
  // Clamp panel width to viewport so the sidebar is never clipped off-screen.
  const PW = Math.min(448, window.innerWidth - 16);
  const PH = 440;
  let left, top = null, bottom = null;
  if (outerEl) {
    // Chatbar mode: right-aligned with the input, popping up above
    const rect = outerEl.getBoundingClientRect();
    left = Math.max(8, _getChatInputRight() - PW);
    bottom = window.innerHeight - rect.top + 8;
  } else if (refEl) {
    // Generic mode: anchor above the input's right edge
    const rect = refEl.getBoundingClientRect();
    left = Math.min(Math.max(8, rect.right - PW), window.innerWidth - PW - 8);
    if (rect.top - 8 > PH) {
      // Fits above
      top = Math.max(8, rect.top - PH - 8);
    } else {
      // Drop below
      top = Math.min(rect.bottom + 8, window.innerHeight - PH - 8);
    }
  } else {
    left = Math.max(8, window.innerWidth - PW - 20);
    top = Math.max(8, (window.innerHeight - PH) / 2);
  }
  if (bottom !== null) {
    panel.style.cssText = `left:${left}px;bottom:${bottom}px;top:auto;`;
  } else {
    panel.style.cssText = `left:${left}px;top:${top}px;bottom:auto;`;
  }
  panel.classList.add('show');
  setTimeout(() => panel.querySelector('.epp-search-inp')?.focus(), 80);
}

function _pickerTopTabs(active) {
  return `<div class="picker-top-tabs">
    <button class="picker-top-tab${active==='gif'?' active':''}" onclick="_switchPickerTab('gif')">GIFs</button>
    <button class="picker-top-tab${active==='sticker'?' active':''}" onclick="_switchPickerTab('sticker')">Stickers</button>
    <button class="picker-top-tab${active==='emoji'?' active':''}" onclick="_switchPickerTab('emoji')">Emoji</button>
  </div>`;
}
function _switchPickerTab(tab) {
  const target = activeEmojiTarget || _giphyInput || _stickerInput || 'ch-input';
  if (tab === 'gif') { document.getElementById('emoji-picker')?.classList.remove('show'); document.getElementById('sticker-picker')?.remove(); openGiphyPicker(target); }
  else if (tab === 'sticker') { document.getElementById('emoji-picker')?.classList.remove('show'); document.getElementById('giphy-picker')?.remove(); openStickerPicker(target); }
  else {
    document.getElementById('giphy-picker')?.remove(); document.getElementById('sticker-picker')?.remove();
    // Force-open emoji picker (don't toggle off)
    activeEmojiTarget = target;
    const panel = document.getElementById('emoji-picker');
    if (panel && !panel.classList.contains('show')) { toggleEmojiPicker(target); }
  }
}

function buildEmojiPicker() {
  const panel = document.getElementById('emoji-picker');
  if (!panel) return;

  panel.innerHTML = `
    <div class="epp-main">
      ${_pickerTopTabs('emoji')}
      <div style="padding:8px 10px;border-bottom:1px solid rgba(255,255,255,.03);flex-shrink:0;">
        <div style="position:relative;">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.2)" stroke-width="2" style="position:absolute;left:10px;top:50%;transform:translateY(-50%);pointer-events:none;"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
          <input class="epp-search-inp" placeholder="Search" style="width:100%;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.05);border-radius:10px;color:#fff;font-family:var(--font-ui);font-size:12px;padding:8px 12px 8px 32px;outline:none;box-sizing:border-box;transition:border-color .15s,box-shadow .15s;" oninput="searchEmojis(this.value)">
        </div>
      </div>
      <div id="epp-grid" style="flex:1;overflow-y:auto;padding:0 8px 8px;max-height:340px;position:relative;"></div>
      <div style="padding:6px 10px;border-top:1px solid rgba(255,255,255,.03);font-size:10px;color:rgba(255,255,255,.15);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;">
        <span id="epp-hover-label">Select an emoji</span>
        <button onclick="_showEmojiInfo()" style="background:none;border:none;color:rgba(255,255,255,.15);cursor:pointer;font-size:12px;padding:2px;" title="Emoji Info">ℹ</button>
      </div>
    </div>
    <div class="epp-sidebar" id="epp-sidebar">
      ${buildEmojiSidebar()}
    </div>
  `;
  renderEmojiGrid();
  // After initial render, wire the intersection observer for auto-highlight
  _wireEmojiScrollSpy();
  _wireEmojiGridDelegation();
  _wireEmojiSidebarDelegation();
}

// One delegated listener on the grid handles click / contextmenu / mouseover
// for every cell. Massively faster than attaching hundreds of inline handlers
// during HTML construction, and keeps the rendered markup tiny.
function _wireEmojiGridDelegation() {
  const grid = document.getElementById('epp-grid');
  if (!grid || grid._eppDelegated) return;
  grid._eppDelegated = true;
  grid.addEventListener('click', (e) => {
    const cell = e.target.closest('.emoji-cell');
    if (!cell || !grid.contains(cell)) return;
    if (cell.dataset.ftzLocked === '1') {
      toast("Radiance required to use this bastion's emojis outside the bastion", 'error');
      return;
    }
    if (cell.dataset.ftz) {
      insertFortizedEmoji(cell.dataset.ftz, cell.dataset.ftzUrl || '');
      return;
    }
    if (cell.dataset.ue) {
      insertEmoji(cell.dataset.ue);
      return;
    }
  });
  grid.addEventListener('contextmenu', (e) => {
    const cell = e.target.closest('.emoji-cell');
    if (!cell || !cell.dataset.ue) return;
    e.preventDefault();
    toggleFavEmoji(cell.dataset.ue);
  });
  // Hover preview — update the bottom status bar with the emoji name. Using
  // mouseover (which bubbles) + data attributes is an order of magnitude
  // cheaper than wiring onmouseenter on every cell.
  grid.addEventListener('mouseover', (e) => {
    const cell = e.target.closest('.emoji-cell');
    if (!cell) return;
    if (cell.dataset.ftz) {
      _emojiHover(':' + cell.dataset.ftz + ':', cell.dataset.ftzFrom || null, cell.dataset.ftzUrl || '', true);
      return;
    }
    if (cell.dataset.ue) {
      const emoji = cell.dataset.ue;
      const cache = _emojiShortcodeCache();
      const shortcode = cache[emoji];
      const label = shortcode ? ':' + shortcode + ':' : (EMOJI_NAMES[emoji] || emoji);
      const el = document.getElementById('epp-hover-label');
      if (el) el.textContent = label + (_favEmojis.includes(emoji) ? ' ★' : '');
    }
  });
}

function _wireEmojiSidebarDelegation() {
  const sb = document.getElementById('epp-sidebar');
  if (!sb || sb._eppDelegated) return;
  sb._eppDelegated = true;
  sb.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-epp-tab]');
    if (!btn) return;
    setEmojiTab(btn.getAttribute('data-epp-tab'));
  });
}

function setEmojiTab(tabId) {
  // Discord-style behavior: clicking a sidebar icon SCROLLS to that section in
  // the single continuous grid, it does NOT switch what's visible.
  _emojiPickerTab = tabId;
  _setActiveEmojiSidebarBtn(tabId);
  scrollToEmojiSection(tabId);
}
function _setActiveEmojiSidebarBtn(tabId) {
  document.querySelectorAll('.epp-sidebar-btn').forEach(b => b.classList.remove('active'));
  const activeBtn = document.getElementById('etab-' + tabId);
  if (activeBtn) activeBtn.classList.add('active');
}
function scrollToEmojiSection(sectionId) {
  const grid = document.getElementById('epp-grid');
  if (!grid) return;
  const hdr = grid.querySelector('.epp-section[data-section="' + sectionId + '"]');
  if (!hdr) return;
  // Suppress scrollspy so the intersection observer doesn't fight the jump
  _emojiScrollSpySuspend = true;
  grid.scrollTo({ top: hdr.offsetTop - 2, behavior: 'smooth' });
  setTimeout(() => { _emojiScrollSpySuspend = false; }, 500);
}

// Intersection-observer scroll-spy: highlights the sidebar button for whichever
// section is currently at the top of the scrollable emoji grid.
function _wireEmojiScrollSpy() {
  const grid = document.getElementById('epp-grid');
  if (!grid) return;
  if (_emojiScrollSpyObserver) { try { _emojiScrollSpyObserver.disconnect(); } catch {} _emojiScrollSpyObserver = null; }
  const sections = Array.from(grid.querySelectorAll('.epp-section'));
  if (!sections.length) return;
  _emojiScrollSpyObserver = new IntersectionObserver((entries) => {
    if (_emojiScrollSpySuspend) return;
    // Find the top-most intersecting header
    const visible = entries.filter(e => e.isIntersecting).sort((a,b) => a.boundingClientRect.top - b.boundingClientRect.top);
    if (!visible.length) return;
    const id = visible[0].target.getAttribute('data-section');
    if (id) _setActiveEmojiSidebarBtn(id);
  }, { root: grid, rootMargin: '0px 0px -80% 0px', threshold: 0 });
  sections.forEach(s => _emojiScrollSpyObserver.observe(s));
}

// Hover preview — updates the bar at the bottom of the emoji picker with the
// emoji glyph + shortcode label, Discord-style.
function _emojiHover(label, fromBastion, url, isCustom) {
  const el = document.getElementById('epp-hover-label');
  if (!el) return;
  let html = '';
  if (url) {
    html = `<img src="${escapeHTML(url)}" style="width:18px;height:18px;vertical-align:-4px;object-fit:contain;margin-right:6px;">`;
  }
  html += `<span style="color:rgba(255,255,255,.7);font-weight:600;">${escapeHTML(label)}</span>`;
  if (fromBastion) html += `<span style="color:rgba(255,255,255,.3);margin-left:6px;">· ${escapeHTML(fromBastion)}</span>`;
  el.innerHTML = html;
}

// Legacy shim — kept for callers (like toggleFavEmoji) that want to refresh
// the picker. In the new Discord-style model there is a SINGLE grid showing
// every section, so this just re-renders the whole thing.
function renderEmojiTab(_tabId) { renderEmojiGrid(); }

// Build ONE continuous grid containing every section back-to-back with sticky
// headers, Discord-style. The sidebar jumps to sections; it does NOT switch
// categories.
//
// Sections are emitted as empty shells with a reserved height, then hydrated
// on-demand via IntersectionObserver as the user scrolls. Only the first few
// sections are rendered up-front — the rest stay as cheap placeholders until
// they come near the viewport. This keeps initial paint fast even with
// thousands of emojis in total.
function _isValidBastionEmoji(ce) {
  if (!ce || typeof ce !== 'object') return false;
  if (ce.deleted || ce.removed) return false;
  if (!ce.name || typeof ce.name !== 'string') return false;
  if (!ce.data || typeof ce.data !== 'string') return false;
  // Must be a usable URL/data URI, not empty, null-string, placeholder, etc.
  const d = ce.data.trim();
  if (!d) return false;
  if (d === 'null' || d === 'undefined' || d === 'deleted') return false;
  if (!/^(https?:|data:|blob:|\/)/i.test(d)) return false;
  return true;
}

// Hydrate a single section shell by replacing its empty inner HTML with the
// full grid cells for that section. Idempotent — hydrating an already-filled
// shell is a no-op.
function _hydrateEmojiSection(shell) {
  if (!shell || !shell.classList.contains('epp-lazy')) return;
  const grid = shell.closest('#epp-grid');
  const spec = grid?._eppSectionSpec?.[shell.getAttribute('data-section-id')];
  if (!spec) return;
  shell.innerHTML = spec.build();
  shell.classList.remove('epp-lazy');
}

function _wireEmojiLazyHydrator() {
  const grid = document.getElementById('epp-grid');
  if (!grid) return;
  if (grid._eppLazyObs) { try { grid._eppLazyObs.disconnect(); } catch {} }
  const shells = Array.from(grid.querySelectorAll('.epp-section-grid.epp-lazy'));
  if (!shells.length) return;
  // Hydrate the first 2 shells immediately so the picker isn't blank on open.
  shells.slice(0, 2).forEach(_hydrateEmojiSection);
  const remaining = shells.filter(s => s.classList.contains('epp-lazy'));
  if (!remaining.length) return;
  const obs = new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        _hydrateEmojiSection(e.target);
        obs.unobserve(e.target);
      }
    });
  }, { root: grid, rootMargin: '400px 0px', threshold: 0 });
  remaining.forEach(s => obs.observe(s));
  grid._eppLazyObs = obs;
}

function renderEmojiGrid() {
  const grid = document.getElementById('epp-grid');
  if (!grid) return;
  const isRadiance = _hasActiveRadiance();
  const bastions = CU?.bastions || [];
  const freqData = (() => { try { return JSON.parse(localStorage.getItem('ftz_emoji_freq')||'{}'); } catch { return {}; } })();
  const freqList = Object.entries(freqData).sort((a,b) => b[1]-a[1]).slice(0,48).map(([e]) => e);

  const sectionHdr = (id, title, extra) => `<div class="epp-section" data-section="${id}">${escapeHTML(title)}${extra||''}</div>`;
  const ftzCell = (name, url, fromBastion) => {
    if (!url) return '';
    const safeName = escapeHTML(name);
    const safeUrl = escapeHTML(url);
    const safeFrom = fromBastion ? escapeHTML(fromBastion) : '';
    const titleStr = `:${safeName}:${safeFrom?' from '+safeFrom:''}`;
    return `<div class="emoji-cell emoji-cell-custom" data-ftz="${safeName}" data-ftz-url="${safeUrl}"${safeFrom?` data-ftz-from="${safeFrom}"`:''} title="${titleStr}">`
      + `<img src="${safeUrl}" alt=":${safeName}:" loading="lazy" decoding="async">`
      + `</div>`;
  };

  // Build a spec list for every section: header + empty shell + a build() fn
  // that produces the cells for that section. Shells get a reserved height
  // so the scrollbar is sized correctly before hydration.
  //
  //   cols  = grid columns
  //   rows  = approximate number of rows (used for intrinsic-size)
  const sections = [];

  // 1) Frequently used
  if (freqList.length || _recentEmojis.length) {
    const rows = (freqList.length ? freqList : _recentEmojis.slice(0,24));
    sections.push({
      id: 'frequent', title: 'Frequently used', extra: '', cols: 8, rowCount: Math.ceil(rows.length/8), tight: false,
      build: () => rows.map(e => FORTIZED_EMOJI_MAP[e] ? ftzCell(e, FORTIZED_EMOJI_MAP[e]) : renderEmojiCell(e)).join(''),
    });
  }

  // 2) Favorites
  sections.push({
    id: 'favorites', title: 'Favorites', extra: '', cols: 8,
    rowCount: Math.max(1, Math.ceil(_favEmojis.length/8)), tight: false,
    build: () => _favEmojis.length
      ? _favEmojis.map(e => renderEmojiCell(e)).join('')
      : `<div class="epp-empty">Right-click any emoji to favorite it.</div>`,
  });

  // 3) Fortized Guide (tight grid)
  const ftzCount = FORTIZED_CHARACTERS.length + FORTIZED_TEXTMOJIS.length;
  sections.push({
    id: 'ftz', title: 'Fortized Guide', extra: '', cols: 8,
    rowCount: Math.ceil(ftzCount/8), tight: true,
    build: () =>
      FORTIZED_CHARACTERS.map(name => ftzCell(name, FORTIZED_EMOJI_MAP[name])).join('') +
      FORTIZED_TEXTMOJIS.map(name => ftzCell(name, FORTIZED_EMOJI_MAP[name])).join(''),
  });

  // 4) Bastion custom emojis — skip bastions with zero *valid* emojis so that
  // deleted/removed emojis don't leave ghost sections behind.
  bastions.forEach((b, bi) => {
    const validEmojis = (b.customEmojis || []).filter(_isValidBastionEmoji);
    if (!validEmojis.length) return;
    const locked = !isRadiance && bi !== curBastion;
    const safeBas = escapeHTML(b.name||'');
    sections.push({
      id: 'bastion-' + bi,
      title: b.name || ('Bastion ' + (bi+1)),
      extra: locked ? ' <span class="epp-lock">RADIANCE</span>' : '',
      cols: 8, rowCount: Math.ceil(validEmojis.length/8), tight: false,
      build: () => validEmojis.map(ce => {
        const safeName = escapeHTML(ce.name);
        const safeData = escapeHTML(ce.data);
        const lockAttrs = locked ? ' data-ftz-locked="1"' : '';
        const lockStyle = locked ? 'opacity:.4;filter:grayscale(.5);' : '';
        // onerror: a bastion emoji URL that 404s after load (e.g. the
        // underlying image was purged from storage) self-destructs its cell
        // so the picker never displays a broken image.
        return `<div class="emoji-cell emoji-cell-custom" data-ftz="${safeName}" data-ftz-url="${safeData}" data-ftz-from="${safeBas}"${lockAttrs} title=":${safeName}:"${lockStyle?` style="${lockStyle}"`:''}>`
          + `<img src="${safeData}" alt=":${safeName}:" loading="lazy" decoding="async" onerror="this.closest('.emoji-cell')?.remove()">`
          + `</div>`;
      }).join(''),
    });
  });

  // 5) Unicode category sections
  EMOJI_PICKER_TABS.forEach(tab => {
    if (!tab.emojis) return;
    sections.push({
      id: tab.id,
      title: tab.label || (tab.id.charAt(0).toUpperCase() + tab.id.slice(1)),
      extra: '', cols: 8, rowCount: Math.ceil(tab.emojis.length/8), tight: false,
      build: () => tab.emojis.map(e => renderEmojiCell(e)).join(''),
    });
  });

  // Emit shells. Each shell is an empty grid with a reserved intrinsic size
  // so the scrollbar is sized correctly before hydration — otherwise
  // hydrating a mid-scroll section would shift content beneath the user.
  //
  // Row height ≈ 38px for the tight (Fortized) grid, 36px for normal grids.
  let html = '';
  for (const s of sections) {
    const rowH = s.tight ? 40 : 38;
    const intrinsicH = Math.max(48, s.rowCount * rowH + 14);
    const cls = 'epp-section-grid' + (s.tight ? ' epp-section-grid-tight' : '') + ' epp-lazy';
    html += sectionHdr(s.id, s.title, s.extra);
    html += `<div class="${cls}" data-section-id="${s.id}" style="grid-template-columns:repeat(${s.cols},1fr);contain-intrinsic-size: 1px ${intrinsicH}px;"></div>`;
  }
  grid.innerHTML = html;
  grid._eppSectionSpec = {};
  sections.forEach(s => { grid._eppSectionSpec[s.id] = s; });
  _wireEmojiLazyHydrator();
}

function emojiToTwemojiUrl(emoji) {
  if (!emoji) return '';
  // :name: shortcodes — resolve Fortized Guide / bastion custom emoji image.
  // Lets reaction pills, status pickers, etc. transparently render Fortized
  // emojis using the same rendering path as unicode emojis.
  if (typeof emoji === 'string' && emoji.length > 2 && emoji.charCodeAt(0) === 58 && emoji.charCodeAt(emoji.length-1) === 58) {
    const name = emoji.slice(1, -1);
    if (typeof FORTIZED_EMOJI_MAP !== 'undefined' && FORTIZED_EMOJI_MAP[name]) return FORTIZED_EMOJI_MAP[name];
    const bastions = (typeof CU !== 'undefined' && CU?.bastions) || [];
    for (const b of bastions) {
      const ce = (b?.customEmojis || []).find(e => e && e.name === name);
      if (ce?.data) return ce.data;
    }
  }
  // Honor custom overrides first (e.g. Fortized money emojis replace twemoji)
  if (typeof EMOJI_URL_OVERRIDES !== 'undefined' && EMOJI_URL_OVERRIDES[emoji]) {
    return EMOJI_URL_OVERRIDES[emoji];
  }
  // Convert emoji char to codepoint(s) for Twemoji URL. Twemoji's filename
  // convention strips the FE0F variation selector for simple emojis (❤️ →
  // 2764.svg) but KEEPS it for ZWJ sequences (❤️‍🔥 → 2764-fe0f-200d-1f525.svg,
  // 🐻‍❄️ → 1f43b-200d-2744-fe0f.svg). Stripping FE0F unconditionally — which
  // we used to do — broke every ZWJ-compound emoji.
  const hasZWJ = emoji.indexOf('‍') >= 0;
  const codePoints = [...emoji]
    .map(c => c.codePointAt(0).toString(16))
    .filter(c => hasZWJ || c !== 'fe0f')
    .join('-');
  return 'https://cdn.jsdelivr.net/gh/jdecked/twemoji@latest/assets/svg/' + codePoints + '.svg';
}

