      const textDim2 = isLight ? 'rgba(0,0,0,.05)' : 'rgba(255,255,255,.04)';
      const textMuted = isLight ? 'rgba(0,0,0,.35)' : 'rgba(255,255,255,.3)';
      const pfpHtml = CU?.pfp
