async function _loadAvatarGifCategoryPreviews() {
  const previewCards = document.querySelectorAll('img[data-avgif-cat]');
  if (!previewCards.length) return;
  try {
    const cid = CU?.username || 'anon';
    const res = await fetch(KLIPY_BASE + '/gifs/trending?per_page=6&content_filter=medium&customer_id=' + encodeURIComponent(cid));
    const data = await res.json();
    const items = data.data?.data || data.data || [];
    const trendCard = document.querySelector('img[data-avgif-cat="trending"]');
    if (trendCard && items[0]) trendCard.src = _klipyGifUrl(items[0], 'sm') || _klipyGifUrl(items[0], 'xs') || '';
  } catch(_){}
  const cats = [...previewCards].filter(c => c.dataset.avgifCat !== 'trending');
  for (let i = 0; i < cats.length; i += 4) {
    const batch = cats.slice(i, i + 4);
    await Promise.allSettled(batch.map(async (card) => {
      try {
        const cat = card.dataset.avgifCat;
        const cid = CU?.username || 'anon';
        const res = await fetch(KLIPY_BASE + '/gifs/search?q=' + encodeURIComponent(cat) + '&per_page=1&content_filter=medium&customer_id=' + encodeURIComponent(cid));
        const data = await res.json();
        const items = data.data?.data || data.data || [];
        if (items[0]) card.src = _klipyGifUrl(items[0], 'sm') || _klipyGifUrl(items[0], 'xs') || '';
      } catch(_){}
    }));
  }
}

function _handleAvatarGifSearch(q) {
  const coll = document.getElementById('avgif-collection-view');
  const grid = document.getElementById('avgif-grid');
  const backBar = document.getElementById('avgif-back-bar');
  const label = document.getElementById('avgif-back-label');
  clearTimeout(window._avGifSearchTimer);
  window._avGifSearchTimer = setTimeout(() => {
    if (!q.trim()) {
      if (coll) coll.style.display = '';
      if (grid) grid.style.display = 'none';
      if (backBar) backBar.style.display = 'none';
      return;
    }
    if (coll) coll.style.display = 'none';
    if (grid) { grid.style.display = ''; grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);">Searching...</div>'; }
    if (backBar) { backBar.style.display = ''; if (label) label.textContent = 'Search: ' + q; }
    _avGifSearchQuery(q);
  }, 260);
}

function _avGifBackToCollections() {
  const coll = document.getElementById('avgif-collection-view');
  const grid = document.getElementById('avgif-grid');
  const backBar = document.getElementById('avgif-back-bar');
  const searchInput = document.getElementById('avgif-search-input');
  if (coll) coll.style.display = '';
  if (grid) grid.style.display = 'none';
  if (backBar) backBar.style.display = 'none';
  if (searchInput) searchInput.value = '';
}

async function _avGifCategoryPick(category) {
  const coll = document.getElementById('avgif-collection-view');
  const grid = document.getElementById('avgif-grid');
  const backBar = document.getElementById('avgif-back-bar');
  const label = document.getElementById('avgif-back-label');
  if (!grid) return;
  if (coll) coll.style.display = 'none';
  grid.style.display = '';
  if (backBar) backBar.style.display = '';
  if (label) label.textContent = category === 'trending' ? 'Trending GIFs' : category.charAt(0).toUpperCase() + category.slice(1);
  grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);">Loading...</div>';
  try {
    const cid = CU?.username || 'anon';
    const path = category === 'trending'
      ? '/gifs/trending?per_page=30'
      : '/gifs/search?q=' + encodeURIComponent(category) + '&per_page=30';
    const res = await fetch(KLIPY_BASE + path + '&content_filter=medium&customer_id=' + encodeURIComponent(cid));
    const data = await res.json();
    const items = data.data?.data || data.data || [];
    _renderAvatarGifResults(items);
  } catch { grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);">Failed to load</div>'; }
}

async function _avGifSearchQuery(q) {
  const grid = document.getElementById('avgif-grid');
  if (!grid) return;
  try {
    const cid = CU?.username || 'anon';
    const res = await fetch(KLIPY_BASE + '/gifs/search?q=' + encodeURIComponent(q) + '&per_page=30&content_filter=medium&customer_id=' + encodeURIComponent(cid));
    const data = await res.json();
    const items = data.data?.data || data.data || [];
    _renderAvatarGifResults(items);
  } catch { grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);">Search failed</div>'; }
}

function _renderAvatarGifResults(items) {
  const grid = document.getElementById('avgif-grid');
  if (!grid) return;
  if (!items.length) { grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);">No GIFs found</div>'; return; }
  grid.innerHTML = items.map(g => {
    const thumb = _klipyGifUrl(g, 'sm') || _klipyGifUrl(g, 'xs');
    const full  = _klipyGifUrl(g, 'hd') || _klipyGifUrl(g, 'md') || thumb;
    if (!thumb || !full) return '';
    return '<div class="gif-card" style="position:relative;border-radius:10px;overflow:hidden;cursor:pointer;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.05);break-inside:avoid;margin-bottom:6px;transition:all .2s cubic-bezier(.22,1,.36,1);" onclick="_applyGifAvatar(\''+escapeHTML(full)+'\')" onmouseenter="this.style.transform=\'scale(1.03) translateY(-2px)\';this.style.boxShadow=\'0 8px 24px rgba(0,0,0,.35)\';this.style.borderColor=\'rgba(255,249,62,.12)\'" onmouseleave="this.style.transform=\'\';this.style.boxShadow=\'\';this.style.borderColor=\'rgba(255,255,255,.05)\'"><img src="'+escapeHTML(thumb)+'" loading="lazy" style="width:100%;display:block;border-radius:9px;" draggable="false"></div>';
  }).join('');
}

async function _applyGifAvatar(url) {
  if (!url) return;
  CU.pfp = url;
  _saveRecentAvatar(url);
  await saveUser();
  try { updateUserbar(); } catch(_){}
  try { buildProfileView('myprofile'); } catch(_){}
  document.querySelectorAll('.ftz-confirm-overlay').forEach(el => el.remove());
  toast('Avatar updated!', 'success');
}

// Save recent avatar to localStorage (most-recent first, capped at 5)
function _saveRecentAvatar(url) {
  if (!url) return;
  // Skip very large data-URLs (big animated GIFs) so we don't compete with
  // the main user cache for the ~5 MB localStorage quota.
  if (typeof url === 'string' && url.startsWith('data:') && url.length > 400_000) return;
  const key = 'ftz_recent_avatars_' + CU.username;
  const recent = JSON.parse(localStorage.getItem(key)||'[]').filter(u => u !== url);
  recent.unshift(url);
  try {
    localStorage.setItem(key, JSON.stringify(recent.slice(0,5)));
  } catch(_) {
    // Quota exceeded — trim harder and retry
    try { localStorage.setItem(key, JSON.stringify(recent.slice(0,3))); } catch(_){}
    try { localStorage.setItem(key, JSON.stringify(recent.slice(0,1))); } catch(_){}
  }
}

async function updatePfp(e) {
  const file = e.target.files[0];
  if (!file) return;
  if (file.size > 8*1024*1024) { toast('Max 8MB', 'error'); return; }
  const isGif = file.type === 'image/gif' || /\.gif$/i.test(file.name);
  const reader = new FileReader();
  reader.onload = async ev => {
    const fileData = ev.target.result;
    if (isGif) {
      // Show crop modal for GIF — applyCrop will return CSS crop params instead of canvas data
      showCropModal(fileData, 1, async (result) => {
        // result is {gifData, crop} from the GIF path in applyCrop
        CU.pfp = result.gifData;
        CU.pfpCrop = result.crop;
        _pfpCropCache[CU.username] = result.crop;
        await saveUser();
        updateUserbar();
        buildProfileView('myprofile');
        try { const s = FortizedSocial.getSocket(); if(s) s.emit('profile:update', { username: CU.username, pfp: result.gifData, pfpCrop: result.crop, field: 'pfp' }); } catch(e){}
        _saveRecentAvatar(result.gifData);
        toast('Animated avatar updated! ✓', 'success');
      });
      // Set the GIF flag on _cropData after showCropModal initializes it
      _cropData._isGif = true;
      _cropData._gifSrc = fileData;
    } else {
      // Clear pfpCrop for non-GIF avatars
      CU.pfpCrop = null;
      delete _pfpCropCache[CU.username];
      showCropModal(fileData, 1, async (cropped) => {
        CU.pfp = cropped;
        await saveUser();
        updateUserbar();
        buildProfileView('myprofile');
        try { const s = FortizedSocial.getSocket(); if(s) s.emit('profile:update', { username: CU.username, pfp: cropped, pfpCrop: null, field: 'pfp' }); } catch(e){}
        _saveRecentAvatar(cropped);
        toast('Avatar updated! ✓', 'success');
      });
    }
  };
  reader.readAsDataURL(file);
}
async function updateBanner(e) {
  // Require Basic Radiance or Radiance+ to change banner
  const hasRadiance = CU?.radianceUntil && new Date(CU.radianceUntil) > new Date();
  if (!hasRadiance) {
    toast('Custom banners require a Radiance subscription!', 'error');
    e.target.value = '';
    return;
  }
  const file = e.target.files[0];
  if (!file) return;
  if (file.size > 8*1024*1024) { toast('Max 8MB', 'error'); return; }
  const reader = new FileReader();
  reader.onload = async ev => {
    const fileData = ev.target.result;
    showCropModal(fileData, 16/5, async (cropped) => {
      CU.banner = cropped;
      await saveUser();
      buildProfileView('myprofile');
      toast('Banner updated! ✓', 'success');
    });
  };
  reader.readAsDataURL(file);
}
async function setMyStatus(s) {
  if (!CU?.username) return;
  setUserStatus(s);
  // Re-render own profile panel if open
  const own = document.getElementById('own-profile-panel');
  if (own) { toggleOwnProfilePanel(); toggleOwnProfilePanel(); }
}
function toggleNotifSetting(key,el){notifSettings[key]=!notifSettings[key];el.classList.toggle('on',notifSettings[key]);}
async function saveNotifSettings(){const btn=document.querySelector('[onclick*="saveNotifSettings"]');if(btn){btn.classList.add('btn-loading');btn.disabled=true;}CU.notifSettings=notifSettings;await saveUser();if(btn){btn.classList.remove('btn-loading');btn.disabled=false;}toast('Notification settings saved!','success');}

