function _ctxSvg(name) {
  return _ctxIcons[name] || '';
}

// ── Translate message using browser built-in or fallback ──
async function _translateMessage(msgRow, text) {
  if (!text || !text.trim()) { toast('Nothing to translate', 'info'); return; }
  const cleanText = text.replace(/<[^>]+>/g, '').replace(/\[FTZ[A-Z]+:[^\]]+\]/g, '').trim();
  if (!cleanText) { toast('Nothing to translate', 'info'); return; }
  // Detect user's browser language
  const targetLang = (navigator.language || 'en').split('-')[0];
  try {
    // Try using the free MyMemory Translation API
    const res = await fetch(`https://api.mymemory.translated.net/get?q=${encodeURIComponent(cleanText.slice(0,500))}&langpair=autodetect|${targetLang}`);
    const data = await res.json();
    if (data?.responseData?.translatedText) {
      const translated = data.responseData.translatedText;
      // Show translation inline below message
      let existingTr = msgRow.querySelector('.msg-translation');
      if (existingTr) existingTr.remove();
      const trDiv = document.createElement('div');
      trDiv.className = 'msg-translation';
      trDiv.style.cssText = 'margin-top:6px;padding:8px 12px;background:rgba(254,248,61,.04);border:1px solid rgba(254,248,61,.1);border-radius:10px;font-size:12.5px;color:rgba(255,255,255,.65);line-height:1.55;';
      trDiv.innerHTML = '<span style="font-size:9.5px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(254,248,61,.4);display:block;margin-bottom:4px;">🌐 Translation</span>' + escapeHTML(translated);
      const textEl = msgRow.querySelector('.msg-text') || msgRow.querySelector('.msg-body');
      if (textEl) textEl.appendChild(trDiv);
      else msgRow.appendChild(trDiv);
      toast('Translated!', 'success');
    } else { toast('Translation unavailable', 'error'); }
  } catch { toast('Translation failed — check your connection', 'error'); }
}

// Close context menu
function _closeCtxMenu() {
  const menu = document.getElementById('ctx-menu');
  const overlay = document.getElementById('ctx-overlay');
  if (menu && menu.classList.contains('ctx-visible')) {
    menu.style.transition = 'opacity .1s ease, transform .1s ease';
    menu.style.opacity = '0';
    menu.style.transform = 'scale(.97)';
    setTimeout(() => {
      menu.classList.remove('ctx-visible');
      menu.innerHTML = '';
      menu.style.transition = '';
      menu.style.opacity = '';
      menu.style.transform = '';
    }, 100);
  } else if (menu) {
    menu.classList.remove('ctx-visible');
    menu.innerHTML = '';
  }
  if (overlay) overlay.style.display = 'none';
}

// Build context menu items from grouped structure
// groups = [ { label?, items: [ { icon, label, hint?, action?, danger?, disabled? } ] } ]
function showCtxMenu(x, y, groups) {
  _closeCtxMenu();
  const menu = document.getElementById('ctx-menu');
  const overlay = document.getElementById('ctx-overlay');
  menu.innerHTML = '';

  const isMobile = window.innerWidth <= 768;

  groups.forEach((group, gi) => {
    const gDiv = document.createElement('div');
    gDiv.className = 'ctx-group';
    if (group.label) {
      const lbl = document.createElement('div');
      lbl.className = 'ctx-section-label';
      lbl.textContent = group.label;
      gDiv.appendChild(lbl);
    }
    let itemIdx = 0;
    group.items.forEach(item => {
      const el = document.createElement('div');
      el.className = 'ctx-item' + (item.danger ? ' danger' : '') + (item.disabled ? ' disabled' : '');
      el.style.opacity = '0';
      el.style.transform = 'translateX(-6px)';
      el.innerHTML =
        `<span class="ctx-icon">${item.icon || ''}</span>` +
        `<span class="ctx-label">${item.label}</span>` +
        (item.hint ? `<span class="ctx-hint">${item.hint}</span>` : '');

      // Staggered fade-in
      const delay = itemIdx * 20;
      requestAnimationFrame(() => {
        setTimeout(() => {
          el.style.transition = 'opacity .12s ease, transform .12s ease';
          el.style.opacity = '1';
          el.style.transform = 'translateX(0)';
        }, delay);
      });
      itemIdx++;

      if (item.action && !item.disabled) {
        el.onclick = ev => {
          ev.stopPropagation();
          // Copy action feedback
          if (item.copyFeedback) {
            const iconSpan = el.querySelector('.ctx-icon');
            item.action();
            iconSpan.innerHTML = _ctxSvg('check');
            iconSpan.style.opacity = '1';
            const _ctxLbl = el.querySelector('.ctx-label'); if (_ctxLbl) _ctxLbl.textContent = 'Copied!';
            el.style.background = 'rgba(62,207,110,.08)';
            el.style.color = '#3ecf6e';
            setTimeout(() => _closeCtxMenu(), 400);
            return;
          }
          item.action();
          _closeCtxMenu();
        };
      }
      gDiv.appendChild(el);
    });
    menu.appendChild(gDiv);
  });

  if (isMobile) {
    // Bottom-sheet mode
    menu.style.left = '';
    menu.style.top = '';
    menu.style.right = '';
    menu.style.bottom = '';
    if (overlay) { overlay.style.display = 'block'; overlay.className = 'ctx-overlay'; overlay.onclick = _closeCtxMenu; }
  } else {
    menu.style.left = x + 'px';
    menu.style.top = y + 'px';
  }

  menu.classList.add('ctx-visible');

  if (!isMobile) {
    requestAnimationFrame(() => {
      const r = menu.getBoundingClientRect();
      if (r.right > window.innerWidth - 8) menu.style.left = Math.max(8, x - r.width) + 'px';
      if (r.bottom > window.innerHeight - 8) menu.style.top = Math.max(8, y - r.height) + 'px';
    });
  }
}

// ── Main Context Menu Handler ──
function handleContextMenu(e) {
  const target = e.target;
  // Block right-click on internal Fortized images/media (emojis, emblems, banners, uploads)
  if (target.tagName === 'IMG' || target.tagName === 'VIDEO') {
    const isInternal = target.closest('.msg-emoji, .ftz-embed, .ftz-embed-gif, .epp-emoji-grid, .epp-custom-emoji, .invite-avatar, .invite-right-logo, .emoji-detail-popup') ||
      target.classList.contains('msg-emoji') || target.dataset.emojiType ||
      target.closest('.bastion-banner') || target.closest('.bastion-icon');
    if (isInternal) { e.preventDefault(); e.stopPropagation(); return; }
  }
  // Bail out for elements that have their own inline context menu handlers
  if (target.closest('.rail-bastion') || target.closest('.rail-btn[oncontextmenu]')) return;
  const msgRow = target.closest('.msg-row');
  const isInput = target.tagName === 'TEXTAREA' || target.tagName === 'INPUT';
  const isAuthor = target.closest('.msg-author');
  const isSidebar = target.closest('.sidebar');
  const isSidebarLogo = target.closest('.sidebar-logo');
  const isSidebarBlank = isSidebar && !target.closest('.rail-btn') && !target.closest('.rail-bastion') && !target.closest('.userbar') && !target.closest('.sidebar-logo') && !target.closest('.onyx-pill');
  const isChatArea = target.closest('.msg-list') || target.closest('.chat-main') || target.closest('#chat-area');
  const isSystemMsg = msgRow && msgRow.classList.contains('msg-system');
  const context = curDM ? 'dm' : curGC ? 'gc' : 'ch';

  // ── 1) User context menu (clicking on author name) ──
  if (isAuthor && !isSystemMsg) {
    e.preventDefault();
    const username = isAuthor.dataset.author || isAuthor.textContent.trim();
    const isMe = username === CU?.username;
    const inBastion = curBastion !== null;
    const b = inBastion ? CU.bastions?.[curBastion] : null;
    const isOwner = b?.owner === CU?.username;

    const _ctxBlocked = !isMe && isUserBlocked(username);
    const _ctxIgnored = !isMe && isUserIgnored(username);
    const profileGroup = {
      label: 'Profile',
      items: [
        { icon: _ctxSvg('profile'), label: 'View Profile', action: () => viewUserProfile(username) },
        { icon: _ctxSvg('message'), label: 'Message', action: () => openDMView(username), disabled: isMe || _ctxBlocked },
        { icon: _ctxSvg('mention'), label: 'Mention', action: () => { const ta = document.querySelector('.chat-input-row textarea'); if (ta) { ta.value += `@${username} `; ta.focus(); } } },
        ...(!isMe && !_ctxBlocked ? [{ icon: _ctxSvg('addFriend'), label: 'Add Friend', action: () => quickAddFriend(username) }] : []),
      ]
    };

    const groups = [profileGroup];

    if (!isMe) {
      const safetyItems = [];
      safetyItems.push({ icon: '🚫', label: _ctxBlocked ? 'Unblock' : 'Block', danger: !_ctxBlocked, action: () => toggleBlockUser(username) });
      if (!_ctxBlocked) {
        safetyItems.push({ icon: '🔇', label: _ctxIgnored ? 'Unignore' : 'Ignore', action: () => _ctxIgnored ? unignoreUser(username) : showIgnorePicker(username) });
      }
      groups.push({ label: 'Safety', items: safetyItems });
    }

    if (inBastion && !isMe) {
      const bastionItems = [];
      bastionItems.push({ icon: _ctxSvg('roles'), label: 'View Roles', action: () => viewUserProfile(username) });
      bastionItems.push({ icon: _ctxSvg('mute'), label: isUserMutedLocal(username) ? 'Unmute' : 'Mute', action: () => toggleMuteUserLocal(username) });
      if (isOwner) {
        bastionItems.push({ icon: _ctxSvg('kick'), label: 'Kick', action: () => _kickBastionMember(username), danger: true });
        bastionItems.push({ icon: _ctxSvg('ban'), label: 'Ban', action: () => _banBastionMember(username), danger: true });
      }
      groups.push({ label: 'Bastion', items: bastionItems });
    }

    showCtxMenu(e.clientX, e.clientY, groups);
    return;
  }

  // ── 2) Message context menu ──
  if (msgRow && !isSystemMsg) {
    e.preventDefault();
    const msgId = msgRow.dataset.msgid;
    const text = msgRow.dataset.text || '';
    const isOwn = msgRow.dataset.from === CU?.username;
    const isPinned = msgRow.classList.contains('pinned');
    const inBastion = curBastion !== null;

    const primaryGroup = {
      label: 'Primary',
      items: [
        { icon: _ctxSvg('reply'), label: 'Reply', hint: 'R', action: () => replyToMsg(msgId, msgRow.querySelector('.msg-author')?.textContent || '', context) },
        { icon: _ctxSvg('emoji'), label: 'React', action: () => addReactionUI(msgId, context) },
        { icon: _ctxSvg('forward'), label: 'Forward', action: () => forwardMsg(text, _forwardOriginFromRow(msgRow)) },
        { icon: _ctxSvg('copy'), label: 'Copy Text', hint: 'C', action: () => navigator.clipboard.writeText(text), copyFeedback: true },
      ]
    };

    const interactionGroup = {
      label: 'Interaction',
      items: [
        { icon: isPinned ? _ctxSvg('unpin') : _ctxSvg('pin'), label: isPinned ? 'Unpin Message' : 'Pin Message', action: () => pinMessage(msgId, text) },
        ...(inBastion ? [{ icon: _ctxSvg('thread'), label: 'Create Thread', action: () => openThread(msgId, text, msgRow?.dataset?.from || '') }] : []),
        { icon: _ctxSvg('globe'), label: 'Translate', action: () => { _translateMessage(msgRow, text); } },
        { icon: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>', label: 'Add Note on User', action: () => _openUserNote(msgRow?.dataset?.from || '') },
      ]
    };

    const moderationGroup = {
      label: 'Moderation',
      items: []
    };

    if (isOwn) {
      moderationGroup.items.push({ icon: _ctxSvg('edit'), label: 'Edit', action: () => editMsg(msgId, context) });
    }
    moderationGroup.items.push({ icon: _ctxSvg('report'), label: 'Report Message', action: () => reportMessage(msgId, text, msgRow.dataset.from) });
    const isBastionAdminCtx = inBastion && hasPerm('manage_messages');
    if (isOwn || isBastionAdminCtx) {
      moderationGroup.items.push({ icon: _ctxSvg('trash'), label: 'Delete', danger: true, action: () => deleteMsg(msgId, context) });
    }

    const groups = [primaryGroup, interactionGroup, moderationGroup];
    showCtxMenu(e.clientX, e.clientY, groups);
    return;
  }

  // ── 3) System message — limited actions ──
  if (isSystemMsg) {
    e.preventDefault();
    const text = msgRow?.dataset?.text || msgRow?.textContent?.trim() || '';
    const msgId = msgRow.dataset.msgid;
    const inBastion = curBastion !== null;
    const isBastionAdminCtx = inBastion && hasPerm('manage_messages');
    const sysItems = [
      { icon: _ctxSvg('copy'), label: 'Copy Text', action: () => navigator.clipboard.writeText(text), copyFeedback: true },
    ];
    if (isBastionAdminCtx) {
      sysItems.push({ icon: _ctxSvg('trash'), label: 'Delete', danger: true, action: () => deleteMsg(msgId, context) });
    }
    showCtxMenu(e.clientX, e.clientY, [{ items: sysItems }]);
    return;
  }

  // ── 3.5) Friend list item context menu ──
  const friendItem = target.closest('.friend-item');
  if (friendItem && !msgRow) {
    e.preventDefault();
    const friendName = friendItem.dataset?.username || friendItem.querySelector('.friend-name')?.textContent?.trim() || '';
    if (friendName) {
      const isFriend = (CU?.friends||[]).includes(friendName);
      showCtxMenu(e.clientX, e.clientY, [
        { label: friendName, items: [
          { icon: _ctxSvg('message'), label: 'Message', action: () => openDMView(friendName) },
          { icon: _ctxSvg('profile'), label: 'View Profile', action: () => viewUserProfile(friendName) },
          { icon: _ctxSvg('markRead'), label: 'Mark as Read', action: () => toast('Marked as read!', 'success') },
        ]},
        { items: [
          { icon: _ctxSvg('copy'), label: 'Copy Username', action: () => navigator.clipboard.writeText(friendName), copyFeedback: true },
          { icon: _ctxSvg('mention'), label: 'Mention in Chat', action: () => { const ta = document.querySelector('.chat-input-row textarea'); if (ta) { ta.value += `@${friendName} `; ta.focus(); } } },
        ]},
        ...(isFriend ? [{ items: [
          { icon: _ctxSvg('kick'), label: 'Remove Friend', danger: true, action: () => showCustomConfirm('Remove ' + friendName + ' from friends?', () => removeFriend(friendName)) },
        ]}] : []),
      ]);
      return;
    }
  }

  // ── 3.6) Member list item context menu ──
  const memberItem = target.closest('.member-row') || target.closest('[data-member]');
  if (memberItem && !msgRow) {
    e.preventDefault();
    const memberName = memberItem.dataset?.member || memberItem.dataset?.username || memberItem.querySelector('.member-name')?.textContent?.trim() || '';
    if (memberName) {
      const isMe = memberName === CU?.username;
      const inBastion = curBastion !== null;
      const b = inBastion ? CU.bastions?.[curBastion] : null;
      const isOwner = b?.owner === CU?.username;
      const groups = [
        { label: memberName, items: [
          { icon: _ctxSvg('profile'), label: 'View Profile', action: () => viewUserProfile(memberName) },
          ...(!isMe ? [{ icon: _ctxSvg('message'), label: 'Message', action: () => openDMView(memberName) }] : []),
          { icon: _ctxSvg('mention'), label: 'Mention', action: () => { const ta = document.querySelector('.chat-input-row textarea'); if (ta) { ta.value += `@${memberName} `; ta.focus(); } } },
          { icon: _ctxSvg('copy'), label: 'Copy Username', action: () => navigator.clipboard.writeText(memberName), copyFeedback: true },
        ]},
      ];
      if (!isMe && inBastion && isOwner) {
        groups.push({ label: 'Moderation', items: [
          { icon: _ctxSvg('mute'), label: isUserMutedLocal(memberName) ? 'Unmute' : 'Mute', action: () => toggleMuteUserLocal(memberName) },
          { icon: _ctxSvg('kick'), label: 'Kick', danger: true, action: () => _kickBastionMember(memberName) },
          { icon: _ctxSvg('ban'), label: 'Ban', danger: true, action: () => _banBastionMember(memberName) },
        ]});
      }
      showCtxMenu(e.clientX, e.clientY, groups);
      return;
    }
  }

  // ── 3.7) Image context menu — disabled (no Copy Image Link / Open in Browser) ──

  // ── 3.8) Link context menu ──
  const linkEl = target.closest('a[href]');
  if (linkEl && !isInput && !isSidebar) {
    e.preventDefault();
    showCtxMenu(e.clientX, e.clientY, [
      { items: [
        { icon: _ctxSvg('globe'), label: 'Open Link', action: () => window.open(linkEl.href, '_blank') },
        { icon: _ctxSvg('copy'), label: 'Copy Link', action: () => navigator.clipboard.writeText(linkEl.href), copyFeedback: true },
      ]}
    ]);
    return;
  }

  // ── 4) Input field context menu ──
  if (isInput) {
    e.preventDefault();
    showCtxMenu(e.clientX, e.clientY, [
      { items: [
        { icon: _ctxSvg('paste'), label: 'Paste', action: async () => { const t = await navigator.clipboard.readText(); target.value += t; } },
        { icon: _ctxSvg('copy'), label: 'Copy', action: () => navigator.clipboard.writeText(target.value), copyFeedback: true },
        { icon: _ctxSvg('selectAll'), label: 'Select All', action: () => { target.select(); } },
      ]}
    ]);
    return;
  }

  // ── 5) Sidebar logo / blank area context menu ──
  if (isSidebarLogo || isSidebarBlank) {
    e.preventDefault();
    const groups = [
      { items: [
        { icon: _ctxSvg('search'), label: 'Search', action: () => { const s = document.querySelector('.topbar-search input'); if (s) { s.focus(); s.click(); } else { toast('Search coming soon', 'info'); } } },
        { icon: _ctxSvg('settings'), label: 'Settings', action: () => showView('profile') },
        { icon: _ctxSvg('switchAcct'), label: 'Switch Account', action: () => toggleAccountSwitcher() },
      ]},
      { items: [
        { icon: _ctxSvg('logout'), label: 'Logout', danger: true, action: () => doLogout() },
      ]}
    ];
    showCtxMenu(e.clientX, e.clientY, groups);
    return;
  }

  // ── 6) Empty chat space context menu ──
  if (isChatArea) {
    e.preventDefault();
    const inBastion = curBastion !== null;
    const b = inBastion ? CU.bastions?.[curBastion] : null;
    const isOwner = b?.owner === CU?.username;

    const items = [
      { icon: _ctxSvg('markRead'), label: 'Mark All as Read', action: () => toast('All read!', 'success') },
    ];

    if (window.getSelection()?.toString()) {
      items.unshift({ icon: _ctxSvg('copy'), label: 'Copy Selection', action: () => navigator.clipboard.writeText(window.getSelection().toString()), copyFeedback: true });
    }

    const groups = [{ items }];

    if (inBastion) {
      const bastionItems = [];
      const canManageCh = isOwner || hasPerm('manage_channels');
      if (canManageCh) {
        bastionItems.push({ icon: _ctxSvg('create'), label: 'Create Room', action: () => showCreateRoomModal(curBastion) });
      }
      if (isOwner) {
        bastionItems.push({ icon: _ctxSvg('settings'), label: 'Bastion Settings', action: () => openBastionSettings() });
      }
      if (bastionItems.length) groups.push({ label: 'Bastion', items: bastionItems });
      groups.push({ items: [
        { icon: _ctxSvg('leave'), label: 'Leave Bastion', danger: true, action: () => leaveBastion(curBastion) },
      ]});
    }

    showCtxMenu(e.clientX, e.clientY, groups);
    return;
  }

  // ── 7) Fallback — generic context menu (only when a selection exists) ──
  if (window.getSelection()?.toString()) {
    showCtxMenu(e.clientX, e.clientY, [{ items: [
      { icon: _ctxSvg('copy'), label: 'Copy Selection', action: () => navigator.clipboard.writeText(window.getSelection().toString()), copyFeedback: true },
    ] }]);
  }
}

