// Uses NSFWJS-style client-side detection for images/gifs/videos
// Banned content hashes are stored for re-identification

let _nsfwBannedHashes = JSON.parse(localStorage.getItem('ftz_nsfw_banned_hashes')||'[]');

function _simpleImageHash(dataUrl) {
  // Simple perceptual hash for content re-identification
  let hash = 0;
  const str = dataUrl.slice(dataUrl.indexOf(',')+1, dataUrl.indexOf(',')+500);
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return 'h_' + Math.abs(hash).toString(36);
}

async function scanContentForNSFW(fileData, fileName, uploader, fileType) {
  // NSFW scanning disabled — always return safe
  return { flagged: false, label: 'SCAN_DISABLED', score: 0 };
}

let _nsfwModel = null;
let _nsfwModelLoading = false;
let _nsfwModelRetries = 0;

async function _loadNSFWModel() {
  if (_nsfwModel) return _nsfwModel;
  if (_nsfwModelLoading) {
    // Wait for model to finish loading (max 30s)
    let waited = 0;
    while (_nsfwModelLoading && waited < 30000) { await new Promise(r => setTimeout(r, 200)); waited += 200; }
    return _nsfwModel;
  }
  _nsfwModelLoading = true;
  // Retry up to 3 times with backoff
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      if (typeof nsfwjs === 'undefined') {
        console.warn('NSFWJS library not loaded, waiting...');
        await new Promise(r => setTimeout(r, 2000));
        if (typeof nsfwjs === 'undefined') { throw new Error('nsfwjs library not available'); }
      }
      if (typeof tf !== 'undefined') {
        try { await tf.ready(); } catch (e) { _dbg('[TF] ready failed', e); }
      }
      _nsfwModel = await nsfwjs.load('https://cdn.jsdelivr.net/npm/nsfwjs@2.4.2/model/', { size: 299 });
      if (_nsfwModel) { _dbg('[NSFW] Model loaded (attempt ' + (attempt+1) + ')'); break; }
    } catch(e) {
      console.error('NSFWJS model load attempt ' + (attempt+1) + ' failed:', e);
      _nsfwModel = null;
      if (attempt < 2) await new Promise(r => setTimeout(r, (attempt+1) * 2000));
    }
  }
  _nsfwModelLoading = false;
  _nsfwModelRetries = 0;
  return _nsfwModel;
}

async function _analyzeMediaContent(fileData, fileName, fileType) {
  return new Promise(resolve => {
    let resolved = false;
    const safeResolve = (val) => { if (!resolved) { resolved = true; resolve(val); } };
    if (/^video\//i.test(fileType) || /\.(mp4|webm|mov|avi)$/i.test(fileName)) {
      // For video, extract first frame
      const video = document.createElement('video');
      video.muted = true; video.preload = 'auto';
      video.crossOrigin = 'anonymous';
      video.onloadeddata = () => {
        video.currentTime = Math.min(1, video.duration || 1);
        video.onseeked = async () => {
          try {
            const result = await _analyzeFrame(video, video.videoWidth, video.videoHeight);
            URL.revokeObjectURL(video.src);
            safeResolve(result);
          } catch(e) {
            console.warn('Video frame analysis failed:', e);
            safeResolve({ label: 'SUGGESTIVE', score: '0.50' });
          }
        };
      };
      video.onerror = () => {
        console.warn('Video load failed for NSFW scan');
        safeResolve({ label: 'SUGGESTIVE', score: '0.50' });
      };
      video.src = fileData.startsWith('data:') ? fileData : URL.createObjectURL(new Blob([fileData]));
      setTimeout(() => safeResolve({ label: 'SUGGESTIVE', score: '0.50' }), 15000);
    } else {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = async () => {
        try {
          const result = await _analyzeFrame(img, img.width, img.height);
          safeResolve(result);
        } catch(e) {
          console.warn('Image frame analysis failed:', e);
          safeResolve({ label: 'SUGGESTIVE', score: '0.50' });
        }
      };
      img.onerror = () => {
        console.warn('Image load failed for NSFW scan');
        safeResolve({ label: 'SUGGESTIVE', score: '0.50' });
      };
      img.src = fileData;
      setTimeout(() => safeResolve({ label: 'SUGGESTIVE', score: '0.50' }), 15000);
    }
  });
}

async function _analyzeFrame(source, w, h) {
  // Draw source to canvas for NSFWJS
  const canvas = document.createElement('canvas');
  const maxDim = 299;
  const scale = Math.min(maxDim / (w || 1), maxDim / (h || 1), 1);
  canvas.width = Math.max(1, Math.round((w || 1) * scale));
  canvas.height = Math.max(1, Math.round((h || 1) * scale));
  const ctx = canvas.getContext('2d');
  try { ctx.drawImage(source, 0, 0, canvas.width, canvas.height); } catch(e) {
    console.warn('Canvas drawImage failed:', e);
    return { label: 'SUGGESTIVE', score: '0.50' };
  }

  // Use NSFWJS for real AI classification
  try {
    const model = await _loadNSFWModel();
    if (!model) {
      console.warn('NSFWJS model unavailable, using fallback heuristic');
      return _analyzeFrameFallback(ctx, canvas.width, canvas.height);
    }
    const predictions = await model.classify(canvas);
    // predictions = [{className: 'Porn'|'Sexy'|'Hentai'|'Drawing'|'Neutral', probability: 0-1}, ...]
    const predMap = {};
    predictions.forEach(p => { predMap[p.className] = p.probability; });

    const pornScore = predMap['Porn'] || 0;
    const hentaiScore = predMap['Hentai'] || 0;
    const sexyScore = predMap['Sexy'] || 0;
    const explicitScore = pornScore + hentaiScore;
    const combinedScore = explicitScore + (sexyScore * 0.5);

    _dbg('[NSFW] scan:', JSON.stringify(predMap), '→ explicit:', explicitScore.toFixed(2), 'combined:', combinedScore.toFixed(2));

    if (explicitScore > 0.30) return { label: 'EXPLICIT', score: combinedScore.toFixed(2) };
    if (combinedScore > 0.45) return { label: 'SUGGESTIVE', score: combinedScore.toFixed(2) };
    if (sexyScore > 0.50) return { label: 'SUGGESTIVE', score: sexyScore.toFixed(2) };
    return { label: 'SAFE', score: (1 - combinedScore).toFixed(2) };
  } catch(e) {
    console.warn('NSFWJS classify error, using fallback:', e);
    return _analyzeFrameFallback(ctx, canvas.width, canvas.height);
  }
}

function _analyzeFrameFallback(ctx, w, h) {
  // Fallback skin-tone heuristic if NSFWJS fails to load
  const data = ctx.getImageData(0, 0, w, h).data;
  let skinPixels = 0, totalPixels = w * h;
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i], g = data[i+1], b = data[i+2];
    if (r > 95 && g > 40 && b > 20 && r > g && r > b && (r - g) > 15 && Math.abs(r - g) < 100) {
      skinPixels++;
    }
  }
  const skinRatio = skinPixels / totalPixels;
  if (skinRatio > 0.55) return { label: 'EXPLICIT', score: skinRatio.toFixed(2) };
  if (skinRatio > 0.40) return { label: 'SUGGESTIVE', score: skinRatio.toFixed(2) };
  return { label: 'SAFE', score: skinRatio.toFixed(2) };
}

function _flagNsfwContent(fileData, fileName, uploader, fileType, aiLabel, aiScore, hash) {
  const mediaType = /^video\//i.test(fileType) || /\.(mp4|webm|mov|avi)$/i.test(fileName) ? 'video'
    : /\.gif$/i.test(fileName) ? 'gif' : 'image';

  const item = {
    id: 'nsfw_' + Date.now(),
    uploader,
    fileName,
    aiLabel,
    aiScore,
    hash,
    type: mediaType,
    status: 'pending',
    flaggedAt: new Date().toISOString(),
    bastionId: curBastion !== null ? (CU.bastions?.[curBastion]?.globalId || CU.bastions?.[curBastion]?.name) : null,
    // Store a thumbnail (first 50KB) for review, not the full file
    thumbnail: fileData?.slice(0, 50000) || null,
  };

  const queue = JSON.parse(localStorage.getItem('ftz_nsfw_queue') || '[]');
  queue.push(item);
  localStorage.setItem('ftz_nsfw_queue', JSON.stringify(queue));

  // Sync to Supabase
  try { FortizedSocial.adminSaveNsfwQueue(queue); } catch(e) { console.warn('[NSFW] Queue save:', e?.message); }

  logAudit('nsfw_flagged', uploader, `AI flagged ${mediaType} "${fileName}" as ${aiLabel} (score: ${aiScore})`);
}

