async function adjustOnyx(direction) {
  const username = document.getElementById('eco-username')?.value?.trim();
  const amount = parseInt(document.getElementById('eco-amount')?.value)||0;
  const reason = document.getElementById('eco-reason')?.value?.trim();
  if (!username) { toast('Enter a username','error'); return; }
  if (!amount||amount<=0) { toast('Enter a valid amount','error'); return; }
  if (!reason) { toast('Reason is required','error'); return; }
  let u = null;
  try { u = await FortizedSocial.getUserByName(username); } catch(e) { _wrn('[Admin] User lookup:', e?.message); }
  if (!u) { toast('User not found','error'); return; }
  const delta = direction > 0 ? amount : -amount;
  u.onyx = Math.max(0, (u.onyx||0) + delta);
  try {
    await FortizedSocial.saveUserObject(u);
    logAudit(direction>0?'onyx_give':'onyx_remove', username, `${direction>0?'+':''}${delta} Onyx - ${reason}`);
    toast(`${direction>0?'Gave':'Removed'} ${amount} Onyx ${direction>0?'to':'from'} ${username}. New balance: ${u.onyx}`,'success');
    document.getElementById('eco-amount').value='';
    document.getElementById('eco-reason').value='';
  } catch(e) { console.error('[Settings] Save failed:', e); toast('Failed to save changes. Please try again.','error'); }
}


// ════════════════════════════════════════════
// INVITE QUEST - Personal invite link
// ════════════════════════════════════════════
async function _showInviteFriendsPanel() {
  // Generate a personal invite code if not existing
  if (!CU.personalInviteCode) {
    CU.personalInviteCode = CU.username + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
    saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
  }
  const link = location.origin + '/app?ref=' + CU.personalInviteCode;
  // Mark daily quest done
  if (!CU.questsDailyLog) CU.questsDailyLog = {};
  CU.questsDailyLog.invite = new Date().toDateString();
  saveUser().catch(e => console.warn('[Save] Failed:', e?.message));

  const ov = document.createElement('div');
  ov.className = 'input-dialog-overlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);backdrop-filter:blur(4px);z-index:9900;display:flex;align-items:center;justify-content:center;padding:20px;animation:inviteOverlayIn .3s ease both;';

  ov.innerHTML = `<div style="background:var(--panel,#13161d);border:1.5px solid rgba(255,249,62,.1);border-radius:18px;width:100%;max-width:460px;display:flex;flex-direction:column;box-shadow:0 24px 60px rgba(0,0,0,.7),0 0 80px rgba(255,249,62,.03);animation:invitePanelIn .25s cubic-bezier(.22,1,.36,1) both;overflow:hidden;">
    <!-- Header -->
    <div style="padding:20px 20px 14px;">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">
        <h3 style="font-family:var(--font-display);font-size:16px;font-weight:800;color:#fff;margin:0;letter-spacing:-.02em;">Invite people to Fortized</h3>
        <button onclick="this.closest('.input-dialog-overlay').remove()" style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);color:rgba(255,255,255,.4);cursor:pointer;font-size:16px;line-height:1;padding:4px 8px;border-radius:8px;transition:all .15s;">&times;</button>
      </div>
      <div style="font-size:12px;color:rgba(255,255,255,.4);margin-bottom:16px;">You earn <strong style="color:var(--accent);">9 Onyx</strong> for each friend who joins!</div>
      <div style="padding:16px;border-radius:12px;background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.05);">
        <div style="font-size:12px;color:rgba(255,255,255,.5);margin-bottom:10px;">Share this link with people outside of Fortized to invite them:</div>
        <div style="display:flex;gap:8px;align-items:center;">
          <input type="text" id="invite-link-display" value="${link}" readonly style="flex:1;padding:9px 14px;border-radius:10px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);color:rgba(255,255,255,.6);font-size:12px;font-family:monospace;outline:none;cursor:text;min-width:0;" onclick="this.select()">
          <button onclick="_copyInviteLink(this)" class="btn-a" style="padding:9px 18px;border-radius:10px;font-size:12.5px;font-weight:700;white-space:nowrap;">Copy</button>
        </div>
      </div>
    </div>
  </div>`;

  document.body.appendChild(ov);
  ov.onclick = e => { if (e.target === ov) ov.remove(); };
}

function _renderInviteFriendsList(list) {
  const el = document.getElementById('invite-friends-list');
  if (!el) return;
  if (!list.length) {
    el.innerHTML = '<div style="padding:20px;text-align:center;color:#949ba4;font-size:13px;">No results found</div>';
    return;
  }
  el.innerHTML = list.map(r => {
    const statusColor = FtzStatus.color(r.status);
    const isOnline = FtzStatus.isPresent(r.status);
    return `<div class="invite-friend-row" data-username="${escapeHTML(r.username)}" data-displayname="${escapeHTML(r.displayName.toLowerCase())}" style="display:flex;align-items:center;gap:12px;padding:8px 10px;border-radius:10px;transition:background .12s;cursor:default;">
      <div style="position:relative;flex-shrink:0;">
        <div style="width:32px;height:32px;border-radius:50%;overflow:hidden;background:rgba(255,255,255,.04);">${buildAvatarHTML(r.pfp,r.displayName,32)}</div>
        <span style="position:absolute;bottom:-1px;right:-1px;width:10px;height:10px;border-radius:50%;background:${statusColor};border:2.5px solid var(--panel,#13161d);"></span>
      </div>
      <div style="flex:1;min-width:0;">
        <div style="font-size:13px;font-weight:600;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(r.displayName)}</div>
        <div style="font-size:11px;color:rgba(255,255,255,.3);">${isOnline ? FtzStatus.publicLabel(r.status) : 'Offline'}</div>
      </div>
      <button onclick="_sendInviteDM(this,'${escapeHTML(r.username)}')" style="padding:6px 14px;border-radius:8px;background:rgba(255,249,62,.06);border:1px solid rgba(255,249,62,.15);color:var(--accent);font-size:12px;font-weight:600;cursor:pointer;transition:all .15s;white-space:nowrap;font-family:var(--font-ui);">Invite</button>
    </div>`;
  }).join('');
}

function _filterInviteFriends(query) {
  const q = (query||'').toLowerCase().trim();
  const all = window._inviteFriendsSorted || [];
  if (!q) { _renderInviteFriendsList(all); return; }
  _renderInviteFriendsList(all.filter(r => r.displayName.toLowerCase().includes(q) || r.username.toLowerCase().includes(q)));
}

async function _sendInviteDM(btn, username) {
  btn.disabled = true;
  btn.textContent = 'Sending...';
  btn.style.borderColor = '#4e5058';
  btn.style.color = '#949ba4';
  try {
    const link = location.origin + '/app?ref=' + CU.personalInviteCode;
    const dmPath = P_dm_path(CU.username, username);
    const msgRef = firebase.database().ref(dmPath).push();
    await msgRef.set({id:msgRef.key, from:CU.username, text:'Hey! Join me on Fortized: ' + link, timestamp:Date.now()});
    btn.textContent = 'Sent';
    btn.style.background = 'rgba(62,207,110,.15)';
    btn.style.borderColor = 'rgba(62,207,110,.3)';
    btn.style.color = '#3ecf6e';
  } catch {
    btn.textContent = 'Failed';
    btn.disabled = false;
    setTimeout(()=>{ btn.textContent = 'Invite'; btn.style.background='rgba(255,249,62,.06)'; btn.style.borderColor = 'rgba(255,249,62,.15)'; btn.style.color = 'var(--accent)'; }, 2000);
  }
}

function _copyInviteLink(btn) {
  const input = document.getElementById('invite-link-display');
  if (!input) return;
  navigator.clipboard.writeText(input.value).then(() => {
    const orig = btn.textContent;
    btn.textContent = 'Copied!';
    btn.style.background = '#3ecf6e';
    btn.style.color = '#0f1119';
    setTimeout(() => { btn.textContent = orig; btn.style.background = ''; btn.style.color = ''; }, 2000);
  }).catch(() => toast('Failed to copy', 'error'));
}

// ── Radiance Gift Modal ──────────────
async function openRadianceGiftModal() {
  if (!CU?.radianceUntil && !CU?.radiancePlus) {
    toast('You need Radiance to gift subscriptions', 'error');
    return;
  }

  const friendsList = CU?.friends || [];
  const selected = new Set();

  // Fetch friend data with PFPs
  const friends = await Promise.all(friendsList.map(async (uname) => {
    try {
      const u = await FortizedSocial.getUserByName(uname);
      return {username:uname, displayName:u?.displayName||uname, pfp:u?.pfp||null, status:u?.status||0};
    } catch (e) {
      return {username:uname, displayName:uname, pfp:null, status:0};
    }
  }));

  const overlay = document.createElement('div');
  overlay.className = 'radiance-gift-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);backdrop-filter:blur(4px);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px;animation:fadeIn .2s ease;';

  overlay.innerHTML = `<div style="background:rgba(20,20,30,.95);border:1px solid rgba(255,119,228,.15);border-radius:14px;width:100%;max-width:480px;max-height:80vh;display:flex;flex-direction:column;box-shadow:0 24px 60px rgba(0,0,0,.8);overflow:hidden;animation:slideUp .25s cubic-bezier(.22,1,.36,1);">
    <!-- Header -->
    <div style="padding:24px;border-bottom:1px solid rgba(255,255,255,.05);">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
        <h3 style="font-family:var(--font-display);font-size:18px;font-weight:900;color:#fff;margin:0;letter-spacing:-.02em;">Gift Radiance</h3>
        <button onclick="this.closest('.radiance-gift-overlay').remove()" style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);color:rgba(255,255,255,.4);cursor:pointer;font-size:18px;line-height:1;padding:4px 8px;border-radius:8px;transition:all .15s;">&times;</button>
      </div>
      <div style="font-size:12px;color:rgba(255,255,255,.45);">Select up to 5 friends and send them a Radiance subscription.</div>
    </div>

    <!-- Search Box -->
    <div style="padding:16px;border-bottom:1px solid rgba(255,255,255,.05);">
      <input type="text" id="gift-friend-search" placeholder="Search friends..." style="width:100%;padding:10px 14px;border-radius:8px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);color:#fff;font-size:13px;outline:none;" oninput="filterGiftFriends(this.value)">
    </div>

    <!-- Friends List -->
    <div id="gift-friends-list" style="flex:1;overflow-y:auto;padding:12px;">
      ${friends.map((f, i) => `
        <div style="display:flex;align-items:center;gap:12px;padding:12px;border-radius:10px;transition:background .12s;cursor:pointer;margin-bottom:4px;" onclick="toggleFriendSelection(${i},this)">
          <input type="checkbox" data-friend-idx="${i}" style="width:18px;height:18px;cursor:pointer;accent-color:#ff77e4;" onchange="updateGiftCost()">
          <div style="flex-shrink:0;">
            <div style="width:36px;height:36px;border-radius:50%;overflow:hidden;background:rgba(255,255,255,.04);">${f.pfp ? `<img src="${escapeHTML(f.pfp)}" style="width:100%;height:100%;object-fit:cover;" onerror="this.src='${_defaultPfpUrl(f.username)}';"/>` : buildAvatarHTML(null, f.displayName, 36)}</div>
          </div>
          <div style="flex:1;min-width:0;">
            <div style="font-size:13px;font-weight:600;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(f.displayName)}</div>
            <div style="font-size:11px;color:rgba(255,255,255,.3);">@${escapeHTML(f.username)}</div>
          </div>
        </div>
      `).join('')}
    </div>

    <!-- Footer with Cost and Button -->
    <div style="padding:16px;border-top:1px solid rgba(255,255,255,.05);background:rgba(0,0,0,.3);">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">
        <span style="font-size:12px;color:rgba(255,255,255,.5);">Cost for <span id="gift-count">0</span> friend<span id="gift-plural">s</span>:</span>
        <div style="display:flex;align-items:center;gap:6px;">
          <img src="/Onyx.png" style="width:16px;height:16px;object-fit:contain;">
          <span id="gift-cost" style="font-family:var(--font-display);font-weight:900;font-size:16px;color:#fff93e;">0</span>
        </div>
      </div>
      <button id="gift-submit-btn" onclick="submitRadianceGift()" style="width:100%;padding:12px;background:linear-gradient(135deg,rgba(255,119,228,.2),rgba(255,119,228,.1));border:1px solid rgba(255,119,228,.3);border-radius:8px;color:#ff77e4;font-family:var(--font-display);font-size:14px;font-weight:800;cursor:pointer;transition:all .18s;letter-spacing:-.01em;" onmouseover="this.style.background='linear-gradient(135deg,rgba(255,119,228,.3),rgba(255,119,228,.2))';this.style.borderColor='rgba(255,119,228,.5)'" onmouseout="this.style.background='linear-gradient(135deg,rgba(255,119,228,.2),rgba(255,119,228,.1))';this.style.borderColor='rgba(255,119,228,.3)'">Share Radiance</button>
    </div>
  </div>`;

  document.body.appendChild(overlay);
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };

  window._radianceGiftSelected = selected;
  window._radianceGiftFriends = friends;
}

function toggleFriendSelection(idx, el) {
  const cb = el.querySelector('input[type="checkbox"]');
  const selected = window._radianceGiftSelected || new Set();
  if (cb.checked) selected.add(idx);
  else selected.delete(idx);
  if (selected.size > 5) { selected.delete(idx); cb.checked = false; toast('Max 5 friends', 'warn'); }
  updateGiftCost();
}

function filterGiftFriends(query) {
  const q = (query || '').toLowerCase().trim();
  const list = document.getElementById('gift-friends-list');
  const rows = list?.querySelectorAll('[onclick*="toggleFriendSelection"]') || [];
  const friends = window._radianceGiftFriends || [];
  rows.forEach((row, i) => {
    const f = friends[i];
    const matches = !q || f.displayName.toLowerCase().includes(q) || f.username.toLowerCase().includes(q);
    row.style.display = matches ? '' : 'none';
  });
}

function updateGiftCost() {
  const selected = window._radianceGiftSelected || new Set();
  const count = selected.size;
  const COSTS = {0:0, 1:400, 2:700, 3:900, 4:1100, 5:1300};
  const cost = COSTS[count] || 0;
  document.getElementById('gift-cost').textContent = cost;
  document.getElementById('gift-count').textContent = count;
  document.getElementById('gift-plural').textContent = count !== 1 ? 's' : '';
  document.getElementById('gift-submit-btn').disabled = count === 0;
  document.getElementById('gift-submit-btn').style.opacity = count === 0 ? '0.5' : '1';
}

async function submitRadianceGift() {
  const selected = Array.from(window._radianceGiftSelected || new Set());
  const friends = window._radianceGiftFriends || [];
  const COSTS = {0:0, 1:400, 2:700, 3:900, 4:1100, 5:1300};
  const cost = COSTS[selected.length];

  if (!selected.length) return;
  if ((CU?.onyx || 0) < cost) {
    toast('Not enough Onyx', 'error');
    return;
  }

  const btn = document.getElementById('gift-submit-btn');
  btn.disabled = true;
  const orig = btn.textContent;
  btn.textContent = 'Gifting...';

  try {
    const giftList = selected.map(idx => friends[idx].username);
    // Call gift function (you'll implement this)
    await sendRadianceGifts(giftList, cost);
    btn.textContent = 'Sent!';
    setTimeout(() => document.querySelector('.radiance-gift-overlay')?.remove(), 1500);
  } catch (err) {
    btn.textContent = orig;
    btn.disabled = false;
    toast(err.message || 'Gift failed', 'error');
  }
}

async function sendRadianceGifts(usernames, cost) {
  // Deduct onyx, send DMs with gift info
  CU.onyx = (CU.onyx || 0) - cost;
  await saveUser();

  const giftMsg = 'Hey! I sent you a Radiance subscription! Check your Atelier now!';
  for (const u of usernames) {
    const dmPath = P_dm_path(CU.username, u);
    const msgRef = firebase.database().ref(dmPath).push();
    await msgRef.set({id:msgRef.key, from:CU.username, text:giftMsg, timestamp:Date.now()});
  }

  toast(`Gifted Radiance to ${usernames.length} friend${usernames.length!==1?'s':''}!`, 'success');
}

// ── Discord-style Bastion Invite UI ──────────────
async function showBastionInviteUI(bastionIdx) {
  const b = CU?.bastions?.[bastionIdx ?? curBastion];
  if (!b) { toast('No bastion selected', 'error'); return; }
  const bi = bastionIdx ?? curBastion;

  // Ensure bastion has a globalId before creating invites
  if (!b.globalId) {
    b.globalId = (b.owner || CU.username) + '_' + Date.now();
    await saveUser();
    await FortizedSocial.addBastionMember(b.globalId, CU.username);
  }
  const gid = b.globalId;

  // Get or create an invite code for this bastion
  let inviteCode = '';
  const invites = b.invites || [];
  const active = invites.find(inv => {
    if (inv.expires && new Date(inv.expires) < new Date()) return false;
    if (inv.maxUses && inv.uses >= inv.maxUses) return false;
    return true;
  });
  if (active) {
    inviteCode = active.code;
  } else {
    // Auto-generate a unique, identifiable invite code: bastion prefix + timestamp + random
    const _bPrefix = (b.name||'b').replace(/[^a-zA-Z0-9]/g,'').slice(0,4).toLowerCase();
    inviteCode = _bPrefix + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
    const newInv = { code: inviteCode, createdBy: CU.username, created: new Date().toISOString(), uses: 0 };
    if (!b.invites) b.invites = [];
    b.invites.push(newInv);
    saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
    if (gid) {
      try { _syncBastionToGlobal(curBastion); } catch(e) { console.warn('[Invite] Sync failed:', e?.message); }
      // Also save to dedicated invites table so API can look it up
      try { await FortizedSocial.saveInvite(inviteCode, {code: inviteCode, bastionId: gid, bastionName: b.name, createdBy: CU.username, created: newInv.created, expires: null, maxUses: 0, uses: 0}); } catch(e) { console.warn('[Invite] Supabase save failed:', e?.message); }
      // Sync full bastion data to global so API has latest info
      _syncBastionToGlobal(bi);
    }
  }
  const inviteLink = location.origin + '/app?invite=' + inviteCode;
  const friends = CU?.friends || [];
  const bastionMembers = Object.keys(b.memberRoles || {});

  const ov = document.createElement('div');
  ov.className = 'input-dialog-overlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);backdrop-filter:blur(4px);z-index:9900;display:flex;align-items:center;justify-content:center;padding:20px;animation:inviteOverlayIn .3s ease both;';

  ov.innerHTML = `<div style="background:var(--panel,#13161d);border:1.5px solid rgba(255,249,62,.1);border-radius:18px;width:100%;max-width:460px;max-height:80vh;display:flex;flex-direction:column;box-shadow:0 24px 60px rgba(0,0,0,.7),0 0 80px rgba(255,249,62,.03);animation:invitePanelIn .25s cubic-bezier(.22,1,.36,1) both;overflow:hidden;">
    <div style="padding:20px 20px 0;">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">
        <h3 style="font-family:var(--font-display);font-size:16px;font-weight:800;color:#fff;margin:0;letter-spacing:-.02em;">Invite friends to ${escapeHTML(b.name)}</h3>
        <button onclick="this.closest('.input-dialog-overlay').remove()" style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);color:rgba(255,255,255,.4);cursor:pointer;font-size:16px;line-height:1;padding:4px 8px;border-radius:8px;transition:all .15s;">&times;</button>
      </div>
      <div style="font-size:12px;color:rgba(255,255,255,.35);margin-bottom:14px;display:flex;align-items:center;gap:8px;">${b.icon?`<img src="${escapeHTML(b.icon)}" style="width:18px;height:18px;border-radius:6px;object-fit:cover;">`:`<span style="font-family:var(--font-display);font-weight:800;font-size:14px;color:var(--accent);">${(b.name||'B')[0].toUpperCase()}</span>`} <span style="font-weight:600;color:rgba(255,255,255,.6);">${escapeHTML(b.name)}</span></div>
      <div style="position:relative;margin-bottom:14px;">
        <svg style="position:absolute;left:12px;top:50%;transform:translateY(-50%);color:rgba(255,255,255,.2);" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input type="text" id="bastion-invite-search" placeholder="Search friends..." autocomplete="off" style="width:100%;padding:9px 14px 9px 34px;border-radius:10px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);color:#fff;font-family:var(--font-ui);font-size:13px;outline:none;box-sizing:border-box;transition:border-color .2s;" oninput="_filterBastionInviteFriends(this.value)">
      </div>
    </div>
    <div id="bastion-invite-friends-list" style="flex:1;overflow-y:auto;padding:0 10px 10px;min-height:120px;max-height:340px;">
      <div style="padding:20px;text-align:center;color:rgba(255,255,255,.3);font-size:13px;">Loading friends...</div>
    </div>
    <div style="padding:14px 20px;border-top:1px solid rgba(255,255,255,.04);background:rgba(255,255,255,.01);">
      <div style="font-size:10px;font-weight:700;color:rgba(255,255,255,.25);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;">Or, send a bastion invite link to a friend</div>
      <div style="display:flex;gap:8px;align-items:center;">
        <input type="text" id="bastion-invite-link-display" value="${inviteLink}" readonly style="flex:1;padding:9px 14px;border-radius:10px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);color:rgba(255,255,255,.6);font-size:12px;font-family:monospace;outline:none;cursor:text;min-width:0;" onclick="this.select()">
        <button onclick="_copyBastionInviteLink(this)" class="btn-a" style="padding:9px 18px;border-radius:10px;font-size:12.5px;font-weight:700;white-space:nowrap;">Copy</button>
      </div>
    </div>
  </div>`;

  document.body.appendChild(ov);
  ov.onclick = e => { if (e.target === ov) ov.remove(); };

  // Load friends
  const listEl = document.getElementById('bastion-invite-friends-list');
  if (!friends.length) {
    listEl.innerHTML = '<div class="ftz-empty"><div class="ftz-empty-icon">👥</div><div class="ftz-empty-title">No friends yet</div><div class="ftz-empty-text">Add friends to invite them!</div></div>';
    return;
  }

  const friendData = await Promise.all(friends.map(async f => {
    try {
      const u = await FortizedSocial.getUserByName(f);
      const st = FtzStatus.sanitize(u?.status || 'offline');
      return {username:f, displayName:u?.displayName||f, pfp:u?.pfp||null, status:st, isMember: bastionMembers.includes(f)};
    } catch { return {username:f, displayName:f, pfp:null, status:'offline', isMember: bastionMembers.includes(f)}; }
  }));

  const online = friendData.filter(r => FtzStatus.isPresent(r.status));
  const offline = friendData.filter(r => !FtzStatus.isPresent(r.status));
  const sorted = [...online, ...offline];
  window._bastionInviteFriendsSorted = sorted;
  window._bastionInviteCode = inviteCode;
  _renderBastionInviteFriendsList(sorted);
}

function _renderBastionInviteFriendsList(list) {
  const el = document.getElementById('bastion-invite-friends-list');
  if (!el) return;
  if (!list.length) {
    el.innerHTML = '<div style="padding:20px;text-align:center;color:#949ba4;font-size:13px;">No results found</div>';
    return;
  }
  el.innerHTML = list.map(r => {
    const statusColor = FtzStatus.color(r.status);
    const isOnline = FtzStatus.isPresent(r.status);
    const btnHTML = r.isMember
      ? `<span style="padding:6px 12px;font-size:11px;font-weight:600;color:rgba(255,255,255,.25);">Joined</span>`
      : `<button onclick="_sendBastionInviteDM(this,'${escapeHTML(r.username)}')" style="padding:6px 14px;border-radius:8px;background:rgba(255,249,62,.06);border:1px solid rgba(255,249,62,.15);color:var(--accent);font-size:12px;font-weight:600;cursor:pointer;transition:all .15s;white-space:nowrap;font-family:var(--font-ui);">Invite</button>`;
    return `<div class="bastion-invite-friend-row" data-username="${escapeHTML(r.username)}" data-displayname="${escapeHTML(r.displayName.toLowerCase())}" style="display:flex;align-items:center;gap:12px;padding:8px 10px;border-radius:10px;transition:background .12s;cursor:default;">
      <div style="position:relative;flex-shrink:0;">
        <div style="width:32px;height:32px;border-radius:50%;overflow:hidden;background:rgba(255,255,255,.04);">${buildAvatarHTML(r.pfp,r.displayName,32)}</div>
        <span style="position:absolute;bottom:-1px;right:-1px;width:10px;height:10px;border-radius:50%;background:${statusColor};border:2.5px solid var(--panel,#13161d);"></span>
      </div>
      <div style="flex:1;min-width:0;">
        <div style="font-size:13px;font-weight:600;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(r.displayName)}</div>
        <div style="font-size:11px;color:rgba(255,255,255,.3);">${isOnline ? FtzStatus.publicLabel(r.status) : 'Offline'}</div>
      </div>
      ${btnHTML}
    </div>`;
  }).join('');
}

function _filterBastionInviteFriends(query) {
  const q = (query||'').toLowerCase().trim();
  const all = window._bastionInviteFriendsSorted || [];
  if (!q) { _renderBastionInviteFriendsList(all); return; }
  _renderBastionInviteFriendsList(all.filter(r => r.displayName.toLowerCase().includes(q) || r.username.toLowerCase().includes(q)));
}

async function _sendBastionInviteDM(btn, username) {
  btn.disabled = true;
  btn.textContent = 'Sending...';
  btn.style.borderColor = '#4e5058';
  btn.style.color = '#949ba4';
  try {
    const inviteCode = window._bastionInviteCode;
    const link = location.origin + '/app?invite=' + inviteCode;
    const dmPath = P_dm_path(CU.username, username);
    const msgRef = firebase.database().ref(dmPath).push();
    // Always emit BOTH the ISO `timestamp` and the legacy `time` field —
    // older render paths fall back to `time`, and writing only `Date.now()`
    // (a numeric epoch) caused "Invalid Date" to surface in the date
    // divider when downstream consumers stringified the field with the
    // wrong assumption.
    const _now = new Date();
    await msgRef.set({id:msgRef.key, from:CU.username, text:'Join my bastion! ' + link, timestamp:_now.toISOString(), time:_now.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});
    btn.textContent = 'Sent';
    btn.style.background = 'rgba(62,207,110,.15)';
    btn.style.borderColor = 'rgba(62,207,110,.3)';
    btn.style.color = '#3ecf6e';
  } catch {
    btn.textContent = 'Failed';
    btn.disabled = false;
    setTimeout(()=>{ btn.textContent = 'Invite'; btn.style.background='rgba(255,249,62,.06)'; btn.style.borderColor = 'rgba(255,249,62,.15)'; btn.style.color = 'var(--accent)'; }, 2000);
  }
}

function _copyBastionInviteLink(btn) {
  const input = document.getElementById('bastion-invite-link-display');
  if (!input) return;
  navigator.clipboard.writeText(input.value).then(() => {
    const orig = btn.textContent;
    btn.textContent = 'Copied!';
    btn.style.background = '#3ecf6e';
    btn.style.color = '#0f1119';
    setTimeout(() => { btn.textContent = orig; btn.style.background = ''; btn.style.color = ''; }, 2000);
  }).catch(() => toast('Failed to copy', 'error'));
}

function regeneratePersonalInvite() {
  const code = CU.username + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
  CU.personalInviteCode = code;
  saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
  const display = document.getElementById('invite-link-display');
  const link = location.origin + '/app?ref=' + code;
  if (display) {
    display.textContent = link;
    display.title = 'Click to copy';
    display.style.cursor = 'pointer';
    display.onclick = () => {
      navigator.clipboard.writeText(link).then(()=>toast('Invite link copied!','success')).catch(()=>toast('Link: '+link,'info'));
    };
  }
  toast('Invite link regenerated!','success');
}

function checkPersonalInviteLink() {
  const params = new URLSearchParams(location.search);
  const ref = params.get('ref');
  if (!ref || !ref.includes('-')) return;
  const inviterName = ref.split('-')[0];
  if (inviterName === CU.username) return; // can't refer yourself
  // Record who referred this user
  CU.referredBy = CU.referredBy || inviterName;
  // After 24h, inviter gets 9 Onyx — check on next load
  const joined = CU.joinedAt || new Date().toISOString();
  CU.joinedAt = joined;
  saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
  // Check if 24h have passed and award inviter
  if (CU.referredBy && !CU.referralRewarded) {
    const joinedDate = new Date(CU.joinedAt);
    if ((Date.now() - joinedDate.getTime()) > 86400000) {
      FortizedSocial.getUserByName(CU.referredBy).then(async inviter => {
        if (!inviter) return;
        inviter.onyx = (inviter.onyx||0) + 9;
        await FortizedSocial.saveUserObject(inviter);
        CU.referralRewarded = true;
        await saveUser();
      }).catch(()=>{});
    }
  }
}

function animateOnyxGain(amount) {
  const balEl = document.getElementById('onyx-val') || document.getElementById('atelier-balance');
  if (!balEl) return;
  // Create floating +N animation
  const el = document.createElement('div');
  el.textContent = '+' + amount + ' Onyx';
  el.style.cssText = `position:fixed;font-family:var(--font-display);font-weight:800;font-size:18px;color:var(--accent);pointer-events:none;z-index:9999;text-shadow:0 0 20px rgba(255,249,62,.6);transition:all 1.2s cubic-bezier(.22,1,.36,1);`;
  const rect = balEl.getBoundingClientRect();
  el.style.left = rect.left + 'px';
  el.style.top = rect.top + 'px';
  el.style.opacity = '1';
  document.body.appendChild(el);
  requestAnimationFrame(() => {
    el.style.transform = 'translateY(-60px) scale(1.2)';
    el.style.opacity = '0';
  });
  setTimeout(() => el.remove(), 1300);
  // Pulse the balance counter
  balEl.style.transition = 'transform .2s,color .2s';
  balEl.style.transform = 'scale(1.25)';
  balEl.style.color = '#fff';
  setTimeout(() => { balEl.style.transform = ''; balEl.style.color = 'var(--accent)'; }, 400);
}

