// BASTION INVITE LINKS — WORKING
// ════════════════════════════════════════════
async function checkInviteLink() {
  const params = new URLSearchParams(location.search);
  const invite = params.get('invite');
  const bastionParam = params.get('bastion');
  
  // Handle ?bastion=NAME direct join
  if (bastionParam && !invite) {
    const url = new URL(location.href);
    url.searchParams.delete('bastion');
    history.replaceState({}, '', url);
    if (!CU?.username) return; // not logged in
    await promptJoinPublicBastion(bastionParam);
    return;
  }
  
  if (!invite) return;
  // Clean URL immediately
  const url = new URL(location.href);
  url.searchParams.delete('invite');
  history.replaceState({}, '', url);

  // Use the enhanced joinByInvite that handles both logged-in and guest users
  await joinByInvite(invite);
}

