async function detectRunningApps() {
  // Only works in Electron desktop app — uses native process detection
  if (!window.fortizedDesktop?.isDesktopApp) return [];
  try {
    const procs = await window.fortizedDesktop.getProcesses();
    if (procs) return _matchAllRunningApps(procs);
  } catch (e) { _dbg('[Desktop] getProcesses failed', e); }
  try {
    const games = await window.fortizedDesktop.detectGames();
    if (games.length) return games;
  } catch (e) { _dbg('[Desktop] detectGames failed', e); }
  return [];
}

function addRegisteredGame() {
  // Show app picker overlay
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(12,14,20,.9);backdrop-filter:blur(16px);z-index:9000;display:flex;align-items:center;justify-content:center;padding:20px;';
  overlay.innerHTML = `
    <div style="background:var(--panel);border:1px solid var(--border);border-radius:22px;max-width:480px;width:100%;max-height:80vh;display:flex;flex-direction:column;overflow:hidden;">
      <div style="padding:20px 22px 14px;border-bottom:1px solid var(--border);">
        <div style="font-family:var(--font-display);font-size:18px;font-weight:800;margin-bottom:6px;">Add Game</div>
        <input class="field-input" id="game-search-inp" placeholder="Search or type a name…" style="width:100%;" oninput="filterGamePicker(this.value)">
      </div>
      <div id="game-picker-list" style="overflow-y:auto;flex:1;padding:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px;">
        <div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);">Loading apps…</div>
      </div>
      <div style="padding:12px 20px;border-top:1px solid var(--border);display:flex;gap:8px;">
        <button class="btn-g" style="flex:1;" onclick="this.closest('[style*=fixed]').remove()">Cancel</button>
        <button class="btn-a" style="flex:1;" onclick="addCustomGameManually()">+ Custom Name</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  detectRunningApps().then(apps => renderGamePicker(apps, overlay));
}

let _allApps = [];
function renderGamePicker(apps, overlay) {
  _allApps = apps;
  const list = overlay.querySelector('#game-picker-list');
  if (!list) return;
  list.innerHTML = apps.map(app => `
    <div class="game-picker-item"
         onclick="selectGameFromPicker('${escapeHTML(app.name)}','${app.icon||'🎮'}',this.closest('[style*=fixed]'))">
      <span style="font-size:22px;">${app.icon||'🎮'}</span>
      <span style="font-size:13px;font-weight:600;">${escapeHTML(app.name)}</span>
    </div>`).join('');
}

function filterGamePicker(q) {
  const filtered = q ? _allApps.filter(a => a.name.toLowerCase().includes(q.toLowerCase())) : _allApps;
  const list = document.getElementById('game-picker-list');
  if (!list) return;
  if (!filtered.length && q) {
    list.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:16px;">
      <div style="color:var(--muted);margin-bottom:10px;">No match found</div>
      <button class="btn-a" onclick="selectGameFromPicker('${escapeHTML(q)}','🎮',this.closest('[style*=fixed]'))">Add "${escapeHTML(q)}"</button>
    </div>`;
    return;
  }
  renderGamePicker(filtered, document.getElementById('game-picker-list')?.closest('[style*=fixed]') || document.body);
}

async function selectGameFromPicker(name, icon, overlay) {
  CU.registeredGames = CU.registeredGames || [];
  if (CU.registeredGames.some(g => g.name === name)) {
    toast(name + ' already added','info');
    overlay?.remove();
    return;
  }
  CU.registeredGames.push({ name, icon, addedAt: new Date().toISOString(), active: true });
  await saveUser();
  overlay?.remove();
  buildProfileView('registered_games');
  toast(name + ' added to Registered Games!','success');
}

function addCustomGameManually() {
  const inp = document.getElementById('game-search-inp');
  const name = inp?.value?.trim();
  if (!name) { toast('Type a game name first','error'); return; }
  const overlay = inp?.closest('[style*=fixed]');
  selectGameFromPicker(name, '🎮', overlay);
}


// ════════════════════════════════════════════
// BLOCK / UNBLOCK USER  (Discord-style)
// ════════════════════════════════════════════
function _getBlockedList() { return JSON.parse(localStorage.getItem('ftz_blocked') || '[]'); }
function _saveBlockedList(list) { localStorage.setItem('ftz_blocked', JSON.stringify(list)); }

function toggleBlockUser(username) {
  if (isUserBlocked(username)) {
    _unblockUser(username);
  } else {
    _blockUserConfirm(username);
  }
}

function _blockUserConfirm(username) {
  const isFriend = (CU.friends || []).includes(username);
  showCustomConfirm(
    `Block ${username}?${isFriend ? ' This will also remove them from your friends.' : ''} They won't be able to send you friend requests, and their messages will be hidden.`,
    async () => {
      const blocked = _getBlockedList();
      if (!blocked.includes(username)) blocked.push(username);
      _saveBlockedList(blocked);
      // Auto-unfriend
      if (isFriend) {
        try {
          await FortizedSocial.removeFriend(CU.username, username);
          await refreshCU();
          renderFriendsList();
          renderDMSidebar(document.getElementById('sidebar-scroll'));
        } catch (e) { console.error('Unfriend on block:', e); }
      }
      // Cancel any pending friend requests
      const sentPending = (CU.friendRequestsSent || []).includes(username);
      const recvPending = (CU.friendRequestsReceived || []).includes(username);
      if (sentPending || recvPending) {
        try {
          await FortizedSocial.declineFriendRequest(CU.username, username);
          await refreshCU();
        } catch (e) { _dbg('[Block] cancel friend request failed', e); }
      }
      // Persist to Firebase
      try { await firebase.database().ref('users/' + CU.username + '/blockedUsers').set(blocked); } catch(e) { console.warn('[Block] Save failed:', e?.message); }
      toast(`Blocked ${username}`, 'info');
      closeModal('modal-user');
      // Re-render messages to blur them
      _applyBlockBlurToExistingMessages(username, true);
    }
  );
}

function _unblockUser(username) {
  const blocked = _getBlockedList().filter(u => u !== username);
  _saveBlockedList(blocked);
  try { firebase.database().ref('users/' + CU.username + '/blockedUsers').set(blocked.length ? blocked : null); } catch(e) { console.warn('[Unblock] Save failed:', e?.message); }
  toast(`Unblocked ${username}`, 'success');
  closeModal('modal-user');
  _applyBlockBlurToExistingMessages(username, false);
}

function isUserBlocked(username) {
  return _getBlockedList().includes(username);
}

// ── Conversation mute (silences notifications, keeps messages visible) ──
function _getMutedConvos() {
  try { return JSON.parse(localStorage.getItem('ftz_muted_convos') || '[]'); } catch { return []; }
}
function _saveMutedConvos(arr) {
  localStorage.setItem('ftz_muted_convos', JSON.stringify([...new Set(arr)]));
}
function isConvoMuted(kind, id) {
  if (!id) return false;
  return _getMutedConvos().includes(kind + ':' + id);
}
function toggleMuteConvo(kind, id) {
  if (!id) return false;
  const key = kind + ':' + id;
  const list = _getMutedConvos();
  const idx = list.indexOf(key);
  if (idx >= 0) {
    list.splice(idx, 1);
    _saveMutedConvos(list);
    toast('Notifications unmuted for ' + id, 'success');
    return false;
  }
  list.push(key);
  _saveMutedConvos(list);
  toast('Notifications muted for ' + id, 'info');
  return true;
}

// ── Local per-user mute (silences notifications + messages from a user) ──
function _getMutedUsers() {
  try { return JSON.parse(localStorage.getItem('ftz_muted_users') || '[]'); } catch { return []; }
}
function _saveMutedUsers(arr) {
  localStorage.setItem('ftz_muted_users', JSON.stringify([...new Set(arr)]));
}
function isUserMutedLocal(username) {
  return !!username && _getMutedUsers().includes(username.toLowerCase());
}
function toggleMuteUserLocal(username) {
  if (!username) return false;
  const u = username.toLowerCase();
  const list = _getMutedUsers();
  const idx = list.indexOf(u);
  if (idx >= 0) {
    list.splice(idx, 1);
    _saveMutedUsers(list);
    toast(username + ' unmuted', 'success');
    return false;
  }
  list.push(u);
  _saveMutedUsers(list);
  toast(username + ' muted — you won\'t hear notifications from them', 'info');
  return true;
}

// Apply/remove blur to all visible messages from a user
function _applyBlockBlurToExistingMessages(username, shouldBlur) {
  document.querySelectorAll('.msg-row').forEach(row => {
    if (row.dataset.from !== username) return;
    if (shouldBlur) {
      row.classList.add('msg-blurred');
      row.classList.remove('msg-revealed');
      if (!row.querySelector('.msg-blur-reveal')) {
        const rv = document.createElement('div');
        rv.className = 'msg-blur-reveal';
        rv.innerHTML = '<span>Blocked message — click to reveal</span>';
        rv.onclick = (e) => { e.stopPropagation(); row.classList.add('msg-revealed'); };
        row.appendChild(rv);
      }
    } else {
      row.classList.remove('msg-blurred', 'msg-revealed');
      row.querySelector('.msg-blur-reveal')?.remove();
    }
  });
}

// ════════════════════════════════════════════
// IGNORE USER (timed mute, keeps friend)
// ════════════════════════════════════════════
const IGNORE_DURATIONS = [
  { label: '15 minutes', ms: 15 * 60 * 1000 },
  { label: '1 hour', ms: 60 * 60 * 1000 },
  { label: '5 hours', ms: 5 * 60 * 60 * 1000 },
  { label: '1 day', ms: 24 * 60 * 60 * 1000 },
  { label: '1 week', ms: 7 * 24 * 60 * 60 * 1000 },
  { label: '2 weeks', ms: 14 * 24 * 60 * 60 * 1000 },
];

function _getIgnoreList() {
  const raw = JSON.parse(localStorage.getItem('ftz_ignored') || '{}');
  // Prune expired entries
  const now = Date.now();
  let changed = false;
  for (const u in raw) { if (raw[u] <= now) { delete raw[u]; changed = true; } }
  if (changed) localStorage.setItem('ftz_ignored', JSON.stringify(raw));
  return raw;
}
function _saveIgnoreList(obj) { localStorage.setItem('ftz_ignored', JSON.stringify(obj)); }

// Sync ignore list from Firebase on load
async function _syncIgnoreListFromFirebase() {
  if (!CU?.username) return;
  try {
    const snap = await firebase.database().ref('users/' + CU.username + '/ignoredUsers').once('value');
    const fbData = snap.val();
    if (fbData && typeof fbData === 'object') {
      const localList = _getIgnoreList();
      let merged = false;
      for (const username in fbData) {
        const expiry = fbData[username];
        if (expiry > Date.now() && (!localList[username] || localList[username] < expiry)) {
          localList[username] = expiry;
          merged = true;
        }
      }
      if (merged) _saveIgnoreList(localList);
    }
  } catch (e) { _dbg('[Ignore] sync from Firebase failed', e); }
}

function isUserIgnored(username) {
  const list = _getIgnoreList();
  return list[username] && list[username] > Date.now();
}

function getIgnoreExpiry(username) {
  const list = _getIgnoreList();
  return list[username] || 0;
}

function unignoreUser(username) {
  const list = _getIgnoreList();
  delete list[username];
  _saveIgnoreList(list);
  // Sync to Firebase
  try { firebase.database().ref('users/' + CU.username + '/ignoredUsers/' + username).remove(); } catch(e) { _wrn('[Ignore] Remove sync:', e?.message); }
  toast(`Unignored ${username}`, 'success');
  try { closeModal('modal-user'); } catch (e) { _dbg('[Modal] close failed', e); }
  _applyIgnoreBlurToExistingMessages(username, false);
}

function showIgnorePicker(username) {
  try { closeModal('modal-user'); } catch (e) { _dbg('[Modal] close failed', e); }
  document.getElementById('modal-ignore-picker')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.id = 'modal-ignore-picker';
  overlay.style.cssText = 'display:flex;align-items:center;justify-content:center;';
  overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };
  overlay.innerHTML = `
    <div class="modal" style="max-width:400px;border-radius:20px;background:linear-gradient(165deg,var(--panel),rgba(8,10,18,.98));border:1.5px solid rgba(245,158,11,.12);box-shadow:0 24px 72px rgba(0,0,0,.7);">
      <div class="modal-body" style="padding:24px;">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;">
          <div style="width:36px;height:36px;border-radius:12px;background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.15);display:flex;align-items:center;justify-content:center;font-size:18px;">🔇</div>
          <div>
            <div style="font-family:var(--font-display);font-size:17px;font-weight:800;color:#fff;">Ignore ${escapeHTML(username)}</div>
            <div style="font-size:12px;color:rgba(255,255,255,.4);margin-top:2px;">Messages will be blurred. They stay on your friends list.</div>
          </div>
        </div>
        <div class="ignore-picker" style="display:flex;flex-direction:column;gap:6px;">
          ${IGNORE_DURATIONS.map((d, i) => `
            <div class="ig-opt-item" onclick="_applyIgnore('${escapeHTML(username)}', ${d.ms})">
              <span style="font-size:16px;">🔇</span>
              <span style="flex:1;font-weight:600;">${d.label}</span>
              <span style="font-size:11px;color:rgba(255,255,255,.25);font-weight:600;">Select</span>
            </div>`).join('')}
        </div>
        <button onclick="document.getElementById('modal-ignore-picker')?.remove()" style="width:100%;margin-top:14px;padding:10px;background:rgba(255,255,255,.04);border:1.5px solid rgba(255,255,255,.08);border-radius:12px;color:rgba(255,255,255,.45);font-size:13px;font-weight:600;cursor:pointer;transition:all .15s;">Cancel</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
}

function _applyIgnore(username, durationMs) {
  const list = _getIgnoreList();
  list[username] = Date.now() + durationMs;
  _saveIgnoreList(list);
  // Also persist to Firebase for cross-device sync
  try { firebase.database().ref('users/' + CU.username + '/ignoredUsers/' + username).set(Date.now() + durationMs); } catch(e) { _wrn('[Ignore] Set sync:', e?.message); }
  document.getElementById('modal-ignore-picker')?.remove();
  const dur = IGNORE_DURATIONS.find(d => d.ms === durationMs);
  toast(`Ignoring ${username} for ${dur ? dur.label : 'a while'}`, 'info');
  _applyIgnoreBlurToExistingMessages(username, true);
}

function _applyIgnoreBlurToExistingMessages(username, shouldBlur) {
  document.querySelectorAll('.msg-row').forEach(row => {
    if (row.dataset.from !== username) return;
    if (shouldBlur) {
      if (!row.classList.contains('msg-blurred')) {
        row.classList.add('msg-blurred');
        row.classList.remove('msg-revealed');
        if (!row.querySelector('.msg-blur-reveal')) {
          const rv = document.createElement('div');
          rv.className = 'msg-blur-reveal';
          rv.innerHTML = '<span>Ignored message — click to reveal</span>';
          rv.onclick = (e) => { e.stopPropagation(); row.classList.add('msg-revealed'); };
          row.appendChild(rv);
        }
      }
    } else {
      row.classList.remove('msg-blurred', 'msg-revealed');
      row.querySelector('.msg-blur-reveal')?.remove();
    }
  });
}

// ════════════════════════════════════════════
// NOTIFICATION SOUND (louder + DND-aware)
// ════════════════════════════════════════════
let _notifSoundPlaying = false;
function playNotifSound(type = 'message') {
  if (CU?.status === 'dnd') return;
  if (!notifSettings?.sounds) return;
  if (_notifSoundPlaying) return; // coalesce: only one at a time
  _notifSoundPlaying = true;
  setTimeout(()=>{ _notifSoundPlaying=false; }, 800);
  try {
    const audio = new Audio('/fortized notification.mp3');
    audio.volume = type === 'mention' ? 1.0 : type === 'call' ? 0.9 : 0.8;
    audio.play().catch(() => {
      // Fallback to oscillator if audio file fails
      _playNotifFallback(type);
    });
  } catch (e) {
    _playNotifFallback(type);
  }
}
function _playNotifFallback(type) {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const master = ctx.createGain();
    master.gain.value = 0.7;
    master.connect(ctx.destination);

    if (type === 'message') {
      const osc1 = ctx.createOscillator();
      const g1 = ctx.createGain();
      osc1.connect(g1); g1.connect(master);
      osc1.type = 'sine';
      osc1.frequency.setValueAtTime(880, ctx.currentTime);
      osc1.frequency.setValueAtTime(1100, ctx.currentTime + 0.08);
      g1.gain.setValueAtTime(0.7, ctx.currentTime);
      g1.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
      osc1.start(ctx.currentTime);
      osc1.stop(ctx.currentTime + 0.4);
    } else if (type === 'friend') {
      [523, 659, 784].forEach((freq, i) => {
        const osc = ctx.createOscillator();
        const g = ctx.createGain();
        osc.connect(g); g.connect(master);
        osc.type = 'triangle';
        osc.frequency.value = freq;
        const t = ctx.currentTime + i * 0.1;
        g.gain.setValueAtTime(0.5, t);
        g.gain.exponentialRampToValueAtTime(0.001, t + 0.25);
        osc.start(t); osc.stop(t + 0.25);
      });
    } else if (type === 'call') {
      [440, 550, 660, 550].forEach((freq, i) => {
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.connect(g); g.connect(master);
        o.type = 'sine'; o.frequency.value = freq;
        const t = ctx.currentTime + i * 0.15;
        g.gain.setValueAtTime(0, t);
        g.gain.linearRampToValueAtTime(0.5, t + 0.04);
        g.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
        o.start(t); o.stop(t + 0.15);
      });
    } else if (type === 'mention') {
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.connect(g); g.connect(master);
      osc.type = 'sine';
      osc.frequency.setValueAtTime(1320, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(660, ctx.currentTime + 0.15);
      g.gain.setValueAtTime(0.8, ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.3);
    }
    setTimeout(() => { try { ctx.close(); } catch (e) { _dbg('[Audio] ctx close failed', e); } }, 1000);
  } catch (e) { _dbg('[Audio] sound play failed', e); }
}





// ════════════════════════════════════════════
// RADIANCE: track cumulative time, badge HTML
// ════════════════════════════════════════════
function trackRadianceTime() {
  if (!CU || !CU.radianceUntil) return;
  const now = new Date(), until = new Date(CU.radianceUntil);
  if (until <= now) return;
  const last = CU._radianceLastCheck ? new Date(CU._radianceLastCheck) : now;
  const elapsed = now - last;
  if (elapsed > 0 && elapsed < 86400000) CU.radianceTotalMs = (CU.radianceTotalMs||0) + elapsed;
  CU._radianceLastCheck = now.toISOString();
  saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
}
function radianceBadgeHTML(user) {
  if (!user) return '';
  const active = user.radianceUntil && new Date(user.radianceUntil) > new Date();
  const totalDays = user.radianceTotalMs ? Math.floor(user.radianceTotalMs / 86400000) : 0;
  if (!active && totalDays < 1) return '';
  const isPlus = user.radiancePlus && new Date(user.radiancePlus) > new Date();
  const icon = isPlus ? _radiancePlusImg('12') : _radianceImg('12');
  const label = active ? ' Radiance Active' : (' ' + totalDays + 'd Radiance');
  const badgeColor = isPlus ? '#ffd93e' : '#ff9d3e';
  const badgeBg = isPlus ? 'rgba(255,220,62,.15),rgba(255,249,62,.1)' : 'rgba(255,160,62,.15),rgba(255,180,62,.1)';
  const badgeBorder = isPlus ? 'rgba(255,220,62,.3)' : 'rgba(255,160,62,.3)';
  return '<span style="display:inline-flex;align-items:center;gap:4px;background:linear-gradient(90deg,'+badgeBg+');border:1px solid '+badgeBorder+';border-radius:var(--radius-pill);padding:2px 9px;font-size:10px;font-weight:700;color:'+badgeColor+';">' + icon + label + '</span>';
}

