function _gifChip(btn, category, inputId) {
  _gifChipActivate(btn);
  const grid = document.getElementById('giphy-grid');
  if (grid) grid.style.display = '';
  if (category === 'trending') {
    const searchInput = document.getElementById('giphy-search-input');
    if (searchInput) searchInput.value = '';
    switchGiphyTab('trending', inputId);
  } else {
    const searchInput = document.getElementById('giphy-search-input');
    if (searchInput) searchInput.value = category;
    searchGifs(category, inputId);
  }
}
function _gifChipActivate(btn) {
  const row = document.getElementById('gif-nav-row');
  if (row) row.querySelectorAll('.gif-cat-chip').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  btn.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
}

// Collection grid — pick a category card
function _gifCollectionPick(category, inputId) {
  const collectionView = document.getElementById('gif-collection-view');
  const grid = document.getElementById('giphy-grid');
  const backBar = document.getElementById('gif-back-bar');
  const label = document.getElementById('gif-back-label');
  if (collectionView) collectionView.style.display = 'none';
  if (grid) grid.style.display = '';
  if (backBar) backBar.style.display = '';
  if (label) label.textContent = category === 'favourites' ? 'Favourites' : category === 'trending' ? 'Trending GIFs' : category.charAt(0).toUpperCase() + category.slice(1);
  if (category === 'favourites') { switchGiphyTab('favourites', inputId); }
  else if (category === 'trending') { loadGiphyTrending(inputId); }
  else { searchGifs(category, inputId); }
}

// Back button — return to collection grid
function _gifBackToCollections(inputId) {
  const collectionView = document.getElementById('gif-collection-view');
  const grid = document.getElementById('giphy-grid');
  const backBar = document.getElementById('gif-back-bar');
  const searchInput = document.getElementById('giphy-search-input');
  if (collectionView) collectionView.style.display = '';
  if (grid) grid.style.display = 'none';
  if (backBar) backBar.style.display = 'none';
  if (searchInput) searchInput.value = '';
}

// Load preview GIF thumbnails for collection cards
async function _loadCollectionPreviews() {
  const previewCards = document.querySelectorAll('[data-cat-preview]');
  if (!previewCards.length) return;
  // Load trending preview
  try {
    const cid = CU?.username || 'anon';
    const res = await fetch(KLIPY_BASE + '/gifs/trending?per_page=6&content_filter=medium&customer_id=' + encodeURIComponent(cid));
    const data = await res.json();
    const items = data.data?.data || data.data || [];
    // Assign first gif to trending, then distribute to categories
    const trendCard = document.querySelector('[data-cat-preview="trending"]');
    if (trendCard && items[0]) trendCard.src = _klipyGifUrl(items[0], 'sm') || _klipyGifUrl(items[0], 'xs');
  } catch (e) { _dbg('[Klipy] trending fetch failed', e); }
  // Load a preview for each category (batch a few at a time)
  const cats = [...previewCards].filter(c => c.dataset.catPreview !== 'trending');
  for (let i = 0; i < cats.length; i += 4) {
    const batch = cats.slice(i, i + 4);
    await Promise.allSettled(batch.map(async (card) => {
      try {
        const cat = card.dataset.catPreview;
        const cid = CU?.username || 'anon';
        const res = await fetch(KLIPY_BASE + '/gifs/search?q=' + encodeURIComponent(cat) + '&per_page=1&content_filter=medium&customer_id=' + encodeURIComponent(cid));
        const data = await res.json();
        const items = data.data?.data || data.data || [];
        if (items[0]) card.src = _klipyGifUrl(items[0], 'sm') || _klipyGifUrl(items[0], 'xs');
      } catch (e) { _dbg('[Klipy] category preview failed', e); }
    }));
  }
}

function _giphyOutsideClose(e) {
  const picker = document.getElementById('giphy-picker');
  if (picker && !picker.contains(e.target)) picker.remove();
}

function switchGiphyTab(tab, inputId) {
  _giphyTab = tab;
  if (tab === 'favourites') renderFavGifs(inputId);
  else if (tab === 'trending') loadGiphyTrending(inputId);
}

function handleGiphySearch(q, inputId) {
  const grid = document.getElementById('giphy-grid');
  const collectionView = document.getElementById('gif-collection-view');
  const backBar = document.getElementById('gif-back-bar');
  clearTimeout(window._giphySearchTimer);
  window._giphySearchTimer = setTimeout(() => {
    if (!q.trim()) {
      _giphyTab = 'trending';
      // Show collections again
      if (collectionView) collectionView.style.display = '';
      if (grid) grid.style.display = 'none';
      if (backBar) backBar.style.display = 'none';
      return;
    }
    // Hide collections, show grid
    if (collectionView) collectionView.style.display = 'none';
    if (grid) grid.style.display = '';
    if (backBar) { backBar.style.display = ''; const label = document.getElementById('gif-back-label'); if (label) label.textContent = 'Search: ' + q; }
    searchGifs(q, inputId);
  }, 300);
}

async function loadGiphyTrending(inputId) {
  const grid = document.getElementById('giphy-grid');
  if (!grid) return;
  grid.style.display = '';
  grid.innerHTML = '<div style="grid-column:1/-1;display:flex;justify-content:center;padding:20px;"><div class="pl-spinner" style="width:20px;height:20px;border-width:2px;"></div></div>';
  try {
    const cid = CU?.username || 'anon';
    const res = await fetch(KLIPY_BASE + '/gifs/trending?per_page=30&content_filter=medium&customer_id=' + encodeURIComponent(cid));
    const data = await res.json();
    renderGiphyResults((data.data?.data || data.data || []), inputId);
  } catch { grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);">Failed to load</div>'; }
}

async function searchGifs(q, inputId) {
  const grid = document.getElementById('giphy-grid');
  if (!grid) return;
  grid.style.display = '';
  grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);">Searching…</div>';
  try {
    const cid = CU?.username || 'anon';
    const res = await fetch(KLIPY_BASE + '/gifs/search?q=' + encodeURIComponent(q) + '&per_page=30&content_filter=medium&customer_id=' + encodeURIComponent(cid));
    const data = await res.json();
    renderGiphyResults((data.data?.data || data.data || []), inputId);
  } catch { grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);">Search failed</div>'; }
}

async function _resolveKlipySlug(placeholderId, slug) {
  const el = document.getElementById(placeholderId);
  if (!el) return;
  try {
    const cid = CU?.username || 'anon';
    const res = await fetch(KLIPY_BASE + '/gifs/search?q=' + encodeURIComponent(slug.replace(/-/g, ' ')) + '&per_page=5&content_filter=medium&customer_id=' + encodeURIComponent(cid));
    const data = await res.json();
    const items = data.data?.data || data.data || [];
    // Try to find exact slug match, otherwise use first result
    const match = items.find(g => g.slug === slug) || items[0];
    if (match) {
      const gifUrl = _klipyGifUrl(match, 'hd') || _klipyGifUrl(match, 'md') || _klipyGifUrl(match, 'sm') || _klipyGifUrl(match, 'xs');
      if (gifUrl) {
        const safe = escapeHTML(gifUrl);
        const gid = match.slug || match.id || slug;
        el.innerHTML = `<img src="${safe}" loading="lazy"><button class="chat-gif-fav-btn" onclick="event.stopPropagation();saveFavGif({id:'${escapeHTML(String(gid))}',url:'${safe}'})" title="Save to favourites"><svg width="14" height="14" viewBox="0 0 24 24" fill="#fff93e" stroke="none"><polygon points="12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26"/></svg></button>`;
        el.style.minHeight = '';
        el.onclick = () => _openMediaLightbox(gifUrl);
        return;
      }
    }
    // Fallback — open on Klipy
    el.innerHTML = `<div style="font-size:11px;color:rgba(255,255,255,.3);cursor:pointer;" onclick="openExternalLink(event,'https://klipy.com/gifs/${escapeHTML(slug)}')">Could not load GIF — click to view on Klipy</div>`;
    el.style.minHeight = '';
  } catch {
    el.innerHTML = `<div style="font-size:11px;color:rgba(255,255,255,.3);cursor:pointer;" onclick="openExternalLink(event,'https://klipy.com/gifs/${escapeHTML(slug)}')">Could not load GIF — click to view on Klipy</div>`;
    el.style.minHeight = '';
  }
}

function _klipyGifUrl(item, size) {
  // Extract best available GIF URL from Klipy response item
  // Prefer webp/mp4 over gif — gif format has 256-color limit causing grainy/banded visuals
  const f = item.file || {};
  const sz = f[size] || f.hd || f.md || f.sm || f.xs || {};
  return sz.webp?.url || sz.mp4?.url || sz.gif?.url || sz.jpg?.url || '';
}

function renderGiphyResults(gifs, inputId) {
  const grid = document.getElementById('giphy-grid');
  if (!grid) return;
  if (!gifs || !gifs.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px 20px;gap:8px;"><div style="font-size:24px;opacity:.4;">🔍</div><div style="font-size:12px;color:rgba(255,255,255,.25);">No GIFs found</div></div>';
    return;
  }
  grid.innerHTML = gifs.map(g => {
    const thumb = _klipyGifUrl(g, 'hd') || _klipyGifUrl(g, 'md') || _klipyGifUrl(g, 'sm') || _klipyGifUrl(g, 'xs');
    const fullUrl = _klipyGifUrl(g, 'hd') || _klipyGifUrl(g, 'md') || thumb;
    const gid = g.slug || g.id || ('klipy-' + Math.random().toString(36).slice(2,8));
    if (!thumb && !fullUrl) return '';
    return `<div class="gif-card" data-id="${escapeHTML(String(gid))}" data-url="${escapeHTML(fullUrl)}" data-input="${escapeHTML(inputId)}" style="position:relative;border-radius:10px;overflow:hidden;cursor:pointer;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.05);break-inside:avoid;margin-bottom:8px;transition:all .2s cubic-bezier(.22,1,.36,1);">
      <img src="${escapeHTML(thumb)}" style="width:100%;display:block;border-radius:9px;image-rendering:auto;" loading="lazy" draggable="false">
      <div class="gif-hover-overlay" style="position:absolute;inset:0;opacity:0;transition:.18s;background:linear-gradient(to top,rgba(0,0,0,.7) 0%,transparent 45%);display:flex;align-items:flex-end;justify-content:space-between;padding:10px;pointer-events:none;border-radius:10px;">
        <div style="font-size:10px;font-weight:600;color:rgba(255,255,255,.9);text-shadow:0 1px 4px rgba(0,0,0,.6);max-width:70%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHTML(g.title||'')}</div>
      </div>
      <button class="gif-fav-btn" onclick="event.stopPropagation();saveFavGif({id:'${escapeHTML(String(gid))}',url:'${escapeHTML(fullUrl)}'})" title="Save" style="position:absolute;top:6px;right:6px;background:rgba(0,0,0,.55);backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.1);color:#ffd93e;border-radius:8px;width:28px;height:28px;font-size:12px;cursor:pointer;display:flex;align-items:center;justify-content:center;opacity:0;transition:.18s;pointer-events:auto;">★</button>
    </div>`;
  }).join('');
  grid.querySelectorAll('.gif-card').forEach(card => {
    const ov = card.querySelector('.gif-hover-overlay');
    const fav = card.querySelector('.gif-fav-btn');
    card.addEventListener('mouseenter', () => { card.style.transform='scale(1.03) translateY(-2px)'; card.style.boxShadow='0 8px 24px rgba(0,0,0,.35)'; card.style.borderColor='rgba(255,249,62,.12)'; ov.style.opacity='1'; fav.style.opacity='1'; });
    card.addEventListener('mouseleave', () => { card.style.transform=''; card.style.boxShadow=''; card.style.borderColor='rgba(255,255,255,.05)'; ov.style.opacity='0'; fav.style.opacity='0'; });
    card.addEventListener('click', () => sendGifDirectly(card.dataset.id, card.dataset.input, card.dataset.url));
  });
}

function sendGifDirectly(id, inputId, url) {
  // Close picker first
  document.getElementById('giphy-picker')?.remove();
  const gifUrl = url || '';
  if (!gifUrl) return;
  // Track send_gif quest completion
  if (CU && !CU.completedQuests?.includes('send_gif')) {
    CU.completedQuests = [...(CU.completedQuests||[]), 'send_gif'];
    saveUser(true);
  }
  // Use [FTZGIF] token so parseMD renders it inline directly
  const token = '[FTZGIF:' + gifUrl + ']';
  // Inject into chat input and trigger send
  const inp = document.getElementById(inputId);
  if (inp) {
    const prev = inp.value.trim();
    inp.value = prev ? prev + ' ' + token : token;
    inp.focus();
    // Auto-send immediately
    if (inputId === 'dm-input') handleChatSend('dm');
    else if (inputId === 'gc-input') sendGCMessage();
    else if (inputId === 'ch-input') handleChatSend('ch', curChannel);
  }
}

// Legacy - kept for fav gifs clicking
function insertGifById(id, inputId, url) {
  sendGifDirectly(id, inputId, url);
}

// ════════════════════════════════════════════
// STICKER PICKER — bastion-uploaded stickers
// (Stickers are sent as [FTZSTICKER:url] tokens, never as :name: shortcodes,
//  so they can never collide with the :emoji: shortcode syntax.)
// ════════════════════════════════════════════
let _stickerInput = 'ch-input';
function openStickerPicker(inputId) {
  _stickerInput = inputId || 'ch-input';
  document.getElementById('sticker-picker')?.remove();
  document.getElementById('giphy-picker')?.remove();
  document.getElementById('emoji-picker')?.classList.remove('show');
  document.getElementById('botcmd-picker')?.remove();

  const refEl = document.getElementById(_stickerInput);
  const outerEl = refEl ? refEl.closest('.chat-input-outer') : null;
  const rect = outerEl ? outerEl.getBoundingClientRect() : {right:400, top:300};
  const picker = document.createElement('div');
  picker.id = 'sticker-picker';
  picker.className = 'chat-picker-base sticker-picker-panel';
  const stickerLeft = Math.max(8, _getChatInputRight() - 460);
  const stickerBottom = Math.max(60, window.innerHeight - (rect.top || window.innerHeight - 80) + 6);
  picker.style.cssText = `left:${stickerLeft}px;bottom:${stickerBottom}px;`;

  // Gather stickers from all bastions the user is in
  const allStickers = [];
  const bastionNames = {};

  if (CU?.bastions) {
    Object.entries(CU.bastions).forEach(([idx, b]) => {
      const stickers = b.stickers || b.customStickers || [];
      stickers.forEach(s => {
        allStickers.push({...s, bastionName: b.name || 'Unknown', bastionIdx: idx});
      });
      if (stickers.length) bastionNames[idx] = b.name || 'Unknown';
    });
  }

  const bastionTabsHTML = Object.entries(bastionNames).map(([idx, name]) =>
    `<button class="spp-tab" onclick="_filterStickerBastion('${idx}', event)">${escapeHTML(name)}</button>`
  ).join('');

  picker.innerHTML = `
    ${_pickerTopTabs('sticker')}
    <div style="padding:10px 14px 0;flex-shrink:0;">
      <div class="chat-picker-search" style="padding:0;border:none;position:relative;">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.2)" stroke-width="2" style="position:absolute;left:11px;top:50%;transform:translateY(-50%);pointer-events:none;"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input id="sticker-search-input" placeholder="Search stickers…" style="width:100%;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.05);border-radius:10px;color:#fff;font-family:var(--font-ui);font-size:12.5px;padding:9px 12px 9px 34px;outline:none;box-sizing:border-box;transition:all .18s;" oninput="_searchStickers(this.value)">
      </div>
    </div>
    ${bastionTabsHTML ? `<div class="spp-tabs"><button class="spp-tab active" onclick="_filterStickerBastion('all', event)">All</button>${bastionTabsHTML}</div>` : ''}
    <div class="spp-grid" id="sticker-grid"></div>
    <div style="padding:6px 10px;border-top:1px solid rgba(255,255,255,.03);display:flex;justify-content:center;align-items:center;flex-shrink:0;">
      <span style="font-size:10px;color:rgba(255,255,255,.25);">Stickers come from bastions you're in.</span>
    </div>
  `;

  document.body.appendChild(picker);
  _renderStickers(allStickers);
  document.addEventListener('mousedown', _stickerOutsideClose, {once:true, capture:true});
}

window._allStickersCache = [];
function _renderStickers(stickers) {
  window._allStickersCache = stickers;
  const grid = document.getElementById('sticker-grid');
  if (!grid) return;
  if (!stickers.length) {
    grid.innerHTML = `<div class="spp-empty">
      <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" style="margin-bottom:8px;opacity:.4;"><path d="M12 2a10 10 0 1 0 10 10H12V2z"/><path d="M21 12a9 9 0 0 0-9-9v9h9z"/></svg>
      No stickers available yet.<br>
      <span style="font-size:11px;color:rgba(255,255,255,.2);">Bastion owners can upload stickers in Bastion Settings.</span>
    </div>`;
    return;
  }
  grid.innerHTML = stickers.map(s => `
    <div class="spp-sticker" onclick="_sendSticker('${escapeHTML(s.url||'')}','${escapeHTML(s.name||'sticker')}')" title="${escapeHTML(s.name||'Sticker')}${s.bastionName?' — '+escapeHTML(s.bastionName):''}">
      <img src="${escapeHTML(s.url||'')}" alt="${escapeHTML(s.name||'')}" loading="lazy" draggable="false">
    </div>
  `).join('');
}

function _searchStickers(q) {
  const filtered = q.trim()
    ? window._allStickersCache.filter(s => (s.name||'').toLowerCase().includes(q.toLowerCase()))
    : window._allStickersCache;
  _renderStickers(filtered);
}

function _filterStickerBastion(bastionIdx, event) {
  document.querySelectorAll('.spp-tab').forEach(t => t.classList.remove('active'));
  if (event && event.target) event.target.classList.add('active');
  if (bastionIdx === 'all') {
    _renderStickers(window._allStickersCache);
  } else {
    const filtered = window._allStickersCache.filter(s => String(s.bastionIdx) === String(bastionIdx));
    const grid = document.getElementById('sticker-grid');
    if (!grid) return;
    if (!filtered.length) {
      grid.innerHTML = '<div class="spp-empty">No stickers from this bastion.</div>';
      return;
    }
    grid.innerHTML = filtered.map(s => `
      <div class="spp-sticker" onclick="_sendSticker('${escapeHTML(s.url||'')}','${escapeHTML(s.name||'sticker')}')" title="${escapeHTML(s.name||'Sticker')}">
        <img src="${escapeHTML(s.url||'')}" alt="${escapeHTML(s.name||'')}" loading="lazy" draggable="false">
      </div>
    `).join('');
  }
}

function _sendSticker(url, name) {
  document.getElementById('sticker-picker')?.remove();
  const inp = document.getElementById(_stickerInput);
  if (inp) {
    const token = `[FTZSTICKER:${url}]`;
    const prev = inp.value.trim();
    inp.value = prev ? prev + ' ' + token : token;
    inp.focus();
    // Auto-send sticker
    if (_stickerInput === 'dm-input') handleChatSend('dm');
    else if (_stickerInput === 'gc-input') sendGCMessage();
    else if (_stickerInput === 'ch-input') handleChatSend('ch', curChannel);
  }
}

function _stickerOutsideClose(e) {
  const picker = document.getElementById('sticker-picker');
  if (!picker) return;
  if (!picker.contains(e.target)) { picker.remove(); return; }
  document.addEventListener('mousedown', _stickerOutsideClose, {once:true, capture:true});
}

// ════════════════════════════════════════════
// BOT COMMAND SHORTCUT PANEL
// ════════════════════════════════════════════
function openBotCommandPanel(inputId, context) {
  document.getElementById('botcmd-picker')?.remove();
  document.getElementById('sticker-picker')?.remove();
  document.getElementById('giphy-picker')?.remove();
  document.getElementById('emoji-picker')?.classList.remove('show');

  const refEl = document.getElementById(inputId);
  const outerEl = refEl ? refEl.closest('.chat-input-outer') : null;
  const rect = outerEl ? outerEl.getBoundingClientRect() : {right:400, top:300};
  const picker = document.createElement('div');
  picker.id = 'botcmd-picker';
  picker.className = 'chat-picker-base botcmd-panel';
  const botLeft = Math.max(8, _getChatInputRight() - 420);
  picker.style.cssText = `left:${botLeft}px;bottom:${window.innerHeight-rect.top+6}px;`;

  // Gather bot commands from current bastion
  let commands = [];
  if (context === 'ch' && curBastion !== null) {
    const b = CU?.bastions?.[curBastion];
    const deployedBots = b?.deployedBots || [];
    deployedBots.forEach(bot => {
      if (bot.enabled === false) return;
      const cmds = bot.commands || [];
      cmds.forEach(cmd => {
        commands.push({name: cmd.name, desc: cmd.desc || cmd.description || 'No description', botName: bot.name || 'Bot'});
      });
    });
  }

  picker.innerHTML = `
    <div class="bcp-header">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="4 17 10 11 4 5"/><line x1="12" y1="19" x2="20" y2="19"/></svg>
      Bot Commands
      <span style="font-size:8.5px;color:rgba(96,165,250,.45);letter-spacing:.08em;font-weight:700;text-transform:uppercase;margin-left:auto;background:rgba(96,165,250,.06);padding:3px 9px;border-radius:var(--radius-pill);border:1px solid rgba(96,165,250,.1);">${commands.length} cmd${commands.length!==1?'s':''}</span>
    </div>
    <div style="padding:10px 14px 0;flex-shrink:0;">
      <div class="chat-picker-search" style="padding:0;border:none;position:relative;">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.2)" stroke-width="2" style="position:absolute;left:11px;top:50%;transform:translateY(-50%);pointer-events:none;"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input placeholder="Search commands…" style="width:100%;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.05);border-radius:10px;color:#fff;font-family:var(--font-ui);font-size:12.5px;padding:9px 12px 9px 34px;outline:none;box-sizing:border-box;transition:all .18s;" oninput="_filterBotCmds(this.value,'${escapeHTML(inputId)}')">
      </div>
    </div>
    <div class="botcmd-list" id="botcmd-list"></div>
  `;

  document.body.appendChild(picker);
  window._botcmdCache = commands;

  const list = document.getElementById('botcmd-list');
  if (!commands.length) {
    list.innerHTML = `<div class="botcmd-empty">
      <div style="margin-bottom:6px;opacity:.3;"><img src="/Fortized Bot.png" style="width:22px;height:22px;"></div>
      No bot commands available${context !== 'ch' ? '<br><span style="font-size:11px;color:rgba(255,255,255,.2);">Bot commands are only available in bastion channels.</span>' : ' in this bastion.'}
    </div>`;
  } else {
    list.innerHTML = commands.map(cmd => `
      <div class="botcmd-item" onclick="_insertBotCmd('${escapeHTML(cmd.name)}','${escapeHTML(inputId)}')">
        <span class="bci-prefix">!</span>
        <span class="bci-name">${escapeHTML(cmd.name)}</span>
        <span class="bci-desc">${escapeHTML(cmd.desc)}</span>
        <span class="bci-bot">${escapeHTML(cmd.botName)}</span>
      </div>
    `).join('');
  }

  document.addEventListener('mousedown', _botcmdOutsideClose, {once:true, capture:true});
}

window._botcmdCache = [];
function _filterBotCmds(q, inputId) {
  const list = document.getElementById('botcmd-list');
  if (!list) return;
  const filtered = q.trim() ? window._botcmdCache.filter(c => c.name.toLowerCase().includes(q.toLowerCase()) || c.desc.toLowerCase().includes(q.toLowerCase())) : window._botcmdCache;
  if (!filtered.length) { list.innerHTML = '<div class="botcmd-empty">No matching commands.</div>'; return; }
  list.innerHTML = filtered.map(cmd => `<div class="botcmd-item" onclick="_insertBotCmd('${escapeHTML(cmd.name)}','${escapeHTML(inputId)}')"><span class="bci-prefix">!</span><span class="bci-name">${escapeHTML(cmd.name)}</span><span class="bci-desc">${escapeHTML(cmd.desc)}</span><span class="bci-bot">${escapeHTML(cmd.botName)}</span></div>`).join('');
}
function _insertBotCmd(cmdName, inputId) {
  document.getElementById('botcmd-picker')?.remove();
  const inp = document.getElementById(inputId);
  if (inp) {
    inp.value = '!' + cmdName + ' ';
    inp.focus();
  }
}

function _botcmdOutsideClose(e) {
  const picker = document.getElementById('botcmd-picker');
  if (!picker) return;
  if (!picker.contains(e.target)) { picker.remove(); return; }
  document.addEventListener('mousedown', _botcmdOutsideClose, {once:true, capture:true});
}


// ════════════════════════════════════════════
// FILE UPLOAD (30MB / 45MB for Radiance)
// ════════════════════════════════════════════
function openFileUpload(context) {
  const hasRadiance = CU?.radianceUntil && new Date(CU.radianceUntil) > new Date();
  const maxMB = hasRadiance ? 45 : 30;
  document.getElementById('ftz-file-input')?.remove();
  const fileInp = document.createElement('input');
  fileInp.type='file'; fileInp.id='ftz-file-input';
  fileInp.accept='*/*'; fileInp.style.display='none';
  document.body.appendChild(fileInp);
  fileInp.click();
  fileInp.onchange = () => {
    const file = fileInp.files[0]; if (!file) { fileInp.remove(); return; }
    if (file.size > maxMB * 1024 * 1024) {
      toast('File too large. Max ' + maxMB + 'MB', 'error'); fileInp.remove(); return;
    }
    const reader = new FileReader();
    reader.onload = async ev => {
      const fileData = ev.target.result;
      window._pendingAttachment = { name: file.name, type: file.type, data: fileData, size: file.size, context };
      showAttachmentPreview(file.name, file.type, fileData, file.size, context);
    };
    reader.readAsDataURL(file);
    fileInp.remove();
  };
}


function _closeEl(id){const e=document.getElementById(id);if(e)e.remove();}
function _closeWTPlayer(){_closeEl('wt-player-overlay');if(_vc)_vc.watchingTogether=false;}

function showAttachmentPreview(name, type, dataUrl, size, context) {
  document.getElementById('attach-preview-bar')?.remove();
  const isImage = type.startsWith('image/');
  const isVideo = type.startsWith('video/');
  const isAudio = type.startsWith('audio/');
  const sizeMB = (size/1024/1024).toFixed(2);

  const bar = document.createElement('div');
  bar.id = 'attach-preview-bar';
  bar.className = 'chatbar-file-preview';

  let previewHTML = '';
  if (isImage) {
    previewHTML = `<img src="${escapeHTML(dataUrl)}" id="cfp-img-preview">`;
  } else if (isVideo) {
    previewHTML = `<video src="${escapeHTML(dataUrl)}" style="width:100%;max-height:160px;display:block;" muted></video>`;
  } else if (isAudio) {
    previewHTML = `<div style="width:100%;height:60px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.03);"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="1.5"><path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/></svg></div>`;
  } else {
    previewHTML = `<div style="width:100%;height:60px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.03);font-size:28px;">📎</div>`;
  }

  bar.innerHTML = `<div class="chatbar-file-card" id="cfp-card">
    <div class="cfp-actions">
      <button class="cfp-btn" onclick="_showModifyAttachment()" title="Modify Attachment"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
      <button class="cfp-btn cfp-remove" onclick="_clearAttachment()" title="Remove"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="3,6 5,6 21,6"/><path d="M19 6l-1 14H6L5 6"/><path d="M9 6V4h6v2"/></svg></button>
    </div>
    ${window._pendingAttachment?._spoiler ? '<div class="cfp-spoiler-overlay"><span class="cfp-spoiler-tag">Spoiler</span></div>' : ''}
    ${previewHTML}
    <div class="cfp-name">${escapeHTML(name)} · ${sizeMB} MB</div>
  </div>`;

  // context may be 'dm', 'gc', 'ch' OR 'dm-input', 'gc-input', 'ch-input'
  const inputId = context.endsWith('-input') ? context : (context==='dm' ? 'dm-input' : context==='gc' ? 'gc-input' : 'ch-input');
  const ctxKey = inputId === 'dm-input' ? 'dm' : inputId === 'gc-input' ? 'gc' : 'ch';
  const outerWrap = document.getElementById(inputId)?.closest('.chat-input-outer');
  if (outerWrap) outerWrap.insertBefore(bar, outerWrap.firstChild);
  // Persist the attachment as part of the chat draft so it survives refresh.
  try { _persistPendingAttachmentChange(ctxKey, inputId); } catch(_) {}
}

function _showModifyAttachment() {
  const att = window._pendingAttachment;
  if (!att) return;
  const isImage = att.type.startsWith('image/');
  const overlay = document.createElement('div');
  overlay.className = 'ftz-confirm-overlay';
  overlay.innerHTML = `<div class="ftz-confirm-card" style="max-width:400px;">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
      <div class="ftz-confirm-title" style="margin:0;">Modify Attachment</div>
      <button onclick="this.closest('.ftz-confirm-overlay').remove()" style="background:none;border:none;color:rgba(255,255,255,.3);cursor:pointer;font-size:18px;">&times;</button>
    </div>
    ${isImage ? `<img src="${escapeHTML(att.data)}" style="width:100%;max-height:200px;object-fit:contain;border-radius:10px;margin-bottom:12px;background:rgba(255,255,255,.03);">` : ''}
    <div style="margin-bottom:8px;font-size:12px;font-weight:600;color:rgba(255,255,255,.5);">Filename</div>
    <input id="_mod-att-name" value="${escapeHTML(att.name)}" style="width:100%;padding:8px 12px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:8px;color:#fff;font-size:13px;outline:none;box-sizing:border-box;margin-bottom:12px;">
    <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px;color:rgba(255,255,255,.6);margin-bottom:16px;">
      <input type="checkbox" id="_mod-att-spoiler" ${att._spoiler ? 'checked' : ''} style="accent-color:var(--accent);width:16px;height:16px;">
      Mark as spoiler
    </label>
    <div class="ftz-confirm-actions">
      <button class="ftz-btn ftz-btn-ghost" onclick="this.closest('.ftz-confirm-overlay').remove()">Cancel</button>
      <button class="ftz-btn ftz-btn-danger" style="background:var(--accent);color:#13161d;border-color:var(--accent);" onclick="_applyModifyAttachment(this)">Save</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
}

function _applyModifyAttachment(btn) {
  const att = window._pendingAttachment;
  if (!att) return;
  const newName = document.getElementById('_mod-att-name')?.value?.trim() || att.name;
  const isSpoiler = document.getElementById('_mod-att-spoiler')?.checked || false;
  att.name = newName;
  att._spoiler = isSpoiler;
  btn.closest('.ftz-confirm-overlay').remove();
  showAttachmentPreview(att.name, att.type, att.data, att.size, att.context);
}

function _clearAttachment(){
  document.getElementById("attach-preview-bar")?.remove();
  window._pendingAttachment=null;
  // Update persisted draft so the cleared file isn't restored next open.
  try {
    const ctx = (curBastion!==null && curChannel!==null) ? 'ch' : (curGC ? 'gc' : (curDM ? 'dm' : null));
    if (ctx) _persistPendingAttachmentChange(ctx, ctx==='dm'?'dm-input':ctx==='gc'?'gc-input':'ch-input');
  } catch(_) {}
}

