// ═══════════════════════════════════════════════════════════
// HANDLE CHAT SEND (with file attachment support)
// ═══════════════════════════════════════════════════════════
async function handleChatSend(context, chIdx) {
  const att = window._pendingAttachment;
  if (att) {
    const isImage = att.type.startsWith('image/');
    const isVideo = att.type.startsWith('video/');
    const isAudio = att.type.startsWith('audio/');
    const sizeMB = (att.size/1024/1024).toFixed(2)+' MB';
    let fileUrl = att.data; // fallback to base64
    // Try uploading to Supabase Storage CDN (much smaller message text)
    try {
      const blob = await fetch(att.data).then(r => r.blob());
      const result = await FortizedSocial.uploadFile(att.name, blob);
      if (result.url) { fileUrl = result.url; }
      else { _dbg('[Upload] Storage failed, using base64 fallback:', result.error); }
    } catch(e) { _dbg('[Upload] Storage unavailable, using base64:', e.message); }
    let token;
    if (isImage) token = '[FTZIMG:'+att.name+'|'+fileUrl+']';
    else if (isVideo) token = '[FTZVID:'+att.name+'|'+fileUrl+']';
    else if (isAudio) token = '[FTZAUD:'+att.name+'|'+fileUrl+']';
    else token = '[FTZFILE:'+att.name+'|'+sizeMB+'|'+fileUrl+']';
    const inp = document.getElementById(context==='dm'?'dm-input':context==='gc'?'gc-input':'ch-input');
    if (inp) {
      // The chat input is a contenteditable div with a `.value` shim that
      // `_initRichInput` installs. If the shim hasn't been wired yet (race
      // on first open / after a re-render), `inp.value` is undefined and
      // `.trim()` would throw — locking up the entire send pipeline. Fall
      // back to textContent so the attachment-token append always works.
      const existingRaw = (typeof inp.value === 'string') ? inp.value : (inp.textContent || '');
      const existing = existingRaw.trim();
      if (typeof inp.value === 'string') {
        inp.value = (existing ? existing+' ' : '') + token;
      } else {
        inp.textContent = (existing ? existing+' ' : '') + token;
      }
    }
    _clearAttachment();
  }
  if (context==='dm') sendDM();
  else if (context==='gc') sendGCMessage();
  else if (chIdx!=null) sendChannelMsg(chIdx);
  else if (curChannel!=null) sendChannelMsg(curChannel);
}

// ═══════════════════════════════════════════════════════════
// CUSTOM STATUS BUBBLES
// ═══════════════════════════════════════════════════════════
function refreshCustomStatusBubble() {
  const el = document.getElementById('ua-custom-status');
  if (!el) return;
  const cs = CU && CU.customStatus;
  if (cs && cs.text) {
    const emojiUrl = cs.emoji ? emojiToTwemojiUrl(cs.emoji) : '';
    const emojiHTML = emojiUrl
      ? `<span class="csb-emoji"><img src="${emojiUrl}" style="width:13px;height:13px;object-fit:contain;" onerror="this.outerHTML='${escapeHTML(cs.emoji)}'"></span>`
      : (cs.emoji ? `<span class="csb-emoji">${escapeHTML(cs.emoji)}</span>` : '');
    el.innerHTML = emojiHTML + `<span class="csb-text">${escapeHTML(cs.text)}</span>`;
    if (!el.classList.contains('active')) el.classList.add('active');
  } else {
    el.innerHTML = '';
    el.classList.remove('active');
  }
}

// Also update all custom status displays with twemoji rendering
function _renderStatusEmoji(emoji) {
  if (!emoji) return '';
  try {
    const url = emojiToTwemojiUrl(emoji);
    return `<img src="${url}" style="width:14px;height:14px;object-fit:contain;vertical-align:-2px;" onerror="this.outerHTML='${escapeHTML(emoji)}'">`;
  } catch { return escapeHTML(emoji); }
}

