    +'<div class="vc-q-bar" style="width:3px;height:7px;border-radius:1px;background:rgba(255,255,255,.2);transition:background .3s;"></div>'
    +'<div class="vc-q-bar" style="width:3px;height:10px;border-radius:1px;background:rgba(255,255,255,.2);transition:background .3s;"></div>'
    +'<div class="vc-q-bar" style="width:3px;height:14px;border-radius:1px;background:rgba(255,255,255,.2);transition:background .3s;"></div>'
    +'</div>'
    +'<div id="vc-timer" style="font-family:monospace;font-size:13px;color:rgba(255,255,255,.5);">0:00</div>'
