function _gdmClassifyPlatform(p) {
  const name = (p.name || '').toLowerCase();
  const abbr = (p.abbr || '').toLowerCase();
  const hay = name + ' ' + abbr;
  if (/playstation 5|\bps5\b/.test(hay)) return 'ps5';
  if (/playstation 4|\bps4\b/.test(hay)) return 'ps4';
  if (/playstation 3|\bps3\b/.test(hay)) return 'ps3';
  if (/vita/.test(hay)) return 'psvita';
  if (/xbox series/.test(hay)) return 'xsx';
  if (/xbox one/.test(hay)) return 'xone';
  if (/xbox 360|x360/.test(hay)) return 'x360';
  if (/switch|nsw|nintendo/.test(hay)) return 'switch';
  if (/\bios\b|iphone|ipad/.test(hay)) return 'ios';
  if (/android/.test(hay)) return 'android';
  if (/mac\s?os|macintosh|os x/.test(hay)) return 'mac';
  if (/linux/.test(hay)) return 'linux';
  if (/quest|oculus|meta/.test(hay)) return 'meta';
  if (/windows|\bpc\b|\bwin\b/.test(hay)) return 'pc';
  if (/web|browser/.test(hay)) return 'web';
  return 'generic';
}

function _gdmReviewBand(v) {
  if (v == null) return null;
  if (v >= 90) return 'Overwhelmingly Positive';
  if (v >= 80) return 'Very Positive';
  if (v >= 70) return 'Mostly Positive';
  if (v >= 55) return 'Mixed';
  if (v >= 40) return 'Mostly Negative';
  return 'Very Negative';
}

function _gdmReviewTone(v) {
  // Maps a 0-100 rating to a semantic tone for the colour-coded chip.
  if (v == null) return 'mute';
  if (v >= 80) return 'great';
  if (v >= 70) return 'good';
  if (v >= 55) return 'mixed';
  if (v >= 40) return 'bad';
  return 'awful';
}

// Community-flavoured band labels. Used anywhere that shows the merged
// IGDB + Fortized score so the UI reads as a community-led thing, not a
// corporate review aggregator.
function _gdmCommunityLabel(v) {
  if (v == null) return '—';
  if (v >= 90) return 'Community Favourite';
  if (v >= 80) return 'Mostly Loved';
  if (v >= 70) return 'Well-Liked';
  if (v >= 55) return 'Divisive';
  if (v >= 40) return 'Rough';
  return 'Disliked';
}

// Merge IGDB's player rating + Fortized 👏/👌/👎 votes into a single
// community score (0-100) + total voter count + per-bucket tally.
// Fortized vote weights: great = 100, ok = 55, bad = 10.
function _gdmCommunityAggregate(game, reviews) {
  const tallies = { up: 0, mid: 0, down: 0 };
  (reviews || []).forEach(r => {
    if (r.vote === 'up') tallies.up++;
    else if (r.vote === 'mid') tallies.mid++;
    else if (r.vote === 'down') tallies.down++;
  });
  const fortTotal = tallies.up + tallies.mid + tallies.down;
  const fortScore = fortTotal
    ? (tallies.up * 100 + tallies.mid * 55 + tallies.down * 10) / fortTotal
    : null;

  const igdbScore = typeof game?.userRating === 'number' ? game.userRating : null;
  const igdbCount = game?.userRatingCount || 0;

  // Weighted average — IGDB's count is often dominant; Fortized votes
  // still move the needle because weights stack naturally.
  let mergedScore = null;
  const totalWeight = igdbCount + fortTotal;
  if (totalWeight > 0) {
    mergedScore = ((igdbScore ?? 0) * igdbCount + (fortScore ?? 0) * fortTotal) / totalWeight;
    if (igdbScore == null) mergedScore = fortScore;
    if (fortScore == null) mergedScore = igdbScore;
  }

  // "+N this week" delta counts only Fortized votes in the last 7 days
  // — IGDB doesn't give us per-vote timestamps, so community velocity
  // is Fortized-only by necessity.
  const weekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
  const weekDelta = (reviews || []).filter(r => (r.at || 0) >= weekAgo).length;

  return {
    score: mergedScore,
    total: totalWeight,
    tallies,
    fortTotal,
    igdbCount,
    weekDelta,
  };
}

// Buckets Fortized reviews into the last 7 days for the sparkline.
// Returns an array of 7 integers, oldest-first.
function _gdmReviewActivityBuckets(reviews) {
  const buckets = [0, 0, 0, 0, 0, 0, 0];
  const now = Date.now();
  const dayMs = 24 * 60 * 60 * 1000;
  (reviews || []).forEach(r => {
    const age = now - (r.at || 0);
    if (age < 0 || age > 7 * dayMs) return;
    const idx = 6 - Math.floor(age / dayMs);
    if (idx >= 0 && idx <= 6) buckets[idx]++;
  });
  return buckets;
}

function _gdmRenderEmbedHTML(game) {
  const reviews = _gdmGetReviewsFor(game?.name || '');
  const agg = _gdmCommunityAggregate(game, reviews);
  if (!agg.total) {
    return `<div class="gdm-embed-empty">
      <div class="gdm-embed-empty-num">—</div>
      <div class="gdm-embed-empty-sub">No community reviews yet. Be the first.</div>
    </div>`;
  }
  const tone = _gdmReviewTone(agg.score);
  const label = _gdmCommunityLabel(agg.score);
  const pct = Math.round(agg.score);
  // Estimate bucket percentages. For Fortized votes we have exact tallies;
  // for IGDB we split its count across up/mid/down using its 0-100 rating.
  const igdbUp = agg.igdbCount > 0 ? Math.round(agg.igdbCount * Math.max(0, Math.min(1, (game.userRating ?? 0) / 100))) : 0;
  const igdbDown = agg.igdbCount > 0 ? Math.round(agg.igdbCount * Math.max(0, Math.min(1, (100 - (game.userRating ?? 0)) / 100)) * 0.5) : 0;
  const igdbMid = Math.max(0, agg.igdbCount - igdbUp - igdbDown);
  const totalUp = agg.tallies.up + igdbUp;
  const totalMid = agg.tallies.mid + igdbMid;
  const totalDown = agg.tallies.down + igdbDown;
  const totalAll = Math.max(1, totalUp + totalMid + totalDown);
  const upPct = (totalUp / totalAll) * 100;
  const midPct = (totalMid / totalAll) * 100;
  const downPct = 100 - upPct - midPct;
  const buckets = _gdmReviewActivityBuckets(reviews);
  const spark = _gdmSparklinePath(buckets, 120, 24);
  return `
    <div class="gdm-embed-main">
      <div class="gdm-embed-score gdm-tone-${tone}">
        <div class="gdm-embed-num">${pct}<span class="gdm-embed-num-unit">%</span></div>
        <div class="gdm-embed-band">${escapeHTML(label)}</div>
      </div>
      <div class="gdm-embed-bar-wrap">
        <div class="gdm-embed-bar">
          <div class="gdm-embed-seg gdm-embed-seg--up" style="width:${upPct.toFixed(1)}%" title="${totalUp.toLocaleString()} positive"></div>
          <div class="gdm-embed-seg gdm-embed-seg--mid" style="width:${midPct.toFixed(1)}%" title="${totalMid.toLocaleString()} mixed"></div>
          <div class="gdm-embed-seg gdm-embed-seg--down" style="width:${downPct.toFixed(1)}%" title="${totalDown.toLocaleString()} negative"></div>
        </div>
        <div class="gdm-embed-tally-row">
          <span class="gdm-embed-tally gdm-embed-tally--up"><span class="gdm-embed-tally-emoji">👏</span>${totalUp.toLocaleString()}</span>
          <span class="gdm-embed-tally gdm-embed-tally--mid"><span class="gdm-embed-tally-emoji">👌</span>${totalMid.toLocaleString()}</span>
          <span class="gdm-embed-tally gdm-embed-tally--down"><span class="gdm-embed-tally-emoji">👎</span>${totalDown.toLocaleString()}</span>
          <span class="gdm-embed-total">${agg.total.toLocaleString()} voter${agg.total === 1 ? '' : 's'}</span>
        </div>
      </div>
    </div>
    <div class="gdm-embed-spark">
      <div class="gdm-embed-spark-head">
        <span>Activity · last 7 days</span>
        <span class="gdm-embed-delta${agg.weekDelta > 0 ? ' gdm-embed-delta--up' : ''}">${agg.weekDelta > 0 ? '+' : ''}${agg.weekDelta}</span>
      </div>
      <svg class="gdm-embed-sparkline" viewBox="0 0 120 24" preserveAspectRatio="none" aria-hidden="true">
        <path d="${spark}" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
    </div>`;
}

function _gdmSparklinePath(buckets, w, h) {
  if (!buckets || buckets.length < 2) return '';
  const max = Math.max(1, ...buckets);
  const step = w / (buckets.length - 1);
  return buckets.map((v, i) => {
    const x = (i * step).toFixed(1);
    const y = (h - (v / max) * (h - 2) - 1).toFixed(1);
    return (i === 0 ? 'M' : 'L') + x + ',' + y;
  }).join(' ');
}

function _renderGameDetailsModal(overlay, requestedName, game) {
  const card = overlay.querySelector('.gdm-card');
  if (!card) return;
  if (!game) {
    card.innerHTML = `
      <button class="gdm-close" onclick="document.getElementById('game-details-modal').remove()" title="Close">×</button>
      <div class="gdm-empty">
        <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" style="color:var(--muted);"><rect x="2" y="6" width="20" height="12" rx="4"/><path d="M7 12h3M8.5 10.5v3M15 12h.01M18 12h.01"/></svg>
        <div class="gdm-empty-title">We don't have details for "${escapeHTML(requestedName)}" yet</div>
        <div class="gdm-empty-sub">This game isn't in our catalog right now. Try again later or search with a slightly different name.</div>
      </div>`;
    return;
  }
  const releaseDate = game.releaseDate
    ? new Date(game.releaseDate).toLocaleDateString(undefined, { day:'numeric', month:'long', year:'numeric' })
    : null;
  const genres = (game.genres || []).join(', ') || '—';
  const devs = (game.developers || []).join(', ');
  const pubs = (game.publishers || []).join(', ');
  // Dedupe platforms by family so PS3/PS4/PS5 collapse into a single PlayStation
  // icon, with the tooltip listing every specific console it covers.
  const platformByKind = new Map();
  (game.platforms || []).forEach(p => {
    const k = _gdmClassifyPlatform(p);
    if (!platformByKind.has(k)) platformByKind.set(k, []);
    platformByKind.get(k).push(p.name);
  });
  const platformsHTML = [...platformByKind.entries()].map(([k, names]) => {
    const info = _GDM_PLATFORM_ICONS[k] || _GDM_PLATFORM_ICONS.generic;
    const tip = names.join(' · ');
    return `<span class="gdm-platform-icon" title="${escapeHTML(tip)}" aria-label="${escapeHTML(tip)}">${info.svg}</span>`;
  }).join('');
  // Dedupe by kind (so duplicate Twitter links etc. don't take a slot),
  // rank by priority, cap at 7.
  const linksSorted = (() => {
    const seen = new Map();
    (game.links || []).forEach(l => {
      const kind = _gdmClassifyLink(l);
      if (!seen.has(kind)) seen.set(kind, { kind, url: l.url });
    });
    const arr = [...seen.values()];
    arr.sort((a,b) => _GDM_LINK_PRIORITY.indexOf(a.kind) - _GDM_LINK_PRIORITY.indexOf(b.kind));
    return arr.slice(0, 7);
  })();
  const linksHTML = linksSorted.map(l => {
    const kind = _GDM_LINK_ICONS[l.kind] ? l.kind : 'link';
    const label = _GDM_LINK_LABELS[kind] || 'Link';
    return `<a class="gdm-link-chip" href="${escapeHTML(l.url)}" target="_blank" rel="noopener noreferrer" title="${escapeHTML(label)}" aria-label="${escapeHTML(label)}">${_GDM_LINK_ICONS[kind]}</a>`;
  }).join('');
  const screenshots = (game.screenshots || []);
  const videos = (game.videos || []);
  const heroSrc = (screenshots[0] && screenshots[0].full) || game.coverUrl || '';
  const ratings = [];
  // Critics stay in their own small embed (methodologically different
  // from community sentiment).
  const criticHTML = typeof game.criticRating === 'number'
    ? `<div class="gdm-critic-embed gdm-tone-${escapeHTML(_gdmReviewTone(game.criticRating))}">
         <div class="gdm-critic-label">Critics</div>
         <div class="gdm-critic-score">${Math.round(game.criticRating)}<span>/100</span></div>
         <div class="gdm-critic-sub">${(game.criticRatingCount || 0).toLocaleString()} outlets</div>
       </div>`
    : '';
  const canAdd = typeof addGameToCollection === 'function';
  const safeName = escapeHTML(game.name);
  const safeNameAttr = safeName.replace(/'/g, "\\'");
  // Assemble the media strip: videos first (with play overlay) then screenshots.
  // Videos play inline in the hero; screenshots open the in-app lightbox.
  const mediaItems = [
    ...videos.map((v, i) => ({ kind:'video', thumb: v.thumb, idx: i, label: v.name || 'Trailer', embedUrl: v.embedUrl })),
    ...screenshots.map((s, i) => ({ kind:'shot', thumb: s.thumb, full: s.full, idx: i, label: 'Screenshot' })),
  ].slice(0, 10);
  _gdmMediaList = mediaItems;
  _gdmMediaIdx = 0;
  const hasMedia = mediaItems.length > 0;
  const mediaHTML = hasMedia ? `
    <div class="gdm-media-stage" id="gdm-media-stage">
      <div id="gdm-media-hero-slot"></div>
      ${mediaItems.length > 1 ? `
        <button class="gdm-media-nav gdm-media-nav--prev" onclick="_gdmMediaStep(-1)" aria-label="Previous"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg></button>
        <button class="gdm-media-nav gdm-media-nav--next" onclick="_gdmMediaStep(1)" aria-label="Next"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg></button>
        <div class="gdm-media-counter"><span id="gdm-media-counter-txt">1 / ${mediaItems.length}</span></div>
      ` : ''}
    </div>
    ${mediaItems.length > 1 ? `<div class="gdm-media-strip" id="gdm-media-strip">${mediaItems.map((it, i) =>
      `<button class="gdm-media-thumb${i===0?' gdm-media-thumb--active':''}${it.kind==='video'?' gdm-media-thumb--video':''}" onclick="_gdmMediaSelect(${i})" title="${escapeHTML(it.label)}"><img src="${escapeHTML(it.thumb)}" alt="">${it.kind==='video'?`<span class="gdm-thumb-play"><svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg></span>`:''}</button>`
    ).join('')}</div>` : ''}
  ` : '';
  _gdmLastGame = game;
  card.innerHTML = `
    <div class="gdm-hero" style="${heroSrc ? `background-image:linear-gradient(180deg,rgba(10,8,8,.12),rgba(10,8,8,.85)),url('${escapeHTML(heroSrc)}');` : ''}">
      <div class="gdm-hero-actions">
        ${canAdd ? (function(){
          const inColl = (CU?.gameCollection || []).some(g => g.name === game.name);
          return inColl
            ? `<button class="gdm-add-btn gdm-add-btn--added" onclick="_gdmRemoveFromProfile('${safeNameAttr}')" title="Click to remove from your profile"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg> On Your Profile</button>`
            : `<button class="gdm-add-btn" onclick="_gdmAddToProfile('${safeNameAttr}')"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg> Add to Profile</button>`;
        })() : ''}
        <div class="gdm-menu-wrap">
          <button class="gdm-close gdm-menu-btn" onclick="_gdmToggleMenu(event)" title="More" aria-haspopup="true"><svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="12" r="2"/></svg></button>
          <div class="gdm-menu" id="gdm-menu" style="display:none;">
            <button class="gdm-menu-item" onclick="_gdmReportIssue()"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg> Report issue</button>
          </div>
        </div>
        <button class="gdm-close" onclick="document.getElementById('game-details-modal').remove()" title="Close">×</button>
      </div>
      <div class="gdm-hero-bottom">
        ${game.coverThumb ? `<img class="gdm-cover" src="${escapeHTML(game.coverThumb)}" alt="${safeName}">` : ''}
        <div class="gdm-hero-text">
          <div class="gdm-kicker">Game</div>
          <div class="gdm-title">${safeName}</div>
          <div class="gdm-genres">${escapeHTML(genres)}</div>
        </div>
      </div>
    </div>
    <div class="gdm-body">
      <div class="gdm-main">
        ${mediaHTML}
        ${game.summary ? `<p class="gdm-summary">${escapeHTML(game.summary)}</p>` : ''}
      </div>
      <aside class="gdm-side">
        <div class="gdm-side-card">
          <div class="gdm-side-head">Bastion</div>
          <div id="gdm-community-slot" class="gdm-community-slot">
            <div class="gdm-community-loading">Looking for an official Bastion…</div>
          </div>
        </div>
        <div class="gdm-side-card">
          <div class="gdm-side-head">Details</div>
          <div class="gdm-row"><span class="gdm-row-k">Genres</span><span class="gdm-row-v">${escapeHTML(genres)}</span></div>
          ${pubs ? `<div class="gdm-row"><span class="gdm-row-k">Publisher</span><span class="gdm-row-v">${escapeHTML(pubs)}</span></div>` : ''}
          ${devs ? `<div class="gdm-row"><span class="gdm-row-k">Developer</span><span class="gdm-row-v">${escapeHTML(devs)}</span></div>` : ''}
          ${releaseDate ? `<div class="gdm-row"><span class="gdm-row-k">Release Date</span><span class="gdm-row-v">${escapeHTML(releaseDate)}</span></div>` : ''}
          ${platformsHTML ? `<div class="gdm-row"><span class="gdm-row-k">Platforms</span><span class="gdm-row-v gdm-row-v--platforms">${platformsHTML}</span></div>` : ''}
          ${linksHTML ? `<div class="gdm-row"><span class="gdm-row-k">Links</span><span class="gdm-row-v gdm-row-v--links">${linksHTML}</span></div>` : ''}
        </div>
      </aside>
      <div class="gdm-reviews-banner">
        <div class="gdm-reviews-head">
          <div class="gdm-side-head">Community</div>
          <div class="gdm-reviews-head-note">Your vote counts toward the community score.</div>
        </div>
        <div class="gdm-reviews-embed" id="gdm-reviews-embed">${_gdmRenderEmbedHTML(game)}</div>
        <div class="gdm-reviews-row">
          <div class="gdm-thumbs">
            <button class="gdm-thumb gdm-thumb--up" data-vote="up" onclick="_gdmPickVote(this,'up')" title="Great"><span class="gdm-thumb-emoji">👏</span><span>Great</span></button>
            <button class="gdm-thumb gdm-thumb--mid" data-vote="mid" onclick="_gdmPickVote(this,'mid')" title="OK"><span class="gdm-thumb-emoji">👌</span><span>OK</span></button>
            <button class="gdm-thumb gdm-thumb--down" data-vote="down" onclick="_gdmPickVote(this,'down')" title="Bad"><span class="gdm-thumb-emoji">👎</span><span>Bad</span></button>
          </div>
          <div class="gdm-review-compose">
            <input id="gdm-review-text" class="gdm-review-input" placeholder="Add a short comment (optional)" maxlength="200">
            <button class="gdm-review-submit" onclick="_gdmSubmitReview('${safeNameAttr}')">Post</button>
          </div>
          <div class="gdm-review-carousel" id="gdm-review-carousel"></div>
        </div>
        ${criticHTML ? `<div class="gdm-reviews-foot">${criticHTML}</div>` : ''}
      </div>
    </div>`;
  // Kick off the Fortized user-review carousel for this game.
  _gdmStartReviewCarousel(game.name);
  _gdmRenderHero();
  try { if (typeof window._twemojiReparse === 'function') window._twemojiReparse(card); } catch(_){}
}

let _gdmLastGame = null;

function _gdmToggleMenu(e) {
  e?.stopPropagation?.();
  const m = document.getElementById('gdm-menu');
  if (!m) return;
  const open = m.style.display !== 'none';
  m.style.display = open ? 'none' : 'block';
  if (!open) {
    const close = () => { m.style.display = 'none'; document.removeEventListener('click', close); };
    setTimeout(() => document.addEventListener('click', close), 0);
  }
}

function _gdmOpenLightbox(index) {
  const g = _gdmLastGame;
  if (!g || !g.screenshots || !g.screenshots[index]) return;
  const overlay = document.createElement('div');
  overlay.className = 'gdm-lightbox';
  const s = g.screenshots[index];
  overlay.innerHTML = `<img src="${escapeHTML(s.full)}" alt=""><button class="gdm-lightbox-close" title="Close">×</button>`;
  overlay.onclick = () => overlay.remove();
  document.body.appendChild(overlay);
}

function _gdmOpenVideo(index) {
  const g = _gdmLastGame;
  if (!g || !g.videos || !g.videos[index]) return;
  const v = g.videos[index];
  const overlay = document.createElement('div');
  overlay.className = 'gdm-lightbox gdm-lightbox--video';
  overlay.innerHTML = `<div class="gdm-video-frame" onclick="event.stopPropagation()"><iframe src="${escapeHTML(v.embedUrl)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen loading="lazy"></iframe></div><button class="gdm-lightbox-close" title="Close">×</button>`;
  overlay.onclick = () => overlay.remove();
  document.body.appendChild(overlay);
}

function _gdmReportIssue() {
  const g = _gdmLastGame;
  const gameName = g ? g.name : '';
  document.getElementById('gdm-report-modal')?.remove();
  const m = document.getElementById('gdm-menu'); if (m) m.style.display = 'none';
  const overlay = document.createElement('div');
  overlay.id = 'gdm-report-modal';
  overlay.className = 'gdm-report-overlay';
  overlay.innerHTML = `
    <div class="gdm-report-card" onclick="event.stopPropagation()">
      <button class="gdm-report-close" onclick="document.getElementById('gdm-report-modal').remove()" aria-label="Close">×</button>
      <div class="gdm-report-title">What went wrong?</div>
      <div class="gdm-report-sub">Please select your issue for <strong>${escapeHTML(gameName || 'this game')}</strong></div>
      <label class="gdm-report-opt"><input type="radio" name="gdm-report" value="wrong_game"><span>Wrong game is shown</span></label>
      <label class="gdm-report-opt"><input type="radio" name="gdm-report" value="missing_info"><span>Missing or outdated info</span></label>
      <label class="gdm-report-opt"><input type="radio" name="gdm-report" value="bad_media"><span>Bad or broken screenshots / video</span></label>
      <label class="gdm-report-opt"><input type="radio" name="gdm-report" value="other"><span>Other feedback</span></label>
      <textarea class="gdm-report-text" id="gdm-report-text" placeholder="Optional: tell us more…" maxlength="500"></textarea>
      <div class="gdm-report-actions">
        <button class="gdm-report-cancel" onclick="document.getElementById('gdm-report-modal').remove()">Cancel</button>
        <button class="gdm-report-submit" onclick="_gdmSubmitReport('${escapeHTML(gameName).replace(/'/g, "\\'")}')">Send report</button>
      </div>
    </div>`;
  overlay.onclick = () => overlay.remove();
  document.body.appendChild(overlay);
}

function _gdmReportReview(reviewId, reviewUser, gameName) {
  document.getElementById('gdm-report-modal')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'gdm-report-modal';
  overlay.className = 'gdm-report-overlay';
  overlay.innerHTML = `
    <div class="gdm-report-card" onclick="event.stopPropagation()">
      <button class="gdm-report-close" onclick="document.getElementById('gdm-report-modal').remove()" aria-label="Close">×</button>
      <div class="gdm-report-title">Report this review</div>
      <div class="gdm-report-sub">By <strong>@${escapeHTML(reviewUser || 'unknown')}</strong> on <strong>${escapeHTML(gameName || 'this game')}</strong></div>
      <label class="gdm-report-opt"><input type="radio" name="gdm-rev-report" value="spam"><span>Spam or advertising</span></label>
      <label class="gdm-report-opt"><input type="radio" name="gdm-rev-report" value="offensive"><span>Offensive language or harassment</span></label>
      <label class="gdm-report-opt"><input type="radio" name="gdm-rev-report" value="off_topic"><span>Off-topic / not about the game</span></label>
      <label class="gdm-report-opt"><input type="radio" name="gdm-rev-report" value="false_info"><span>Misleading or false information</span></label>
      <label class="gdm-report-opt"><input type="radio" name="gdm-rev-report" value="other"><span>Other</span></label>
      <textarea class="gdm-report-text" id="gdm-rev-report-text" placeholder="Optional: tell us more…" maxlength="500"></textarea>
      <div class="gdm-report-actions">
        <button class="gdm-report-cancel" onclick="document.getElementById('gdm-report-modal').remove()">Cancel</button>
        <button class="gdm-report-submit" onclick="_gdmSubmitReviewReport('${escapeHTML(reviewId).replace(/'/g, "\\'")}','${escapeHTML(reviewUser).replace(/'/g, "\\'")}','${escapeHTML(gameName).replace(/'/g, "\\'")}')">Send report</button>
      </div>
    </div>`;
  overlay.onclick = () => overlay.remove();
  document.body.appendChild(overlay);
}

async function _gdmSubmitReviewReport(reviewId, reviewUser, gameName) {
  const choice = document.querySelector('input[name="gdm-rev-report"]:checked')?.value;
  const note = document.getElementById('gdm-rev-report-text')?.value?.trim() || '';
  if (!choice) { toast('Pick a reason first', 'error'); return; }
  const report = {
    id: 'gdmrevrep_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
    kind: 'review_report',
    reporter: CU?.username || null,
    username: reviewUser,            // makes it appear in the user's targeted-actions in admin UI
    reason: choice,
    context: 'Review by @' + (reviewUser || '?') + ' on game: ' + (gameName || 'unknown'),
    note,
    game: gameName,
    reviewId,
    status: 'pending',
    createdAt: new Date().toISOString(),
  };
  try { await FortizedSocial.adminSaveReport(report); }
  catch(e) { console.warn('[GDM] Review report save failed:', e?.message); }
  try {
    const existing = JSON.parse(localStorage.getItem('ftz_reports') || '[]');
    if (!existing.find(r => r.id === report.id)) existing.push(report);
    localStorage.setItem('ftz_reports', JSON.stringify(existing));
  } catch(_) {}
  document.getElementById('gdm-report-modal')?.remove();
  toast('Thanks — review reported.', 'success');
}

async function _gdmSubmitReport(gameName) {
  const choice = document.querySelector('input[name="gdm-report"]:checked')?.value;
  const note = document.getElementById('gdm-report-text')?.value?.trim() || '';
  if (!choice) { toast('Pick a reason first', 'error'); return; }
  const report = {
    id: 'gdmrep_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
    kind: 'game_feedback',
    reporter: CU?.username || null,
    reason: choice,
    context: 'Game: ' + (gameName || 'unknown'),
    note,
    game: gameName,
    status: 'pending',
    createdAt: new Date().toISOString(),
  };
  // Send to the Supabase reports queue so it shows up in the admin console.
  try { await FortizedSocial.adminSaveReport(report); }
  catch(e) { console.warn('[GDM] Report save to Supabase failed, caching locally:', e?.message); }
  // Always cache locally too (same pattern the user-report flow uses)
  try {
    const existing = JSON.parse(localStorage.getItem('ftz_reports') || '[]');
    if (!existing.find(r => r.id === report.id)) existing.push(report);
    localStorage.setItem('ftz_reports', JSON.stringify(existing));
  } catch(_) {}
  document.getElementById('gdm-report-modal')?.remove();
  toast('Thanks — report sent to moderators.', 'success');
}

// Opens the game-detail modal from any profile-widget game card, closing
// the profile modal first so the two don't stack on top of each other.
function _openGameFromWidget(gameName) {
  if (!gameName) return;
  try { closeModal('modal-user'); } catch (_) {}
  // Also close the mini profile preview popup if it's open (that's a
  // separate floating element, not the modal).
  try { document.getElementById('mini-profile-preview')?.remove(); } catch (_) {}
  // Defer slightly so the close animation finishes before the new modal
  // pops in — feels "natural", as requested.
  setTimeout(() => openGameDetailsModal(gameName), 100);
}

async function _gdmAddToProfile(gameName) {
  try {
    if (typeof addGameToCollection !== 'function') return;
    const g = _gdmLastGame;
    const cover = g?.coverUrl || g?.coverThumb || null;
    const thumb = g?.coverThumb || g?.coverUrl || null;
    const genre = (g?.genres && g.genres.length) ? g.genres.join(', ') : 'Game';
    // Skip toast from addGameToCollection — we toast ourselves after the flip.
    const already = (CU?.gameCollection || []).some(x => x.name === gameName);
    if (already) return; // UI shouldn't even show Add in this state, but belt-and-braces
    CU.gameCollection = CU.gameCollection || [];
    const entry = { name: gameName, icon: '🎮', genre, addedAt: new Date().toISOString() };
    if (cover) entry.coverUrl = cover;
    if (thumb) entry.coverThumb = thumb;
    CU.gameCollection.push(entry);
    await saveUser();
    _gdmRefreshModalState(gameName);
    try { buildProfileView('game_collection'); } catch (_) {}
    toast('Added ' + gameName + ' to your profile.', 'success');
  } catch(e) {
    console.warn('[GDM] Add to profile failed:', e);
    toast('Couldn\'t add to profile.', 'error');
  }
}

async function _gdmRemoveFromProfile(gameName) {
  try {
    CU.gameCollection = (CU?.gameCollection || []).filter(g => g.name !== gameName);
    await saveUser();
    _gdmRefreshModalState(gameName);
    try { buildProfileView('game_collection'); } catch (_) {}
    toast('Removed from your profile.', 'success');
  } catch (e) {
    console.warn('[GDM] Remove from profile failed:', e);
    toast('Couldn\'t remove from profile.', 'error');
  }
}

// Flip the Add/Remove button in place without tearing down the modal.
function _gdmRefreshModalState(gameName) {
  const btn = document.querySelector('.gdm-add-btn');
  if (!btn) return;
  const inCollection = (CU?.gameCollection || []).some(g => g.name === gameName);
  const safeName = escapeHTML(gameName).replace(/'/g, "\\'");
  if (inCollection) {
    btn.classList.add('gdm-add-btn--added');
    btn.setAttribute('onclick', `_gdmRemoveFromProfile('${safeName}')`);
    btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg> On Your Profile';
    btn.title = 'Click to remove from your profile';
  } else {
    btn.classList.remove('gdm-add-btn--added');
    btn.setAttribute('onclick', `_gdmAddToProfile('${safeName}')`);
    btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg> Add to Profile';
    btn.title = '';
  }
}

// ── Media hero state (used by arrows, thumb strip, inline video) ──
let _gdmMediaList = [];
let _gdmMediaIdx = 0;

function _gdmRenderHero() {
  const slot = document.getElementById('gdm-media-hero-slot');
  if (!slot) return;
  const item = _gdmMediaList[_gdmMediaIdx];
  if (!item) { slot.innerHTML = ''; return; }
  if (item.kind === 'video') {
    // Inline YouTube-nocookie iframe with autoplay so the click-to-switch feels instant
    const src = (item.embedUrl || '') + ((item.embedUrl || '').includes('?') ? '&' : '?') + 'autoplay=1';
    slot.innerHTML = `<iframe class="gdm-media-iframe" src="${escapeHTML(src)}" title="${escapeHTML(item.label)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen loading="lazy"></iframe>`;
  } else {
    const fullSrc = item.full || item.thumb;
    slot.innerHTML = `<button class="gdm-media-hero" onclick="_gdmOpenLightbox(${item.idx})" title="View full-size"><img src="${escapeHTML(fullSrc)}" alt=""></button>`;
  }
  const c = document.getElementById('gdm-media-counter-txt');
  if (c) c.textContent = (_gdmMediaIdx + 1) + ' / ' + _gdmMediaList.length;
  document.querySelectorAll('#gdm-media-strip .gdm-media-thumb').forEach((el, i) => {
    el.classList.toggle('gdm-media-thumb--active', i === _gdmMediaIdx);
  });
}

function _gdmMediaSelect(idx) {
  if (!_gdmMediaList.length) return;
  _gdmMediaIdx = ((idx % _gdmMediaList.length) + _gdmMediaList.length) % _gdmMediaList.length;
  _gdmRenderHero();
}

function _gdmMediaStep(delta) {
  if (!_gdmMediaList.length) return;
  _gdmMediaSelect(_gdmMediaIdx + delta);
}

// ── Fortized user reviews (per-game) ──
// MVP storage: localStorage, keyed by lower-cased game name. When a
// Supabase `game_reviews` table lands we'll mirror to it, but the UX works
// offline-first so the carousel never depends on the network.
const _GDM_REVIEWS_KEY = 'ftz_game_reviews_v1';
let _gdmPickedVote = null;
let _gdmCarouselTimer = null;
let _gdmCarouselPaused = false;

function _gdmLoadReviews() {
  try { return JSON.parse(localStorage.getItem(_GDM_REVIEWS_KEY) || '{}'); }
  catch(_) { return {}; }
}
function _gdmSaveReviews(all) {
  try { localStorage.setItem(_GDM_REVIEWS_KEY, JSON.stringify(all)); } catch(_) {}
}
function _gdmGetReviewsFor(gameName) {
  const all = _gdmLoadReviews();
  const key = (gameName || '').toLowerCase();
  return Array.isArray(all[key]) ? all[key] : [];
}

function _gdmPickVote(btn, vote) {
  _gdmPickedVote = vote;
  document.querySelectorAll('.gdm-thumb').forEach(b => b.classList.remove('gdm-thumb--active'));
  btn.classList.add('gdm-thumb--active');
}

async function _gdmSubmitReview(gameName) {
  if (!_gdmPickedVote) { toast('Pick 👍, ✋ or 👎 first', 'error'); return; }
  const text = (document.getElementById('gdm-review-text')?.value || '').trim().slice(0, 280);
  const entry = {
    id: 'rev_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
    game: gameName,
    vote: _gdmPickedVote,
    text,
    user: CU?.username || 'anonymous',
    displayName: CU?.displayName || CU?.username || 'Someone',
    pfp: CU?.pfp || null,
    at: Date.now(),
  };
  const all = _gdmLoadReviews();
  const key = (gameName || '').toLowerCase();
  if (!Array.isArray(all[key])) all[key] = [];
  // Replace any previous review from the same user so one-per-user stays true.
  all[key] = all[key].filter(r => r.user !== entry.user);
  all[key].unshift(entry);
  all[key] = all[key].slice(0, 200);
  _gdmSaveReviews(all);
  // Reset the form, refresh the carousel with the new entry at the front.
  _gdmPickedVote = null;
  document.querySelectorAll('.gdm-thumb').forEach(b => b.classList.remove('gdm-thumb--active'));
  const ta = document.getElementById('gdm-review-text'); if (ta) ta.value = '';
  toast('Review posted!', 'success');
  _gdmStartReviewCarousel(gameName);
  // Re-paint the community embed so the bar + score + delta move immediately.
  const host = document.getElementById('gdm-reviews-embed');
  if (host && _gdmLastGame) {
    host.innerHTML = _gdmRenderEmbedHTML(_gdmLastGame);
    try { if (typeof window._twemojiReparse === 'function') window._twemojiReparse(host); } catch(_){}
  }
}

function _gdmStopReviewCarousel() {
  if (_gdmCarouselTimer) { clearTimeout(_gdmCarouselTimer); _gdmCarouselTimer = null; }
}

function _gdmStartReviewCarousel(gameName) {
  _gdmStopReviewCarousel();
  const host = document.getElementById('gdm-review-carousel');
  if (!host) return;
  const reviews = _gdmGetReviewsFor(gameName);
  if (!reviews.length) { host.innerHTML = '<div class="gdm-review-empty">No reviews yet — be the first to share what you think.</div>'; return; }
  let idx = 0;
  const labelFor = v => v === 'up' ? 'Great' : v === 'down' ? 'Bad' : 'OK';
  const emojiFor = v => v === 'up' ? '👏' : v === 'down' ? '👎' : '👌';
  const paint = () => {
    const r = reviews[idx % reviews.length];
    const pfp = r.pfp
      ? `<img src="${escapeHTML(r.pfp)}" onerror="this.outerHTML='<div class=&quot;gdm-rc-pfp-fallback&quot;>${escapeHTML((r.displayName||'?')[0].toUpperCase())}</div>'">`
      : `<div class="gdm-rc-pfp-fallback">${escapeHTML((r.displayName||'?')[0].toUpperCase())}</div>`;
    host.innerHTML = `
      <div class="gdm-review-chip gdm-review-chip--in gdm-vote-${escapeHTML(r.vote)}" onmouseenter="_gdmCarouselPaused=true" onmouseleave="_gdmCarouselPaused=false;_gdmScheduleNext()">
        <div class="gdm-rc-head">
          <div class="gdm-rc-pfp">${pfp}</div>
          <div class="gdm-rc-meta">
            <div class="gdm-rc-name">${escapeHTML(r.displayName || r.user)}</div>
            <div class="gdm-rc-handle">@${escapeHTML(r.user)}</div>
          </div>
          <div class="gdm-rc-vote"><span class="gdm-rc-emoji">${emojiFor(r.vote)}</span><span>${labelFor(r.vote)}</span></div>
          <button class="gdm-rc-flag" title="Report this review" onclick="event.stopPropagation();_gdmReportReview('${escapeHTML(r.id).replace(/'/g, "\\'")}','${escapeHTML(r.user || '').replace(/'/g, "\\'")}','${escapeHTML(r.game || '').replace(/'/g, "\\'")}')"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg></button>
        </div>
        ${r.text ? `<div class="gdm-rc-body">${escapeHTML(r.text)}</div>` : ''}
      </div>`;
    try { if (typeof window._twemojiReparse === 'function') window._twemojiReparse(host); } catch(_){}
  };
  window._gdmScheduleNext = function() {
    _gdmStopReviewCarousel();
    if (reviews.length <= 1) return;
    _gdmCarouselTimer = setTimeout(function tick() {
      if (_gdmCarouselPaused) { _gdmCarouselTimer = setTimeout(tick, 500); return; }
      const chip = host.querySelector('.gdm-review-chip');
      if (chip) { chip.classList.remove('gdm-review-chip--in'); chip.classList.add('gdm-review-chip--out'); }
      setTimeout(() => { idx++; paint(); window._gdmScheduleNext(); }, 360);
    }, 5000);
  };
  paint();
  window._gdmScheduleNext();
}


function refreshGameActivityBar() {
  const bar = document.getElementById('game-activity-bar');
  if (!bar) return;
  const gameActivity = activityState.activities.find(a => a.id === 'game');
  if (gameActivity) {
    bar.style.display = 'flex';
    const coverSrc = gameActivity.metadata?.coverThumb || gameActivity.metadata?.coverUrl || _getManualCover(gameActivity.name);
    const coverHtml = coverSrc
      ? '<img src="'+escapeHTML(coverSrc)+'" style="width:24px;height:32px;border-radius:4px;object-fit:cover;flex-shrink:0;" onerror="this.outerHTML=\'<span style=font-size:13px>'+gameActivity.icon+'</span>\'">'
      : '<span style="font-size:13px;">' + gameActivity.icon + '</span>';
    const genreHtml = gameActivity.metadata?.genre ? '<span style="font-size:9px;color:rgba(255,255,255,.25);margin-left:4px;">'+escapeHTML(gameActivity.metadata.genre)+'</span>' : '';
    bar.innerHTML = coverHtml
      +'<span style="font-size:11px;font-weight:700;color:var(--text);">'+escapeHTML(gameActivity.name)+genreHtml+'</span>'
      +'<span style="font-size:10px;color:var(--muted);">Playing</span>'
      +'<button onclick="setGameActivity(null)" title="Stop" style="margin-left:auto;background:none;border:none;color:var(--muted);cursor:pointer;font-size:14px;line-height:1;">✕</button>';
  } else {
    bar.style.display = 'none';
  }
}

// Recent activities persisted in localStorage (up to 8, most-recent-first)
function _loadRecentActivities() {
  try { return JSON.parse(localStorage.getItem('ftz_recent_activities') || '[]').filter(e => e && e.name); }
  catch { return []; }
}
function _recordRecentActivity(name, icon) {
  if (!name) return;
  try {
    const list = _loadRecentActivities().filter(e => e.name !== name);
    list.unshift({ name, icon: icon || '🎮', ts: Date.now() });
    localStorage.setItem('ftz_recent_activities', JSON.stringify(list.slice(0, 8)));
  } catch {}
}

async function openGameActivityPicker() {
  _closeEl('game-activity-modal');
  _userCustomApps = JSON.parse(localStorage.getItem('ftz_custom_apps')||'[]');
  const isDesktop = !!window.fortizedDesktop?.isDesktopApp;
  const recents = _loadRecentActivities();
  const modal = document.createElement('div');
  modal.id = 'game-activity-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(12,14,20,.8);z-index:9000;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(8px);';
  const box = document.createElement('div');
  box.style.cssText = 'background:var(--panel);border:1px solid var(--border);border-radius:20px;padding:22px;width:420px;max-width:95vw;max-height:85vh;display:flex;flex-direction:column;box-shadow:0 24px 60px rgba(0,0,0,.7);';

  const iconChoices = ['🎮','🕹️','🎯','🎲','🏆','⚔️','🛡️','🔫','🏎️','⚽','🏀','🎧','🎨','📺','📚','💻','🖥️','🧩','🪄','🎬','🎤','🪐'];

  const currentBanner = (activityState.primary?.type === 'playing')
    ? '<div style="display:flex;align-items:center;gap:8px;padding:10px 12px;background:rgba(62,207,110,.08);border:1px solid rgba(62,207,110,.2);border-radius:12px;margin-bottom:14px;flex-shrink:0;"><span>'+activityState.primary.icon+'</span><span style="font-size:13px;font-weight:700;">'+escapeHTML(activityState.primary.name)+'</span><button id="ga-stop-btn" style="margin-left:auto;background:rgba(248,113,113,.12);border:1px solid rgba(248,113,113,.25);color:var(--red);font-size:11px;padding:3px 8px;border-radius:7px;cursor:pointer;">Stop</button></div>'
    : '';

  const manualSection =
      '<div style="font-size:11px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);margin-bottom:8px;flex-shrink:0;">Set activity manually</div>'
    + '<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px;flex-shrink:0;">'
    + '<button id="ga-icon-btn" type="button" title="Pick icon" style="width:38px;height:38px;border-radius:10px;border:1px solid var(--border);background:var(--panel2);font-size:20px;cursor:pointer;flex-shrink:0;display:flex;align-items:center;justify-content:center;">🎮</button>'
    + '<input id="ga-manual-name" class="field-input" placeholder="What are you playing or doing?" maxlength="60" style="font-size:13px;flex:1;">'
    + '<button id="ga-manual-set" class="btn-primary" style="flex-shrink:0;padding:9px 14px;font-size:12px;font-weight:700;border-radius:10px;">Set</button>'
    + '</div>'
    + '<div id="ga-icon-pop" style="display:none;flex-wrap:wrap;gap:4px;padding:8px;background:var(--panel2);border:1px solid var(--border);border-radius:10px;margin-bottom:10px;flex-shrink:0;">'
    + iconChoices.map(ic => '<button type="button" data-ic="'+ic+'" style="width:32px;height:32px;border:none;background:transparent;font-size:18px;cursor:pointer;border-radius:7px;">'+ic+'</button>').join('')
    + '</div>';

  const recentSection = recents.length
    ? '<div style="font-size:11px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);margin:4px 0 8px;flex-shrink:0;">Recent</div>'
      + '<div id="ga-recents" style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px;flex-shrink:0;">'
      + recents.map(r => '<button type="button" class="ga-recent-chip" data-game-name="'+escapeHTML(r.name).replace(/"/g,'&quot;')+'" data-game-icon="'+escapeHTML(r.icon||'🎮')+'" style="display:inline-flex;align-items:center;gap:6px;padding:6px 10px;background:var(--panel2);border:1px solid var(--border);border-radius:9px;cursor:pointer;font-size:12px;color:#fff;"><span>'+(r.icon||'🎮')+'</span><span>'+escapeHTML(r.name)+'</span></button>').join('')
      + '</div>'
    : '';

  const procSection = isDesktop
    ? '<div style="font-size:11px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);margin-bottom:8px;flex-shrink:0;">Running on your PC</div>'
      + '<input id="ga-search" class="field-input" placeholder="Search running apps…" style="font-size:12.5px;margin-bottom:8px;flex-shrink:0;">'
      + '<div id="ga-proc-list" style="flex:1;overflow-y:auto;min-height:80px;">'
      + '<div style="text-align:center;padding:20px;"><div class="pl-spinner" style="width:18px;height:18px;border-width:2px;margin:0 auto;"></div><div style="font-size:11px;color:var(--muted);margin-top:6px;">Scanning…</div></div>'
      + '</div>'
    : '<div style="padding:10px 12px;background:rgba(255,249,62,.06);border:1px solid rgba(255,249,62,.15);border-radius:10px;font-size:11px;color:rgba(255,255,255,.6);flex-shrink:0;">Tip: install the Fortized desktop app to auto-detect running games.</div>';

  box.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;flex-shrink:0;">'
    +'<div style="font-family:var(--font-display);font-size:16px;font-weight:800;">🎮 Game Activity</div>'
    +'<button id="ga-close" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:20px;width:28px;height:28px;display:flex;align-items:center;justify-content:center;border-radius:50%;">✕</button>'
    +'</div>'
    + currentBanner
    + manualSection
    + recentSection
    + procSection;
  modal.appendChild(box);
  document.body.appendChild(modal);
  document.getElementById('ga-close').onclick = () => _closeEl('game-activity-modal');
  modal.addEventListener('click', e => { if (e.target === modal) _closeEl('game-activity-modal'); });
  document.getElementById('ga-stop-btn')?.addEventListener('click', () => { setGameActivity(null); _closeEl('game-activity-modal'); });

  // Manual entry wiring
  let chosenIcon = '🎮';
  const iconBtn = document.getElementById('ga-icon-btn');
  const iconPop = document.getElementById('ga-icon-pop');
  const nameInput = document.getElementById('ga-manual-name');
  const setBtn = document.getElementById('ga-manual-set');
  iconBtn.onclick = () => { iconPop.style.display = iconPop.style.display === 'flex' ? 'none' : 'flex'; };
  iconPop.addEventListener('click', e => {
    const b = e.target.closest('[data-ic]');
    if (!b) return;
    chosenIcon = b.dataset.ic;
    iconBtn.textContent = chosenIcon;
    iconPop.style.display = 'none';
    nameInput.focus();
  });
  function commitManual() {
    const n = (nameInput.value || '').trim();
    if (!n) { nameInput.focus(); return; }
    setGameActivity(n, chosenIcon);
    _recordRecentActivity(n, chosenIcon);
    _closeEl('game-activity-modal');
  }
  setBtn.onclick = commitManual;
  nameInput.addEventListener('keydown', e => {
    if (e.key === 'Enter') { e.preventDefault(); commitManual(); }
    else if (e.key === 'Escape') { _closeEl('game-activity-modal'); }
  });
  nameInput.focus();

  // Recent chips
  document.getElementById('ga-recents')?.addEventListener('click', e => {
    const chip = e.target.closest('[data-game-name]');
    if (!chip) return;
    setGameActivity(chip.dataset.gameName, chip.dataset.gameIcon || '🎮');
    _recordRecentActivity(chip.dataset.gameName, chip.dataset.gameIcon || '🎮');
    _closeEl('game-activity-modal');
  });

  if (!isDesktop) return;

  // Fetch running processes via desktop native detection
  const listEl = document.getElementById('ga-proc-list');
  let appEntries = [];
  try {
    const procs = await window.fortizedDesktop.getProcesses();
    if (!procs || !procs.length) {
      listEl.innerHTML = '<div style="text-align:center;padding:20px;color:var(--muted);font-size:12px;">No running apps found.</div>';
      return;
    }
    const systemProcs = new Set(['system','idle','svchost','csrss','wininit','winlogon','services','lsass','smss','dwm','conhost','explorer','taskhostw','runtimebroker','sihost','fontdrvhost','ctfmon','dllhost','searchhost','startmenuexperiencehost','shellexperiencehost','textinputhost','widgetservice','securityhealthsystray','systemsettings','applicationframehost','lockapp','searchui','cortana','registry','memory compression','system idle process','kernel_task','launchd','loginwindow','windowserver','systemuiserver','dock','finder','spotlight','mds','mds_stores','distnoted','cfprefsd','pboard','init','systemd','dbus-daemon','polkitd','rsyslogd','cron','atd','agetty','login','bash','sh','zsh','fish','Xorg','gnome-shell','plasmashell','pipewire','pulseaudio','wireplumber','dconf-service','gvfsd','xdg-desktop-portal','at-spi-bus-launcher','xdg-document-portal','xdg-permission-store','evolution-data-server','goa-daemon','goa-identity-service','gnome-keyring-d','agent','gpg-agent','ssh-agent','nm-applet','tracker-miner-fs','gsd-','evolution-calendar','evolution-addressbook']);
    const unique = [...new Set(procs.map(p => typeof p === 'string' ? p : p?.name || '').filter(Boolean))]
      .filter(name => !systemProcs.has(name.toLowerCase()) && name.length > 1)
      .sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
    appEntries = unique.map(name => {
      const lower = name.toLowerCase();
      const known = KNOWN_GAMES.find(g => g.keywords.some(kw => lower.includes(kw)) || lower.includes(g.name.toLowerCase()));
      return { procName: name, displayName: known ? known.name : name, icon: known ? known.icon : '🖥️' };
    });
  } catch {
    listEl.innerHTML = '<div style="text-align:center;padding:20px;color:var(--muted);font-size:12px;">Could not scan apps.</div>';
    return;
  }

  function renderList(filter) {
    const filtered = filter
      ? appEntries.filter(a => a.displayName.toLowerCase().includes(filter.toLowerCase()) || a.procName.toLowerCase().includes(filter.toLowerCase()))
      : appEntries;
    if (!filtered.length) {
      listEl.innerHTML = '<div style="text-align:center;padding:16px;color:var(--muted);font-size:12px;">No matches.</div>';
      return;
    }
    listEl.innerHTML = '<div style="display:flex;flex-direction:column;gap:4px;">'
      + filtered.map(a => {
        const isActive = _gameActivity?.name === a.displayName;
        return '<div data-game-name="'+escapeHTML(a.displayName).replace(/"/g,'&quot;')+'" data-game-icon="'+a.icon+'" style="display:flex;align-items:center;gap:10px;padding:9px 12px;background:'+(isActive?'rgba(62,207,110,.06)':'var(--panel2)')+';border:1px solid '+(isActive?'rgba(62,207,110,.2)':'var(--border)')+';border-radius:11px;cursor:pointer;transition:all .12s;" '
          +'onmouseenter="this.style.borderColor=\'var(--accent)\'" onmouseleave="this.style.borderColor=\''+(isActive?'rgba(62,207,110,.2)':'var(--border)')+'\'">'
          +'<span style="font-size:18px;">'+a.icon+'</span>'
          +'<div style="flex:1;min-width:0;">'
          +'<div style="font-size:12.5px;font-weight:700;color:#fff;">'+escapeHTML(a.displayName)+'</div>'
          +(a.displayName !== a.procName ? '<div style="font-size:10px;color:var(--muted);">'+escapeHTML(a.procName)+'</div>' : '')
          +'</div>'
          +(isActive ? '<span style="font-size:9px;font-weight:700;text-transform:uppercase;color:var(--green);letter-spacing:.06em;">Active</span>' : '')
          +'</div>';
      }).join('')
      + '</div>';
  }

  renderList('');
  document.getElementById('ga-search').addEventListener('input', e => renderList(e.target.value));
  listEl.addEventListener('click', e => {
    const tile = e.target.closest('[data-game-name]');
    if (tile) {
      setGameActivity(tile.dataset.gameName, tile.dataset.gameIcon);
      _recordRecentActivity(tile.dataset.gameName, tile.dataset.gameIcon);
      _closeEl('game-activity-modal');
    }
  });
}

// Show game activity on other users' profiles
function renderGameActivityOnProfile(u, containerEl) {
  if (!u?.gameActivity?.name) return;
  const ga = u.gameActivity;
  const cover = ga.coverUrl || ga.coverThumb || _getManualCover(ga.name);
  const div = document.createElement('div');
  div.style.cssText = 'display:flex;align-items:center;gap:12px;padding:10px 14px;background:rgba(62,207,110,.06);border:1px solid rgba(62,207,110,.15);border-radius:12px;margin-bottom:12px;';
  div.innerHTML = (cover
    ? '<img src="'+escapeHTML(cover)+'" style="width:36px;height:48px;border-radius:6px;object-fit:cover;flex-shrink:0;" onerror="this.outerHTML=\'<span style=font-size:24px;flex-shrink:0;>'+(ga.icon||'🎮')+'</span>\'">'
    : '<span style="font-size:24px;flex-shrink:0;">'+(ga.icon||'🎮')+'</span>')
    +'<div style="flex:1;min-width:0;"><div style="font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--green);">Playing a Game</div>'
    +'<div style="font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+escapeHTML(ga.name)+'</div>'
    +(ga.genre ? '<div style="font-size:10.5px;color:rgba(255,255,255,.25);margin-top:1px;">'+escapeHTML(ga.genre)+'</div>' : '')
    +'</div>';
  if (containerEl) containerEl.prepend(div);
}

