let _forumCurrentCategory = null;
let _forumCurrentThread = null;
let _forumThreadImageData = null;
let _forumPostImageData = null;
let _forumThreadAttachments = [];
let _forumPostAttachments = [];
let _forumLivePreviewTimer = null;
let _forumAllThreadsCache = [];

const _FORUM_ATT_MAX_BYTES = 10 * 1024 * 1024; // 10 MB per file

function _forumClassifyAttachment(file) {
  const mime = (file.type || '').toLowerCase();
  if (mime === 'image/gif') return 'gif';
  if (mime.startsWith('video/')) return 'video';
  if (mime.startsWith('image/')) return 'image';
  return null;
}

function _forumRenderAttachmentsHTML(list, opts) {
  if (!Array.isArray(list) || !list.length) return '';
  const maxH = (opts && opts.compact) ? 220 : 360;
  return list.map(a => {
    const safeUrl = escapeHTML(a.url || '');
    if (a.type === 'video') {
      return `<video controls playsinline preload="metadata" class="forum-att-media forum-att-video" style="max-height:${maxH}px;" src="${safeUrl}"></video>`;
    }
    return `<img class="forum-att-media forum-att-image" src="${safeUrl}" style="max-height:${maxH}px;" alt="${escapeHTML(a.name || 'attachment')}">`;
  }).join('');
}

function _forumMediaBadgesHTML(item) {
  const atts = Array.isArray(item?.attachments) ? item.attachments : [];
  const hasLegacy = !!(item && item.image);
  if (!atts.length && !hasLegacy) return '';
  const hasVid = atts.some(a => a.type === 'video');
  const hasGif = atts.some(a => a.type === 'gif');
  const imgCount = atts.filter(a => a.type === 'image').length + (hasLegacy ? 1 : 0);
  const badges = [];
  if (hasVid) badges.push('<span class="forum-media-badge" title="Contains video"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="23 7 16 12 23 17 23 7"/><rect x="1" y="5" width="15" height="14" rx="2" ry="2"/></svg>Video</span>');
  if (hasGif) badges.push('<span class="forum-media-badge" title="Contains GIF"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="14" rx="2" ry="2"/><path d="M7 9v6M11 9v6M14 9h3M14 12h2M20 9v6"/></svg>GIF</span>');
  if (imgCount) {
    const lbl = imgCount > 1 ? `Images · ${imgCount}` : 'Image';
    badges.push(`<span class="forum-media-badge" title="Contains image">${'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg>'}${lbl}</span>`);
  }
  return badges.join('');
}

// Per-category last-visit timestamps for "new posts" indicators
function _forumGetLastVisits() {
  try { return JSON.parse(localStorage.getItem('ftz_forum_visits') || '{}'); } catch(e) { return {}; }
}
function _forumSaveLastVisit(catId) {
  try {
    const v = _forumGetLastVisits();
    v[catId] = Date.now();
    localStorage.setItem('ftz_forum_visits', JSON.stringify(v));
  } catch(e) {}
}
function _forumCanPostInCategory(catId) {
  if (catId === 'announcements' || catId === 'event-records') return isAdmin();
  return true;
}
function _forumCanPin() { return isSuperAdmin(); }
function _forumCountNewInCategory(threads, catId) {
  const visits = _forumGetLastVisits();
  const last = visits[catId] || 0;
  if (!last) return 0; // Never visited — don't flood with "new" everywhere; only mark after first visit
  return (threads || []).filter(t => (t.updated_at || t.created_at) > last).length;
}

function _forumTimeAgo(ts) {
  const s = Math.floor((Date.now() - new Date(ts).getTime()) / 1000);
  if (s < 60) return 'just now';
  const m = Math.floor(s / 60); if (m < 60) return m + 'm ago';
  const h = Math.floor(m / 60); if (h < 24) return h + 'h ago';
  const d = Math.floor(h / 24); if (d < 30) return d + 'd ago';
  return Math.floor(d / 30) + 'mo ago';
}

function _forumFormatCount(n) {
  if (!n) return '0';
  if (n >= 1000000) return (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
  if (n >= 1000) return (n / 1000).toFixed(1).replace(/\.0$/, '') + 'K';
  return n.toLocaleString();
}

async function _forumInit() {
  const root = document.getElementById('forum-root');
  if (!root) return;
  _forumCurrentCategory = null;
  _forumCurrentThread = null;

  let totalThreads = 0, totalPosts = 0;
  const catCounts = {};
  let allThreads = [];
  try {
    allThreads = await Promise.all(FORUM_CATEGORIES.map(c => FortizedSocial.getForumThreads(c.id, 200, 0)));
    _forumAllThreadsCache = allThreads.flat();
    FORUM_CATEGORIES.forEach((c, i) => {
      const threads = allThreads[i] || [];
      const replies = threads.reduce((s, t) => s + (t.reply_count || 0), 0);
      catCounts[c.id] = { threads: threads.length, posts: threads.length + replies };
      totalThreads += threads.length;
      totalPosts += threads.length + replies;
    });
  } catch(e) { console.error('[Forum] Stats load:', e); allThreads = FORUM_CATEGORIES.map(() => []); }

  const recentThreads = [..._forumAllThreadsCache].sort((a, b) => (b.updated_at || b.created_at) - (a.updated_at || a.created_at)).slice(0, 12);
  const myThreads = _forumAllThreadsCache.filter(t => t.author === CU?.username).sort((a, b) => b.created_at - a.created_at).slice(0, 8);

  const groups = {
    announcements: { label: 'Official', cats: FORUM_CATEGORIES.filter(c => c.group === 'announcements') },
    fortized: { label: 'Main', cats: FORUM_CATEGORIES.filter(c => c.group === 'fortized') },
    community: { label: 'Community', cats: FORUM_CATEGORIES.filter(c => c.group === 'community') },
  };

  root.innerHTML = `
    <div class="forum-scroll" id="forum-scroll-shell">
      <div class="disc-hero" style="height:140px;">
        <img src="/Fortized banner.png?v=2" class="disc-hero-bg" alt="" onerror="this.style.display='none'">
        <div class="disc-hero-fade"></div>
        <div class="disc-hero-content">
          <h1 style="font-family:var(--font-display);font-size:22px;font-weight:900;color:#fff;margin:0 0 3px;text-shadow:0 2px 12px rgba(0,0,0,.5);">Fortized Forum</h1>
          <p style="font-size:11.5px;color:rgba(255,255,255,.4);margin:0;">Engage with the community and share your thoughts.</p>
        </div>
      </div>
      <div id="forum-page-content">
        <div style="padding:16px 28px 0;max-width:1200px;margin:0 auto;">
          <div style="display:flex;align-items:center;gap:12px;margin-bottom:16px;">
            <div class="forum-hero-stats" style="display:flex;gap:10px;">
              <div class="forum-hero-stat">
                <div class="forum-hero-stat-num">${_forumFormatCount(totalThreads)}</div>
                <div class="forum-hero-stat-label">Posts</div>
              </div>
              <div class="forum-hero-stat">
                <div class="forum-hero-stat-num">${_forumFormatCount(totalPosts)}</div>
                <div class="forum-hero-stat-label">Replies</div>
              </div>
            </div>
            <div style="flex:1;"></div>
            <div class="forum-search-wrap" style="max-width:280px;">
              <svg class="forum-search-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
              <input class="forum-search-input" id="forum-search" placeholder="Search posts..." oninput="_forumGlobalSearch(this.value)">
            </div>
          </div>
        </div>

        <div class="forum-body">
          <div class="forum-sidebar">
            <div class="forum-section-title">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
              Recent Activity
            </div>
            <div class="forum-activity-card">
              ${recentThreads.length ? recentThreads.map(th => {
                const cat = FORUM_CATEGORIES.find(c => c.id === th.category) || FORUM_CATEGORIES[0];
                const pfpF = _defaultPfpUrl(th.author || '');
                return `<div class="forum-activity-item" onclick="_forumViewThread('${th.id}')">
                  <img class="forum-activity-avatar" data-forum-author="${escapeHTML(th.author||'')}" src="${escapeHTML(th.author_pfp || pfpF)}" onerror="this.src='${pfpF}'">
                  <div class="forum-activity-info">
                    <div class="forum-activity-title"><span class="fa-cat-dot" style="background:${cat.color}"></span>${escapeHTML(th.title)}</div>
                    <div class="forum-activity-meta">${escapeHTML(th.author)} · ${_forumTimeAgo(th.updated_at || th.created_at)}</div>
                  </div>
                </div>`;
              }).join('') : '<div style="padding:20px;text-align:center;color:var(--muted);font-size:12px;">No activity yet</div>'}
            </div>

            <div class="forum-section-title" style="margin-top:8px;">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
              Your Posts
            </div>
            <div class="forum-your-posts">
              ${myThreads.length ? myThreads.map(th => {
                const cat = FORUM_CATEGORIES.find(c => c.id === th.category) || FORUM_CATEGORIES[0];
                return `<div class="forum-activity-item" onclick="_forumViewThread('${th.id}')">
                  <div class="forum-activity-info">
                    <div class="forum-activity-title"><span class="fa-cat-dot" style="background:${cat.color}"></span>${escapeHTML(th.title)}</div>
                    <div class="forum-activity-meta">${th.reply_count || 0} replies · ${_forumTimeAgo(th.created_at)}</div>
                  </div>
                </div>`;
              }).join('') : `<div class="forum-your-posts-empty">
                <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
                Your posts will appear here!
              </div>`}
            </div>

            <div id="forum-ad-slot" class="forum-ad-slot" style="margin-top:16px;">
              <div class="ad-empty">Ad</div>
            </div>
          </div>

          <div class="forum-main" id="forum-main-content">
            ${Object.values(groups).map(g => `
              <div>
                <div class="forum-group-header">
                  <span class="forum-group-label">${g.label}</span>
                  <div class="forum-group-line"></div>
                  <div class="forum-group-col-header">
                    <span class="forum-group-col-label">Posts</span>
                    <span class="forum-group-col-label">Replies</span>
                  </div>
                </div>
                ${g.cats.map((cat, ci) => {
                  const threadsForCat = allThreads[FORUM_CATEGORIES.indexOf(cat)] || [];
                  const newCount = _forumCountNewInCategory(threadsForCat, cat.id);
                  const lockIcon = cat.id === 'announcements' && !isAdmin()
                    ? '<svg class="forum-cat-lock" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" title="Staff-only"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>'
                    : '';
                  const newBadge = newCount > 0
                    ? `<span class="forum-cat-new" title="${newCount} new since your last visit">${newCount} new</span>`
                    : '';
                  return `
                  <div class="forum-cat-entry" style="--cat-color:${cat.color}" onclick="_forumOpenCategory('${cat.id}')">
                    <div class="forum-cat-icon" style="background:${cat.color}18;color:${cat.color};">${cat.icon}</div>
                    <div class="forum-cat-info">
                      <div class="forum-cat-name">${cat.name} ${lockIcon} ${newBadge}</div>
                      <div class="forum-cat-desc">${escapeHTML(cat.desc)}</div>
                    </div>
                    <div class="forum-cat-count">${_forumFormatCount(catCounts[cat.id]?.threads || 0)}</div>
                    <div class="forum-cat-count">${_forumFormatCount(catCounts[cat.id]?.posts || 0)}</div>
                  </div>
                `;}).join('')}
              </div>
            `).join('')}
          </div>
        </div>
      </div>
    </div>
  `;
  _forumRenderAd();
  _forumHydratePfps(document.getElementById('forum-page-content'));

  // If something (e.g. "What's happening" on the homepage) asked us to open a
  // specific thread, do it now that the forum shell is rendered. Doing it
  // here avoids the race where a poll-based caller renders the thread and
  // then _forumInit's awaited render wipes it out.
  if (window._forumPendingThread) {
    const tid = window._forumPendingThread;
    window._forumPendingThread = null;
    try { await _forumViewThread(tid); } catch(e) { console.warn('[Forum] pending open failed:', e); }
  }
}

let _forumAdTimer = null;
async function _forumRenderAd() {
  const slot = document.getElementById('forum-ad-slot');
  if (!slot) return;
  if (_forumAdTimer) { clearInterval(_forumAdTimer); _forumAdTimer = null; }
  async function _showAd() {
    try {
      const ads = await _getAllActiveAds();
      const rectAds = ads.filter(a => a.ratio === 'rectangle');
      if (!rectAds.length) { slot.innerHTML = '<div class="ad-empty">Ad</div>'; return; }
      const ad = _pickWeightedAd(rectAds);
      if (!ad) return;
      slot.innerHTML = _renderAdHTML(ad, 'rectangle');
      slot.onclick = () => _adClickAction(ad);
    } catch(e) { slot.innerHTML = '<div class="ad-empty">Ad</div>'; }
  }
  await _showAd();
  _forumAdTimer = setInterval(_showAd, 75000);
}

async function _forumOpenCategory(catId) {
  _forumCurrentCategory = catId;
  _forumSaveLastVisit(catId);
  const content = document.getElementById('forum-page-content');
  if (!content) { const root = document.getElementById('forum-root'); if (!root) return; await _forumInit(); return; }
  const cat = FORUM_CATEGORIES.find(c => c.id === catId) || FORUM_CATEGORIES[0];

  content.innerHTML = `
    <div style="display:flex;flex-direction:column;flex:1;min-height:0;">
      <div class="forum-threadlist-header">
        <button class="forum-back-btn" onclick="_forumInit()">← Back</button>
        <span class="forum-threadlist-cat-icon" style="color:${cat.color};">${cat.icon}</span>
        <div style="flex:1;min-width:0;">
          <div class="forum-threadlist-title">${cat.name}</div>
          <div class="forum-threadlist-desc">${escapeHTML(cat.desc)}</div>
        </div>
        <div class="forum-toolbar" style="margin-top:0;flex:0;">
          <div class="forum-search-wrap" style="max-width:240px;">
            <svg class="forum-search-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
            <input class="forum-search-input" placeholder="Search in ${escapeHTML(cat.name)}..." oninput="_forumSearchInCategory(this.value)">
          </div>
          ${_forumCanPostInCategory(catId) ? `<button class="forum-new-btn" onclick="_forumShowCreatePost('${catId}')">+ New Post</button>` : `<button class="forum-new-btn" disabled style="opacity:.45;cursor:not-allowed;" title="${catId === 'event-records' ? 'Only admins & superadmins can post here' : 'Only admins can post announcements'}">Staff-only</button>`}
        </div>
      </div>
      <div class="forum-threadlist-body">
        <div class="forum-threadlist-inner" id="forum-threads-container">
          <div class="forum-empty"><p>Loading posts...</p></div>
        </div>
      </div>
    </div>
  `;
  await _forumLoadThreads();
}

async function _forumLoadThreads() {
  const container = document.getElementById('forum-threads-container');
  if (!container) return;

  try {
    const threads = await FortizedSocial.getForumThreads(_forumCurrentCategory, 50, 0);
    if (!threads.length) {
      container.innerHTML = `<div class="forum-empty">
        <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
        <p>No posts yet. Be the first to start a discussion!</p>
      </div>`;
      return;
    }

    const cat = FORUM_CATEGORIES.find(c => c.id === _forumCurrentCategory) || FORUM_CATEGORIES[0];
    const sorted = [...threads].sort((a, b) => {
      if (!!b.pinned - !!a.pinned) return (!!b.pinned) - (!!a.pinned);
      return (b.updated_at || b.created_at) - (a.updated_at || a.created_at);
    });
    const canPin = _forumCanPin();
    const pinnedInCat = sorted.filter(t => t.pinned).length;

    // Batch-fetch posts for all visible threads so we can surface a YouTube-style top reply.
    let postsByThread = {};
    try {
      postsByThread = await FortizedSocial.getForumPostsForThreads(sorted.map(t => t.id));
    } catch(_) { postsByThread = {}; }

    container.innerHTML = sorted.map(th => {
      const pfpF = _defaultPfpUrl(th.author || '');
      const score = _forumNetScore(th);
      const scoreClass = score > 0 ? 'pos' : score < 0 ? 'neg' : '';
      const scoreLabel = score > 0 ? '+' + score : (score === 0 ? '0' : String(score));
      const posts = (postsByThread[th.id] || []);
      // Pick the highest-net-score reply; tiebreak on recency, and only surface if it has positive net support.
      let topReply = null;
      if (posts.length) {
        const scored = posts.map(p => ({ p, s: _forumNetScore(p) }));
        scored.sort((a, b) => {
          if (b.s !== a.s) return b.s - a.s;
          return (b.p.created_at || 0) - (a.p.created_at || 0);
        });
        if (scored[0].s > 0) topReply = scored[0].p;
      }
      const topReplyBlock = topReply ? `
        <div class="forum-thread-topreply" onclick="event.stopPropagation();_forumViewThread('${th.id}')" title="View thread">
          <span class="ftr-label">★ Top reply</span>
          <img class="ftr-avatar" data-forum-author="${escapeHTML(topReply.author||'')}" src="${escapeHTML(topReply.author_pfp || _defaultPfpUrl(topReply.author||''))}" onerror="this.src='${_defaultPfpUrl(topReply.author||'')}'">
          <span class="ftr-handle">@${escapeHTML(topReply.author)}</span>
          <span class="ftr-snippet">${_forumRenderInline((topReply.content || '').slice(0, 180))}</span>
          <span class="ftr-score">▲ ${_forumNetScore(topReply)}</span>
        </div>` : '';

      return `
      <div class="forum-thread-card${th.pinned ? ' forum-thread-card--pinned' : ''}" onclick="_forumViewThread('${th.id}')">
        <div class="forum-thread-row">
          <div class="forum-thread-score" title="Net votes">
            <div class="forum-thread-score-num ${scoreClass}">${scoreLabel}</div>
            <div class="forum-thread-score-lbl">votes</div>
          </div>
          <img class="forum-thread-avatar" data-forum-author="${escapeHTML(th.author||'')}" src="${escapeHTML(th.author_pfp || pfpF)}" onerror="this.src='${pfpF}'">
          <div class="forum-thread-info">
            <div class="forum-thread-title">${th.pinned ? '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor" stroke="none" style="color:var(--accent);vertical-align:middle;margin-right:4px;"><path d="M12 2L9.19 8.63 2 9.24l5.46 4.73L5.82 21 12 17.27 18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2z"/></svg> ' : ''}${escapeHTML(th.title)}${th.category === 'announcements' ? ' <span class="forum-official-logo forum-official-logo--inline" role="img" aria-label="Official Fortized" title="Official Fortized announcement"></span>' : ''}</div>
            <div class="forum-thread-meta">
              <span>by <strong style="color:var(--text);">${escapeHTML(th.author)}</strong></span>
              <span class="forum-thread-meta-sep"></span>
              <span><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:3px;"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>${_forumBoostedViews(th)}</span>
              <span class="forum-thread-meta-sep"></span>
              <span><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:3px;"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>${th.reply_count || 0}</span>
              ${_forumMediaBadgesHTML(th) ? `<span class="forum-thread-meta-sep"></span><span class="forum-thread-badges">${_forumMediaBadgesHTML(th)}</span>` : ''}
            </div>
          </div>
          <div class="forum-thread-right">
            ${canPin ? `<button class="forum-pin-btn${th.pinned?' forum-pin-btn--on':''}" title="${th.pinned?'Unpin':(pinnedInCat>=3?'Pin cap reached (3)':'Pin to top')}" onclick="event.stopPropagation();_forumTogglePin('${th.id}')"><svg width="12" height="12" viewBox="0 0 24 24" fill="${th.pinned?'currentColor':'none'}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="17" x2="12" y2="22"/><path d="M5 17h14l-1.5-3.5a4 4 0 0 1-.5-2V6H7v5.5a4 4 0 0 1-.5 2L5 17z"/></svg></button>` : ''}
            <div class="forum-thread-time">${_forumTimeAgo(th.updated_at || th.created_at)}</div>
            <span class="forum-thread-cat-badge" style="background:${cat.color}18;color:${cat.color};">${cat.icon} ${cat.name}</span>
          </div>
        </div>
        ${topReplyBlock}
      </div>
    `;
    }).join('');
    _forumHydratePfps(container);
    try { if (typeof window._twemojiReparse === 'function') window._twemojiReparse(container); } catch(_){}
  } catch(e) {
    console.error('[Forum] Load failed:', e);
    container.innerHTML = '<div class="forum-empty"><p style="color:var(--red);">Failed to load posts</p></div>';
  }
}

async function _forumTogglePin(threadId) {
  if (!_forumCanPin()) { toast('Only superadmins can pin posts.', 'error'); return; }
  try {
    const thread = await FortizedSocial.getForumThread(threadId);
    if (!thread) return;
    const catId = thread.category;
    if (!thread.pinned) {
      // Enforce 3-per-category cap
      const threadsInCat = await FortizedSocial.getForumThreads(catId, 200, 0);
      const pinned = threadsInCat.filter(t => t.pinned).length;
      if (pinned >= 3) { toast('Pin cap reached (3 per category). Unpin one first.', 'error'); return; }
    }
    await FortizedSocial.updateForumThread(threadId, { pinned: !thread.pinned });
    toast(thread.pinned ? 'Unpinned.' : 'Pinned to top.', 'success');
    await _forumLoadThreads();
  } catch(e) {
    console.error('[Forum] Pin failed:', e);
    toast('Failed to update pin state', 'error');
  }
}

// Navigate to forum then open a specific thread. The forum view initialises
// asynchronously, so we wait for its content container to exist before
// dispatching the thread render.
async function _homeOpenForumThread(threadId) {
  // Ask _forumInit to jump straight to this thread after it finishes rendering
  // the category shell. Racing the two renderers (init vs. viewThread) would
  // leave the user on the category list because init awaits then overwrites
  // forum-root, clobbering viewThread's render.
  window._forumPendingThread = threadId;
  showView('forum');
}

async function _forumViewThread(threadId, opts) {
  const content = document.getElementById('forum-page-content');
  if (!content) return;
  const skipViewInc = !!(opts && opts.skipViewInc);

  try {
    const thread = await FortizedSocial.getForumThread(threadId);
    const posts = await FortizedSocial.getForumPosts(threadId);
    const author = await FortizedSocial.getUserByName(thread.author);
    const cat = FORUM_CATEGORIES.find(c => c.id === thread.category) || FORUM_CATEGORIES[0];

    // Only increment views on first/real open, never on in-thread refresh (vote, edit, delete)
    if (!skipViewInc && _forumViewedThreads !== threadId) {
      await FortizedSocial.updateForumThread(threadId, { views: (thread.views || 0) + 1 });
      _forumViewedThreads = threadId;
      thread.views = (thread.views || 0) + 1;
    }
    _forumCurrentThread = threadId;
    _forumCurrentPosts = posts;

    const backAction = _forumCurrentCategory
      ? `_forumOpenCategory('${_forumCurrentCategory}')`
      : `_forumInit()`;

    const opScore = _forumNetScore(thread);
    const opUpvoted = _forumIsUpvoted(thread);
    const opDownvoted = _forumIsDownvoted(thread);

    content.innerHTML = `
      <div style="display:flex;flex-direction:column;flex:1;min-height:0;">
        <div class="forum-detail-header">
          <button class="forum-detail-back" onclick="${backAction}">← Back</button>
          <div style="flex:1;min-width:0;">
            <div class="forum-detail-title">${escapeHTML(thread.title)}${thread.category === 'announcements' ? ' <span class="forum-official-logo" role="img" aria-label="Official Fortized" title="Official Fortized announcement"></span>' : ''}</div>
            <div class="forum-detail-stats">
              <span>${_forumBoostedViews(thread)} views</span>
              <span>·</span>
              <span>${posts.length} replies</span>
              <span>·</span>
              <span class="forum-thread-cat-badge" style="background:${cat.color}18;color:${cat.color};">${cat.icon} ${cat.name}</span>
            </div>
          </div>
        </div>

        <div class="forum-detail-body">
          <div class="forum-detail-inner">
            <div class="forum-op-card" id="fp-${escapeHTML(thread.id)}">
              <div class="forum-user-col">
                <img class="forum-op-avatar" data-forum-author="${escapeHTML(thread.author||'')}" src="${escapeHTML(author?.pfp || _defaultPfpUrl(thread.author))}" onerror="this.src='${_defaultPfpUrl(thread.author)}'">
                <div class="forum-user-name">${escapeHTML(author?.displayName || thread.author)}</div>
                <div class="forum-user-handle">@${escapeHTML(thread.author)}</div>
                <div class="forum-user-streak" data-streak-for="${escapeHTML(thread.author||'')}" style="margin-top:6px;">${(+author?.dailyStreak) ? renderStreakChip(+author.dailyStreak) : ''}</div>
                ${(function(){const r=getStaffRole(thread.author);return r?`<div class="forum-user-role forum-user-role--${escapeHTML(r)}">${r==='superadmin'?'Superadmin':r==='admin'?'Admin':'Moderator'}</div>`:'';})()}
                ${author?.createdAt ? `<div class="forum-user-joined">Joined ${_forumTimeAgo(new Date(author.createdAt).getTime())}</div>` : ''}
              </div>
              <div class="forum-op-content">
                <div class="forum-op-author" style="display:none;">
                  <strong>${escapeHTML(author?.displayName || thread.author)}</strong>
                  <span class="forum-op-handle">@${escapeHTML(thread.author)}</span>
                </div>
                <div class="forum-op-date">${new Date(thread.created_at).toLocaleString()}${thread.edited_at ? ` <span class="forum-edited" title="Edited ${new Date(thread.edited_at).toLocaleString()}">(edited)</span>` : ''}</div>
                <div class="forum-op-text" id="forum-op-text">${_forumRenderBody(thread.content || '')}</div>
                ${thread.image ? `<img class="forum-op-image" src="${escapeHTML(thread.image)}">` : ''}
                ${Array.isArray(thread.attachments) && thread.attachments.length ? `<div class="forum-att-grid">${_forumRenderAttachmentsHTML(thread.attachments)}</div>` : ''}
                <div class="forum-post-actions">
                  <div class="forum-vote-group${thread.category === 'announcements' ? ' forum-vote-group--upvote-only' : ''}">
                    <button class="forum-vote-btn up ${opUpvoted?'active':''}" onclick="_forumVote('thread','${thread.id}',1)" title="Upvote"><span class="fvb-icon">👏</span></button>
                    <div class="forum-vote-score ${opScore>0?'pos':opScore<0?'neg':''}">${opScore.toLocaleString()}</div>
                    ${thread.category === 'announcements' ? '' : `<button class="forum-vote-btn down ${opDownvoted?'active':''}" onclick="_forumVote('thread','${thread.id}',-1)" title="Downvote"><span class="fvb-icon">👎</span></button>`}
                  </div>
                  ${_forumCanEditPost(thread) ? `<button class="forum-pa-btn" onclick="_forumEditThread('${thread.id}')">${_svgIcon('pencil')} Edit</button>` : ''}
                  ${_forumCanDeleteThread(thread) ? `<button class="forum-pa-btn danger" onclick="_forumDeleteThreadConfirm('${thread.id}')">${_svgIcon('trash')} Delete</button>` : ''}
                </div>
                ${(function(){ const { staff } = _forumExtractStaffResponse(posts); return _forumRenderStaffResponseCard(thread, staff); })()}
              </div>
            </div>

            <div class="forum-replies-divider"><span>${(function(){ const {rest} = _forumExtractStaffResponse(posts); return rest.length; })()} ${(function(){ const {rest} = _forumExtractStaffResponse(posts); return rest.length === 1 ? 'Reply' : 'Replies'; })()}</span></div>

            <div id="forum-posts-list">
              ${(function(){ const {rest} = _forumExtractStaffResponse(posts); return rest.map(post => _forumRenderPostCard(post, threadId, thread)).join(''); })()}
            </div>

            <div class="forum-reply-compose">
              <div class="forum-reply-compose-title">Reply to this post</div>
              <div id="forum-quote-preview" style="display:none;"></div>
              ${buildFormatToolbarHTML('forum-post-text')}
              <textarea id="forum-post-text" placeholder="Share your thoughts... Markdown supported. Use @ to mention someone." oninput="_forumMentionInput(this)"></textarea>
              <div id="forum-mention-popup" class="forum-mention-popup" style="display:none;"></div>
              <div class="forum-reply-compose-actions">
                <input id="forum-post-image-upload" type="file" accept="image/*,video/*" multiple style="display:none;" onchange="_forumPostAttachmentsAdd(event)">
                <button class="forum-img-btn" onclick="document.getElementById('forum-post-image-upload').click()"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;margin-right:4px;"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg> Add Media</button>
                <button class="forum-img-btn" onclick="toggleEmojiPicker('forum-post-text')" title="Add emoji"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;margin-right:4px;"><circle cx="12" cy="12" r="10"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg>Emoji</button>
                ${_forumCanStaffRespond(thread, posts) ? `<button class="forum-img-btn forum-staff-toggle" onclick="_forumToggleStaffResponseMode(this)" title="Post as Staff Response (attaches to the original post)"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;margin-right:4px;"><path d="M12 2L3 6v6c0 5.5 3.8 10.7 9 12 5.2-1.3 9-6.5 9-12V6z"/></svg>Staff Response</button>` : ''}
                <span class="forum-file-label" id="forum-post-file-label">No attachment selected</span>
                <button class="forum-submit-btn" data-forum-submit onclick="_forumStaffResponseMode ? _forumSubmitStaffResponse('${threadId}') : _forumCreatePost('${threadId}')">Post Reply</button>
              </div>
              <div id="forum-post-image-preview" style="margin-top:10px;"></div>
            </div>
          </div>
        </div>
      </div>
    `;
    _forumHydratePfps(content);
    _forumPostAttachments = [];
    _forumPostImageData = null;
    _forumStaffResponseMode = false;
    _forumRenderPostAttachmentsEdit();
  } catch(e) {
    console.error('[Forum] View thread failed:', e);
    content.innerHTML = '<div class="forum-empty"><p style="color:var(--red);">Failed to load thread</p></div>';
  }
}

// ── Forum: post card renderer, vote helpers, permissions ──
let _forumCurrentPosts = [];
let _forumPendingQuote = null;
let _forumViewedThreads = null; // tracks which thread had its view already incremented this session
let _forumStaffResponseMode = false; // admin/superadmin toggle for Bugs category only

function _forumCanStaffRespond(thread, posts) {
  // Staff responses apply to Bugs & Troubleshooting and Suggestions —
  // categories where an official reply needs to be visible at the top.
  // Once one exists, the compose toggle hides so a new one can't be posted —
  // the author edits via the Edit button, superadmins delete to free the slot.
  if (!thread) return false;
  const allowed = thread.category === 'bugs' || thread.category === 'suggestions';
  if (!allowed) return false;
  if (!isAdmin() && !isSuperAdmin()) return false;
  const { staff } = _forumExtractStaffResponse(posts);
  return !staff;
}

function _forumToggleStaffResponseMode(btn) {
  _forumStaffResponseMode = !_forumStaffResponseMode;
  if (btn) btn.classList.toggle('active', _forumStaffResponseMode);
  const submitBtn = document.querySelector('.forum-submit-btn[data-forum-submit]');
  if (submitBtn) submitBtn.textContent = _forumStaffResponseMode ? 'Post Staff Response' : 'Post Reply';
  const compose = document.querySelector('.forum-reply-compose');
  if (compose) compose.classList.toggle('forum-reply-compose--staff', _forumStaffResponseMode);
}

const _FORUM_STAFF_MARKER = '[FTZ_STAFF_RESPONSE]';

async function _forumSubmitStaffResponse(threadId) {
  const text = document.getElementById('forum-post-text')?.value?.trim();
  if (!text) { toast('Write something first', 'error'); return; }
  const atts = Array.isArray(_forumPostAttachments) ? _forumPostAttachments.slice() : [];
  const firstImage = atts.find(a => a.type === 'image' || a.type === 'gif');

  // Saved as a regular forum_post with a marker on the first line so we can
  // pluck it back out on render. The Supabase schema doesn't have a dedicated
  // column for staff responses and the update-retry loop silently drops unknown
  // fields, which is why the previous thread-level approach never persisted.
  try {
    // Wipe any prior staff response for this thread so there's only ever one.
    const existing = await FortizedSocial.getForumPosts(threadId);
    const prior = (existing || []).find(p => typeof p.content === 'string' && p.content.startsWith(_FORUM_STAFF_MARKER));
    if (prior) {
      try { await FortizedSocial.deleteForumPost(prior.id); } catch (_) {}
    }

    const post = {
      id: 'staff_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
      thread_id: threadId,
      author: CU.username,
      author_displayName: CU.displayName || CU.username,
      author_pfp: CU.pfp || null,
      content: _FORUM_STAFF_MARKER + '\n' + text,
      image: (firstImage ? firstImage.url : null) || null,
      attachments: atts,
      created_at: Date.now(),
      edited_at: null,
      likes: [],
      dislikes: [],
    };
    await FortizedSocial.createForumPost(post);

    document.getElementById('forum-post-text').value = '';
    _forumPostAttachments = [];
    _forumStaffResponseMode = false;
    const prev = document.getElementById('forum-post-image-preview'); if (prev) prev.innerHTML = '';
    toast('Staff response posted — visible at the top of the thread.', 'success');
    await _forumViewThread(threadId, { skipViewInc: true });
  } catch (e) {
    console.error('[Forum] Staff response save failed:', e);
    toast('Staff response failed: ' + (e?.message || 'unknown error'), 'error');
  }
}

function _forumExtractStaffResponse(posts) {
  // Returns the staff-response post + the rest of the replies, so the reply
  // list doesn't duplicate what's shown in the pinned card.
  if (!Array.isArray(posts)) return { staff: null, rest: [] };
  let staff = null;
  const rest = [];
  posts.forEach(p => {
    if (!staff && typeof p.content === 'string' && p.content.startsWith(_FORUM_STAFF_MARKER)) staff = p;
    else rest.push(p);
  });
  return { staff, rest };
}

function _forumRenderStaffResponseCard(thread, staffPost) {
  if (!staffPost) return '';
  const body = (staffPost.content || '').slice(_FORUM_STAFF_MARKER.length).replace(/^\n/, '');
  const pfpFallback = _defaultPfpUrl(staffPost.author || '');
  const role = (getStaffRole(staffPost.author) || '').toLowerCase();
  const roleLabel = role === 'superadmin' ? 'Superadmin' : role === 'admin' ? 'Admin' : role === 'moderator' ? 'Moderator' : 'Staff';
  const atts = Array.isArray(staffPost.attachments) && staffPost.attachments.length
    ? `<div class="forum-att-grid">${_forumRenderAttachmentsHTML(staffPost.attachments, { compact: true })}</div>` : '';
  const img = staffPost.image && !atts ? `<img src="${escapeHTML(staffPost.image)}" style="max-width:100%;max-height:300px;border-radius:10px;margin-top:8px;">` : '';
  const isAuthor = CU?.username === staffPost.author;
  const canDel = isSuperAdmin();
  const canEdit = isAuthor || isSuperAdmin();
  const safeId = escapeHTML(staffPost.id).replace(/'/g, "\\'");
  const safeThread = escapeHTML(thread.id).replace(/'/g, "\\'");
  return `
    <div class="forum-staff-card" id="staff-response-${escapeHTML(staffPost.id)}" data-staff-id="${escapeHTML(staffPost.id)}">
      <div class="forum-staff-ribbon">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2L3 6v6c0 5.5 3.8 10.7 9 12 5.2-1.3 9-6.5 9-12V6z"/><path d="M9 12l2 2 4-4"/></svg>
        Official Staff Response
      </div>
      <div class="forum-staff-body">
        <img class="forum-staff-avatar" data-forum-author="${escapeHTML(staffPost.author||'')}" src="${escapeHTML(staffPost.author_pfp || pfpFallback)}" onerror="this.src='${pfpFallback}'">
        <div class="forum-staff-content">
          <div class="forum-staff-head">
            <strong>${escapeHTML(staffPost.author_displayName || staffPost.author)}</strong>
            <span class="forum-staff-handle">@${escapeHTML(staffPost.author || '')}</span>
            <span class="forum-staff-role forum-staff-role--${escapeHTML(role)}">${escapeHTML(roleLabel)}</span>
            <span data-streak-for="${escapeHTML(staffPost.author||'')}" style="display:inline-flex;"></span>
            <span class="forum-staff-time">${_forumTimeAgo(staffPost.created_at)}</span>
            ${staffPost.edited_at ? `<span class="forum-edited" title="Edited ${new Date(staffPost.edited_at).toLocaleString()}">edited</span>` : ''}
          </div>
          <div class="forum-staff-text" data-staff-body>${_forumRenderBody(body)}</div>
          ${img}${atts}
          ${(canEdit || canDel) ? `<div class="forum-staff-actions">
            ${canEdit ? `<button class="forum-pa-btn" onclick="_forumEditStaffResponse('${safeId}')">${_svgIcon('pencil')} Edit</button>` : ''}
            ${canDel ? `<button class="forum-pa-btn danger" onclick="_forumClearStaffResponse('${safeThread}','${safeId}')">${_svgIcon('trash')} Remove</button>` : ''}
          </div>` : ''}
        </div>
      </div>
    </div>`;
}

function _forumEditStaffResponse(postId) {
  const card = document.getElementById('staff-response-' + postId);
  if (!card) return;
  const bodyEl = card.querySelector('[data-staff-body]');
  const actionsEl = card.querySelector('.forum-staff-actions');
  if (!bodyEl) return;
  // Pull the raw text out of the post (strip the marker) for the textarea.
  const allPosts = _forumCurrentPosts || [];
  const post = allPosts.find(p => p.id === postId);
  const raw = post && typeof post.content === 'string'
    ? post.content.slice(_FORUM_STAFF_MARKER.length).replace(/^\n/, '')
    : '';
  bodyEl.innerHTML = `<textarea class="forum-staff-edit-area" id="staff-edit-${escapeHTML(postId)}" maxlength="6000">${escapeHTML(raw)}</textarea>`;
  if (actionsEl) actionsEl.innerHTML = `
    <button class="forum-pa-btn" onclick="_forumSaveStaffResponseEdit('${escapeHTML(postId).replace(/'/g, "\\'")}')">Save</button>
    <button class="forum-pa-btn danger" onclick="_forumViewThread(_forumCurrentThread,{skipViewInc:true})">Cancel</button>
  `;
  bodyEl.querySelector('textarea')?.focus();
}

async function _forumSaveStaffResponseEdit(postId) {
  const ta = document.getElementById('staff-edit-' + postId);
  const newText = ta?.value?.trim();
  if (!newText) { toast('Write something first', 'error'); return; }
  try {
    await FortizedSocial.updateForumPost(postId, {
      content: _FORUM_STAFF_MARKER + '\n' + newText,
      edited_at: Date.now(),
    });
    toast('Staff response updated.', 'success');
    await _forumViewThread(_forumCurrentThread, { skipViewInc: true });
  } catch (e) {
    console.warn('[Forum] Edit staff response failed:', e);
    toast('Couldn\'t save the edit.', 'error');
  }
}

async function _forumClearStaffResponse(threadId, postId) {
  try {
    await FortizedSocial.deleteForumPost(postId);
    toast('Staff response removed.', 'success');
    await _forumViewThread(threadId, { skipViewInc: true });
  } catch (e) {
    console.warn('[Forum] Clear staff response failed:', e);
    toast('Remove failed', 'error');
  }
}

function _forumRenderPostCard(post, threadId, thread) {
  const score = _forumNetScore(post);
  const up = _forumIsUpvoted(post);
  const dn = _forumIsDownvoted(post);
  const canEdit = _forumCanEditPost(post);
  const canDel = _forumCanDeletePost(post);
  // Every reply shows a quote block. If the post has its own stored quote use
  // it; otherwise synthesize one from the thread OP so legacy replies (posted
  // before auto-quote landed) still render with context.
  let qId = post.quote_id, qAuthor = post.quote_author, qText = post.quote_text;
  if ((!qAuthor || !qText) && thread) {
    qId = thread.id;
    qAuthor = thread.author;
    qText = (thread.content || '').slice(0, 500);
  }
  const quoteBlock = (qAuthor && qText) ? `
    <div class="forum-quote-block" onclick="_forumJumpToPost('${escapeHTML(qId||'')}')">
      <div class="fqb-author">↩ @${escapeHTML(qAuthor)}</div>
      <div class="fqb-text">${_forumRenderBody((qText||'').slice(0, 280))}</div>
    </div>` : '';
  const pfpFallback = _defaultPfpUrl(post.author || '');
  const staffRole = getStaffRole(post.author);
  return `
    <div class="forum-reply-card" id="fp-${post.id}">
      <div class="forum-user-col">
        <img class="forum-reply-avatar" data-forum-author="${escapeHTML(post.author||'')}" src="${escapeHTML(post.author_pfp || pfpFallback)}" onerror="this.src='${pfpFallback}'">
        <div class="forum-user-name">${escapeHTML(post.author_displayName || post.author)}</div>
        <div class="forum-user-handle">@${escapeHTML(post.author)}</div>
        <div class="forum-user-streak" data-streak-for="${escapeHTML(post.author||'')}" style="margin-top:6px;"></div>
        ${staffRole?`<div class="forum-user-role forum-user-role--${escapeHTML(staffRole)}">${staffRole==='superadmin'?'Superadmin':staffRole==='admin'?'Admin':'Moderator'}</div>`:''}
      </div>
      <div class="forum-reply-content">
        <div class="frc-meta">
          <span class="frc-time">${_svgIcon('clock', 12)}<span>${_forumTimeAgo(post.created_at)}</span></span>
          ${post.edited_at?`<span class="forum-edited" title="Edited ${new Date(post.edited_at).toLocaleString()}">edited</span>`:''}
        </div>
        ${quoteBlock}
        <div class="frc-body" id="fp-body-${post.id}">${_forumRenderBody(post.content || '')}</div>
        ${post.image ? `<img src="${escapeHTML(post.image)}" style="max-width:100%;max-height:300px;border-radius:10px;margin-top:8px;">` : ''}
        ${Array.isArray(post.attachments) && post.attachments.length ? `<div class="forum-att-grid">${_forumRenderAttachmentsHTML(post.attachments, {compact:true})}</div>` : ''}
        <div class="forum-post-actions">
          <div class="forum-vote-group">
            <button class="forum-vote-btn up ${up?'active':''}" onclick="_forumVote('post','${post.id}',1)" title="Upvote"><span class="fvb-icon">👏</span></button>
            <div class="forum-vote-score ${score>0?'pos':score<0?'neg':''}">${score.toLocaleString()}</div>
            <button class="forum-vote-btn down ${dn?'active':''}" onclick="_forumVote('post','${post.id}',-1)" title="Downvote"><span class="fvb-icon">👎</span></button>
          </div>
          ${canEdit ? `<button class="forum-pa-btn" onclick="_forumEditPost('${post.id}')">${_svgIcon('pencil')} Edit</button>` : ''}
          ${canDel ? `<button class="forum-pa-btn danger" onclick="_forumDeletePostConfirm('${post.id}','${threadId}')">${_svgIcon('trash')} Delete</button>` : ''}
        </div>
      </div>
    </div>`;
}

// Shared inline SVG icons for forum UI (NOT emojis)
function _svgIcon(name, size=13) {
  const s = size;
  switch(name) {
    case 'pencil': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>`;
    case 'trash': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2"/></svg>`;
    case 'quote': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="currentColor" style="vertical-align:-2px;"><path d="M7 7h4v4H7c0 2 1 3 3 3v2c-4 0-6-2-6-5V7zm9 0h4v4h-4c0 2 1 3 3 3v2c-4 0-6-2-6-5V7z"/></svg>`;
    case 'pin': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><line x1="12" y1="17" x2="12" y2="22"/><path d="M5 17h14l-2-4V5a2 2 0 0 0-2-2H9a2 2 0 0 0-2 2v8l-2 4z"/></svg>`;
    case 'send': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>`;
    case 'bell': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>`;
    case 'gift': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><polyline points="20 12 20 22 4 22 4 12"/><rect x="2" y="7" width="20" height="5"/><line x1="12" y1="22" x2="12" y2="7"/><path d="M12 7H7.5a2.5 2.5 0 0 1 0-5C11 2 12 7 12 7z"/><path d="M12 7h4.5a2.5 2.5 0 0 0 0-5C13 2 12 7 12 7z"/></svg>`;
    case 'heart': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>`;
    case 'swap': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><polyline points="17 1 21 5 17 9"/><path d="M3 11V9a4 4 0 0 1 4-4h14"/><polyline points="7 23 3 19 7 15"/><path d="M21 13v2a4 4 0 0 1-4 4H3"/></svg>`;
    case 'tag': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>`;
    case 'calendar': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>`;
    case 'mic': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><line x1="12" y1="19" x2="12" y2="23"/></svg>`;
    case 'clock': return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" style="vertical-align:-2px;flex-shrink:0;"><circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="1.7"/><path d="M12 8V12L14.5 14.5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
    default: return '';
  }
}

// Cache of author -> { pfp, streak } so the forum (and other places with
// pre-rendered author HTML) can hydrate pfp and streak chips after render
// without blocking on network.
const _forumAuthorCache = new Map();
// Back-compat alias: keep the old name working for any other callers.
const _forumPfpCache = _forumAuthorCache; // retained for reference; reads .pfp
async function _forumHydratePfps(root) {
  try {
    const scope = (typeof root === 'string') ? document.querySelector(root) : (root || document);
    if (!scope) return;
    const imgs = scope.querySelectorAll('img[data-forum-author]');
    const streakHosts = scope.querySelectorAll('[data-streak-for]');
    const authors = new Set();
    imgs.forEach(i => { const a = i.getAttribute('data-forum-author'); if (a) authors.add(a); });
    streakHosts.forEach(h => { const a = h.getAttribute('data-streak-for'); if (a) authors.add(a); });
    await Promise.all([...authors].map(async a => {
      if (_forumAuthorCache.has(a)) return;
      try {
        const u = await FortizedSocial.getUserByName(a);
        _forumAuthorCache.set(a, { pfp: u?.pfp || '', streak: +u?.dailyStreak || 0 });
      } catch(_) { _forumAuthorCache.set(a, { pfp: '', streak: 0 }); }
    }));
    imgs.forEach(i => {
      const a = i.getAttribute('data-forum-author');
      const entry = _forumAuthorCache.get(a);
      if (entry?.pfp) i.src = entry.pfp;
    });
    streakHosts.forEach(h => {
      const a = h.getAttribute('data-streak-for');
      const entry = _forumAuthorCache.get(a);
      const streak = entry?.streak || 0;
      if (streak > 0 && typeof renderStreakChip === 'function') {
        h.innerHTML = renderStreakChip(streak);
      } else {
        h.innerHTML = '';
      }
    });
  } catch(e) { console.warn('[Forum] pfp hydrate failed:', e); }
}

// Staff get a visible upvote multiplier on their own posts: superadmins +10%,
// admins +5%. Computed at render time so it tracks the live `likes` array.
function _forumStaffBoost(author) {
  const role = _forumAuthorRole(author);
  if (role === 'superadmin') return 0.10;
  if (role === 'admin') return 0.05;
  return 0;
}
function _forumBoostedUpvotes(obj) {
  const ups = Array.isArray(obj.likes) ? obj.likes.length : 0;
  const boost = _forumStaffBoost(obj.author);
  if (!boost || !ups) return ups;
  // Round up so the bonus is always at least +1 when a staff post has any
  // upvotes — otherwise small counts (1-5 ups) would round to 0 and look
  // like the boost isn't applied.
  return ups + Math.max(1, Math.ceil(ups * boost));
}
// Same boost logic applied to view counts so staff posts show a visibly
// higher view number at render time without touching the stored value.
function _forumBoostedViews(obj) {
  const v = Number(obj?.views) || 0;
  const boost = _forumStaffBoost(obj?.author);
  if (!boost || !v) return v;
  return v + Math.max(1, Math.ceil(v * boost));
}
function _forumNetScore(obj) {
  const dns = Array.isArray(obj.dislikes) ? obj.dislikes.length : 0;
  return _forumBoostedUpvotes(obj) - dns;
}
function _forumIsUpvoted(obj) {
  return Array.isArray(obj.likes) && obj.likes.includes(CU?.username);
}
function _forumIsDownvoted(obj) {
  return Array.isArray(obj.dislikes) && obj.dislikes.includes(CU?.username);
}
async function _forumVote(kind, id, dir) {
  if (!CU?.username) { toast('Sign in to vote', 'error'); return; }
  const me = CU.username;
  try {
    if (kind === 'thread') {
      const t = await FortizedSocial.getForumThread(id);
      // Announcement threads can be applauded but not downvoted —
      // they're official platform updates, not community debate posts.
      // Replies to announcement threads can still be downvoted (handled
      // in the `else` branch below), per the policy.
      if (t?.category === 'announcements' && dir === -1) {
        toast("You can't downvote an announcement.", 'info');
        return;
      }
      const likes = Array.isArray(t.likes) ? t.likes.slice() : [];
      const dislikes = Array.isArray(t.dislikes) ? t.dislikes.slice() : [];
      const liSet = new Set(likes);
      const diSet = new Set(dislikes);
      if (dir === 1) {
        if (liSet.has(me)) liSet.delete(me);
        else { liSet.add(me); diSet.delete(me); }
      } else {
        if (diSet.has(me)) diSet.delete(me);
        else { diSet.add(me); liSet.delete(me); }
      }
      await FortizedSocial.updateForumThread(id, { likes: [...liSet], dislikes: [...diSet] });
    } else {
      const p = _forumCurrentPosts.find(x => x.id === id);
      if (!p) return;
      const likes = Array.isArray(p.likes) ? p.likes.slice() : [];
      const dislikes = Array.isArray(p.dislikes) ? p.dislikes.slice() : [];
      const liSet = new Set(likes);
      const diSet = new Set(dislikes);
      if (dir === 1) {
        if (liSet.has(me)) liSet.delete(me);
        else { liSet.add(me); diSet.delete(me); }
      } else {
        if (diSet.has(me)) diSet.delete(me);
        else { diSet.add(me); liSet.delete(me); }
      }
      await FortizedSocial.updateForumPost(id, { likes: [...liSet], dislikes: [...diSet] });
    }
    await _forumViewThread(_forumCurrentThread, {skipViewInc:true});
    try { if (typeof window._twemojiReparse === 'function') window._twemojiReparse(document.getElementById('forum-thread-view') || document.body); } catch(_){}
  } catch(e) {
    console.error('[Forum] Vote failed:', e);
    toast('Vote failed', 'error');
  }
}

function _forumAuthorRole(u) {
  if (!u) return 'user';
  try {
    if (typeof _roleListHas === 'function') {
      if (_roleListHas(SUPER_ADMINS, u)) return 'superadmin';
      const staff = JSON.parse(localStorage.getItem('ftz_staff') || '{}');
      if (_roleListHas(staff.admins || [], u)) return 'admin';
      if (_roleListHas(staff.moderators || [], u)) return 'moderator';
    } else {
      if (SUPER_ADMINS.includes(u)) return 'superadmin';
      const staff = JSON.parse(localStorage.getItem('ftz_staff') || '{}');
      if ((staff.admins || []).includes(u)) return 'admin';
      if ((staff.moderators || []).includes(u)) return 'moderator';
    }
  } catch(_){}
  return 'user';
}
function _forumCanEditPost(obj) {
  return CU?.username && obj.author === CU.username;
}
function _forumCanDeletePost(obj) {
  if (!CU?.username) return false;
  if (obj.author === CU.username) return true;
  if (isSuperAdmin()) return true;
  if ((isAdmin() || isModerator()) && _forumAuthorRole(obj.author) !== 'superadmin') return true;
  return false;
}
function _forumCanDeleteThread(obj) { return _forumCanDeletePost(obj); }

function _forumRenderBody(text) {
  // Render @mentions before markdown so they're styled links
  let s = escapeHTML(text || '');
  s = s.replace(/@([a-zA-Z0-9_]{2,32})/g, (m, n) => `<span class="forum-mention" onclick="viewUserProfile('${n}')">@${n}</span>`);
  return parseMD(s);
}

// Plain-text inline render for compact previews (top-reply chips, etc.): strip newlines,
// drop markdown markers, no block elements.
function _forumRenderInline(text) {
  return escapeHTML((text || '')
    .replace(/\r?\n+/g, ' ')
    .replace(/`{1,3}([^`]+)`{1,3}/g, '$1')
    .replace(/\*{1,3}([^*]+)\*{1,3}/g, '$1')
    .replace(/_{1,2}([^_]+)_{1,2}/g, '$1')
    .replace(/~~([^~]+)~~/g, '$1')
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .trim());
}

function _forumQuoteReply(postId) {
  const p = _forumCurrentPosts.find(x => x.id === postId);
  if (!p) return;
  _forumPendingQuote = { id: p.id, author: p.author, text: (p.content||'').slice(0, 500) };
  const box = document.getElementById('forum-quote-preview');
  if (box) {
    box.style.display = '';
    box.innerHTML = `<div class="forum-quote-block">
      <button class="fqb-clear" onclick="_forumClearQuote()" title="Remove quote">×</button>
      <div class="fqb-author">❝ Replying to @${escapeHTML(p.author)}</div>
      <div class="fqb-text">${_forumRenderBody(p.content.slice(0,280))}</div>
    </div>`;
  }
  const ta = document.getElementById('forum-post-text');
  if (ta) ta.focus();
}
function _forumClearQuote() {
  _forumPendingQuote = null;
  const box = document.getElementById('forum-quote-preview');
  if (box) { box.style.display = 'none'; box.innerHTML = ''; }
}

function _forumJumpToPost(pid) {
  const el = document.getElementById('fp-' + pid);
  if (el) { el.scrollIntoView({behavior:'smooth', block:'center'}); el.classList.add('frc-flash'); setTimeout(()=>el.classList.remove('frc-flash'), 1400); }
}

async function _forumEditPost(postId) {
  const p = _forumCurrentPosts.find(x => x.id === postId);
  if (!p) return;
  const bodyEl = document.getElementById('fp-body-' + postId);
  if (!bodyEl) return;
  const current = p.content || '';
  bodyEl.innerHTML = `
    <textarea id="fp-edit-${postId}" class="fp-edit-area" rows="4">${escapeHTML(current)}</textarea>
    <div class="fp-edit-actions">
      <button class="forum-pa-btn" onclick="_forumSavePostEdit('${postId}')">Save</button>
      <button class="forum-pa-btn" onclick="_forumViewThread('${_forumCurrentThread}')">Cancel</button>
    </div>`;
  document.getElementById('fp-edit-' + postId)?.focus();
}
async function _forumSavePostEdit(postId) {
  const ta = document.getElementById('fp-edit-' + postId);
  if (!ta) return;
  const newText = ta.value.trim();
  if (!newText) { toast('Cannot be empty', 'error'); return; }
  const p = _forumCurrentPosts.find(x => x.id === postId);
  const history = Array.isArray(p?.edit_history) ? p.edit_history.slice() : [];
  history.push({ content: p.content, at: Date.now() });
  try {
    await FortizedSocial.updateForumPost(postId, { content: newText, edited_at: Date.now(), edit_history: history });
    toast('Edited', 'success');
    await _forumViewThread(_forumCurrentThread, {skipViewInc:true});
  } catch(e) {
    console.error('[Forum] Edit post failed:', e);
    toast('Edit failed', 'error');
  }
}
async function _forumEditThread(threadId) {
  const t = await FortizedSocial.getForumThread(threadId);
  const bodyEl = document.getElementById('forum-op-text');
  if (!bodyEl) return;
  bodyEl.innerHTML = `
    <textarea id="ft-edit-${threadId}" class="fp-edit-area" rows="6">${escapeHTML(t.content||'')}</textarea>
    <div class="fp-edit-actions">
      <button class="forum-pa-btn" onclick="_forumSaveThreadEdit('${threadId}')">Save</button>
      <button class="forum-pa-btn" onclick="_forumViewThread('${threadId}')">Cancel</button>
    </div>`;
  document.getElementById('ft-edit-' + threadId)?.focus();
}
async function _forumSaveThreadEdit(threadId) {
  const ta = document.getElementById('ft-edit-' + threadId);
  if (!ta) return;
  const v = ta.value.trim();
  if (!v) { toast('Cannot be empty', 'error'); return; }
  try {
    const t = await FortizedSocial.getForumThread(threadId);
    const history = Array.isArray(t.edit_history) ? t.edit_history.slice() : [];
    history.push({ content: t.content, at: Date.now() });
    await FortizedSocial.updateForumThread(threadId, { content: v, edited_at: Date.now(), edit_history: history });
    toast('Edited', 'success');
    await _forumViewThread(threadId, {skipViewInc:true});
  } catch(e) {
    console.error('[Forum] Edit thread failed:', e);
    toast('Edit failed', 'error');
  }
}
function _forumDeletePostConfirm(postId, threadId) {
  showCustomConfirm('Delete this reply permanently?', async () => {
    try {
      await FortizedSocial.deleteForumPost(postId);
      toast('Reply deleted', 'success');
      await _forumViewThread(threadId, {skipViewInc:true});
    } catch(e) { toast('Delete failed', 'error'); }
  });
}
function _forumDeleteThreadConfirm(threadId) {
  showCustomConfirm('Delete this entire thread permanently?', async () => {
    try {
      await FortizedSocial.deleteForumThread(threadId);
      toast('Thread deleted', 'success');
      _forumInit();
    } catch(e) { toast('Delete failed', 'error'); }
  });
}

// Mention autocomplete in forum compose
async function _forumMentionInput(ta) {
  const popup = document.getElementById('forum-mention-popup');
  if (!popup) return;
  const val = ta.value;
  const pos = ta.selectionStart;
  const before = val.slice(0, pos);
  const m = before.match(/@([a-zA-Z0-9_]{0,32})$/);
  if (!m) { popup.style.display = 'none'; return; }
  const q = m[1].toLowerCase();
  try {
    const users = await FortizedSocial.getAllUsers();
    const names = Object.keys(users || {}).filter(u => u.toLowerCase().includes(q)).slice(0, 6);
    if (!names.length) { popup.style.display = 'none'; return; }
    popup.innerHTML = names.map(n => {
      const u = users[n];
      const f = _defaultPfpUrl(n);
      return `<div class="fmn-item" onclick="_forumMentionPick('${n}')">
        <img src="${escapeHTML(u.pfp||f)}" onerror="this.src='${f}'">
        <span><strong>${escapeHTML(u.displayName||n)}</strong> <span style="color:var(--muted);">@${escapeHTML(n)}</span></span>
      </div>`;
    }).join('');
    popup.style.display = '';
  } catch(_) { popup.style.display = 'none'; }
}
function _forumMentionPick(name) {
  const ta = document.getElementById('forum-post-text');
  if (!ta) return;
  const pos = ta.selectionStart;
  const before = ta.value.slice(0, pos);
  const after = ta.value.slice(pos);
  const replaced = before.replace(/@([a-zA-Z0-9_]{0,32})$/, '@' + name + ' ');
  ta.value = replaced + after;
  ta.focus();
  const newPos = replaced.length;
  ta.setSelectionRange(newPos, newPos);
  document.getElementById('forum-mention-popup').style.display = 'none';
}

