function getDecorationSrc(decoId) {
  const d = PROFILE_DECORATIONS.find(d=>d.id===decoId);
  return d ? d.src : null;
}
function buildDecorationOverlay(decoId, sizeClass) {
  const src = getDecorationSrc(decoId);
  if (!src) return '';
  const cls = sizeClass || 'profile-decoration-overlay';
  return `<img src="${src}" class="${cls}" alt="" draggable="false">`;
}
async function buyDecoration(decoId, price) {
  const bal = CU?.onyx||0;
  const d = PROFILE_DECORATIONS.find(d=>d.id===decoId);
  if (!d) return;
  if (bal < price) { toast('Not enough Onyx! Need '+price+' Onyx','error'); return; }
  showCustomConfirm('Buy '+d.name+' for '+price+' Onyx?', async () => {
    CU.onyx = bal - price;
    CU.ownedDecorations = [...(CU.ownedDecorations||[]), decoId];
    CU.activeDecoration = decoId;
    if (Array.isArray(CU.wishlist)) CU.wishlist = CU.wishlist.filter(id => id !== decoId);
    await saveUser(true); updateOnyxDisplay();
    distributeOnyxRevenue(price);
    toast(d.name+' unlocked and equipped!','success');
    renderAtelierTab('shop');
  });
}
async function equipDecoration(decoId) {
  CU.activeDecoration = decoId || null;
  // Mark this field as freshly user-edited so a concurrent refreshCU
  // can't silently restore the old value from a stale DB read while
  // saveUser is still in flight. The protected-merge in refreshCU
  // checks this map before overriding cosmetic fields.
  window._recentlyEditedFields = window._recentlyEditedFields || {};
  window._recentlyEditedFields.activeDecoration = Date.now();
  // Sync UI everywhere CU's avatar appears BEFORE any async work, so the
  // user sees the change instantly. Without these the only update was
  // the userbar; chat/memberlist/profile-card avatars kept the stale
  // overlay until each surface re-rendered organically.
  try { updateUserbar?.(); } catch {}
  _refreshOwnDecorationOverlays();
  // AWAIT the save. Earlier this was fire-and-forget for UI snappiness,
  // but that meant: if the user refreshed before the save returned, the
  // DB still had the old decoration and it "came back" on reload — the
  // exact bug staw reported. UI is already correct from the sync code
  // above; awaiting here only blocks the picker close briefly, not the
  // visible state.
  let saveOk = true;
  try {
    await saveUser(true);
  } catch (e) {
    saveOk = false;
    console.warn('[Deco] save failed', e?.message);
  }
  toast(
    saveOk ? (decoId ? 'Decoration equipped!' : 'Decoration removed') : 'Decoration save failed — try again',
    saveOk ? 'success' : 'error'
  );
}

// Scrub or refresh decoration overlays anywhere CU's own avatar is rendered.
// On equip: insert/update overlays that point at the new decoration src.
// On remove (CU.activeDecoration = null): strip every overlay that targets
// CU. Scoped to CU's own avatar surfaces; other users' decorations are
// untouched.
function _refreshOwnDecorationOverlays() {
  if (!CU?.username) return;
  const decoSrc = CU.activeDecoration ? (typeof getDecorationSrc === 'function' ? (getDecorationSrc(CU.activeDecoration) || '') : '') : '';
  const ownSelectors = [
    `.ml-entry[data-member="${CSS.escape(CU.username)}"]`,
    `.msg-row[data-from="${CSS.escape(CU.username)}"] .msg-av-inner`,
    '#ua-clickable',
    '.settings-profile-preview .profile-decoration-wrap',
    '#own-profile-panel',
    '#mini-profile-preview .profile-decoration-wrap',
    '.up-card .up-left-av-area .profile-decoration-wrap',
  ];
  ownSelectors.forEach(sel => {
    document.querySelectorAll(sel).forEach(host => {
      // Remove any existing decoration overlay
      host.querySelectorAll('.profile-decoration-overlay,.profile-decoration-overlay-sm,.profile-decoration-overlay-lg,.profile-decoration-overlay-ml')
        .forEach(el => el.remove());
      // If equipping a new decoration, inject the overlay
      if (decoSrc) {
        const cls = host.classList?.contains('msg-av-inner') ? 'profile-decoration-overlay-sm'
          : host.id === 'mini-profile-preview' ? 'profile-decoration-overlay'
          : 'profile-decoration-overlay';
        const img = document.createElement('img');
        img.src = decoSrc;
        img.className = cls;
        img.alt = '';
        img.draggable = false;
        host.appendChild(img);
      }
    });
  });
}

