// Enhanced NSFW gate with age verification check
function enforceAgeGate(contentEl, channelName, onAllow) {
  if (!contentEl) return;
  const tier = getAgeTier(CU?.dateOfBirth);
  if (!tier || tier === AGE_TIERS.CHILD) {
    // ABSOLUTE BLOCK for children
    contentEl.innerHTML = `
      <div class="empty-state" style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:50px;text-align:center;">
        <div style="font-size:54px;margin-bottom:16px;">🛡️</div>
        <div style="font-family:var(--font-display);font-size:20px;font-weight:800;margin-bottom:8px;">Age Restricted</div>
        <div style="font-size:13.5px;color:var(--muted-light);max-width:320px;line-height:1.6;margin-bottom:20px;">
          This channel contains content not suitable for your age group.<br>
          <strong style="color:var(--accent);">#${escapeHTML(channelName)}</strong> requires users to be 18 or older.
        </div>
        <div class="safety-banner warn" style="max-width:400px;">
          ⚠️ Your account is registered as under 18. NSFW content is permanently blocked for your safety.
        </div>
      </div>`;
    return;
  }
  if (tier === AGE_TIERS.TEEN) {
    // Show friction warning but allow after explicit confirmation
    contentEl.innerHTML = `
      <div class="empty-state" style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:50px;text-align:center;">
        <div style="font-size:54px;margin-bottom:16px;">⚠️</div>
        <div style="font-family:var(--font-display);font-size:20px;font-weight:800;margin-bottom:8px;color:var(--yellow);">Mature Content Warning</div>
        <div style="font-size:13.5px;color:var(--muted-light);max-width:340px;line-height:1.6;margin-bottom:20px;">
          <strong style="color:var(--accent);">#${escapeHTML(channelName)}</strong> may contain mature content. This channel has been flagged as 18+ by the Bastion owner.
        </div>
        <div class="safety-banner warn" style="max-width:400px;margin-bottom:18px;">
          ⚠️ You appear to be a minor (16–17). Accessing 18+ channels is logged and reviewed.
        </div>
        <div style="display:flex;gap:10px;">
          <button class="btn-a" onclick="(${onAllow})()" style="font-size:13px;">I confirm I'm 18+ and proceed</button>
          <button class="btn-g" onclick="selectChannel(0)" style="font-size:13px;">Go Back</button>
        </div>
      </div>`;
    return;
  }
  // Adult — allow but log access
  logAudit('nsfw_access', channelName, 'Adult tier access');
  onAllow();
}

// Content scan warning for suspicious uploads
function showContentWarning(reason) {
  const banner = document.createElement('div');
  banner.className = 'safety-banner warn';
  banner.style.cssText = 'position:fixed;top:58px;left:50%;transform:translateX(-50%);z-index:8000;max-width:520px;width:90%;animation:embedIn .2s cubic-bezier(.22,1,.36,1);';
  banner.innerHTML = `<strong>⚠️ Content Notice</strong> · ${escapeHTML(reason)}<button onclick="this.parentElement.remove()" style="margin-left:auto;background:none;border:none;color:inherit;cursor:pointer;font-size:16px;">×</button>`;
  banner.style.display = 'flex';
  document.body.appendChild(banner);
  setTimeout(() => banner.remove(), 5000);
}

// Message content pre-scan (keywords)
const SAFETY_BLOCKLIST = ['n-word', 'slur', 'k-word']; // placeholders — extend as needed
// Get authoritative live status for a user — prefers Socket.IO cache over stale DB
function getLiveStatus(username) {
  if (username === CU?.username) return CU.status || 'online';
  return _liveStatusCache[username] || 'offline';
}

function contentSafetyCheck(text) {
  if (!text) return null;
  // Skip safety check for messages with file attachment tokens (base64 data is naturally repetitive)
  if (/\[FTZ(?:IMG|VID|AUD|FILE|GIF|STICKER):/.test(text)) return null;
  // Check for repeated patterns (spam)
  if (/(.)\1{9,}/.test(text)) return 'Repetitive characters detected (possible spam).';
  // Check for excessive caps
  const caps = (text.match(/[A-Z]/g)||[]).length;
  if (text.length > 20 && caps/text.length > 0.7) return 'Excessive capitalization detected.';
  return null;
}


// ════════════════════════════════════════════════════
// SOCIAL FEATURE 1: FRIEND ACTIVITY
// ════════════════════════════════════════════════════
async function loadFriendActivity() {
  const feedEl = document.getElementById('activity-feed');
  if (!feedEl) return;
  const friends = CU?.friends||[];
  if (!friends.length) {
    feedEl.innerHTML = `
      <div class="activity-item" style="opacity:.6;">
        <div class="act-icon" style="border-radius:50%;">👥</div>
        <div class="act-text"><p>Add friends to see their activity here!</p></div>
        <button class="btn-a" onclick="openModal('modal-add-friend')" style="font-size:12px;padding:6px 14px;flex-shrink:0;">+ Add Friend</button>
      </div>`;
    return;
  }
  feedEl.innerHTML = '<div style="padding:20px;display:flex;justify-content:center;"><div class="pl-spinner" style="width:24px;height:24px;border-width:2px;"></div></div>';
  try {
    const _actSlice = friends.slice(0, 10);
    let _actPresence = null;
    try { _actPresence = await FortizedSocial.queryPresence(_actSlice); } catch(e) { _dbg('[Activity] presence query failed', e); }
    const statuses = await Promise.all(_actSlice.map(async f => {
      try {
        const u = await FortizedSocial.getUserByName(f);
        const _actLiveSt = _actPresence?.[f]?.status;
        const st = _actLiveSt !== undefined ? _actLiveSt : (_actPresence === null ? (u?.status || 'offline') : 'offline');
        return { username:f, displayName:u?.displayName||f, pfp:u?.pfp||null, status:st, game:u?.currentGame||null, customStatus:u?.customStatus||null };
      } catch { return { username:f, displayName:f, pfp:null, status:'offline', game:null }; }
    }));
    if (!feedEl) return;
    const online = statuses.filter(s => FtzStatus.isPresent(s.status));
    const offline = statuses.filter(s => !FtzStatus.isPresent(s.status));
    const render = (s) => {
      const col = FtzStatus.color(s.status);
      const activity = s.game ? `Playing <strong>${escapeHTML(s.game.name)}</strong>` :
        s.customStatus?.text ? `<span style="color:var(--muted-light);">${escapeHTML(s.customStatus.emoji||'')} ${escapeHTML(s.customStatus.text)}</span>` :
        `<span style="color:${col};">${FtzStatus.publicLabel(s.status)}</span>`;
      return `<div class="activity-item" onclick="openDMView('${escapeHTML(s.username)}')">
        <div class="act-icon" style="position:relative;border-radius:50%;">
          ${buildAvatarHTML(s.pfp, s.displayName, 38)}
          <span class="profile-status-dot" data-for="${escapeHTML(s.username)}" data-dot-size="12" style="position:absolute;bottom:-2px;right:-2px;width:12px;height:12px;">${FtzStatus.dotSvg(s.status, 12)}</span>
        </div>
        <div class="act-text">
          <p><strong>${escapeHTML(s.displayName)}</strong></p>
          <div class="act-time act-status-text" data-for="${escapeHTML(s.username)}">${activity}</div>
        </div>
        <button onclick="event.stopPropagation();openDMView('${escapeHTML(s.username)}')" class="act-dm-btn">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg>
          DM
        </button>
      </div>`;
    };
    feedEl.innerHTML = [...online, ...offline].map(render).join('') ||
      `<div class="activity-item" style="justify-content:center;"><div class="act-icon" style="border-radius:50%;">😴</div><div class="act-text"><p>All friends are offline right now.</p></div></div>`;
  } catch(e) {
    if (feedEl) feedEl.innerHTML = `<div class="activity-item"><div class="act-icon" style="border-radius:50%;">⚠️</div><div class="act-text"><p>Could not load friend activity.</p></div></div>`;
  }
}

