function isChannelFocusMode(b, chIdx) {
  const ch = b?.channels?.[chIdx];
  return ch?.focusMode === true;
}

function toggleChannelFocusMode(chIdx) {
  const b = CU?.bastions?.[curBastion];
  if (!b || !b.channels?.[chIdx]) return;
  b.channels[chIdx].focusMode = !b.channels[chIdx].focusMode;
  saveUser();
  if (curChannel === chIdx) selectChannel(chIdx);
  renderBastionSidebar(document.getElementById('sidebar-scroll'));
  toast(b.channels[chIdx].focusMode ? 'Focus Mode enabled' : 'Focus Mode disabled', 'success');
}

