// Mood settings handlers
function toggleMoodDisabled(val) {
  const b = CU?.bastions?.[curBastion]; if (!b) return;
  b.moodDisabled = val;
  saveUser();
  _syncBastionToGlobal(curBastion);
  renderBastionSidebar(document.getElementById('sidebar-scroll'));
  toast(val ? 'Mood disabled' : 'Mood re-enabled', 'success');
}
function toggleMoodLocked(val) {
  const b = CU?.bastions?.[curBastion]; if (!b) return;
  b.moodLocked = val;
  if (val && !b.lockedMood) b.lockedMood = 'strategic';
  saveUser();
  _syncBastionToGlobal(curBastion);
  const opts = document.getElementById('mood-lock-options');
  if (opts) opts.style.display = val ? '' : 'none';
  renderBastionSidebar(document.getElementById('sidebar-scroll'));
  toast(val ? 'Mood locked' : 'Mood unlocked', 'success');
}
function setLockedMood(key) {
  const b = CU?.bastions?.[curBastion]; if (!b) return;
  b.lockedMood = key;
  b.moodLocked = true;
  saveUser();
  _syncBastionToGlobal(curBastion);
  renderBSettingsMain('mood');
  renderBastionSidebar(document.getElementById('sidebar-scroll'));
}
function saveCustomMood() {
  const b = CU?.bastions?.[curBastion]; if (!b) return;
  const emoji = document.getElementById('custom-mood-emoji')?.value?.trim();
  const label = document.getElementById('custom-mood-label')?.value?.trim();
  if (!emoji || !label) { toast('Enter both emoji and name', 'error'); return; }
  b.customMood = {emoji, label};
  saveUser();
  _syncBastionToGlobal(curBastion);
  renderBastionSidebar(document.getElementById('sidebar-scroll'));
  toast('Custom mood saved!', 'success');
}


async function buyAppearance(themeId, cost) {
  const bal = CU?.onyx||0;
  if (bal < cost) { toast('Not enough Onyx! Need '+cost+' ⬡','error'); return; }
  const _catalogued = (typeof _getShopItemById === 'function') ? _getShopItemById(themeId) : null;
  const niceName = (_catalogued && _catalogued.name) || themeId;
  CU.onyx = bal - cost;
  CU.unlockedAppearances = [...(CU.unlockedAppearances||[]), themeId];
  // Clean the item off the wishlist if it was on there
  if (Array.isArray(CU.wishlist)) CU.wishlist = CU.wishlist.filter(id => id !== themeId);
  await saveUser(true); updateOnyxDisplay();
  distributeOnyxRevenue(cost);
  applyAppearance(themeId);
  toast(`${niceName} unlocked!`, 'success');
  renderAtelierTab('shop');
}


// ── Bundle Purchase ──
async function buyBundle(bundleId, cost) {
  const bal = CU?.onyx||0;
  if (bal < cost) { toast('Not enough Onyx! Need '+cost+' Onyx','error'); return; }
  const BUNDLES = {
    midnight_bundle: {name:'Midnight Bundle',appearances:['midnight_citadel'],decorations:['blue_glow']},
  };
  const bundle = BUNDLES[bundleId];
  if (!bundle) return;
  showCustomConfirm('Buy '+bundle.name+' for '+cost+' Onyx?', async () => {
    CU.onyx = bal - cost;
    const unlocked = CU.unlockedAppearances || [];
    bundle.appearances.forEach(a => { if (!unlocked.includes(a)) unlocked.push(a); });
    CU.unlockedAppearances = unlocked;
    if (bundle.decorations) {
      const ownedDecos = CU.ownedDecorations || [];
      bundle.decorations.forEach(d => { if (!ownedDecos.includes(d)) ownedDecos.push(d); });
      CU.ownedDecorations = ownedDecos;
    }
    await saveUser(true); updateOnyxDisplay();
    distributeOnyxRevenue(cost);
    toast('Bundle unlocked! Enjoy your new items.','success');
    renderAtelierTab('shop');
  });
}
// ── Onyx Badge Purchase & Upgrade ──
async function buyOnyxBadge() {
  const cost = 100;
  const bal = CU?.onyx||0;
  if (bal < cost) { toast('Not enough Onyx! Need '+cost+' Onyx','error'); return; }
  showCustomConfirm('Buy Onyx Badge for '+cost+' Onyx?', async () => {
    CU.onyx = bal - cost;
    CU.onyxBadge = true;
    CU.onyxBadgeSpent = cost;
    await saveUser(true); updateOnyxDisplay();
    distributeOnyxRevenue(cost);
    toast('Onyx Badge unlocked! You are now an Onyx Apprentice.','success');
    renderAtelierTab('shop');
  });
}
async function upgradeOnyxBadge(amount) {
  const bal = CU?.onyx||0;
  if (bal < amount) { toast('Not enough Onyx! Need '+amount+' Onyx','error'); return; }
  const newSpent = (CU.onyxBadgeSpent||0) + amount;
  const oldTier = _getOnyxTier(CU.onyxBadgeSpent||0);
  const newTier = _getOnyxTier(newSpent);
  showCustomConfirm('Invest '+amount+' Onyx into your badge?', async () => {
    CU.onyx = bal - amount;
    CU.onyxBadgeSpent = newSpent;
    await saveUser(true); updateOnyxDisplay();
    distributeOnyxRevenue(amount);
    if (newTier.name !== oldTier.name) {
      toast('Badge evolved! You are now '+newTier.name+'!','success');
    } else {
      toast(amount+' Onyx invested into badge. Total: '+newSpent,'success');
    }
    renderAtelierTab('shop');
  });
}

// ════════════════════════════════════════════
// MESSAGE THREADS
// ════════════════════════════════════════════
let _activeThread = null;
let _threadListener = null;
function openThread(msgId, text, from) {
  if (!curBastion && curBastion !== 0) { toast('Threads are only available in Bastion channels','info'); return; }
  const b = CU.bastions?.[curBastion]; const ch = b?.channels?.[curChannel];
  const bid = b?.globalId||b?.name; const chName = ch?.name||'general';
  if (!bid) return;
  _activeThread = { msgId, text, from, bid, chName };
  document.getElementById('thread-panel')?.remove();
  document.getElementById('thread-panel-overlay')?.remove();
  // Overlay
  const overlay = document.createElement('div');
  overlay.id = 'thread-panel-overlay';
  overlay.className = 'thread-panel-v2-overlay';
  overlay.onclick = () => _closeThread();
  document.body.appendChild(overlay);
  const panel = document.createElement('div');
  panel.className = 'thread-panel-v2';
  panel.id = 'thread-panel';
  panel.innerHTML = `
    <div class="thread-panel-header" style="padding:18px 22px 14px;border-bottom:1px solid rgba(255,255,255,.05);display:flex;align-items:center;gap:10px;flex-shrink:0;">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
      <span style="font-family:var(--font-display);font-size:17px;font-weight:800;flex:1;color:#fff;">Thread</span>
      <button onclick="_closeThread()" style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);border-radius:8px;color:rgba(255,255,255,.4);cursor:pointer;width:30px;height:30px;display:flex;align-items:center;justify-content:center;transition:all .12s;">✕</button>
    </div>
    <div class="thread-origin" style="padding:12px 18px;border-bottom:1px solid rgba(255,255,255,.04);background:rgba(255,255,255,.015);">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">
        ${buildAvatarHTML(null, from, 24)}
        <span style="font-size:12px;font-weight:700;color:rgba(255,255,255,.7);">${escapeHTML(from)}</span>
      </div>
      <div style="font-size:12.5px;color:rgba(255,255,255,.4);line-height:1.5;padding-left:32px;">${escapeHTML(text.slice(0,200))}</div>
    </div>
    <div class="thread-replies" id="thread-replies" style="flex:1;overflow-y:auto;padding:8px 14px;"></div>
    <div class="typing-indicator" id="thread-typing-bar" style="opacity:0;padding:4px 14px 2px;">
      <div class="typing-dots"><span></span><span></span><span></span></div>
      <span id="thread-typing-text"></span>
    </div>
    <div class="thread-compose" style="padding:12px 16px;border-top:1px solid rgba(255,255,255,.05);display:flex;gap:8px;align-items:flex-end;flex-shrink:0;">
      <textarea id="thread-input" placeholder="Reply to thread…" rows="1" style="flex:1;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);border-radius:10px;color:#fff;padding:8px 12px;font-family:inherit;font-size:12.5px;resize:none;min-height:36px;max-height:100px;outline:none;transition:border-color .15s;" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();_sendThreadReply();}" oninput="_broadcastThreadTyping()"></textarea>
      <button onclick="_sendThreadReply()" style="padding:8px 14px;background:var(--accent-dim);border:1px solid var(--accent-mid);border-radius:10px;color:var(--accent);font-size:12px;font-weight:700;cursor:pointer;flex-shrink:0;transition:all .12s;" onmouseover="this.style.background='var(--accent)';this.style.color='#0f1119'" onmouseout="this.style.background='var(--accent-dim)';this.style.color='var(--accent)'">Reply</button>
    </div>`;
  document.body.appendChild(panel);
  _listenThreadReplies(bid, chName, msgId);
  _listenThreadTyping(bid, chName, msgId);
}
function _closeThread() {
  _stopThreadTypingBroadcast();
  if (_threadTypingListenerOff) { try { _threadTypingListenerOff(); } catch(e) { _dbg('[Thread] typing listener cleanup failed', e); } _threadTypingListenerOff = null; }
  if (_threadListener) { _threadListener(); _threadListener = null; }
  _activeThread = null;
  _closeEl('thread-panel-overlay');
  const p = document.getElementById('thread-panel');
  if (p) { p.style.opacity='0'; p.style.transform='translate(-50%,-50%) scale(.95)'; p.style.transition='all .15s ease'; setTimeout(()=>p.remove(),150); }
}
function _listenThreadReplies(bid, chName, msgId) {
  if (_threadListener) _threadListener();
  const ref = firebase.database().ref(`threads/${bid}/${chName}/${msgId}`).orderByChild('timestamp');
  const cb = ref.on('value', snap => {
    const replies = [];
    if (snap.exists()) snap.forEach(c => { const v = c.val(); v._key = c.key; replies.push(v); });
    _renderThreadReplies(replies);
  });
  _threadListener = () => ref.off('value', cb);
}
function _renderThreadReplies(replies) {
  const container = document.getElementById('thread-replies');
  if (!container) return;
  if (!replies.length) { container.innerHTML = '<div style="text-align:center;padding:30px 16px;color:var(--muted);font-size:12px;">No replies yet. Start the conversation!</div>'; return; }
  container.innerHTML = replies.map(r => `
    <div class="thread-reply">
      <div class="tr-av">${buildAvatarHTML(null,r.from||'',28)}</div>
      <div class="tr-body">
        <div class="tr-meta"><span class="tr-name">${escapeHTML(r.from||'')}</span><span class="tr-time">${r.timestamp?new Date(r.timestamp).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):''}</span></div>
        <div class="tr-text">${parseMD(escapeHTML(r.text||''))}</div>
      </div>
    </div>`).join('');
  container.scrollTop = container.scrollHeight;
}
async function _sendThreadReply() {
  if (!_activeThread) return;
  const input = document.getElementById('thread-input');
  const text = input?.value?.trim();
  if (!text) return;
  input.value = '';
  _stopThreadTypingBroadcast();
  const { bid, chName, msgId } = _activeThread;
  const reply = { from: CU.username, text, timestamp: new Date().toISOString() };
  try {
    await firebase.database().ref(`threads/${bid}/${chName}/${msgId}`).push(reply);
    // Update thread count on the parent message
    const countRef = firebase.database().ref(`threadCounts/${bid}/${chName}/${msgId}`);
    countRef.transaction(v => (v||0)+1);
    // Update thread badge on the parent message
    const safeParent = msgId.replace(/[^a-z0-9_\-]/gi, '-');
    _loadThreadBadge(bid, chName, msgId, safeParent, _activeThread.text||'', _activeThread.from||'');
  } catch(e) { console.error('[Forum] Reply failed:', e); toast('Failed to reply. Please try again.','error'); }
}

// ── Thread typing indicator ───────────────────────
let _threadTypingTimeout = null;
let _threadIsTyping = false;
let _threadTypingListenerOff = null;

function _threadTypingPath(bid, chName, msgId) { return 'threadTyping/' + bid + '/' + chName + '/' + msgId; }

function _broadcastThreadTyping() {
  if (!CU?.username || !_activeThread) return;
  const { bid, chName, msgId } = _activeThread;
  const ref = firebase.database().ref(_threadTypingPath(bid, chName, msgId) + '/' + CU.username);
  if (!_threadIsTyping) {
    _threadIsTyping = true;
    ref.set({ ts: Date.now(), username: CU.username });
    ref.onDisconnect().remove();
  }
  clearTimeout(_threadTypingTimeout);
  _threadTypingTimeout = setTimeout(() => { _threadIsTyping = false; ref.remove().catch(() => {}); }, 2500);
}

function _stopThreadTypingBroadcast() {
  _threadIsTyping = false;
  clearTimeout(_threadTypingTimeout);
  if (CU?.username && _activeThread) {
    const { bid, chName, msgId } = _activeThread;
    firebase.database().ref(_threadTypingPath(bid, chName, msgId) + '/' + CU.username).remove().catch(() => {});
  }
}

function _listenThreadTyping(bid, chName, msgId) {
  if (_threadTypingListenerOff) { try { _threadTypingListenerOff(); } catch(e) { _dbg('[Thread] typing listener cleanup failed', e); } _threadTypingListenerOff = null; }
  const ref = firebase.database().ref(_threadTypingPath(bid, chName, msgId));
  const handler = ref.on('value', snap => {
    const data = snap.val() || {};
    const others = Object.values(data).filter(v => v && v.username && v.username !== CU.username);
    const bar = document.getElementById('thread-typing-bar');
    const txt = document.getElementById('thread-typing-text');
    if (!bar || !txt) return;
    if (others.length > 0) {
      const names = others.slice(0, 2).map(v => '<strong style="color:rgba(255,255,255,.5);">' + escapeHTML(v.username) + '</strong>');
      txt.innerHTML = names.join(', ') + (others.length === 1 ? ' is typing...' : ' are typing...');
      bar.style.opacity = '1';
    } else {
      bar.style.opacity = '0';
    }
  });
  _threadTypingListenerOff = () => ref.off('value', handler);
}

// ── Thread count badge loader ─────────────────────
function _loadThreadBadge(bid, chName, msgId, safeId, text, from) {
  firebase.database().ref(`threadCounts/${bid}/${chName}/${msgId}`).get().then(snap => {
    const count = snap.val() || 0;
    const slot = document.getElementById('thread-slot-' + safeId);
    if (!slot) return;
    if (count > 0) {
      slot.innerHTML = `<div class="msg-thread-badge" onclick="openThread('${escapeHTML(msgId)}','${escapeHTML((text||'').slice(0,100).replace(/'/g,' '))}','${escapeHTML(from)}')">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
        ${count} ${count===1?'reply':'replies'}
      </div>`;
    } else {
      slot.innerHTML = '';
    }
  }).catch(() => {});
}

// ── Channel Typing Indicator ──────────────────────
let _chTypingTimeout = null;
let _chIsTyping = false;
let _chTypingListenerOff = null;

function _chTypingPath(bid, chName) { return 'chTyping/' + bid + '/' + chName; }

function broadcastChannelTyping() {
  if (!CU?.username || curBastion === null || curChannel === null) return;
  const b = CU.bastions?.[curBastion]; const ch = b?.channels?.[curChannel];
  const bidRaw = b?.globalId || b?.name; const chRaw = ch?.name || 'general';
  if (!bidRaw) return;
  const bid = String(bidRaw).toLowerCase();
  const chName = String(chRaw).toLowerCase();
  FortizedSocial.socketEmit('typing:start', { type: 'bastion', id1: bid, id2: chName });
  if (!_chIsTyping) _chIsTyping = true;
  clearTimeout(_chTypingTimeout);
  _chTypingTimeout = setTimeout(() => { _chIsTyping = false; FortizedSocial.socketEmit('typing:stop', { type: 'bastion', id1: bid, id2: chName }); }, 2500);
}

function _stopChannelTypingBroadcast() {
  _chIsTyping = false;
  clearTimeout(_chTypingTimeout);
  if (CU?.username && curBastion !== null && curChannel !== null) {
    const b = CU.bastions?.[curBastion]; const ch = b?.channels?.[curChannel];
    const bid = b?.globalId || b?.name; const chName = ch?.name || 'general';
    if (bid) firebase.database().ref(_chTypingPath(bid, chName) + '/' + CU.username).remove().catch(() => {});
  }
}

function listenChannelTyping(_bid, _chName) {
  // No-op: bastion channel typing is socket-only (see initSocket.onTyping).
  if (_chTypingListenerOff) { try { _chTypingListenerOff(); } catch(_) {} _chTypingListenerOff = null; }
}

// ════════════════════════════════════════════
// ADVANCED SEARCH
// ════════════════════════════════════════════
let _advSearchFilter = 'all';
let _advSearchSort = 'recent'; // 'recent' | 'oldest' | 'relevant'
function openAdvancedSearch() {
  document.getElementById('adv-search-panel')?.remove();
  document.getElementById('adv-search-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'adv-search-overlay';
  overlay.id = 'adv-search-overlay';
  overlay.onclick = () => { _closeEl('adv-search-panel'); _closeEl('adv-search-overlay'); };
  document.body.appendChild(overlay);
  const panel = document.createElement('div');
  panel.className = 'adv-search-panel';
  panel.id = 'adv-search-panel';
  // Build search scope label
  let scopeLabel = 'Everywhere';
  if (curBastion !== null) { const b = CU.bastions?.[curBastion]; scopeLabel = b?.name || 'Current Bastion'; }
  else if (curDM) scopeLabel = 'DM with ' + curDM;
  panel.innerHTML = `
    <div class="adv-search-header">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
        <span class="ash-title">Deep Search</span>
        <div style="display:flex;align-items:center;gap:6px;">
          <span style="font-size:10px;color:rgba(255,255,255,.15);background:rgba(255,255,255,.04);padding:2px 8px;border-radius:6px;font-weight:600;">Ctrl+K</span>
          <button onclick="_closeEl('adv-search-panel');_closeEl('adv-search-overlay')" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:16px;width:28px;height:28px;border-radius:8px;display:flex;align-items:center;justify-content:center;transition:all .12s;" onmouseover="this.style.background='rgba(255,255,255,.06)';this.style.color='#fff'" onmouseout="this.style.background='none';this.style.color='var(--muted)'">✕</button>
        </div>
      </div>
      <input id="adv-search-input" placeholder="Search messages, members, files…" oninput="_runAdvSearch(this.value)" onkeydown="if(event.key==='Escape'){closeAdvancedSearch?.();}else if(event.key==='Enter'){event.preventDefault();_runAdvSearch(this.value);}" autofocus>
      <div style="display:flex;align-items:center;gap:8px;margin-top:8px;">
        <div style="font-size:10px;color:rgba(255,255,255,.2);">Scope:</div>
        <div style="font-size:10px;color:var(--accent);background:var(--accent-dim);border:1px solid var(--accent-mid);padding:2px 8px;border-radius:6px;font-weight:600;">${escapeHTML(scopeLabel)}</div>
        <div style="flex:1;"></div>
        <div style="display:flex;align-items:center;gap:4px;">
          <div style="font-size:10px;color:rgba(255,255,255,.2);">Sort:</div>
          <select id="adv-search-sort" onchange="_advSearchSort=this.value;_runAdvSearch(document.getElementById('adv-search-input')?.value||'')" style="background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);border-radius:6px;color:rgba(255,255,255,.6);font-size:10px;font-family:var(--font-ui);padding:2px 6px;outline:none;cursor:pointer;">
            <option value="recent" selected>Most Recent</option>
            <option value="oldest">Oldest First</option>
            <option value="relevant">Most Relevant</option>
          </select>
        </div>
      </div>
    </div>
    <div class="adv-search-filters">
      <div class="asf-chip active" onclick="_setSearchFilter('all',this)">All</div>
      <div class="asf-chip" onclick="_setSearchFilter('members',this)">Members</div>
      <div class="asf-chip" onclick="_setSearchFilter('has:image',this)">Has Image</div>
      <div class="asf-chip" onclick="_setSearchFilter('has:video',this)">Has Video</div>
      <div class="asf-chip" onclick="_setSearchFilter('has:file',this)">Has File</div>
      <div class="asf-chip" onclick="_setSearchFilter('has:link',this)">Has Link</div>
      <div class="asf-chip" onclick="_setSearchFilter('has:emoji',this)">Has Emoji</div>
      <div class="asf-chip" onclick="_setSearchFilter('recent',this)">Last 24h</div>
    </div>
    <div class="adv-search-results" id="adv-search-results">
      <div style="text-align:center;padding:40px 20px;color:var(--muted);font-size:13px;">
        <div style="font-size:24px;margin-bottom:10px;opacity:.3;">🔍</div>
        <div style="font-family:var(--font-display);font-weight:700;font-size:14px;color:rgba(255,255,255,.3);margin-bottom:4px;">Deep Search</div>
        <div style="font-size:12px;">Search messages, members, files and links across all channels</div>
        <div style="margin-top:14px;display:flex;flex-wrap:wrap;gap:6px;justify-content:center;">
          <div style="font-size:10px;color:rgba(255,255,255,.15);background:rgba(255,255,255,.03);padding:3px 10px;border-radius:6px;">from:username</div>
          <div style="font-size:10px;color:rgba(255,255,255,.15);background:rgba(255,255,255,.03);padding:3px 10px;border-radius:6px;">in:channel</div>
          <div style="font-size:10px;color:rgba(255,255,255,.15);background:rgba(255,255,255,.03);padding:3px 10px;border-radius:6px;">has:image</div>
          <div style="font-size:10px;color:rgba(255,255,255,.15);background:rgba(255,255,255,.03);padding:3px 10px;border-radius:6px;">before:date</div>
        </div>
      </div>
    </div>`;
  document.body.appendChild(panel);
  document.getElementById('adv-search-input')?.focus();
}
function _setSearchFilter(filter, chip) {
  _advSearchFilter = filter;
  document.querySelectorAll('.asf-chip').forEach(c=>c.classList.remove('active'));
  chip.classList.add('active');
  _runAdvSearch(document.getElementById('adv-search-input')?.value || '');
}
let _advSearchTimeout = null;
function _runAdvSearch(q) {
  clearTimeout(_advSearchTimeout);
  _advSearchTimeout = setTimeout(async () => {
    const results = document.getElementById('adv-search-results');
    if (!results) return;
    if (!q.trim()) { results.innerHTML = '<div style="text-align:center;padding:40px;color:var(--muted);font-size:12px;">Type to search</div>'; return; }
    results.innerHTML = '<div style="text-align:center;padding:20px;color:var(--muted);">Searching…</div>';

    // Parse advanced query operators: from:user, in:channel, before:date, after:date
    let searchQ = q;
    let filterFrom = null, filterIn = null, filterBefore = null, filterAfter = null;
    const opRegex = /(from|in|before|after):(\S+)/gi;
    let match;
    while ((match = opRegex.exec(q)) !== null) {
      const op = match[1].toLowerCase(), val = match[2];
      if (op === 'from') filterFrom = val.toLowerCase();
      else if (op === 'in') filterIn = val.toLowerCase();
      else if (op === 'before') filterBefore = new Date(val);
      else if (op === 'after') filterAfter = new Date(val);
      searchQ = searchQ.replace(match[0], '');
    }
    searchQ = searchQ.trim();

    // Member search
    if (_advSearchFilter === 'members' || _advSearchFilter === 'all') {
      const memberResults = [];
      try {
        if (curBastion !== null) {
          const b = CU.bastions?.[curBastion];
          if (b?.members) {
            for (const m of b.members) {
              if (m.toLowerCase().includes((searchQ||q).toLowerCase())) memberResults.push(m);
            }
          }
        }
        if (CU.friends) {
          for (const f of CU.friends) {
            const fn = typeof f === 'string' ? f : (f.username||f.name||'');
            if (fn && fn.toLowerCase().includes((searchQ||q).toLowerCase()) && !memberResults.includes(fn)) memberResults.push(fn);
          }
        }
      } catch(e) { _dbg('[Search] member search failed', e); }
      if (_advSearchFilter === 'members') {
        if (!memberResults.length) { results.innerHTML = '<div style="text-align:center;padding:40px;color:var(--muted);font-size:12px;">No members found</div>'; return; }
        let html = '';
        for (const uname of memberResults.slice(0, 30)) {
          let pfp = _pfpCache[uname] || null;
          let displayName = uname;
          try {
            const ud = await FortizedSocial.getUserByName(uname);
            if (ud) { pfp = ud.pfp || pfp; displayName = ud.displayName || uname; }
          } catch(e) { _dbg('[Search] user lookup failed', e); }
          html += `<div class="asr-item" onclick="showMiniProfilePreview('${escapeHTML(uname)}',this)">
            <div class="asr-av">${pfp ? `<img src="${escapeHTML(pfp)}" onerror="this.src='${_defaultPfpUrl(uname)}'">` : buildAvatarHTML(null,uname,32)}</div>
            <div class="asr-body"><div class="asr-meta"><span class="asr-from">${escapeHTML(displayName)}</span></div><div class="asr-text" style="font-size:11px;color:var(--muted);">@${escapeHTML(uname)}</div></div>
          </div>`;
        }
        results.innerHTML = html;
        return;
      }
    }

    // Message search
    const allMsgs = [];
    try {
      // Search current DM
      if (curDM) {
        const dmKey = [CU.username, curDM].sort().join('__');
        const snap = await firebase.database().ref('dms/' + dmKey).limitToLast(200).get();
        if (snap.exists()) snap.forEach(c => { const v = c.val(); v._ctx = 'dm'; v._loc = curDM; allMsgs.push(v); });
      }
      // Search ALL bastion channels in current bastion
      if (curBastion !== null) {
        const b = CU.bastions?.[curBastion];
        const bid = b?.globalId||b?.name;
        if (bid && b?.channels) {
          for (const ch of b.channels) {
            const chName = ch.name||'general';
            try {
              const snap = await firebase.database().ref(`bastionMsgs/${bid}/${chName}`).limitToLast(100).get();
              if (snap.exists()) snap.forEach(c => { const v = c.val(); v._ctx = 'ch'; v._loc = chName; allMsgs.push(v); });
            } catch(e) { _dbg('[Search] channel search failed', e); }
          }
        }
      }
      // Search other DM conversations
      if (CU.friends) {
        for (const f of CU.friends) {
          const fn = typeof f === 'string' ? f : (f.username||f.name||'');
          if (!fn || fn === curDM) continue;
          try {
            const dmKey = [CU.username, fn].sort().join('__');
            const snap = await firebase.database().ref('dms/' + dmKey).limitToLast(50).get();
            if (snap.exists()) snap.forEach(c => { const v = c.val(); v._ctx = 'dm'; v._loc = fn; allMsgs.push(v); });
          } catch(e) { _dbg('[Search] DM search failed', e); }
        }
      }
      // Search all bastions (not just current)
      if (CU?.bastions) {
        for (const [idx, b] of Object.entries(CU.bastions)) {
          if (Number(idx) === curBastion) continue;
          const bid = b?.globalId||b?.name;
          if (bid && b?.channels) {
            for (const ch of b.channels.slice(0, 5)) {
              const chName = ch.name||'general';
              try {
                const snap = await firebase.database().ref(`bastionMsgs/${bid}/${chName}`).limitToLast(30).get();
                if (snap.exists()) snap.forEach(c => { const v = c.val(); v._ctx = 'ch'; v._loc = chName; v._bastion = b.name; allMsgs.push(v); });
              } catch(e) { _dbg('[Search] bastion search failed', e); }
            }
          }
        }
      }
    } catch(e) { console.warn('[Search] message search failed', e); }
    let filtered = allMsgs.filter(m => m.text && m.from !== '__system__');
    // Apply text search
    if (searchQ) filtered = filtered.filter(m => (m.text||'').toLowerCase().includes(searchQ.toLowerCase()));
    // Apply advanced operators
    if (filterFrom) filtered = filtered.filter(m => (m.from||'').toLowerCase().includes(filterFrom));
    if (filterIn) filtered = filtered.filter(m => (m._loc||'').toLowerCase().includes(filterIn));
    if (filterBefore && !isNaN(filterBefore)) filtered = filtered.filter(m => m.timestamp && new Date(m.timestamp) < filterBefore);
    if (filterAfter && !isNaN(filterAfter)) filtered = filtered.filter(m => m.timestamp && new Date(m.timestamp) > filterAfter);
    // Apply filter chips
    if (_advSearchFilter === 'has:image') filtered = filtered.filter(m => /\.(png|jpg|jpeg|gif|webp)/i.test(m.text||''));
    else if (_advSearchFilter === 'has:video') filtered = filtered.filter(m => /\.(mp4|webm|mov|avi)/i.test(m.text||'') || /youtube\.com|youtu\.be|vimeo\.com/i.test(m.text||''));
    else if (_advSearchFilter === 'has:file') filtered = filtered.filter(m => /\.(pdf|zip|rar|doc|docx|xls|xlsx|ppt|txt|csv|json|xml)/i.test(m.text||'') || /\[FTZFILE/i.test(m.text||''));
    else if (_advSearchFilter === 'has:link') filtered = filtered.filter(m => /https?:\/\//.test(m.text||''));
    else if (_advSearchFilter === 'has:emoji') filtered = filtered.filter(m => /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F900}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]|:[a-zA-Z0-9_]+:/u.test(m.text||''));
    else if (_advSearchFilter === 'recent') { const day = Date.now() - 86400000; filtered = filtered.filter(m => m.timestamp && new Date(m.timestamp).getTime() > day); }

    // If "all" mode, prepend member results
    let memberHtml = '';
    if (_advSearchFilter === 'all') {
      const memberResults = [];
      try {
        if (curBastion !== null) {
          const b = CU.bastions?.[curBastion];
          if (b?.members) for (const m of b.members) { if (m.toLowerCase().includes((searchQ||q).toLowerCase())) memberResults.push(m); }
        }
        if (CU.friends) {
          for (const f of CU.friends) {
            const fn = typeof f === 'string' ? f : (f.username||f.name||'');
            if (fn && fn.toLowerCase().includes((searchQ||q).toLowerCase()) && !memberResults.includes(fn)) memberResults.push(fn);
          }
        }
      } catch(e) { _dbg('[Search] quick member search failed', e); }
      if (memberResults.length) {
        memberHtml = `<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.25);padding:8px 14px 4px;">Members</div>`;
        for (const uname of memberResults.slice(0, 5)) {
          memberHtml += `<div class="asr-item" onclick="showMiniProfilePreview('${escapeHTML(uname)}',this)">
            <div class="asr-av">${buildAvatarHTML(_pfpCache[uname]||null,uname,32)}</div>
            <div class="asr-body"><div class="asr-meta"><span class="asr-from">${escapeHTML(uname)}</span></div></div>
          </div>`;
        }
      }
    }

    // Sort results
    if (_advSearchSort === 'recent') filtered.sort((a,b) => new Date(b.timestamp||0) - new Date(a.timestamp||0));
    else if (_advSearchSort === 'oldest') filtered.sort((a,b) => new Date(a.timestamp||0) - new Date(b.timestamp||0));
    else if (_advSearchSort === 'relevant') {
      const sq = (searchQ||q).toLowerCase();
      filtered.sort((a,b) => {
        const at = (a.text||'').toLowerCase(), bt = (b.text||'').toLowerCase();
        const aStarts = at.startsWith(sq) ? 1 : 0, bStarts = bt.startsWith(sq) ? 1 : 0;
        if (aStarts !== bStarts) return bStarts - aStarts;
        const aCount = (at.match(new RegExp(sq.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'g'))||[]).length;
        const bCount = (bt.match(new RegExp(sq.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'g'))||[]).length;
        return bCount - aCount;
      });
    }

    if (!filtered.length && !memberHtml) { results.innerHTML = '<div style="text-align:center;padding:40px;color:var(--muted);font-size:12px;">No results found</div>'; return; }
    let msgHtml = '';
    const totalCount = filtered.length;
    if (filtered.length) {
      msgHtml = `<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.25);padding:8px 14px 4px;display:flex;align-items:center;justify-content:space-between;">
        <span>Messages</span><span style="font-weight:500;letter-spacing:0;text-transform:none;">${totalCount} result${totalCount!==1?'s':''}</span>
      </div>`;
      msgHtml += filtered.slice(0,80).map(m => {
        const hl = (searchQ||q).trim() ? (m.text||'').replace(new RegExp('('+((searchQ||q)).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi'),'<mark>$1</mark>') : escapeHTML((m.text||'').slice(0,120));
        const loc = m._ctx === 'dm' ? m._loc : (m._loc ? '# ' + m._loc : '');
        const bastionTag = m._bastion ? `<span style="font-size:9px;color:rgba(255,255,255,.15);background:rgba(255,255,255,.03);padding:1px 5px;border-radius:4px;margin-left:4px;">${escapeHTML(m._bastion)}</span>` : '';
        const timeStr = m.timestamp ? _formatSearchTime(m.timestamp) : '';
        // Extract and render media previews (images, GIFs, videos, files)
        let mediaHtml = '';
        const txt = m.text || '';
        const imgMatches = txt.match(/https?:\/\/\S+\.(png|jpg|jpeg|gif|webp|bmp|svg)(\?\S*)?/gi);
        const vidMatches = txt.match(/https?:\/\/\S+\.(mp4|webm|mov)(\?\S*)?/gi);
        const fileMatches = txt.match(/\[FTZFILE:([^\]]+)\]/gi) || txt.match(/https?:\/\/\S+\.(pdf|zip|rar|doc|docx|xls|xlsx|ppt|txt|csv|json|xml)(\?\S*)?/gi);
        if (imgMatches || vidMatches || fileMatches) {
          mediaHtml = '<div class="asr-media-preview">';
          if (imgMatches) imgMatches.slice(0,4).forEach(url => { mediaHtml += `<img src="${escapeHTML(url)}" loading="lazy" alt="Image" onerror="this.style.display='none'">`; });
          if (vidMatches) vidMatches.slice(0,2).forEach(url => { const _sv='svid-'+Math.random().toString(36).slice(2); mediaHtml += `<div style="position:relative;display:inline-block;max-width:120px;border-radius:8px;overflow:hidden;border:1px solid rgba(255,255,255,.06);"><video id="${_sv}" src="${escapeHTML(url)}" muted preload="metadata" style="max-width:120px;max-height:80px;display:block;cursor:pointer;" onclick="ftzVideoToggle('${_sv}')" ontimeupdate="ftzVideoTick('${_sv}')" onloadedmetadata="ftzVideoMeta('${_sv}')" onended="ftzVideoEnd('${_sv}')"></video><div class="ftz-vp-overlay" id="${_sv}-overlay" onclick="ftzVideoToggle('${_sv}')" style="border-radius:8px;"><div class="ftz-vp-overlay-btn" style="width:28px;height:28px;"><svg width="12" height="12" viewBox="0 0 24 24" fill="#fff"><polygon points="6 3 20 12 6 21 6 3"/></svg></div></div></div>`; });
          if (fileMatches) fileMatches.slice(0,3).forEach(f => {
            const fname = f.replace(/\[FTZFILE:|]/g,'').split('/').pop().split('?')[0] || 'File';
            mediaHtml += `<div class="asr-file-badge"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>${escapeHTML(fname.slice(0,30))}</div>`;
          });
          mediaHtml += '</div>';
        }
        return `<div class="asr-item"><div class="asr-av">${buildAvatarHTML(null,m.from||'?',32)}</div><div class="asr-body"><div class="asr-meta"><span class="asr-from">${escapeHTML(m.from||'')}</span>${loc?`<span class="asr-channel">${escapeHTML(loc)}</span>`:''}${bastionTag}<span class="asr-time">${timeStr}</span></div><div class="asr-text">${hl}</div>${mediaHtml}</div></div>`;
      }).join('');
    }
    results.innerHTML = memberHtml + msgHtml;
  }, 300);
}

function _formatSearchTime(ts) {
  const d = new Date(ts);
  const now = new Date();
  const diff = now - d;
  if (diff < 60000) return 'Just now';
  if (diff < 3600000) return Math.floor(diff/60000) + 'm ago';
  if (diff < 86400000) return Math.floor(diff/3600000) + 'h ago';
  if (diff < 604800000) return Math.floor(diff/86400000) + 'd ago';
  return d.toLocaleDateString();
}

// ════════════════════════════════════════════
// KEYBOARD SHORTCUTS (CONFIGURABLE)
// ════════════════════════════════════════════
let _kbdShortcutsActive = false;
const _defaultKeybinds = [
  {id:'search',label:'Quick Search',desc:'Open the deep search panel',keys:['Ctrl','K'],section:'Navigation',action:()=>openAdvancedSearch()},
  {id:'shortcuts',label:'Shortcut List',desc:'Show keyboard shortcuts overlay',keys:['Ctrl','/'],section:'Navigation',action:()=>_showKbdShortcuts()},
  {id:'mute',label:'Toggle Mute',desc:'Mute/unmute notifications',keys:['Ctrl','Shift','M'],section:'Navigation',action:()=>toast('Notifications toggled','info')},
  {id:'nav-back',label:'Go Back',desc:'Navigate to previous page',keys:['Alt','←'],section:'Navigation',action:()=>history.back()},
  {id:'nav-forward',label:'Go Forward',desc:'Navigate to next page',keys:['Alt','→'],section:'Navigation',action:()=>history.forward()},
  {id:'nav-refresh',label:'Refresh',desc:'Reload the page',keys:['Ctrl','R'],section:'Navigation',action:()=>location.reload()},
  {id:'home',label:'Go Home',desc:'Navigate to the home view',keys:['Ctrl','H'],section:'Navigation',action:()=>showView('home')},
  {id:'dms',label:'Open DMs',desc:'Navigate to direct messages',keys:['Ctrl','D'],section:'Navigation',action:()=>showView('dms')},
  {id:'settings',label:'Open Settings',desc:'Navigate to settings',keys:['Ctrl',','],section:'Navigation',action:()=>showView('profile')},
  {id:'notifications',label:'Toggle Notifications',desc:'Open/close notification panel',keys:['Ctrl','N'],section:'Navigation',action:()=>toggleNotifPanel()},
  {id:'close',label:'Close Panels',desc:'Close open panels and overlays',keys:['Escape'],section:'General',action:()=>{
    document.getElementById('thread-panel') && _closeThread();
    if(document.getElementById('adv-search-panel')){_closeEl('adv-search-panel');_closeEl('adv-search-overlay');}
    document.getElementById('pins-panel') && _closeEl('pins-panel');
    _closeEl('pins-panel-overlay');
    _closeEl('notif-panel-v2'); _closeEl('notif-panel-v2-overlay');
    document.querySelector('.kbd-overlay')?.remove();
    document.querySelector('.soundboard-panel')?.remove();
    document.querySelector('.notif-settings-modal')?.remove();
    document.querySelector('.pw-add-widget-modal-overlay')?.remove();
    document.querySelector('.kbd-capture-overlay')?.remove();
  }},
];
function _getKeybinds() {
  try {
    const saved = JSON.parse(localStorage.getItem('ftz_keybinds') || 'null');
    if (saved && Array.isArray(saved)) {
      return _defaultKeybinds.map(def => {
        const custom = saved.find(s => s.id === def.id);
        return custom ? {...def, keys: custom.keys} : def;
      });
    }
  } catch(e) { _dbg('[Keybinds] load failed', e); }
  return _defaultKeybinds;
}
function _saveKeybinds(binds) {
  localStorage.setItem('ftz_keybinds', JSON.stringify(binds.map(b => ({id:b.id, keys:b.keys}))));
}
function _matchKeybind(e, keys) {
  const needCtrl = keys.includes('Ctrl');
  const needShift = keys.includes('Shift');
  const needAlt = keys.includes('Alt');
  const mainKey = keys.filter(k => !['Ctrl','Shift','Alt','Meta'].includes(k))[0] || '';
  if (needCtrl !== (e.ctrlKey || e.metaKey)) return false;
  if (needShift !== e.shiftKey) return false;
  if (needAlt !== e.altKey) return false;
  if (mainKey === 'Escape') return e.key === 'Escape';
  return e.key.toLowerCase() === mainKey.toLowerCase();
}
function _initKeyboardShortcuts() {
  document.addEventListener('keydown', e => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.isContentEditable) {
      // Escape still works in inputs
      if (e.key === 'Escape') {
        const closeBind = _getKeybinds().find(b => b.id === 'close');
        if (closeBind) closeBind.action();
      }
      return;
    }
    const binds = _getKeybinds();
    for (const bind of binds) {
      if (_matchKeybind(e, bind.keys)) {
        e.preventDefault();
        bind.action();
        return;
      }
    }
  });
}
function _showKbdShortcuts() {
  document.querySelector('.kbd-overlay')?.remove();
  const binds = _getKeybinds();
  const sections = {};
  binds.forEach(b => { if (!sections[b.section]) sections[b.section] = []; sections[b.section].push(b); });
  const el = document.createElement('div');
  el.className = 'kbd-overlay';
  el.onclick = e => { if (e.target === el) el.remove(); };
  let sectionsHtml = '';
  Object.entries(sections).forEach(([name, items]) => {
    sectionsHtml += `<div class="kbd-section"><h3>${escapeHTML(name)}</h3>`;
    items.forEach(b => {
      sectionsHtml += `<div class="kbd-row"><span class="kr-label">${escapeHTML(b.label)}</span><div class="kr-keys">${b.keys.map(k=>`<span class="kr-key">${escapeHTML(k)}</span>`).join('')}</div></div>`;
    });
    sectionsHtml += '</div>';
  });
  el.innerHTML = `<div class="kbd-card">
    <h2>Keyboard Shortcuts</h2>
    <div class="kbd-sub">Configurable in Settings > Keyboard Shortcuts</div>
    ${sectionsHtml}
    <div style="display:flex;gap:8px;justify-content:center;margin-top:14px;">
      <button class="btn-g" style="padding:8px 20px;font-size:12px;" onclick="this.closest('.kbd-overlay').remove()">Close</button>
      <button style="padding:8px 20px;font-size:12px;background:var(--accent-dim);border:1px solid var(--accent-mid);border-radius:8px;color:var(--accent);font-weight:700;cursor:pointer;transition:all .12s;" onclick="this.closest('.kbd-overlay').remove();showView('profile');setTimeout(()=>buildProfileView('keybinds'),100)">Customize</button>
    </div>
  </div>`;
  document.body.appendChild(el);
}

function _renderKeybindsSettings(main) {
  const binds = _getKeybinds();
  const sections = {};
  binds.forEach(b => { if (!sections[b.section]) sections[b.section] = []; sections[b.section].push(b); });
  let html = `<div style="padding:24px;">
    <div style="margin-bottom:28px;padding-bottom:20px;border-bottom:1px solid rgba(255,255,255,.05);">
      <div style="font-family:var(--font-display);font-size:20px;font-weight:800;color:#fff;">Keyboard Shortcuts</div>
      <div style="font-size:12.5px;color:rgba(255,255,255,.35);margin-top:4px;">Customize keyboard shortcuts to match your workflow. Click "Edit" to rebind any shortcut.</div>
    </div>`;
  Object.entries(sections).forEach(([name, items]) => {
    html += `<div style="margin-bottom:24px;">
      <div class="settings-section-title">${escapeHTML(name)}</div>
      <div class="kbd-settings-grid">`;
    items.forEach(b => {
      html += `<div class="kbd-setting-row">
        <div class="ksr-action">
          <div class="ksr-action-name">${escapeHTML(b.label)}</div>
          <div class="ksr-action-desc">${escapeHTML(b.desc)}</div>
        </div>
        <div class="ksr-keys">${b.keys.map(k=>`<span class="ksr-key">${escapeHTML(k)}</span>`).join('')}</div>
        <button class="ksr-edit-btn" onclick="_captureKeybind('${b.id}')">Edit</button>
      </div>`;
    });
    html += '</div></div>';
  });
  html += `<div style="display:flex;gap:8px;margin-top:20px;">
    <button class="settings-save-btn-ghost" onclick="_resetKeybinds()">Reset to Defaults</button>
  </div>
  <div style="margin-top:20px;padding:14px;background:rgba(254,248,61,.03);border:1px solid rgba(254,248,61,.08);border-radius:12px;">
    <div style="font-size:11px;color:rgba(255,255,255,.35);line-height:1.6;">
      <strong style="color:rgba(255,255,255,.5);">Tip:</strong> Press <strong>Ctrl+/</strong> anywhere to view all shortcuts quickly. Your custom bindings are saved locally in your browser.
    </div>
  </div></div>`;
  main.innerHTML = html;
}

function _captureKeybind(bindId) {
  document.querySelector('.kbd-capture-overlay')?.remove();
  const bind = _getKeybinds().find(b => b.id === bindId);
  if (!bind) return;
  const overlay = document.createElement('div');
  overlay.className = 'kbd-capture-overlay';
  overlay.innerHTML = `<div class="kbd-capture-card">
    <h3>Rebind: ${escapeHTML(bind.label)}</h3>
    <div class="kcc-desc">${escapeHTML(bind.desc)}</div>
    <div class="kcc-keys" id="kcc-keys-display">
      <span style="font-size:12px;color:rgba(255,255,255,.25);">Press your desired key combination...</span>
    </div>
    <div class="kcc-hint">Press Escape to cancel</div>
    <div class="kcc-actions">
      <button onclick="document.querySelector('.kbd-capture-overlay')?.remove()" style="padding:8px 18px;border-radius:8px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04);color:rgba(255,255,255,.5);font-size:12px;font-weight:600;cursor:pointer;">Cancel</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);
  let captured = null;
  function handleKey(e) {
    e.preventDefault();
    e.stopPropagation();
    if (e.key === 'Escape' && !e.ctrlKey && !e.shiftKey && !e.altKey) {
      document.removeEventListener('keydown', handleKey, true);
      overlay.remove();
      return;
    }
    const keys = [];
    if (e.ctrlKey || e.metaKey) keys.push('Ctrl');
    if (e.shiftKey) keys.push('Shift');
    if (e.altKey) keys.push('Alt');
    const mainKey = e.key;
    if (!['Control','Shift','Alt','Meta'].includes(mainKey)) {
      keys.push(mainKey.length === 1 ? mainKey.toUpperCase() : mainKey);
      captured = keys;
      const display = document.getElementById('kcc-keys-display');
      if (display) display.innerHTML = keys.map(k => `<span class="kcc-key">${escapeHTML(k)}</span>`).join(' + ');
      // Auto-save after brief delay
      setTimeout(() => {
        document.removeEventListener('keydown', handleKey, true);
        overlay.remove();
        _applyKeybind(bindId, captured);
      }, 400);
    }
  }
  document.addEventListener('keydown', handleKey, true);
}

function _applyKeybind(bindId, keys) {
  const binds = _getKeybinds();
  const bind = binds.find(b => b.id === bindId);
  if (!bind) return;
  bind.keys = keys;
  _saveKeybinds(binds);
  buildProfileView('keybinds');
  toast(`Shortcut for "${bind.label}" updated to ${keys.join('+')}`, 'success');
}

function _resetKeybinds() {
  localStorage.removeItem('ftz_keybinds');
  buildProfileView('keybinds');
  toast('Keyboard shortcuts reset to defaults', 'success');
}

