function _getShopItemById(id) {
  const all = [
    ...(typeof PROFILE_DECORATIONS !== 'undefined' ? PROFILE_DECORATIONS : []),
    ...(typeof SHOP_APPEARANCES_ALL !== 'undefined' ? SHOP_APPEARANCES_ALL : []),
  ];
  return all.find(i => i.id === id) || null;
}

// ── Wishlist ───────────────────────────────────────────
function isOnWishlist(itemId) {
  return Array.isArray(CU?.wishlist) && CU.wishlist.includes(itemId);
}
async function toggleWishlist(itemId) {
  if (!CU) return;
  CU.wishlist = Array.isArray(CU.wishlist) ? CU.wishlist.slice() : [];
  const i = CU.wishlist.indexOf(itemId);
  if (i >= 0) { CU.wishlist.splice(i, 1); toast('Removed from wishlist', 'info'); }
  else { CU.wishlist.push(itemId); toast('Added to wishlist', 'success'); }
  await saveUser(true);
  try { renderAtelierTab('shop'); } catch(_){}
}
async function setWishlistPrivacy(isPrivate) {
  if (!CU) return;
  CU.wishlistPrivate = !!isPrivate;
  await saveUser(true);
  toast(isPrivate ? 'Wishlist set to private' : 'Wishlist set to public', 'success');
}
async function showWishlistModal(username) {
  const isOwn = !username || username === CU?.username;
  const target = isOwn ? CU : await FortizedSocial.getUserByName(username);
  if (!target) { toast('User not found', 'error'); return; }
  const wl = Array.isArray(target.wishlist) ? target.wishlist : [];
  const priv = !!target.wishlistPrivate;
  if (!isOwn && priv) { toast('This wishlist is private', 'error'); return; }
  openSimpleModal(`
    <div class="wl-modal">
      <div class="wl-hdr">
        <h3>${isOwn ? 'Your' : escapeHTML(target.displayName||target.username)+'\'s'} Wishlist</h3>
        ${isOwn ? `<div class="wl-privacy">
          <label><input type="checkbox" ${priv?'checked':''} onchange="setWishlistPrivacy(this.checked)"> Private</label>
        </div>` : ''}
      </div>
      <div class="wl-items">
        ${wl.length ? wl.map(id => {
          const it = _getShopItemById(id);
          if (!it) return '';
          return `<div class="wl-card">
            <div class="wl-name">${escapeHTML(it.name || id)}</div>
            <div class="wl-price">${it.price || '-'} ⬡</div>
            ${!isOwn ? `<button class="wl-gift-btn" onclick="openGiftModal('${id}','${escapeHTML(target.username)}');">🎁 Gift</button>` : ''}
            ${isOwn ? `<button class="wl-rm-btn" onclick="toggleWishlist('${id}');">Remove</button>` : ''}
          </div>`;
        }).join('') : '<p style="text-align:center;color:var(--muted);padding:24px;">No items yet.</p>'}
      </div>
    </div>`);
}

// ── Gifting ────────────────────────────────────────────
async function openGiftModal(itemId, recipientHint) {
  const item = _getShopItemById(itemId);
  if (!item) { toast('Item not found', 'error'); return; }
  const friends = (CU?.friends || []).slice(0, 80);
  const bal = CU?.onyx || 0;
  const price = item.price || 0;
  openSimpleModal(`
    <div class="gift-modal">
      <h3>🎁 Gift "${escapeHTML(item.name||itemId)}"</h3>
      <div class="gift-price">${price} ⬡ · Your balance: ${bal} ⬡</div>
      <label class="gift-label">Recipient</label>
      <input id="gift-recipient" class="gift-input" placeholder="username" value="${escapeHTML(recipientHint||'')}" list="gift-friends-list">
      <datalist id="gift-friends-list">
        ${friends.map(f => `<option value="${escapeHTML(f)}">`).join('')}
      </datalist>
      <label class="gift-label">Message (optional)</label>
      <textarea id="gift-msg" class="gift-input" rows="2" maxlength="180" placeholder="Enjoy!"></textarea>
      <div class="gift-actions">
        <button class="btn-b" onclick="closeSimpleModal()">Cancel</button>
        <button class="btn-a" onclick="confirmGift('${itemId}')">Send Gift</button>
      </div>
    </div>`);
}
async function confirmGift(itemId) {
  const recInp = document.getElementById('gift-recipient');
  const msgInp = document.getElementById('gift-msg');
  const recipient = (recInp?.value || '').trim();
  const msg = (msgInp?.value || '').trim();
  if (!recipient) { toast('Pick a recipient', 'error'); return; }
  if (recipient === CU?.username) { toast('Can\'t gift to yourself', 'error'); return; }
  const item = _getShopItemById(itemId);
  if (!item) return;
  const price = item.price || 0;
  const bal = CU?.onyx || 0;
  if (bal < price) { toast('Not enough Onyx', 'error'); return; }
  try {
    const recUser = await FortizedSocial.getUserByName(recipient);
    if (!recUser) { toast('Recipient not found', 'error'); return; }
    // Deduct full price from gifter
    CU.onyx = bal - price;
    await saveUser(true); updateOnyxDisplay();
    // Grant item to recipient (appearance vs decoration)
    const field = item.kind === 'decoration' ? 'ownedDecorations' : 'unlockedAppearances';
    const owned = Array.isArray(recUser[field]) ? recUser[field].slice() : [];
    if (!owned.includes(itemId)) { owned.push(itemId); await FortizedSocial.adminUpdateUserField(recipient, field, owned); }
    // Tax distribution (no seller — shop item; gifter pays full, tax applied normally)
    await applyTax(price, { reason: 'gift', seller: null });
    // Notify recipient
    try {
      await FortizedSocial.addNotification(recipient, {
        type: 'gift',
        from: CU.username,
        text: `🎁 ${CU.displayName||CU.username} sent you ${item.name||itemId}${msg?' — "'+msg+'"':''}`,
        at: Date.now(),
        read: false,
      });
    } catch(_){}
    closeSimpleModal();
    toast('Gift sent!', 'success');
  } catch(e) {
    console.error('[Gift] failed', e);
    toast('Gift failed', 'error');
  }
}

// ── Trading (no rares, onyx-only, taxed) ──────────────
// ── Trade modal (rebuilt in gamecard design language) ──
let _tradeSelectedItems = new Set();
let _tradePartnerUser = null;

async function openTradeModal(targetUsername) {
  _tradeSelectedItems = new Set();
  _tradePartnerUser = targetUsername ? await FortizedSocial.getUserByName(targetUsername) : null;
  document.getElementById('trade-modal-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'trade-modal-overlay';
  overlay.className = 'trade-overlay';
  overlay.onclick = () => overlay.remove();
  overlay.innerHTML = _renderTradeModalHTML();
  document.body.appendChild(overlay);
  _tradeUpdateTotals();
  setTimeout(() => document.getElementById('trade-partner-input')?.focus(), 60);
}

function _renderTradeModalHTML() {
  const myPfp = CU?.pfp || _defaultPfpUrl(CU?.username || '');
  const myName = CU?.displayName || CU?.username || 'You';
  const friends = (CU?.friends || []).slice(0, 60);
  const tgt = _tradePartnerUser;
  const tradable = [
    ...((CU?.unlockedAppearances || []).map(id => ({ id, kind: 'appearance' }))),
    ...((CU?.ownedDecorations || []).map(id => ({ id, kind: 'decoration' }))),
  ]
    .map(({ id, kind }) => ({ id, kind, it: _getShopItemById(id) }))
    .filter(x => x.it && !x.it.rare && !x.it.seasonal && !x.it.event);

  const itemGrid = tradable.length
    ? tradable.map(({ id, kind, it }) => {
        const sel = _tradeSelectedItems.has(id);
        const cover = kind === 'decoration' && it.src
          ? `<img src="${escapeHTML(it.src)}">`
          : `<div class="trade-item-theme" style="background:${it.previewBg || it.gradient || 'linear-gradient(135deg,#1a1426,#0a0814)'};"></div>`;
        return `<div class="trade-item-tile${sel ? ' trade-item-tile--on' : ''}" onclick="_tradeToggleItem('${escapeHTML(id).replace(/'/g, "\\'")}')">
          ${cover}
          <div class="trade-item-meta">
            <div class="trade-item-name">${escapeHTML(it.name || id)}</div>
            <div class="trade-item-price"><img src="/Onyx.png" alt="">${it.price || 0}</div>
          </div>
          <span class="trade-item-check">${sel ? '✓' : ''}</span>
        </div>`;
      }).join('')
    : '<div class="trade-item-empty">You don\'t have any tradable items yet. Rare &amp; event items aren\'t tradable.</div>';

  return `
    <div class="trade-card" onclick="event.stopPropagation()">
      <button class="trade-close" onclick="document.getElementById('trade-modal-overlay').remove()" aria-label="Close">×</button>
      <div class="trade-hero">
        <div class="trade-hero-kicker">New Trade Offer</div>
        <div class="trade-hero-title">Swap Onyx & items with another user</div>
        <div class="trade-hero-sub">Every trade is taxed 30%. Rare and event items can't be traded — they live on the Marketplace instead.</div>
      </div>
      <div class="trade-body">
        <!-- Partner picker -->
        <div class="trade-partner-row">
          <div class="trade-partner-pfp">
            ${tgt ? `<img src="${escapeHTML(tgt.pfp || _defaultPfpUrl(tgt.username))}" onerror="this.src='${_defaultPfpUrl(tgt.username)}'">` : '<div class="trade-partner-pfp-ph">?</div>'}
          </div>
          <div class="trade-partner-meta">
            <label class="trade-field-label">Partner</label>
            <input id="trade-partner-input" class="trade-input" placeholder="Enter a username" value="${tgt ? escapeHTML(tgt.username) : ''}" list="trade-friends-list" oninput="_tradeUpdateTotals()">
            <datalist id="trade-friends-list">${friends.map(f => `<option value="${escapeHTML(f)}">`).join('')}</datalist>
          </div>
        </div>

        <div class="trade-columns">
          <!-- My offer -->
          <div class="trade-col">
            <div class="trade-col-head">
              <img class="trade-col-pfp" src="${escapeHTML(myPfp)}" onerror="this.src='${_defaultPfpUrl(CU?.username || '')}'">
              <div>
                <div class="trade-col-kicker">You send</div>
                <div class="trade-col-name">${escapeHTML(myName)}</div>
              </div>
            </div>
            <label class="trade-field-label">Onyx</label>
            <div class="trade-onyx-input">
              <img src="/Onyx.png" alt="">
              <input id="trade-my-onyx" type="number" min="0" max="${CU?.onyx || 0}" placeholder="0" oninput="_tradeUpdateTotals()">
              <span class="trade-onyx-avail">/ ${(CU?.onyx || 0).toLocaleString()}</span>
            </div>
            <label class="trade-field-label">Items <span class="trade-field-count" id="trade-my-items-count">0 selected</span></label>
            <div class="trade-item-grid">${itemGrid}</div>
          </div>

          <div class="trade-swap-pip">${_svgIcon('swap', 22)}</div>

          <!-- Their return -->
          <div class="trade-col">
            <div class="trade-col-head">
              <div class="trade-col-pfp trade-col-pfp-ph">${tgt ? `<img src="${escapeHTML(tgt.pfp || _defaultPfpUrl(tgt.username))}">` : '?'}</div>
              <div>
                <div class="trade-col-kicker">They pay</div>
                <div class="trade-col-name">${tgt ? escapeHTML(tgt.displayName || tgt.username) : 'Partner'}</div>
              </div>
            </div>
            <label class="trade-field-label">Onyx</label>
            <div class="trade-onyx-input">
              <img src="/Onyx.png" alt="">
              <input id="trade-their-onyx" type="number" min="0" placeholder="0" oninput="_tradeUpdateTotals()">
              <span class="trade-onyx-avail">paid to you</span>
            </div>
            <div class="trade-return-note">
              Partners can't be forced to send items in return — they pay the Onyx you request. Counter-offers come as a separate trade.
            </div>
          </div>
        </div>

        <!-- Summary -->
        <div class="trade-summary">
          <div class="trade-summary-row">
            <span>You receive (after 30% tax)</span>
            <strong id="trade-net-me">—</strong>
          </div>
          <div class="trade-summary-row">
            <span>Partner receives (after 30% tax)</span>
            <strong id="trade-net-them">—</strong>
          </div>
        </div>

        <div class="trade-actions">
          <button class="trade-btn trade-btn-ghost" onclick="document.getElementById('trade-modal-overlay').remove()">Cancel</button>
          <button class="trade-btn trade-btn-send" onclick="sendTradeOffer()">${_svgIcon('send', 12)} Send Offer</button>
        </div>
      </div>
    </div>`;
}

function _tradeToggleItem(id) {
  if (_tradeSelectedItems.has(id)) _tradeSelectedItems.delete(id); else _tradeSelectedItems.add(id);
  const tile = document.querySelector(`.trade-item-tile[onclick*="${id.replace(/'/g, "\\'")}"]`);
  if (tile) {
    tile.classList.toggle('trade-item-tile--on', _tradeSelectedItems.has(id));
    const check = tile.querySelector('.trade-item-check');
    if (check) check.textContent = _tradeSelectedItems.has(id) ? '✓' : '';
  }
  _tradeUpdateTotals();
}

function _tradeUpdateTotals() {
  const myO = parseInt(document.getElementById('trade-my-onyx')?.value || '0', 10) || 0;
  const thO = parseInt(document.getElementById('trade-their-onyx')?.value || '0', 10) || 0;
  // After-tax receive amounts
  const meReceives = Math.round(thO * 0.7);
  const themReceives = Math.round(myO * 0.7);
  const meEl = document.getElementById('trade-net-me');
  const themEl = document.getElementById('trade-net-them');
  if (meEl) {
    meEl.innerHTML = meReceives > 0
      ? `<img src="/Onyx.png" style="width:12px;height:12px;vertical-align:-2px;"> ${meReceives.toLocaleString()}`
      : '—';
    meEl.style.color = meReceives > 0 ? 'var(--green)' : 'var(--muted)';
  }
  if (themEl) {
    themEl.innerHTML = themReceives > 0
      ? `<img src="/Onyx.png" style="width:12px;height:12px;vertical-align:-2px;"> ${themReceives.toLocaleString()}`
      : '—';
    themEl.style.color = themReceives > 0 ? 'var(--green)' : 'var(--muted)';
  }
  const countEl = document.getElementById('trade-my-items-count');
  if (countEl) countEl.textContent = `${_tradeSelectedItems.size} selected`;
}
async function sendTradeOffer() {
  // Reads from the rebuilt trade modal: partner input, Onyx inputs, and the
  // _tradeSelectedItems Set populated by click-to-toggle tiles.
  const partner = (document.getElementById('trade-partner-input')?.value || '').trim();
  const myOnyx = parseInt(document.getElementById('trade-my-onyx')?.value || '0', 10) || 0;
  const theirOnyx = parseInt(document.getElementById('trade-their-onyx')?.value || '0', 10) || 0;
  const myItems = Array.from((typeof _tradeSelectedItems !== 'undefined' && _tradeSelectedItems) ? _tradeSelectedItems : []);

  if (!partner) { toast('Pick someone to trade with first.', 'error'); return; }
  if (partner === CU?.username) { toast("You can't trade with yourself.", 'error'); return; }
  if (myOnyx === 0 && theirOnyx === 0 && !myItems.length) {
    toast('Put something on the table first.', 'error'); return;
  }
  if ((CU?.onyx || 0) < myOnyx) { toast('Not enough Onyx for this offer.', 'error'); return; }
  for (const id of myItems) {
    const it = _getShopItemById(id);
    if (it?.rare || it?.seasonal || it?.event) { toast('Rare and event items can\'t be traded.', 'error'); return; }
  }

  // Validate the partner exists before sending — avoids silent "user not found".
  let partnerUser = null;
  try { partnerUser = await FortizedSocial.getUserByName(partner); } catch(_) {}
  if (!partnerUser) {
    toast(`We couldn't find @${partner}.`, 'error'); return;
  }

  const FIVE_H = 5 * 60 * 60 * 1000;
  const now = Date.now();
  const offer = {
    id: 'trade_' + now + '_' + Math.random().toString(36).slice(2, 6),
    from: CU.username,
    from_display: CU.displayName || CU.username,
    from_pfp: CU.pfp || null,
    to: partnerUser.username,
    myOnyx, myItems,
    theirOnyx, theirItems: [],
    status: 'pending',
    created_at: now,
    expires_at: now + FIVE_H,
  };

  try {
    await FortizedSocial.addNotification(partnerUser.username, {
      type: 'trade_offer',
      from: CU.username,
      text: `🤝 ${CU.displayName || CU.username} sent you a trade offer — expires in 5h`,
      data: offer,
      at: now,
      read: false,
    });
    document.getElementById('trade-modal-overlay')?.remove();
    toast(`Trade offer sent to @${partnerUser.username}.`, 'success');
  } catch(e) {
    console.warn('[Trade] send failed:', e);
    toast('Failed to send trade offer.', 'error');
  }
}
async function acceptTradeOffer(offer) {
  try {
    if (offer.expires_at && Date.now() > offer.expires_at) {
      toast('This trade offer expired.', 'error');
      return;
    }
    const sender = await FortizedSocial.getUserByName(offer.from);
    if (!sender) { toast('Offer sender is no longer available.', 'error'); return; }
    if ((CU?.onyx || 0) < (offer.theirOnyx || 0)) { toast('Not enough Onyx to accept.', 'error'); return; }
    if ((sender.onyx || 0) < (offer.myOnyx || 0)) { toast('Sender no longer has enough Onyx.', 'error'); return; }

    // Onyx settlement goes through applyTax — "seller" is the net-receiver.
    if (offer.myOnyx > 0) await applyTax(offer.myOnyx, { seller: CU.username, reason: 'trade' });
    if (offer.theirOnyx > 0) await applyTax(offer.theirOnyx, { seller: offer.from, reason: 'trade' });

    // Transfer items (appearances + decorations) from sender → me.
    const myItemIds = Array.isArray(offer.myItems) ? offer.myItems : [];
    const apps = new Set(sender.unlockedAppearances || []);
    const decos = new Set(sender.ownedDecorations || []);
    const myApps = new Set(CU.unlockedAppearances || []);
    const myDecos = new Set(CU.ownedDecorations || []);
    for (const id of myItemIds) {
      if (apps.has(id)) { apps.delete(id); myApps.add(id); }
      else if (decos.has(id)) { decos.delete(id); myDecos.add(id); }
    }
    await FortizedSocial.adminUpdateUserField(offer.from, 'unlockedAppearances', [...apps]);
    await FortizedSocial.adminUpdateUserField(offer.from, 'ownedDecorations', [...decos]);
    CU.unlockedAppearances = [...myApps];
    CU.ownedDecorations = [...myDecos];
    await saveUser(true);
    updateOnyxDisplay();

    // Notify the sender so they see the trade was accepted.
    try {
      await FortizedSocial.addNotification(offer.from, {
        type: 'trade_accepted',
        from: CU.username,
        text: `✅ ${CU.displayName || CU.username} accepted your trade.`,
        data: { offerId: offer.id },
        at: Date.now(),
        read: false,
      });
    } catch(_) {}
    toast('Trade accepted — items transferred.', 'success');
  } catch(e) {
    console.error('[Trade] accept failed', e);
    toast('Trade failed — changes rolled back.', 'error');
  }
}

// Formatted "Xh Ym" countdown used in the notif inbox for pending trades.
function _formatTradeCountdown(expiresAt) {
  const ms = Math.max(0, expiresAt - Date.now());
  if (ms <= 0) return 'Expired';
  const h = Math.floor(ms / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  const s = Math.floor((ms % 60000) / 1000);
  if (h > 0) return `Expires in ${h}h ${m}m`;
  if (m > 0) return `Expires in ${m}m ${s}s`;
  return `Expires in ${s}s`;
}

// Ticks every 15s to update "Expires in Xh Ym" labels across all visible
// trade notifs. No-op when no inbox is open.
if (!window._tradeCountdownTick) {
  window._tradeCountdownTick = setInterval(() => {
    document.querySelectorAll('.np-trade-countdown').forEach(el => {
      const ex = parseInt(el.getAttribute('data-expires') || '0', 10) || 0;
      if (!ex) return;
      el.textContent = _formatTradeCountdown(ex);
      if (Date.now() > ex) el.style.color = 'var(--red)';
    });
  }, 15000);
}

function _handleTradeAccept(payload) {
  try {
    const offer = JSON.parse(decodeURIComponent(payload));
    acceptTradeOffer(offer);
  } catch (e) { console.warn('[Trade] accept parse failed:', e); }
}
function _handleTradeDecline(payload) {
  try {
    const offer = JSON.parse(decodeURIComponent(payload));
    declineTradeOffer(offer);
  } catch (e) { console.warn('[Trade] decline parse failed:', e); }
}

async function declineTradeOffer(offer, opts) {
  const auto = !!(opts && opts.auto);
  try {
    await FortizedSocial.addNotification(offer.from, {
      type: 'trade_declined',
      from: CU?.username || 'system',
      text: auto
        ? `⌛ Your trade offer to @${offer.to} expired.`
        : `❌ ${CU.displayName || CU.username} declined your trade.`,
      data: { offerId: offer.id, reason: auto ? 'expired' : 'declined' },
      at: Date.now(),
      read: false,
    });
  } catch(_) {}
  toast(auto ? 'Offer expired.' : 'Offer declined.', 'info');
}

