// ═══ Discount Stacking System ═══
// Radiance: 10% | Streak (20+ days): 5% | IOTD: 35% | Max: 50% (additive)
function _getActiveDiscounts() {
  const discounts = {};
  if (CU?.radianceUntil && new Date(CU.radianceUntil) > new Date()) {
    discounts.radiance = 0.10;
  }
  if ((CU?.dailyStreak || 0) >= 20) {
    discounts.streak = 0.05;
  }
  return discounts;
}

function _calculateFinalPrice(origPrice, includeIOTD = false) {
  let totalDiscount = 0;
  const discounts = _getActiveDiscounts();
  if (discounts.radiance) totalDiscount += discounts.radiance;
  if (discounts.streak) totalDiscount += discounts.streak;
  if (includeIOTD) totalDiscount += 0.35;
  // Cap at 50%
  totalDiscount = Math.min(totalDiscount, 0.50);
  const finalPrice = Math.max(5, Math.round(origPrice * (1 - totalDiscount)));
  return {
    finalPrice,
    totalDiscount,
    radiance: discounts.radiance || 0,
    streak: discounts.streak || 0,
    breakdown: discounts
  };
}

function _formatDiscountPill(percent) {
  if (!percent) return '';
  return `<span style="display:inline-block;padding:2px 8px;background:rgba(255,249,62,.1);border:1px solid rgba(255,249,62,.2);color:#fff93e;font-size:10px;font-weight:700;border-radius:4px;margin-left:6px;">-${Math.round(percent * 100)}%</span>`;
}

function _renderItemOfTheDay(appearances, ownedAppearances) {
  const pool = [
    ...appearances.map(a => ({ kind:'appearance', item:a })),
    ...(typeof PROFILE_DECORATIONS !== 'undefined' ? PROFILE_DECORATIONS.map(d => ({ kind:'decoration', item:d })) : []),
  ];
  if (!pool.length) return '';
  const dayIndex = Math.floor(Date.now() / 86400000);
  const pick = pool[dayIndex % pool.length];
  const it = pick.item;
  const origPrice = it.price;
  const calc = _calculateFinalPrice(origPrice, true);
  const dealPrice = calc.finalPrice;
  const totalDiscountPct = Math.round(calc.totalDiscount * 100);
  const isOwned = pick.kind === 'appearance'
    ? ownedAppearances.includes(it.id)
    : (CU?.ownedDecorations || []).includes(it.id);
  const preview = pick.kind === 'decoration' && it.src
    ? `<img src="${escapeHTML(it.src)}" style="width:100%;height:100%;object-fit:contain;padding:14px;">`
    : _renderAppearancePreview(it);
  const safeId = escapeHTML(it.id).replace(/'/g, "\\'");
  // Derive a dominant brand colour for the card tint. Decorations ship
  // with .color; appearances expose their main tone via .labelColor.
  const themeHex = _iotdDominantHex(it) || '#fef83d';
  const rgb = _iotdHexToRgb(themeHex) || { r: 254, g: 248, b: 61 };
  const tintStrong = `rgba(${rgb.r},${rgb.g},${rgb.b},.18)`;
  const tintSoft = `rgba(${rgb.r},${rgb.g},${rgb.b},.06)`;
  const tintRail = `rgba(${rgb.r},${rgb.g},${rgb.b},.85)`;
  const cardStyle = `background:radial-gradient(600px 220px at 15% 0%,${tintStrong},transparent 70%),linear-gradient(180deg,${tintSoft},rgba(0,0,0,.35));`;
  const btnStyle = `background:${themeHex};color:var(--rail);`;
  const typeStyle = `color:${themeHex};`;
  return `<div class="fortshop-section fortshop-section--iotd">
    <div class="fortshop-section-head">
      <h3>Item of the Day</h3>
      <span class="fortshop-section-sub">A new deal every day. Rotates at midnight.</span>
    </div>
    <div class="iotd-card" style="${cardStyle}">
      <div class="iotd-card-rail" style="background:${tintRail};"></div>
      <div class="iotd-preview">${preview}</div>
      <div class="iotd-body">
        <div class="iotd-type" style="${typeStyle}">${pick.kind === 'appearance' ? 'APPEARANCE' : 'AVATAR DECORATION'}</div>
        <div class="iotd-name">${escapeHTML(it.name)}</div>
        ${calc.breakdown.radiance || calc.breakdown.streak ? `<div style="font-size:11px;color:rgba(255,249,62,.7);margin-bottom:8px;display:flex;gap:6px;flex-wrap:wrap;">${calc.breakdown.radiance ? '<span style="padding:1px 6px;background:rgba(255,119,228,.15);border:1px solid rgba(255,119,228,.3);border-radius:3px;">Radiance 10%</span>' : ''}${calc.breakdown.streak ? '<span style="padding:1px 6px;background:rgba(167,139,250,.15);border:1px solid rgba(167,139,250,.3);border-radius:3px;">Streak 5%</span>' : ''}<span style="padding:1px 6px;background:rgba(255,249,62,.15);border:1px solid rgba(255,249,62,.3);border-radius:3px;">IOTD 35%</span></div>` : '<div style="font-size:11px;color:rgba(255,249,62,.7);margin-bottom:8px;"><span style="padding:1px 6px;background:rgba(255,249,62,.15);border:1px solid rgba(255,249,62,.3);border-radius:3px;">IOTD 35%</span></div>'}
        <div class="iotd-price-row">
          <span class="iotd-price-orig"><img src="/Onyx.png" alt="">${origPrice}</span>
          <span class="iotd-price-now"><img src="/Onyx.png" alt="">${dealPrice}</span>
          <span class="iotd-discount">-${totalDiscountPct}%</span>
        </div>
        <div class="iotd-countdown">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
          Ends in <span id="iotd-countdown-txt">—</span>
        </div>
        ${isOwned
          ? '<button class="iotd-btn iotd-btn--owned" disabled>✓ Already Owned</button>'
          : `<button class="iotd-btn" style="${btnStyle}" onclick="${pick.kind === 'appearance' ? `buyAppearance('${safeId}',${dealPrice})` : `buyDecoration('${safeId}',${dealPrice})`}">Claim deal</button>`}
      </div>
    </div>
  </div>`;
}

// Hex → {r,g,b}. Accepts "#abc" / "#aabbcc" / "rgb(...)" / "rgba(...)".
function _iotdHexToRgb(input) {
  if (!input) return null;
  const s = String(input).trim();
  let m = s.match(/^#([0-9a-f]{3})$/i);
  if (m) {
    const h = m[1];
    return { r: parseInt(h[0] + h[0], 16), g: parseInt(h[1] + h[1], 16), b: parseInt(h[2] + h[2], 16) };
  }
  m = s.match(/^#([0-9a-f]{6})$/i);
  if (m) {
    const h = m[1];
    return { r: parseInt(h.slice(0, 2), 16), g: parseInt(h.slice(2, 4), 16), b: parseInt(h.slice(4, 6), 16) };
  }
  m = s.match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i);
  if (m) return { r: +m[1], g: +m[2], b: +m[3] };
  return null;
}

// Picks the dominant hex color for an item so the Item of the Day card can
// tint itself automatically. Decorations ship with .color already.
// Appearances expose their main tone via .labelColor.
function _iotdDominantHex(it) {
  if (!it) return null;
  if (it.color) return it.color;
  if (it.labelColor) {
    const rgb = _iotdHexToRgb(it.labelColor);
    if (rgb) return '#' + [rgb.r, rgb.g, rgb.b].map(v => v.toString(16).padStart(2, '0')).join('');
  }
  return null;
}

function _startItemOfDayCountdown() {
  if (_itemOfDayTimer) clearInterval(_itemOfDayTimer);
  const tick = () => {
    const el = document.getElementById('iotd-countdown-txt');
    if (!el) { clearInterval(_itemOfDayTimer); _itemOfDayTimer = null; return; }
    const now = new Date();
    const end = new Date(now); end.setHours(24, 0, 0, 0);
    const ms = Math.max(0, end - now);
    const h = Math.floor(ms / 3600000);
    const m = Math.floor((ms % 3600000) / 60000);
    const s = Math.floor((ms % 60000) / 1000);
    el.textContent = `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
  };
  tick();
  _itemOfDayTimer = setInterval(tick, 1000);
}

function _renderFortshopFeaturedSection(appearances, ownedAppearances) {
  const decos = (typeof PROFILE_DECORATIONS !== 'undefined' ? PROFILE_DECORATIONS : []).slice(0, 4);
  const items = [
    ...appearances.map(a => ({ kind:'appearance', item:a })),
    ...decos.map(d => ({ kind:'decoration', item:d })),
  ];
  if (!items.length) return '';
  return `<div class="fortshop-section">
    <div class="fortshop-section-head">
      <h3>Featured this week</h3>
      <span class="fortshop-section-sub">Handpicked drops curated by the Fortized team.</span>
    </div>
    <div class="fortshop-card-row">
      ${items.map(({ kind, item }) => _renderFortshopUnifiedCard(kind, item, ownedAppearances)).join('')}
    </div>
  </div>`;
}

function _renderFortshopUnifiedCard(kind, item, ownedAppearances) {
  if (!item) return '';
  const isOwned = kind === 'appearance'
    ? (ownedAppearances || []).includes(item.id)
    : (CU?.ownedDecorations || []).includes(item.id);
  const isRareOrEvent = !!(item.rare || item.seasonal || item.event || item.rarity === 'rare' || item.rarity === 'epic' || item.rarity === 'legendary');
  const rarity = item.rarity || (item.seasonal || item.event ? 'event' : isRareOrEvent ? 'rare' : 'common');
  const rarityLabel = isRareOrEvent
    ? (item.event ? 'Event' : item.seasonal ? 'Seasonal' : rarity.charAt(0).toUpperCase() + rarity.slice(1))
    : null;
  const typeLabel = kind === 'appearance' ? 'Appearance' : kind === 'decoration' ? 'Avatar Decoration' : 'Item';
  const safeId = escapeHTML(item.id).replace(/'/g, "\\'");
  const preview = kind === 'decoration' && item.src
    ? `<img src="${escapeHTML(item.src)}">`
    : _renderAppearancePreview(item);
  const buyAction = kind === 'appearance'
    ? `buyAppearance('${safeId}',${item.price})`
    : `buyDecoration('${safeId}',${item.price})`;
  return `<div class="fortshop-card${isRareOrEvent ? ` fortshop-card--${escapeHTML(rarity)}` : ''}" onclick="openShopItemModal('${safeId}','${kind}')">
    ${isRareOrEvent ? `<div class="fortshop-card-rarity" title="${escapeHTML(rarityLabel)}"></div>` : ''}
    <div class="fortshop-card-preview">${preview}</div>
    <div class="fortshop-card-body">
      <div class="fortshop-card-type">${escapeHTML(typeLabel)}${rarityLabel ? ` <span class="fsc-rarity-tag"><svg width="9" height="9" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>${escapeHTML(rarityLabel)}</span>` : ''}</div>
      <div class="fortshop-card-name">${escapeHTML(item.name)}</div>
      ${isOwned
        ? '<button class="fortshop-card-btn fortshop-card-btn--owned" onclick="event.stopPropagation();">✓ Owned</button>'
        : `<button class="fortshop-card-btn" onclick="event.stopPropagation();${buyAction}"><img src="/Onyx.png" alt="">${item.price}</button>`}
    </div>
  </div>`;
}

// Minimalistic Fortized-UI preview rendered INSIDE an appearance card/modal
// so users can actually see what the theme looks like (sidebar + main content
// + accent line + rail dots). Colours driven by the item's previewBg +
// sidebarBg + labelColor fields.
function _renderAppearancePreview(item) {
  const bg = item.previewBg || item.gradient || 'linear-gradient(170deg,#050812 0%,#0a1428 50%,#101e40 100%)';
  const sidebar = item.sidebarBg || '#080e1a';
  const accent = item.labelColor || 'rgba(255,249,62,.55)';
  return `<div class="fsc-appearance-preview" style="background:${bg};">
    <div class="fap-rail">
      <span style="background:${accent};"></span>
      <span></span>
      <span></span>
    </div>
    <div class="fap-sidebar" style="background:${sidebar};">
      <div class="fap-sb-title"></div>
      <div class="fap-sb-row fap-sb-row-active" style="background:${accent};opacity:.18;"></div>
      <div class="fap-sb-row"></div>
      <div class="fap-sb-row"></div>
      <div class="fap-sb-row"></div>
    </div>
    <div class="fap-main">
      <div class="fap-main-hdr"></div>
      <div class="fap-main-line" style="background:${accent};width:42%;"></div>
      <div class="fap-main-line" style="width:68%;"></div>
      <div class="fap-main-line" style="width:54%;"></div>
      <div class="fap-main-bubble"></div>
    </div>
  </div>`;
}

function _renderFortshopSponsoredSlot() {
  // Reuses the same banner-ad container shape as the home page, so real ads
  // from _getAllActiveAds() are broadcast the same way. The actual rotation
  // kicks off in _startFortshopAdRotation once the DOM is live.
  return `<div id="fortshop-ads" class="home-banner-ad home-banner-card"></div>`;
}

let _fortshopAdTimer = null;
async function _startFortshopAdRotation() {
  if (_fortshopAdTimer) { clearInterval(_fortshopAdTimer); _fortshopAdTimer = null; }
  async function _rotate() {
    const el = document.getElementById('fortshop-ads');
    if (!el) { clearInterval(_fortshopAdTimer); _fortshopAdTimer = null; return; }
    try {
      const allAds = await _getAllActiveAds();
      const bannerAd = _pickWeightedAd(allAds, 'banner');
      if (bannerAd) {
        el.innerHTML = _renderAdHTML(bannerAd, 'banner');
        el.onclick = () => _adClickAction(bannerAd);
      } else {
        el.innerHTML = '<div class="ad-empty ad-empty-banner">Ad</div>';
        el.onclick = null;
      }
    } catch (e) { _dbg('[Fortshop] ad rotate failed', e); }
  }
  await _rotate();
  _fortshopAdTimer = setInterval(_rotate, 75000);
}

