// ── Fortshop item-detail modal ──
// Polytoria-style big detail view with price-history embed. Item data is
// looked up via _getShopItemById (the existing helper that knows the static
// SHOP_APPEARANCES + PROFILE_DECORATIONS tables).
function openShopItemModal(itemId, kind) {
  const it = (typeof _getShopItemById === 'function') ? _getShopItemById(itemId) : null;
  if (!it) { toast('Item not found', 'error'); return; }
  document.getElementById('shop-item-modal')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'shop-item-modal';
  overlay.className = 'sim-overlay';
  overlay.onclick = () => overlay.remove();
  overlay.innerHTML = _fsRenderItemDetail(it, kind || 'appearance');
  document.body.appendChild(overlay);
  try { _fsDrawPriceHistory(it).catch(() => {}); } catch (e) { _dbg('[Fortshop] price chart', e); }
  try { _fsLoadResellers(it).catch(() => {}); } catch (e) { _dbg('[Fortshop] resellers', e); }
}

// Fetches live listings for the item + paints them into the modal's
// resellers slot. Sorts by price ascending so the lowest reseller is at
// the top — that's how buyers shop.
async function _fsLoadResellers(it) {
  const slot = document.getElementById('sim-resellers-list');
  const countEl = document.getElementById('sim-resellers-count');
  if (!slot) return;
  let listings = [];
  try {
    // Merged reader — pulls from both Supabase AND the localStorage fallback
    // so listings are visible even if the marketplace_listings table isn't
    // provisioned yet.
    listings = await _fsReadAllListings(it.id);
  } catch (e) { console.warn('[Fortshop] reseller fetch threw:', e); listings = []; }

  if (!listings.length) {
    if (countEl) countEl.textContent = '0 active';
    slot.innerHTML = `<div class="sim-resellers-empty">
      <div class="sim-resellers-empty-title">No one's reselling this yet.</div>
      <div class="sim-resellers-empty-sub">Rare items only show here after someone lists one.</div>
    </div>`;
    return;
  }

  listings.sort((a, b) => (a.price || 0) - (b.price || 0));
  if (countEl) countEl.innerHTML = `${listings.length} active · from <img src="/Onyx.png" alt="" style="width:10px;height:10px;vertical-align:-1px;object-fit:contain;margin-right:2px;">${listings[0].price.toLocaleString()}`;

  const sellerNames = [...new Set(listings.map(l => l.seller).filter(Boolean))];
  const sellerData = {};
  await Promise.all(sellerNames.map(async n => {
    try { sellerData[n] = await FortizedSocial.getUserByName(n); }
    catch (_) { sellerData[n] = null; }
  }));

  const myBal = CU?.onyx || 0;
  slot.innerHTML = listings.map((l, i) => {
    const seller = sellerData[l.seller] || {};
    const displayName = seller.displayName || l.seller || '?';
    const pfpUrl = seller.pfp || _defaultPfpUrl(l.seller || '');
    const isSelf = l.seller === CU?.username;
    const canAfford = myBal >= (l.price || 0);
    const serial = l.serial || ('#' + (i + 1));
    const ownerActions = isSelf ? `
      <button class="sim-reseller-edit" onclick="_fsEditResellListing('${escapeHTML(l.id)}','${escapeHTML(it.id)}',${l.price || 0})" title="Edit price (5 Onyx fee)">Edit</button>
      <button class="sim-reseller-buy sim-reseller-buy--self" onclick="_fsCancelResellListing('${escapeHTML(l.id)}','${escapeHTML(it.id)}')" title="Remove listing (5 Onyx fee)">Remove</button>` : '';
    return `<div class="sim-reseller-row${isSelf ? ' sim-reseller-row--self' : ''}">
      <div class="sim-reseller-pfp"><img src="${escapeHTML(pfpUrl)}" onerror="this.src='${_defaultPfpUrl(l.seller || '')}'"></div>
      <div class="sim-reseller-meta">
        <div class="sim-reseller-name">${escapeHTML(displayName)}</div>
        <div class="sim-reseller-serial">Serial ${escapeHTML(String(serial))}</div>
      </div>
      <div class="sim-reseller-price"><img src="/Onyx.png" alt="">${(l.price || 0).toLocaleString()}</div>
      ${isSelf
        ? ownerActions
        : `<button class="sim-reseller-buy${canAfford ? '' : ' sim-reseller-buy--poor'}" ${canAfford ? '' : 'disabled'} onclick="_fsBuyReseller('${escapeHTML(l.id)}','${escapeHTML(it.id)}')">${canAfford ? 'Buy' : 'Need more Onyx'}</button>`}
    </div>`;
  }).join('');
}

async function _fsBuyReseller(listingId, itemId) {
  try {
    if (typeof buyListing === 'function') await buyListing(listingId);
    const it = _getShopItemById(itemId);
    if (it) { await _fsLoadResellers(it); await _fsDrawPriceHistory(it); }
  } catch (e) {
    console.warn('[Fortshop] reseller buy failed:', e);
    toast('Purchase failed.', 'error');
  }
}

const _FORTSHOP_RESELL_FEE = 5;

async function _fsCancelResellListing(listingId, itemId) {
  if ((CU?.onyx || 0) < _FORTSHOP_RESELL_FEE) {
    toast(`You need ${_FORTSHOP_RESELL_FEE} Onyx to remove a listing.`, 'error');
    return;
  }
  try {
    // Try Supabase; fall through to localStorage for rows that only live
    // client-side (i.e., the table didn't exist when the listing was made).
    let removed = false;
    try {
      const res = await FortizedSocial.sb?.from('marketplace_listings')?.delete()?.eq('id', listingId);
      if (res && !res.error) removed = true;
    } catch(_) {}
    try {
      const local = JSON.parse(localStorage.getItem('ftz_local_marketplace_listings') || '[]');
      const next = local.filter(l => l.id !== listingId);
      if (next.length !== local.length) {
        localStorage.setItem('ftz_local_marketplace_listings', JSON.stringify(next));
        removed = true;
      }
    } catch(_) {}
    if (!removed) throw new Error('listing not found');
    CU.onyx = (CU.onyx || 0) - _FORTSHOP_RESELL_FEE;
    await saveUser(true);
    updateOnyxDisplay();
    toast(`Listing removed. -${_FORTSHOP_RESELL_FEE} Onyx.`, 'success');
    const it = _getShopItemById(itemId);
    if (it) { await _fsLoadResellers(it); await _fsDrawPriceHistory(it); }
  } catch (e) {
    console.warn('[Fortshop] cancel listing failed:', e);
    toast('Could not remove listing.', 'error');
  }
}

// Edit price on a listing you already own — opens the inline form with the
// current price prefilled. Save charges 5 Onyx and updates the listing.
function _fsEditResellListing(listingId, itemId, currentPrice) {
  const slot = document.getElementById('sim-resellers-slot');
  if (!slot) return;
  document.getElementById('sim-list-resale-form')?.remove();
  const safeListing = escapeHTML(listingId).replace(/'/g, "\\'");
  const safeItem = escapeHTML(itemId).replace(/'/g, "\\'");
  const form = document.createElement('div');
  form.id = 'sim-list-resale-form';
  form.className = 'sim-list-resale-form';
  form.innerHTML = `
    <div class="sim-list-resale-head">Edit your asking price<span class="sim-list-resale-fee">5 Onyx fee</span></div>
    <div class="sim-list-resale-row">
      <label for="sim-list-resale-price">New price</label>
      <div class="sim-list-resale-input-wrap">
        <img src="/Onyx.png" alt="">
        <input id="sim-list-resale-price" type="number" min="1" max="999999" value="${currentPrice}" autofocus>
      </div>
    </div>
    <div class="sim-list-resale-actions">
      <button class="sim-list-resale-cancel" onclick="document.getElementById('sim-list-resale-form').remove()">Cancel</button>
      <button class="sim-list-resale-submit" onclick="_fsConfirmEditResale('${safeListing}','${safeItem}')">Save</button>
    </div>`;
  slot.appendChild(form);
  form.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

async function _fsConfirmEditResale(listingId, itemId) {
  const inp = document.getElementById('sim-list-resale-price');
  const p = parseInt(inp?.value || '0', 10);
  if (!p || p < 1) { toast('Enter a valid price.', 'error'); return; }
  if ((CU?.onyx || 0) < _FORTSHOP_RESELL_FEE) {
    toast(`You need ${_FORTSHOP_RESELL_FEE} Onyx to edit a listing.`, 'error');
    return;
  }
  try {
    let updated = false;
    try {
      const res = await FortizedSocial.sb?.from('marketplace_listings')?.update({ price: p })?.eq('id', listingId);
      if (res && !res.error) updated = true;
    } catch(_) {}
    try {
      const local = JSON.parse(localStorage.getItem('ftz_local_marketplace_listings') || '[]');
      const idx = local.findIndex(l => l.id === listingId);
      if (idx >= 0) { local[idx].price = p; localStorage.setItem('ftz_local_marketplace_listings', JSON.stringify(local)); updated = true; }
    } catch(_) {}
    if (!updated) throw new Error('listing not found');
    CU.onyx = (CU.onyx || 0) - _FORTSHOP_RESELL_FEE;
    await saveUser(true);
    updateOnyxDisplay();
    document.getElementById('sim-list-resale-form')?.remove();
    toast(`Price updated. -${_FORTSHOP_RESELL_FEE} Onyx.`, 'success');
    const it = _getShopItemById(itemId);
    if (it) { await _fsLoadResellers(it); await _fsDrawPriceHistory(it); }
  } catch (e) {
    console.warn('[Fortshop] edit listing failed:', e);
    toast('Could not update listing.', 'error');
  }
}

async function _fsPromptListResale(itemId) {
  const item = _getShopItemById(itemId);
  if (!item) { toast('Item not found', 'error'); return; }
  const isRareOrEvent = !!(item.rare || item.seasonal || item.event || item.rarity === 'rare' || item.rarity === 'epic' || item.rarity === 'legendary');
  if (!isRareOrEvent) { toast('Only rare or event items can be resold.', 'error'); return; }
  if (!(CU?.unlockedAppearances || []).includes(itemId) && !(CU?.ownedDecorations || []).includes(itemId)) {
    toast("You don't own this item.", 'error'); return;
  }
  // Inline panel inside the resellers section — avoids a stacked modal that
  // would render behind .sim-overlay (z-index 9999).
  const slot = document.getElementById('sim-resellers-slot');
  if (!slot) return;
  document.getElementById('sim-list-resale-form')?.remove();
  const form = document.createElement('div');
  form.id = 'sim-list-resale-form';
  form.className = 'sim-list-resale-form';
  form.innerHTML = `
    <div class="sim-list-resale-head">List your copy for resale</div>
    <div class="sim-list-resale-row">
      <label for="sim-list-resale-price">Asking price</label>
      <div class="sim-list-resale-input-wrap">
        <img src="/Onyx.png" alt="">
        <input id="sim-list-resale-price" type="number" min="1" max="999999" value="${item.price || 100}" autofocus>
      </div>
    </div>
    <div class="sim-list-resale-actions">
      <button class="sim-list-resale-cancel" onclick="document.getElementById('sim-list-resale-form').remove()">Cancel</button>
      <button class="sim-list-resale-submit" onclick="_fsConfirmListResale('${escapeHTML(itemId).replace(/'/g, "\\'")}')">List it</button>
    </div>`;
  slot.appendChild(form);
  form.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

async function _fsConfirmListResale(itemId) {
  const inp = document.getElementById('sim-list-resale-price');
  const p = parseInt(inp?.value || '0', 10);
  if (!p || p < 1) { toast('Enter a valid price.', 'error'); return; }
  await listForResale(itemId, p);
  document.getElementById('sim-list-resale-form')?.remove();
  const item = _getShopItemById(itemId);
  if (item) { await _fsLoadResellers(item); await _fsDrawPriceHistory(item); }
}

function _fsRenderItemDetail(it, kind) {
  const isRareOrEvent = !!(it.rare || it.seasonal || it.event || it.rarity === 'rare' || it.rarity === 'epic' || it.rarity === 'legendary');
  const rarity = it.rarity || (it.seasonal || it.event ? 'event' : isRareOrEvent ? 'rare' : 'common');
  const rarityLabel = it.event ? 'Event' : it.seasonal ? 'Seasonal' : (rarity.charAt(0).toUpperCase() + rarity.slice(1));
  const typeLabel = kind === 'appearance' ? 'Appearance' : 'Avatar Decoration';
  const isOwned = kind === 'appearance'
    ? (CU?.unlockedAppearances || []).includes(it.id)
    : (CU?.ownedDecorations || []).includes(it.id);
  const seasonOpen = _isItemOnSaleInShop(it);
  const onWL = (typeof isItemOnWishlist === 'function') ? isItemOnWishlist(it.id) : false;
  const preview = kind === 'decoration' && it.src
    ? `<img src="${escapeHTML(it.src)}" alt="">`
    : _renderAppearancePreview(it);
  const safeId = escapeHTML(it.id).replace(/'/g, "\\'");
  const discCalc = _calculateFinalPrice(it.price, false);
  const finalPrice = discCalc.finalPrice;
  const priceLabel = discCalc.totalDiscount > 0
    ? `<span style="text-decoration:line-through;opacity:.5;font-size:13px;">${it.price.toLocaleString()}</span><span style="margin-left:8px;color:#fff93e;font-weight:700;">${finalPrice.toLocaleString()}</span>`
    : finalPrice.toLocaleString();
  return `
    <div class="sim-card" onclick="event.stopPropagation()">
      <button class="sim-close" onclick="document.getElementById('shop-item-modal').remove()" aria-label="Close">×</button>
      <div class="sim-hero sim-hero--${escapeHTML(rarity)}">
        ${isRareOrEvent ? `<div class="sim-hero-badge"><svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>${escapeHTML(rarityLabel)}</div>` : ''}
        <div class="sim-hero-preview">${preview}</div>
        <div class="sim-hero-meta">
          <div class="sim-hero-type">${escapeHTML(typeLabel)}</div>
          <div class="sim-hero-name">${escapeHTML(it.name)}</div>
          ${it.desc ? `<div class="sim-hero-desc">${escapeHTML(it.desc)}</div>` : ''}
        </div>
      </div>

      <div class="sim-body">
        ${isRareOrEvent ? `<div class="sim-market">
          <div class="sim-price-history">
            <div class="sim-ph-head">Price History</div>
            <div class="sim-ph-chart"><svg id="sim-ph-svg" viewBox="0 0 640 220" preserveAspectRatio="none"></svg></div>
            <div class="sim-ph-stats" id="sim-ph-stats">
              <div class="sim-ph-stat"><div class="sim-ph-stat-lbl">Sales</div><div class="sim-ph-stat-num">- -</div></div>
              <div class="sim-ph-stat"><div class="sim-ph-stat-lbl">Original Price</div><div class="sim-ph-stat-num" style="color:var(--green);"><img src="/Onyx.png" alt="">${it.price.toLocaleString()}</div></div>
              <div class="sim-ph-stat"><div class="sim-ph-stat-lbl">Average Price</div><div class="sim-ph-stat-num" style="color:var(--muted);">- -</div></div>
            </div>
            <div class="sim-ph-note">Price history appears once resellers list this item on the Marketplace.</div>
          </div>

          <div class="sim-resellers" id="sim-resellers-slot">
            <div class="sim-resellers-head">
              <span>Resellers</span>
              <span class="sim-resellers-count" id="sim-resellers-count">loading…</span>
            </div>
            <div class="sim-resellers-list" id="sim-resellers-list">
              <div class="sim-resellers-loading">Checking live listings…</div>
            </div>
            ${isOwned ? `<button class="sim-list-resell-btn" onclick="_fsPromptListResale('${safeId}')">${_svgIcon('tag', 12)} List for resale</button>` : ''}
            <div class="sim-resellers-fee">Editing or removing a listing costs 5 Onyx. Max 2 listings per item.</div>
          </div>
        </div>` : ''}

        <div class="sim-buy-panel">
          <div class="sim-buy-price">
            <div class="sim-buy-price-lbl">Price</div>
            <div class="sim-buy-price-num"><img src="/Onyx.png" alt="">${priceLabel}</div>
            ${discCalc.totalDiscount > 0 ? `<div style="font-size:11px;color:rgba(255,249,62,.7);margin-top:6px;display:flex;gap:6px;flex-wrap:wrap;">${discCalc.breakdown.radiance ? '<span style="padding:1px 6px;background:rgba(255,119,228,.15);border:1px solid rgba(255,119,228,.3);border-radius:3px;">Radiance 10%</span>' : ''}${discCalc.breakdown.streak ? '<span style="padding:1px 6px;background:rgba(167,139,250,.15);border:1px solid rgba(167,139,250,.3);border-radius:3px;">Streak 5%</span>' : ''}</div>` : ''}
          </div>
          <div class="sim-buy-actions">
            ${isOwned
              ? '<button class="sim-buy-btn sim-buy-btn--owned" disabled>✓ Owned</button>'
              : (!seasonOpen
                ? '<button class="sim-buy-btn sim-buy-btn--owned" disabled>Season ended - check resellers</button>'
                : `<button class="sim-buy-btn" id="sim-buy-btn" onclick="_fsArmPurchase('${safeId}','${escapeHTML(kind)}',${finalPrice})">Buy · <img src="/Onyx.png" alt="" style="width:13px;height:13px;vertical-align:-2px;"> ${finalPrice.toLocaleString()}</button>`)}
            ${!isOwned ? `<button class="sim-wl-btn${onWL ? ' sim-wl-btn--on' : ''}" onclick="toggleWishlist('${safeId}');_fsRefreshModalWL('${safeId}')" title="${onWL ? 'Remove from wishlist' : 'Add to wishlist'}">${_svgIcon('heart',13)} ${onWL ? 'On wishlist' : 'Wishlist'}</button>` : ''}
          </div>
        </div>
        ${!isOwned ? `<div id="sim-confirm-panel" class="sim-confirm-panel" style="display:none;">
          <label class="sim-confirm-agree">
            <input type="checkbox" id="sim-confirm-agree-box" onchange="document.getElementById('sim-confirm-buy').disabled=!this.checked">
            <span>I agree to the <a href="/legal/fortshop-policy" target="_blank" rel="noopener" style="color:var(--accent);text-decoration:underline;">Fortshop Policy</a>. Items are non-refundable once delivered.</span>
          </label>
          <div class="sim-confirm-actions">
            <button class="sim-confirm-cancel" onclick="_fsDisarmPurchase()">Cancel</button>
            <button class="sim-confirm-buy" id="sim-confirm-buy" disabled onclick="_fsCompletePurchase('${safeId}','${escapeHTML(kind)}',${finalPrice})">Confirm purchase</button>
          </div>
        </div>` : ''}
      </div>
    </div>`;
}

// Single-modal flow — "Buy" arms the inline confirmation panel (with the
// mandatory-agreement checkbox) instead of opening a separate checkout card.
function _fsArmPurchase(itemId, kind, price) {
  const panel = document.getElementById('sim-confirm-panel');
  if (!panel) return;
  panel.style.display = 'block';
  panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  const buyBtn = document.getElementById('sim-buy-btn');
  if (buyBtn) buyBtn.style.display = 'none';
  const box = document.getElementById('sim-confirm-agree-box');
  if (box) { box.checked = false; }
  const confirm = document.getElementById('sim-confirm-buy');
  if (confirm) confirm.disabled = true;
}
function _fsDisarmPurchase() {
  const panel = document.getElementById('sim-confirm-panel');
  if (panel) panel.style.display = 'none';
  const buyBtn = document.getElementById('sim-buy-btn');
  if (buyBtn) buyBtn.style.display = '';
}

function _fsRefreshModalWL(itemId) {
  const btn = document.querySelector('.sim-wl-btn');
  if (!btn) return;
  const onWL = (typeof isItemOnWishlist === 'function') ? isItemOnWishlist(itemId) : false;
  btn.classList.toggle('sim-wl-btn--on', onWL);
  btn.innerHTML = _svgIcon('heart', 13) + ' ' + (onWL ? 'On wishlist' : 'Wishlist');
  btn.title = onWL ? 'Remove from wishlist' : 'Add to wishlist';
}

// Draws a Polytoria-style price history from REAL marketplace trade data.
// Pulls completed listings for this item from the marketplace_listings table
// and buckets them per day. Renders an empty state when there's no history.
async function _fsDrawPriceHistory(it) {
  const svg = document.getElementById('sim-ph-svg');
  const statsEl = document.getElementById('sim-ph-stats');
  if (!svg) return;
  // Only rare / seasonal / event items get trade history in the first place —
  // regular stock doesn't have a Marketplace market.
  const isRareOrEvent = !!(it.rare || it.seasonal || it.event || it.rarity === 'rare' || it.rarity === 'epic' || it.rarity === 'legendary');
  if (!isRareOrEvent) return;

  let listings = [];
  try {
    const raw = await FortizedSocial.sb?.from('marketplace_listings')
      ?.select('*').eq('item_id', it.id).order('created_at', { ascending: true });
    listings = raw?.data || [];
  } catch (_) { listings = []; }

  // No real data yet — show empty state in the chart + stats.
  if (!listings.length) {
    svg.innerHTML = `<text x="320" y="110" text-anchor="middle" font-family="var(--font-ui)" font-size="13" fill="rgba(255,255,255,.35)">No trade history yet.</text>`;
    return;
  }

  // Bucket by day for volume bars.
  const dayMs = 86400000;
  const now = Date.now();
  const cutoff = now - 30 * dayMs;
  const relevant = listings.filter(l => new Date(l.created_at).getTime() >= cutoff);

  // Auto-market price model — series ALWAYS starts at the item's original
  // price. Each day the "market price" is nudged toward the median of the
  // listings active that day, weighted by how many sellers are in the pool:
  //   * fewer than 5 sellers => barely moves (5% of delta per listing)
  //   * 5+ sellers          => fully converges to the median
  // So 2 sellers at 90 and 5 sellers at 10 on a 100-Onyx item => the series
  // drops sharply toward 10 once the pool crosses 5.
  const startDayKey = Math.floor(cutoff / dayMs);
  const endDayKey = Math.floor(now / dayMs);
  const sortedKeys = [];
  for (let k = startDayKey; k <= endDayKey; k++) sortedKeys.push(k);
  const bucketsByDay = new Map(sortedKeys.map(k => [k, []]));
  const newListingsPerDay = new Map(sortedKeys.map(k => [k, 0]));
  relevant.forEach(l => {
    const t = new Date(l.created_at).getTime();
    const k = Math.floor(t / dayMs);
    if (newListingsPerDay.has(k)) newListingsPerDay.set(k, newListingsPerDay.get(k) + 1);
  });
  const median = (arr) => {
    const s = [...arr].sort((a, b) => a - b);
    const m = Math.floor(s.length / 2);
    return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
  };
  const base = it.price;
  const priceSeries = [];
  const volSeries = [];
  let marketPrice = base;
  const THRESHOLD = 5;
  sortedKeys.forEach(k => {
    // Pool = every listing whose created_at is on or before this day and
    // hasn't yet been sold (approximated by "still in the active set").
    const cutoffT = (k + 1) * dayMs;
    const pool = relevant.filter(l => new Date(l.created_at).getTime() <= cutoffT).map(l => l.price || 0);
    if (pool.length > 0) {
      const med = median(pool);
      const weight = Math.min(1, pool.length / THRESHOLD);
      const nudge = weight >= 1 ? 1 : (weight * 0.2);
      marketPrice = Math.round(marketPrice + (med - marketPrice) * nudge);
    }
    priceSeries.push(marketPrice);
    volSeries.push(newListingsPerDay.get(k) || 0);
  });

  // Totals for the stat strip.
  const totalSales = relevant.length;
  const avgPrice = Math.round(priceSeries.reduce((a, b) => a + b, 0) / priceSeries.length);
  if (statsEl) {
    statsEl.innerHTML = `
      <div class="sim-ph-stat"><div class="sim-ph-stat-lbl">Sales</div><div class="sim-ph-stat-num">${totalSales.toLocaleString()}</div></div>
      <div class="sim-ph-stat"><div class="sim-ph-stat-lbl">Original Price</div><div class="sim-ph-stat-num" style="color:var(--green);"><img src="/Onyx.png" alt="">${it.price.toLocaleString()}</div></div>
      <div class="sim-ph-stat"><div class="sim-ph-stat-lbl">Average Price</div><div class="sim-ph-stat-num" style="color:var(--green);"><img src="/Onyx.png" alt="">${avgPrice.toLocaleString()}</div></div>`;
  }

  const days = priceSeries.length;
  const W = 640, H = 220, PAD_L = 48, PAD_R = 16, PAD_T = 18, PAD_B = 36;
  const plotW = W - PAD_L - PAD_R, plotH = H - PAD_T - PAD_B;
  const maxPrice = Math.max(base, ...priceSeries) * 1.08;
  const minPrice = Math.min(0, ...priceSeries) * 0.95;
  const maxVol = Math.max(...volSeries, 1);
  const x = i => PAD_L + (plotW * (days > 1 ? i / (days - 1) : 0.5));
  const yP = v => PAD_T + plotH - ((v - minPrice) / (maxPrice - minPrice || 1)) * plotH;
  const yV = v => PAD_T + plotH - (v / maxVol) * plotH;

  // Y-axis gridlines + labels (price)
  const gridTicks = 5;
  let gridHTML = '';
  for (let i = 0; i <= gridTicks; i++) {
    const v = Math.round(minPrice + ((maxPrice - minPrice) * i) / gridTicks);
    const y = yP(v);
    gridHTML += `<line x1="${PAD_L}" y1="${y}" x2="${W - PAD_R}" y2="${y}" stroke="rgba(255,255,255,.04)" stroke-width="1"/>`;
    gridHTML += `<text x="${PAD_L - 6}" y="${y + 4}" text-anchor="end" font-size="10" fill="rgba(255,255,255,.4)" font-family="var(--font-ui)">${v.toLocaleString()}</text>`;
  }

  // Volume bars (grey, anchored to bottom axis)
  const bars = volSeries.map((v, i) => {
    const bx = x(i) - 16, bh = ((H - PAD_B) - yV(v));
    return `<rect x="${bx}" y="${yV(v)}" width="32" height="${Math.max(1, bh)}" fill="rgba(255,255,255,.12)" rx="2"/>`;
  }).join('');

  // Price line + dots (green)
  const linePath = priceSeries.map((v, i) => (i === 0 ? 'M' : 'L') + x(i) + ',' + yP(v)).join(' ');
  const dots = priceSeries.map((v, i) => `<circle cx="${x(i)}" cy="${yP(v)}" r="3.5" fill="#3ecf6e"/>`).join('');

  // X-axis date labels (just last 10 days)
  const today = new Date();
  const mon = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const xLabels = priceSeries.map((_, i) => {
    const d = new Date(today); d.setDate(today.getDate() - (days - 1 - i));
    if (i % 3 !== 0 && i !== days - 1) return '';
    return `<text x="${x(i)}" y="${H - 10}" text-anchor="middle" font-size="9.5" fill="rgba(255,255,255,.5)" font-family="var(--font-ui)">${d.getDate()} ${mon[d.getMonth()]}</text>`;
  }).join('');

  // Legend
  const legend = `<g transform="translate(${W / 2 - 80},4)">
    <rect x="0" y="2" width="10" height="4" fill="#3ecf6e" rx="1"/>
    <text x="16" y="10" font-size="10" fill="rgba(255,255,255,.7)" font-family="var(--font-ui)">Price</text>
    <rect x="70" y="2" width="10" height="4" fill="rgba(255,255,255,.3)" rx="1"/>
    <text x="86" y="10" font-size="10" fill="rgba(255,255,255,.7)" font-family="var(--font-ui)">Volume</text>
  </g>`;

  svg.innerHTML = legend + gridHTML + bars + `<path d="${linePath}" stroke="#3ecf6e" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/>` + dots + xLabels;
}

// Legacy entry kept as a shim so any stray caller still arms the inline
// confirm panel instead of popping a stacked sub-modal.
function openShopCheckout(itemId, kind) {
  const it = (typeof _getShopItemById === 'function') ? _getShopItemById(itemId) : null;
  if (it) _fsArmPurchase(itemId, kind, it.price);
}

// ── Legacy Fortshop checkout sub-modal (kept for backwards compat) ──
function _legacyOpenShopCheckout_unused(itemId, kind) {
  const it = (typeof _getShopItemById === 'function') ? _getShopItemById(itemId) : null;
  if (!it) { toast('Item not found', 'error'); return; }
  document.getElementById('sim-checkout')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'sim-checkout';
  overlay.className = 'sim-checkout-overlay';
  overlay.onclick = () => overlay.remove();
  const typeLabel = kind === 'appearance' ? 'Appearance' : 'Avatar Decoration';
  const preview = kind === 'decoration' && it.src
    ? `<img src="${escapeHTML(it.src)}" style="width:100%;height:100%;object-fit:contain;padding:6px;">`
    : `<div class="sim-preview-theme" style="background:${(it.previewBg || it.gradient || 'linear-gradient(135deg,#1a1426,#0a0814)')};width:100%;height:100%;"></div>`;
  const safeId = escapeHTML(itemId).replace(/'/g, "\\'");
  overlay.innerHTML = `
    <div class="sim-checkout-card" onclick="event.stopPropagation()">
      <div class="sim-checkout-head">
        <div class="sim-checkout-title">Checkout</div>
        <button class="sim-checkout-close" onclick="document.getElementById('sim-checkout').remove()" aria-label="Close">×</button>
      </div>
      <div class="sim-checkout-item">
        <div class="sim-checkout-item-preview">${preview}</div>
        <div class="sim-checkout-item-meta">
          <div class="sim-checkout-item-name">${escapeHTML(it.name)}</div>
          <div class="sim-checkout-item-type">${escapeHTML(typeLabel)}</div>
        </div>
        <div class="sim-checkout-item-price"><img src="/Onyx.png" alt="">${it.price.toLocaleString()}</div>
      </div>
      <div class="sim-checkout-method">
        <div class="sim-checkout-method-lbl">Payment method</div>
        <div class="sim-checkout-method-row">
          <img src="/Onyx.png" alt="" style="width:18px;height:18px;">
          <span>Onyx balance · ${(CU?.onyx || 0).toLocaleString()} available</span>
        </div>
      </div>
      <div class="sim-checkout-total">
        <span>Total due</span>
        <span class="sim-checkout-total-num"><img src="/Onyx.png" alt="">${it.price.toLocaleString()}</span>
      </div>
      <div class="sim-checkout-legal">
        <label class="sim-checkout-agree">
          <input type="checkbox" id="sim-checkout-agree-box" onchange="document.getElementById('sim-checkout-buy').disabled=!this.checked">
          <span>I agree to the <a href="/legal/fortshop-policy" target="_blank" rel="noopener" style="color:var(--accent);text-decoration:underline;">Fortshop Policy</a>. Items are final once delivered.</span>
        </label>
      </div>
      <div class="sim-checkout-actions">
        <button class="sim-checkout-cancel" onclick="document.getElementById('sim-checkout').remove()">Cancel</button>
        <button class="sim-checkout-buy" id="sim-checkout-buy" disabled onclick="_fsCompletePurchase('${safeId}','${escapeHTML(kind)}',${it.price})">Purchase</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
}

async function _fsCompletePurchase(itemId, kind, price) {
  try {
    // Server-side-ish guard: if the item is seasonal and its season isn't
    // active, bounce the direct-buy attempt. Resellers are still fine.
    const guardItem = _getShopItemById(itemId);
    if (guardItem && !_isItemOnSaleInShop(guardItem)) {
      toast('This seasonal item is no longer sold in Fortshop. Check resellers.', 'error');
      return;
    }
    if (kind === 'appearance' && typeof buyAppearance === 'function') {
      await buyAppearance(itemId, price);
    } else if (kind === 'decoration' && typeof buyDecoration === 'function') {
      await buyDecoration(itemId, price);
    } else if (kind === 'bundle' && typeof buyBundle === 'function') {
      await buyBundle(itemId, price);
    } else {
      toast('Purchase failed — unknown item type.', 'error');
      return;
    }
    document.getElementById('shop-item-modal')?.remove();
  } catch (e) {
    console.warn('[Fortshop] purchase failed:', e);
    toast('Purchase failed.', 'error');
  }
}

// ── Fortshop bundle detail modal ──
