function openShopBundleModal(id) {
  const bundle = _FORTSHOP_BUNDLES[id];
  if (!bundle) { toast('Bundle not found', 'error'); return; }
  const ownedApps = CU?.unlockedAppearances || [];
  const ownedDecos = CU?.ownedDecorations || [];
  const allOwned = bundle.items.every(i => i.kind === 'appearance' ? ownedApps.includes(i.id) : ownedDecos.includes(i.id));
  const savings = Math.max(0, bundle.origTotal - bundle.price);
  const savingsPct = bundle.origTotal > 0 ? Math.round((savings / bundle.origTotal) * 100) : 0;

  document.getElementById('shop-item-modal')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'shop-item-modal';
  overlay.className = 'sim-overlay';
  overlay.onclick = () => overlay.remove();

  const itemsHTML = bundle.items.map(entry => {
    const it = (typeof _getShopItemById === 'function') ? _getShopItemById(entry.id) : null;
    if (!it) return '';
    const owned = entry.kind === 'appearance' ? ownedApps.includes(entry.id) : ownedDecos.includes(entry.id);
    const cover = entry.kind === 'decoration' && it.src
      ? `<img src="${escapeHTML(it.src)}" alt="">`
      : _renderAppearancePreview(it);
    return `<div class="sim-bundle-item${owned ? ' sim-bundle-item--owned' : ''}">
      <div class="sim-bundle-item-preview">${cover}</div>
      <div class="sim-bundle-item-meta">
        <div class="sim-bundle-item-type">${entry.kind === 'appearance' ? 'Appearance' : 'Avatar Decoration'}</div>
        <div class="sim-bundle-item-name">${escapeHTML(it.name)}</div>
        <div class="sim-bundle-item-price"><img src="/Onyx.png" alt="">${it.price}</div>
        ${owned ? '<div class="sim-bundle-item-owned">✓ Already on your profile</div>' : ''}
      </div>
    </div>`;
  }).join('');

  const safeId = escapeHTML(bundle.id).replace(/'/g, "\\'");
  overlay.innerHTML = `
    <div class="sim-card sim-card--bundle sim-hero--${escapeHTML(bundle.theme || 'onyx')}" onclick="event.stopPropagation()">
      <button class="sim-close" onclick="document.getElementById('shop-item-modal').remove()" aria-label="Close">×</button>
      <div class="sim-hero sim-hero--${escapeHTML(bundle.theme || 'onyx')}">
        <div class="sim-hero-badge">Bundle · save ${savingsPct}%</div>
        <div class="sim-hero-meta" style="max-width:none;">
          <div class="sim-hero-type">${escapeHTML(bundle.kicker)}</div>
          <div class="sim-hero-name">${escapeHTML(bundle.name)}</div>
          <div class="sim-hero-desc">${escapeHTML(bundle.desc)}</div>
        </div>
      </div>
      <div class="sim-body">
        <div class="sim-bundle-list">${itemsHTML}</div>
        <div class="sim-buy-panel">
          <div class="sim-buy-price">
            <div class="sim-buy-price-lbl">Bundle price</div>
            <div class="sim-buy-price-num"><img src="/Onyx.png" alt="">${bundle.price.toLocaleString()}</div>
            ${savings > 0 ? `<div class="sim-buy-savings">Save <img src="/Onyx.png" alt="">${savings.toLocaleString()} vs. buying alone</div>` : ''}
          </div>
          <div class="sim-buy-actions">
            ${allOwned
              ? '<button class="sim-buy-btn sim-buy-btn--owned" disabled>✓ Bundle already on your profile</button>'
              : `<button class="sim-buy-btn" id="sim-buy-btn" onclick="_fsArmPurchase('${safeId}','bundle',${bundle.price})">Buy bundle · <img src="/Onyx.png" alt="" style="width:13px;height:13px;vertical-align:-2px;"> ${bundle.price.toLocaleString()}</button>`}
          </div>
        </div>
        ${!allOwned ? `<div id="sim-confirm-panel" class="sim-confirm-panel" style="display:none;">
          <label class="sim-confirm-agree">
            <input type="checkbox" id="sim-confirm-agree-box" onchange="document.getElementById('sim-confirm-buy').disabled=!this.checked">
            <span>I agree to the <a href="/legal/fortshop-policy" target="_blank" rel="noopener" style="color:var(--accent);text-decoration:underline;">Fortshop Policy</a>. Items are final once delivered.</span>
          </label>
          <div class="sim-confirm-actions">
            <button class="sim-confirm-cancel" onclick="_fsDisarmPurchase()">Cancel</button>
            <button class="sim-confirm-buy" id="sim-confirm-buy" disabled onclick="_fsCompletePurchase('${safeId}','bundle',${bundle.price})">Confirm purchase</button>
          </div>
        </div>` : ''}
      </div>
    </div>`;
  document.body.appendChild(overlay);
}

async function _loadShopMarketplace() {
  const grid = document.getElementById('shop-marketplace-grid');
  if (!grid) return;
  try {
    const listings = await getMarketplaceListings().catch(()=>[]);
    const avail = listings.filter(l => !l.sold);
    if (!avail.length) {
      grid.innerHTML = `<div style="padding:40px;text-align:center;color:var(--muted);font-size:12.5px;grid-column:1/-1;">
        <div style="opacity:.4;margin-bottom:10px;">${_svgIcon('tag',32)}</div>
        <div style="font-weight:700;margin-bottom:6px;">No active listings</div>
        <div style="font-size:11.5px;opacity:.8;">Be the first to list a rare or seasonal item for resale.</div>
      </div>`;
      return;
    }
    grid.innerHTML = avail.map(l => {
      const it = _getShopItemById(l.item_id) || {};
      const rarity = it.rare ? 'Rare' : it.seasonal ? 'Seasonal' : 'Item';
      const rarityColor = it.rare ? 'rgba(255,249,62,.85)' : 'rgba(167,139,250,.85)';
      return `<div style="padding:14px;background:var(--panel);border:1.5px solid var(--border);border-radius:14px;display:flex;flex-direction:column;gap:10px;transition:border-color .15s;" onmouseenter="this.style.borderColor='rgba(255,249,62,.2)'" onmouseleave="this.style.borderColor='var(--border)'">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
          <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:${rarityColor};">${rarity}</div>
          <div style="font-size:10.5px;color:var(--muted);">by @${escapeHTML(l.seller||'?')}</div>
        </div>
        <div style="font-size:14px;font-weight:800;color:#fff;">${escapeHTML(it.name || l.item_id)}</div>
        ${it.desc ? `<div style="font-size:11.5px;color:var(--muted-light);line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;">${escapeHTML(it.desc)}</div>` : ''}
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:auto;padding-top:6px;border-top:1px solid var(--border);">
          <div style="display:flex;align-items:center;gap:5px;font-family:var(--font-display);font-size:15px;font-weight:800;color:var(--accent);">
            <img src="/Onyx.png" style="width:13px;height:13px;object-fit:contain;"> ${l.price}
          </div>
          <button onclick="buyListing('${escapeHTML(l.id)}').then(()=>{ _loadShopMarketplace(); })" style="padding:8px 16px;background:var(--accent);color:var(--rail);border:none;border-radius:10px;font-size:11.5px;font-weight:800;cursor:pointer;transition:all .15s;" onmouseenter="this.style.transform='translateY(-1px)'" onmouseleave="this.style.transform=''">Buy</button>
        </div>
      </div>`;
    }).join('');
  } catch(e) {
    console.warn('[Marketplace] load failed', e);
    grid.innerHTML = `<div style="padding:30px;text-align:center;color:var(--muted);grid-column:1/-1;">Couldn't load marketplace.</div>`;
  }
}
async function listForResale(itemId, askPrice) {
  const item = _getShopItemById(itemId);
  if (!item) { toast('Item not found', 'error'); return; }
  const isRareOrEvent = !!(item.rare || item.seasonal || item.event || item.rarity === 'rare' || item.rarity === 'epic' || item.rarity === 'legendary');
  if (!isRareOrEvent) { toast('Only rare or event items can be resold', 'error'); return; }
  if (!(CU?.unlockedAppearances||[]).includes(itemId) && !(CU?.ownedDecorations||[]).includes(itemId)) {
    toast('You don\'t own this item', 'error'); return;
  }
  // Cap: a seller can have at most 2 active listings per item at a time.
  try {
    const existing = await _fsReadAllListings(itemId);
    const mine = existing.filter(l => l.seller === CU?.username);
    if (mine.length >= 2) {
      toast('You already have 2 active listings for this item.', 'error');
      return;
    }
  } catch(_) {}
  const listing = {
    id: 'listing_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
    item_id: itemId,
    seller: CU.username,
    price: Math.max(1, Math.floor(askPrice || item.price || 0)),
    follow_price: false,
    created_at: Date.now(),
    sold: false,
  };
  let wroteToSupabase = false;
  try {
    const res = await FortizedSocial.sb?.from('marketplace_listings')?.insert(listing);
    if (res && !res.error) wroteToSupabase = true;
    else if (res?.error) console.warn('[Fortshop] Supabase insert failed:', res.error.message);
  } catch(e) { console.warn('[Fortshop] Supabase insert threw:', e); }

  // Fallback: persist locally so the listing is visible in the UI even if
  // the marketplace_listings table isn't provisioned on Supabase yet. Merged
  // with the remote set on read by _fsReadAllListings.
  if (!wroteToSupabase) {
    try {
      const local = JSON.parse(localStorage.getItem('ftz_local_marketplace_listings') || '[]');
      local.push(listing);
      localStorage.setItem('ftz_local_marketplace_listings', JSON.stringify(local.slice(-500)));
    } catch(_) {}
  }
  toast(wroteToSupabase ? 'Listed for resale.' : 'Listed for resale (pending sync).', 'success');
}

// Reads listings from Supabase + the localStorage fallback and merges them.
// Dedupes by id (Supabase row wins when both exist). Filters out sold rows.
async function _fsReadAllListings(itemId) {
  let remote = [];
  try {
    const raw = await FortizedSocial.sb?.from('marketplace_listings')
      ?.select('*').eq('item_id', itemId);
    if (raw?.error) console.warn('[Fortshop] marketplace_listings read error:', raw.error.message);
    remote = raw?.data || [];
  } catch(e) { console.warn('[Fortshop] marketplace_listings read threw:', e); }

  let local = [];
  try {
    const all = JSON.parse(localStorage.getItem('ftz_local_marketplace_listings') || '[]');
    local = all.filter(l => l.item_id === itemId);
  } catch(_) {}

  const seen = new Set();
  const merged = [];
  remote.forEach(l => { seen.add(l.id); merged.push(l); });
  local.forEach(l => { if (!seen.has(l.id)) merged.push(l); });
  return merged.filter(l => !l.sold);
}
async function buyListing(listingId) {
  const listings = await getMarketplaceListings();
  const l = listings.find(x => x.id === listingId);
  if (!l || l.sold) { toast('No longer available', 'error'); return; }
  if ((CU?.onyx||0) < l.price) { toast('Not enough Onyx', 'error'); return; }
  try {
    await FortizedSocial.sb?.from('marketplace_listings')?.update({ sold: true, buyer: CU.username, sold_at: Date.now() })?.eq('id', listingId);
    CU.onyx -= l.price;
    // Grant item to buyer
    const item = _getShopItemById(l.item_id);
    const field = item?.kind === 'decoration' ? 'ownedDecorations' : 'unlockedAppearances';
    const owned = (CU[field]||[]).slice();
    if (!owned.includes(l.item_id)) owned.push(l.item_id);
    CU[field] = owned;
    // Remove from seller
    const seller = await FortizedSocial.getUserByName(l.seller);
    if (seller) {
      const sOwn = (seller[field]||[]).filter(i => i !== l.item_id);
      await FortizedSocial.adminUpdateUserField(l.seller, field, sOwn);
    }
    await saveUser(true); updateOnyxDisplay();
    // Apply 30% tax — seller gets 70%
    await applyTax(l.price, { seller: l.seller, reason: 'resale' });
    toast('Purchased!', 'success');
  } catch(e) { console.error('[Marketplace] buy failed', e); toast('Purchase failed', 'error'); }
}

// ── Minimal modal helpers for the above (reuse ftzModal if present) ──
function openSimpleModal(html) {
  closeSimpleModal();
  const m = document.createElement('div');
  m.className = 'simple-modal-wrap';
  m.id = 'simple-modal';
  m.innerHTML = `<div class="simple-modal-card">
    <button class="simple-modal-close" onclick="closeSimpleModal()">×</button>
    ${html}
  </div>`;
  m.onclick = (e) => { if (e.target === m) closeSimpleModal(); };
  document.body.appendChild(m);
}
function closeSimpleModal() {
  document.getElementById('simple-modal')?.remove();
}

// ════════════════════════════════════════════════════════════
// PANIC ESCAPE — global safety net for stuck overlays.
//
// Many modals across the app install their own Escape listeners, but if a
// child element grabs focus (or the listener never gets registered because
// of a thrown error during open), pressing Escape silently does nothing
// and the user is locked out of the UI. This handler runs in the capture
// phase and tears down the topmost obviously-blocking overlay whenever
// Escape is pressed — it's idempotent and only fires when something is
// actually stuck.
// ════════════════════════════════════════════════════════════
(function _installPanicEscape() {
  if (window._ftzPanicEscapeInstalled) return;
  window._ftzPanicEscapeInstalled = true;
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape' || e.ctrlKey || e.shiftKey || e.altKey || e.metaKey) return;
    // Skip if the user is editing text (let textarea/input/contenteditable own Escape).
    const t = e.target;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
    // Find the topmost blocking overlay (highest z-index among full-screen fixed elements).
    const candidates = Array.from(document.querySelectorAll('.modal-overlay.open, [id$="-modal"], [id$="-popup"], [id$="-overlay"]'))
      .filter(el => el.offsetParent !== null && el.parentElement);
    if (!candidates.length) return;
    let top = candidates[0], topZ = -Infinity;
    for (const el of candidates) {
      const z = parseInt(getComputedStyle(el).zIndex, 10) || 0;
      if (z >= topZ) { topZ = z; top = el; }
    }
    if (top) top.remove();
  }, true);
})();

// ════════════════════════════════════════════════════════════
// SEND-PATH CRASH GUARD — catch unhandled errors during message send so
// they don't leave the UI in a stuck "sending…" state. Every send path
// (DM / GC / channel) is wrapped: if any of them throw, log + toast, and
// remove any leftover overlays that might have been opened mid-flight.
// ════════════════════════════════════════════════════════════
window.addEventListener('unhandledrejection', (e) => {
  const msg = e.reason?.message || String(e.reason || '');
  // Only guard send-path failures — surface everything else normally.
  if (!/sendDM|sendGC|sendChannel|handleChatSend|preprocessMessageText|appendMessage/.test(msg + (e.reason?.stack || ''))) return;
  console.error('[SendCrashGuard]', e.reason);
  try { if (typeof toast === 'function') toast('Something glitched while sending. Try again.', 'error'); } catch {}
  // Best-effort overlay sweep so the UI isn't locked.
  document.querySelectorAll('.modal-overlay.open').forEach(el => {
    if (el.dataset.ftzKeepOpen !== '1') el.classList.remove('open');
  });
});

// ════════════════════════════════════════════════════════════
// GLOBAL IMAGE-ERROR FALLBACK
// Capture-phase error listener on the document: when any <img> fails to
// load, replace it with a neutral neutralised tile (subtle background +
// faded glyph) so users never see the browser's broken-image icon. Per-
// element onerror handlers (legacy code) still take precedence — we only
// act when the image had no other handler.
// ════════════════════════════════════════════════════════════
(function _installImageErrorFallback() {
  if (window._ftzImgFallbackInstalled) return;
  window._ftzImgFallbackInstalled = true;
  document.addEventListener('error', (e) => {
    const t = e.target;
    if (!t || t.tagName !== 'IMG') return;
    if (t.dataset.ftzFallback === '1') return; // already handled
    if (t.getAttribute('onerror')) return;     // legacy inline handler will run
    t.dataset.ftzFallback = '1';
    // Hide image, replace with a subtle neutral tile inheriting size + radius.
    const cs = getComputedStyle(t);
    const w = cs.width || (t.width ? t.width + 'px' : '24px');
    const h = cs.height || (t.height ? t.height + 'px' : '24px');
    const radius = cs.borderRadius || '6px';
    const span = document.createElement('span');
    span.setAttribute('aria-hidden', 'true');
    span.style.cssText = `display:inline-block;width:${w};height:${h};border-radius:${radius};background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.05);`;
    if (t.parentNode) t.parentNode.replaceChild(span, t);
  }, true);
})();

// ════════════════════════════════════════════════════════════
// PENDING-SAVE FLUSH — when the user navigates away, force any
// debounced saveUser() to fire NOW instead of being lost. Without this,
// changes made within the last 300ms (the debounce window) silently
// vanish on refresh. The classic case: change decoration → reload too
// fast → DB still has the old value → "decoration came back".
//
// We flush by clearing the timer + calling saveUserObject synchronously
// from the unload handler. Browsers cap async work in unload listeners,
// so we use sendBeacon as a backup transport when available.
// ════════════════════════════════════════════════════════════
window.addEventListener('beforeunload', () => {
  try {
    if (window._saveUserTimer) {
      clearTimeout(window._saveUserTimer);
      window._saveUserTimer = null;
    }
    // Best-effort: fire the save. Browsers will honor the request as
    // long as we don't await it here — the fetch is queued before the
    // page unloads.
    if (typeof FortizedSocial !== 'undefined' && CU?.username && FortizedSocial.saveUserObject) {
      FortizedSocial.saveUserObject(CU).catch(() => {});
    }
  } catch {}
}, { capture: true });

// ════════════════════════════════════════════════════════════
// MEMORY HYGIENE — prune stale entries in _recentlyEditedFields every
// 60s so the map doesn't grow unbounded over a long session.
// ════════════════════════════════════════════════════════════
setInterval(() => {
  const m = window._recentlyEditedFields;
  if (!m) return;
  const cutoff = Date.now() - 30000; // 30s window — well past the 8s used by refreshCU
  for (const k in m) { if (m[k] < cutoff) delete m[k]; }
}, 60000);

